/// One-use final carrier check for an already sealed finite Blob source frame.
///
/// This retains the exact Store checkpoint and authenticated conservative age
/// bound. It is deliberately non-`Clone` and is consumed immediately before
/// carrier I/O.
#[doc(hidden)]
#[derive(Debug)]
pub struct PreparedBlobCustodySend {
    context: BlobCustodySendContextFields,
    checkpoint_sample: aster_mesh::CustodySample,
    authenticated_age_ms: u64,
    projection: BlobSourceProjection,
    retention: BlobSourceRetention,
}

impl VerifiedBlobCustodySend {
    /// Consumes the Store authorization to construct one exact claim.
    pub fn into_claim(
        self,
        source: &ContentVerifiedBlobEnvelope,
        exact_source_bytes: &[u8],
    ) -> Result<(BlobCustodyClaimV1, PreparedBlobCustodySend), BlobCustodyError> {
        let Self {
            context,
            source_transfer_id,
            source_len,
            publication_id,
            blob_id,
            priority,
            ttl_ms,
            prior_cumulative_age_ms,
            sender_sample,
            authenticated_age_ms,
            projection,
            retention,
        } = self;
        let claim = BlobCustodyClaimV1::from_authenticated_source(
            context.session_transcript,
            context.exchange_id,
            context.direction,
            source_transfer_id,
            source,
            exact_source_bytes,
            prior_cumulative_age_ms,
            sender_sample,
            context.finalization_charge_ms,
        )?;
        if claim.source_len() != source_len
            || claim.publication_id() != publication_id
            || claim.blob_id() != blob_id
            || claim.priority() != priority
            || claim.ttl_ms() != ttl_ms
            || claim.forwarding_age_ms() != authenticated_age_ms
        {
            return Err(BlobCustodyError::ContextMismatch);
        }
        Ok((
            claim,
            PreparedBlobCustodySend {
                context,
                checkpoint_sample: sender_sample,
                authenticated_age_ms,
                projection,
                retention,
            },
        ))
    }
}

impl VerifiedBlobCustodySendV2 {
    pub fn into_claim(
        self,
        source: &ContentVerifiedBlobEnvelope,
        exact_source_bytes: &[u8],
    ) -> Result<(BlobCustodyClaimV2, PreparedBlobCustodySend), BlobCustodyError> {
        let VerifiedBlobCustodySendV2 { authority, inner } = self;
        let VerifiedBlobCustodySend {
            context,
            source_transfer_id,
            source_len,
            publication_id,
            blob_id,
            priority,
            ttl_ms,
            prior_cumulative_age_ms,
            sender_sample,
            authenticated_age_ms,
            projection,
            retention,
        } = inner;
        let claim = BlobCustodyClaimV2::from_authenticated_source(
            authority,
            source_transfer_id,
            source,
            exact_source_bytes,
            prior_cumulative_age_ms,
            sender_sample,
        )?;
        if claim.source_len() != source_len
            || claim.publication_id() != publication_id
            || claim.blob_id() != blob_id
            || claim.priority() != priority
            || claim.ttl_ms() != ttl_ms
            || claim.forwarding_age_ms() != authenticated_age_ms
        {
            return Err(BlobCustodyError::ContextMismatch);
        }
        Ok((
            claim,
            PreparedBlobCustodySend {
                context,
                checkpoint_sample: sender_sample,
                authenticated_age_ms,
                projection,
                retention,
            },
        ))
    }

    /// Consumes Store-authenticated native Profile-5 source authority without
    /// reconstructing the legacy manifest envelope grammar.
    pub fn into_profile5_claim(
        self,
    ) -> Result<(aster_mesh::BlobCustodyClaimV2, PreparedBlobCustodySend), BlobCustodyError> {
        let VerifiedBlobCustodySendV2 { authority, inner } = self;
        let VerifiedBlobCustodySend {
            context,
            source_transfer_id,
            source_len,
            publication_id,
            blob_id,
            priority,
            ttl_ms,
            prior_cumulative_age_ms,
            sender_sample,
            authenticated_age_ms,
            projection,
            retention,
        } = inner;
        let claim = aster_mesh::BlobCustodyClaimV2::from_authenticated_profile5_source(
            authority,
            source_transfer_id,
            source_len,
            publication_id,
            blob_id,
            priority,
            ttl_ms,
            prior_cumulative_age_ms,
            sender_sample,
        )?;
        if claim.source_len() != source_len
            || claim.publication_id() != publication_id
            || claim.blob_id() != blob_id
            || claim.priority() != priority
            || claim.ttl_ms() != ttl_ms
            || claim.forwarding_age_ms() != authenticated_age_ms
        {
            return Err(BlobCustodyError::ContextMismatch);
        }
        Ok((
            claim,
            PreparedBlobCustodySend {
                context,
                checkpoint_sample: sender_sample,
                authenticated_age_ms,
                projection,
                retention,
            },
        ))
    }
}

impl VerifiedFiniteBlobAdmission {
    fn from_verified(
        verified: VerifiedBlobCustodyClaimV1,
        receiver_sample: aster_mesh::CustodySample,
    ) -> Self {
        Self {
            source_transfer_id: *verified.source_transfer_id().as_bytes(),
            source_len: verified.source_len(),
            publication_id: verified.publication_id(),
            blob_id: verified.blob_id(),
            priority: verified.priority(),
            ttl_ms: verified.ttl_ms(),
            forwarding_age_ms: verified.forwarding_age_ms(),
            receiver_sample,
            provenance: BlobFiniteProvenance::NetworkV1 {
                semantic_version: 8,
                profile_id: aster_mesh::TransferProfileId::BlobRangesStreamV1 as u16,
            },
        }
    }

    fn from_verified_v2(
        verified: VerifiedBlobCustodyClaimV2,
        receiver_sample: aster_mesh::CustodySample,
    ) -> Self {
        Self {
            source_transfer_id: *verified.source_transfer_id().as_bytes(),
            source_len: verified.source_len(),
            publication_id: verified.publication_id(),
            blob_id: verified.blob_id(),
            priority: verified.priority(),
            ttl_ms: verified.ttl_ms(),
            forwarding_age_ms: verified.forwarding_age_ms(),
            receiver_sample,
            provenance: BlobFiniteProvenance::NetworkV1 {
                semantic_version: 9,
                profile_id: 5,
            },
        }
    }

    fn from_verified_v2_elapsed(
        verified: VerifiedBlobCustodyClaimV2,
        received_sample: aster_mesh::CustodySample,
        promotion_sample: aster_mesh::CustodySample,
    ) -> Result<Self, StoreError> {
        if received_sample.clock_id != promotion_sample.clock_id
            || promotion_sample.tick_ms < received_sample.tick_ms
        {
            return Err(blob_error(BlobStoreError::PendingSourceConflict));
        }
        let elapsed_ms = promotion_sample.tick_ms - received_sample.tick_ms;
        let forwarding_age_ms = verified
            .forwarding_age_ms()
            .checked_add(elapsed_ms)
            .ok_or_else(|| blob_error(BlobStoreError::ExpiredOrRetired))?;
        Ok(Self {
            source_transfer_id: *verified.source_transfer_id().as_bytes(),
            source_len: verified.source_len(),
            publication_id: verified.publication_id(),
            blob_id: verified.blob_id(),
            priority: verified.priority(),
            ttl_ms: verified.ttl_ms(),
            forwarding_age_ms,
            receiver_sample: promotion_sample,
            provenance: BlobFiniteProvenance::NetworkV1 {
                semantic_version: 9,
                profile_id: 5,
            },
        })
    }

    fn forwarding_age_at(
        &self,
        normalized_sample: aster_mesh::CustodySample,
    ) -> Result<u64, StoreError> {
        if normalized_sample.clock_id != self.receiver_sample.clock_id
            || normalized_sample.tick_ms < self.receiver_sample.tick_ms
        {
            return Err(blob_error(BlobStoreError::PendingSourceConflict));
        }
        self.forwarding_age_ms
            .checked_add(normalized_sample.tick_ms - self.receiver_sample.tick_ms)
            .ok_or_else(|| blob_error(BlobStoreError::ExpiredOrRetired))
    }

    #[cfg(any(test, feature = "test-utils"))]
    #[allow(clippy::too_many_arguments)]
    const fn for_test(
        source_transfer_id: [u8; 32],
        source_len: u64,
        publication_id: [u8; 32],
        blob_id: BlobId,
        priority: Priority,
        ttl_ms: u64,
        forwarding_age_ms: u64,
        receiver_sample: aster_mesh::CustodySample,
    ) -> Self {
        Self {
            source_transfer_id,
            source_len,
            publication_id,
            blob_id,
            priority,
            ttl_ms,
            forwarding_age_ms,
            receiver_sample,
            provenance: BlobFiniteProvenance::NetworkV1 {
                semantic_version: 8,
                profile_id: aster_mesh::TransferProfileId::BlobRangesStreamV1 as u16,
            },
        }
    }

    #[cfg(any(test, feature = "test-utils"))]
    #[allow(clippy::too_many_arguments)]
    const fn for_test_with_network_provenance(
        source_transfer_id: [u8; 32],
        source_len: u64,
        publication_id: [u8; 32],
        blob_id: BlobId,
        priority: Priority,
        ttl_ms: u64,
        forwarding_age_ms: u64,
        receiver_sample: aster_mesh::CustodySample,
        semantic_version: u16,
        profile_id: u16,
    ) -> Self {
        Self {
            source_transfer_id,
            source_len,
            publication_id,
            blob_id,
            priority,
            ttl_ms,
            forwarding_age_ms,
            receiver_sample,
            provenance: BlobFiniteProvenance::NetworkV1 {
                semantic_version,
                profile_id,
            },
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum BlobLifetimeEvaluation {
    Durable,
    FiniteLive {
        age_ms: u64,
        remaining_ms: u64,
        deadline: aster_mesh::CustodySample,
    },
    FiniteIndeterminate {
        age_ms: u64,
        deadline: Option<aster_mesh::CustodySample>,
    },
    FiniteExpired {
        age_ms: u64,
    },
}

fn validate_blob_lifetime(lifetime: BlobLifetime) -> Result<(), StoreError> {
    let BlobLifetime::Finite {
        ttl_ms,
        age,
        provenance,
    } = lifetime
    else {
        return Ok(());
    };
    // Preserve well-formed v8+ network provenance as opaque historical data.
    // Contact authority is deliberately stricter and admits only exact
    // semantic-v8/BlobRangesStreamV1 custody; future provenance must remain retainable but
    // non-forwardable by this runtime.
    if ttl_ms == 0
        || age
            .checkpoint
            .is_some_and(|sample| sample.clock_id == [0; 16])
        || (age.checkpoint.is_some() && age.continuity_generation == 0)
        || (age.checkpoint.is_none() && (age.continuity_generation != 0 || !age.continuity_lost))
        || matches!(
            provenance,
            BlobFiniteProvenance::NetworkV1 {
                semantic_version,
                profile_id,
            } if semantic_version < 8 || profile_id == 0
        )
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob lifetime is not canonical",
        )));
    }
    Ok(())
}

fn encode_blob_lifetime(lifetime: BlobLifetime) -> Result<Vec<u8>, StoreError> {
    validate_blob_lifetime(lifetime)?;
    let mut encoded = Vec::new();
    let BlobLifetime::Finite {
        ttl_ms,
        age,
        provenance,
    } = lifetime
    else {
        encoded.push(0);
        return Ok(encoded);
    };
    encoded.push(match provenance {
        BlobFiniteProvenance::Local => 1,
        BlobFiniteProvenance::NetworkV1 { .. } => 2,
    });
    encoded.extend_from_slice(&ttl_ms.to_be_bytes());
    encoded.extend_from_slice(&age.cumulative_age_ms.to_be_bytes());
    encoded.push(u8::from(age.checkpoint.is_some()));
    if let Some(checkpoint) = age.checkpoint {
        encoded.extend_from_slice(&checkpoint.clock_id);
        encoded.extend_from_slice(&checkpoint.tick_ms.to_be_bytes());
    }
    encoded.extend_from_slice(&age.continuity_generation.to_be_bytes());
    encoded.push(u8::from(age.continuity_lost));
    if let BlobFiniteProvenance::NetworkV1 {
        semantic_version,
        profile_id,
    } = provenance
    {
        encoded.extend_from_slice(&semantic_version.to_be_bytes());
        encoded.extend_from_slice(&profile_id.to_be_bytes());
    }
    Ok(encoded)
}

fn decode_blob_lifetime(bytes: &[u8]) -> Result<BlobLifetime, StoreError> {
    let mut cursor = MetadataCursor::new(bytes);
    let tag = cursor.u8()?;
    if tag == 0 {
        cursor.finish()?;
        return Ok(BlobLifetime::Durable);
    }
    let ttl_ms = cursor.u64()?;
    let cumulative_age_ms = cursor.u64()?;
    let checkpoint = match cursor.u8()? {
        0 => None,
        1 => Some(aster_mesh::CustodySample {
            clock_id: cursor.array()?,
            tick_ms: cursor.u64()?,
        }),
        _ => {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob lifetime has an invalid checkpoint tag",
            )));
        }
    };
    let continuity_generation = cursor.u64()?;
    let continuity_lost = match cursor.u8()? {
        0 => false,
        1 => true,
        _ => {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob lifetime has an invalid continuity tag",
            )));
        }
    };
    let provenance = match tag {
        1 => BlobFiniteProvenance::Local,
        2 => BlobFiniteProvenance::NetworkV1 {
            semantic_version: cursor.u16()?,
            profile_id: cursor.u16()?,
        },
        _ => {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob lifetime has an unknown provenance tag",
            )));
        }
    };
    cursor.finish()?;
    let lifetime = BlobLifetime::Finite {
        ttl_ms,
        age: custody::LowerBoundAgeCheckpoint {
            cumulative_age_ms,
            checkpoint,
            continuity_generation,
            continuity_lost,
        },
        provenance,
    };
    validate_blob_lifetime(lifetime)?;
    Ok(lifetime)
}

pub(crate) fn evaluate_blob_lifetime(
    lifetime: BlobLifetime,
    continuity: Option<custody::LowerBoundContinuity>,
    sample: Option<aster_mesh::CustodySample>,
) -> Result<BlobLifetimeEvaluation, StoreError> {
    validate_blob_lifetime(lifetime)?;
    let BlobLifetime::Finite { ttl_ms, age, .. } = lifetime else {
        return Ok(BlobLifetimeEvaluation::Durable);
    };
    if let (Some(checkpoint), Some(continuity), Some(sample)) = (age.checkpoint, continuity, sample)
        && age.continuity_generation == continuity.generation
        && checkpoint.clock_id == continuity.sample.clock_id
        && checkpoint.clock_id == sample.clock_id
        && sample.tick_ms >= checkpoint.tick_ms
        && age
            .cumulative_age_ms
            .checked_add(sample.tick_ms - checkpoint.tick_ms)
            .is_none()
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob lifetime age arithmetic overflowed",
        )));
    }
    let projected = custody::project_lower_bound_age(age, continuity, sample);
    if projected.cumulative_age_ms >= ttl_ms {
        return Ok(BlobLifetimeEvaluation::FiniteExpired {
            age_ms: projected.cumulative_age_ms,
        });
    }
    let remaining_ms = ttl_ms - projected.cumulative_age_ms;
    // A positive TTL is exact even when its mathematical deadline lies beyond
    // the representable custody-clock domain. Such a deadline is unreachable:
    // at `u64::MAX` the accumulated representable age is still smaller than the
    // requested TTL. Saturating the scheduling hint therefore preserves the
    // lifetime contract without turning a valid publication into a schema
    // failure.
    let deadline = projected
        .checkpoint
        .map(|checkpoint| aster_mesh::CustodySample {
            clock_id: checkpoint.clock_id,
            tick_ms: checkpoint.tick_ms.saturating_add(remaining_ms),
        });
    if projected.continuity_lost {
        return Ok(BlobLifetimeEvaluation::FiniteIndeterminate {
            age_ms: projected.cumulative_age_ms,
            deadline,
        });
    }
    Ok(BlobLifetimeEvaluation::FiniteLive {
        age_ms: projected.cumulative_age_ms,
        remaining_ms,
        deadline: deadline.ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "continuous finite Blob lifetime lacks a deadline",
            ))
        })?,
    })
}

fn blob_lifetime_is_visible_read(
    read: &redb::ReadTransaction,
    lifetime: BlobLifetime,
) -> Result<bool, StoreError> {
    let continuity = custody::lower_bound_continuity_read(read)?;
    let sample = continuity.map(|authority| authority.sample);
    Ok(matches!(
        evaluate_blob_lifetime(lifetime, continuity, sample)?,
        BlobLifetimeEvaluation::Durable | BlobLifetimeEvaluation::FiniteLive { .. }
    ))
}

fn blob_lifetime_is_visible_for_contact_read(
    read: &redb::ReadTransaction,
    lifetime: BlobLifetime,
    eligibility: BlobContactEligibility,
) -> Result<bool, StoreError> {
    if !eligibility.admits(lifetime) {
        return Ok(false);
    }
    blob_lifetime_is_visible_read(read, lifetime)
}

fn require_blob_contact_eligibility(
    lifetime: BlobLifetime,
    eligibility: BlobContactEligibility,
) -> Result<(), StoreError> {
    if eligibility.admits(lifetime) {
        Ok(())
    } else {
        Err(blob_error(BlobStoreError::ReadPlanChanged))
    }
}

fn blob_lifetime_is_visible_write(
    write: &redb::WriteTransaction,
    lifetime: BlobLifetime,
) -> Result<bool, StoreError> {
    let continuity = custody::lower_bound_continuity_write(write)?;
    let sample = continuity.map(|authority| authority.sample);
    Ok(matches!(
        evaluate_blob_lifetime(lifetime, continuity, sample)?,
        BlobLifetimeEvaluation::Durable | BlobLifetimeEvaluation::FiniteLive { .. }
    ))
}

fn require_blob_lifetime_visible_read(
    read: &redb::ReadTransaction,
    lifetime: BlobLifetime,
) -> Result<(), StoreError> {
    if blob_lifetime_is_visible_read(read, lifetime)? {
        Ok(())
    } else {
        Err(blob_error(BlobStoreError::ExpiredOrRetired))
    }
}

fn require_blob_lifetime_visible_write(
    write: &redb::WriteTransaction,
    lifetime: BlobLifetime,
) -> Result<(), StoreError> {
    if blob_lifetime_is_visible_write(write, lifetime)? {
        Ok(())
    } else {
        Err(blob_error(BlobStoreError::ExpiredOrRetired))
    }
}

/// Synchronizes both persisted finite-lifetime scanners before an ordinary
/// mutation observes or changes Blob authority.  The transaction either
/// establishes the new fenced pressure pass and invalidates both stale TTL
/// cycles together, or rolls all of that state back with the caller.
fn synchronize_blob_policy_generation_write(
    write: &redb::WriteTransaction,
) -> Result<Option<custody::LowerBoundContinuity>, StoreError> {
    let continuity = custody::lower_bound_continuity_write(write)?;
    if let Some(continuity) = continuity {
        lifecycle::synchronize_ttl_expiry_cycles_write(
            write,
            continuity.generation,
            continuity.sample,
        )?;
    }
    pressure::synchronize_reanchor_state_write(write)?;
    Ok(continuity)
}

#[derive(Clone, Copy)]
struct PolicyGenerationSyncPlan {
    continuity: Option<custody::LowerBoundContinuity>,
    reset_ttl_cycles: bool,
    reset_pressure_reanchor: bool,
}

impl PolicyGenerationSyncPlan {
    const fn needed(self) -> bool {
        self.reset_ttl_cycles || self.reset_pressure_reanchor
    }
}

fn plan_blob_policy_generation_sync_write(
    write: &redb::WriteTransaction,
) -> Result<PolicyGenerationSyncPlan, StoreError> {
    let continuity = custody::lower_bound_continuity_write(write)?;
    let reset_ttl_cycles = match continuity {
        Some(value) => {
            lifecycle::ttl_expiry_cycles_need_sync_write(write, value.generation, value.sample)?
        }
        None => false,
    };
    let reset_pressure_reanchor = pressure::reanchor_state_needs_sync_write(write)?;
    Ok(PolicyGenerationSyncPlan {
        continuity,
        reset_ttl_cycles,
        reset_pressure_reanchor,
    })
}

fn charge_blob_policy_generation_sync_write(
    write: &redb::WriteTransaction,
    plan: PolicyGenerationSyncPlan,
    charge: &mut MaintenanceCharge,
) -> Result<bool, StoreError> {
    if plan.reset_ttl_cycles && !lifecycle::charge_ttl_expiry_sync_state_write(write, charge)? {
        return Ok(false);
    }
    if plan.reset_pressure_reanchor && !pressure::charge_reanchor_sync_state_write(write, charge)? {
        return Ok(false);
    }
    Ok(true)
}

fn apply_blob_policy_generation_sync_write(
    write: &redb::WriteTransaction,
    plan: PolicyGenerationSyncPlan,
) -> Result<(), StoreError> {
    if plan.reset_ttl_cycles {
        let continuity = plan.continuity.ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob TTL generation sync lacks continuity",
            ))
        })?;
        lifecycle::synchronize_ttl_expiry_cycles_write(
            write,
            continuity.generation,
            continuity.sample,
        )?;
    }
    if plan.reset_pressure_reanchor {
        pressure::synchronize_reanchor_state_write(write)?;
    }
    Ok(())
}

/// Projects one pending root into the current continuity generation before a
/// progress mutation.  The source row, authenticated binding, TTL deadline,
/// and pressure root/index move atomically.
fn normalize_pending_blob_policy_write(
    write: &redb::WriteTransaction,
    source: BlobTransferId,
    mut pending: PendingBlobSourceRecord,
    limits: BlobLifecycleLimits,
) -> Result<PendingBlobSourceRecord, StoreError> {
    synchronize_blob_policy_generation_write(write)?;
    let old_lifetime = pending.metadata.lifetime;
    let projected = lifecycle::project_lifetime_for_policy_write(write, old_lifetime)?;
    if projected == old_lifetime {
        return Ok(pending);
    }
    lifecycle::replace_policy_ttl_deadline_write(
        write,
        source,
        lifecycle::TtlDeadlineKind::PendingSource,
        Some(old_lifetime),
        Some(projected),
        limits,
    )?;
    pending.metadata.lifetime = projected;
    pending.authenticated_source_binding =
        pending_blob_authenticated_source_binding(&pending.metadata, &pending.sealed)?;
    let replacement = encode_pending_blob_source(&pending)?;
    let previous_len = write
        .open_table(BLOB_PENDING_SOURCES)?
        .get(source.as_bytes().as_slice())?
        .map(|value| value.value().len())
        .ok_or_else(|| blob_error(BlobStoreError::PendingSourceMissing))?;
    if replacement.len() != previous_len {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "pending Blob generation projection changed fixed row accounting",
        )));
    }
    write
        .open_table(BLOB_PENDING_SOURCES)?
        .insert(source.as_bytes().as_slice(), replacement.as_slice())?;
    pressure::rekey_pending_source_lifetime_write(write, source, &pending)?;
    Ok(pending)
}

fn merge_blob_lifetime(
    stored: BlobLifetime,
    incoming: BlobLifetime,
    continuity: Option<custody::LowerBoundContinuity>,
    sample: Option<aster_mesh::CustodySample>,
) -> Result<BlobLifetime, StoreError> {
    match (stored, incoming) {
        (BlobLifetime::Durable, BlobLifetime::Durable) => Ok(BlobLifetime::Durable),
        (
            BlobLifetime::Finite {
                ttl_ms: stored_ttl,
                age: stored_age,
                provenance: stored_provenance,
            },
            BlobLifetime::Finite {
                ttl_ms: incoming_ttl,
                age: incoming_age,
                provenance: incoming_provenance,
            },
        ) if stored_ttl == incoming_ttl && stored_provenance == incoming_provenance => {
            let _ = evaluate_blob_lifetime(stored, continuity, sample)?;
            let projected = custody::project_lower_bound_age(stored_age, continuity, sample);
            let cumulative_age_ms = projected
                .cumulative_age_ms
                .max(incoming_age.cumulative_age_ms);
            let merged = BlobLifetime::Finite {
                ttl_ms: stored_ttl,
                age: custody::LowerBoundAgeCheckpoint {
                    cumulative_age_ms,
                    checkpoint: projected.checkpoint.or(incoming_age.checkpoint),
                    continuity_generation: if projected.checkpoint.is_some() {
                        projected.continuity_generation
                    } else {
                        incoming_age.continuity_generation
                    },
                    continuity_lost: stored_age.continuity_lost
                        || incoming_age.continuity_lost
                        || projected.continuity_lost,
                },
                provenance: stored_provenance,
            };
            validate_blob_lifetime(merged)?;
            Ok(merged)
        }
        _ => Err(blob_error(BlobStoreError::PendingSourceConflict)),
    }
}

