#[allow(clippy::too_many_arguments)]
fn bounded_composite_maintenance_page_with_source_limit_and_charge(
    write: &redb::WriteTransaction,
    primary: TableDefinition<&'static [u8], &'static [u8]>,
    primary_kind: MaintenanceRowKind,
    secondary: TableDefinition<&'static [u8], &'static [u8]>,
    secondary_kind: MaintenanceRowKind,
    after: Option<&[u8]>,
    source_row_limit: u64,
    mut charge: MaintenanceCharge,
) -> Result<MaintenancePage, StoreError> {
    let total_rows = write
        .open_table(primary)?
        .len()?
        .checked_add(write.open_table(secondary)?.len()?)
        .ok_or(StoreError::ItemCountAccountingOverflow)?;
    let selected_rows = total_rows.min(source_row_limit);
    let mut rows = Vec::new();
    let mut append = |definition, kind, tag, lower, upper| {
        append_maintenance_range(
            write,
            definition,
            kind,
            Some(tag),
            lower,
            upper,
            selected_rows,
            &mut rows,
            &mut charge,
        )
    };
    match after {
        None => {
            if append(
                primary,
                primary_kind,
                MAINTENANCE_PRIMARY_SOURCE_TAG,
                std::ops::Bound::Unbounded,
                std::ops::Bound::Unbounded,
            )? {
                append(
                    secondary,
                    secondary_kind,
                    MAINTENANCE_SECONDARY_SOURCE_TAG,
                    std::ops::Bound::Unbounded,
                    std::ops::Bound::Unbounded,
                )?;
            }
        }
        Some(after) => {
            let (&tag, key) = after.split_first().ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob maintenance composite cursor is empty",
                ))
            })?;
            match tag {
                MAINTENANCE_PRIMARY_SOURCE_TAG => {
                    if append(
                        primary,
                        primary_kind,
                        MAINTENANCE_PRIMARY_SOURCE_TAG,
                        std::ops::Bound::Excluded(key),
                        std::ops::Bound::Unbounded,
                    )? && append(
                        secondary,
                        secondary_kind,
                        MAINTENANCE_SECONDARY_SOURCE_TAG,
                        std::ops::Bound::Unbounded,
                        std::ops::Bound::Unbounded,
                    )? {
                        append(
                            primary,
                            primary_kind,
                            MAINTENANCE_PRIMARY_SOURCE_TAG,
                            std::ops::Bound::Unbounded,
                            std::ops::Bound::Included(key),
                        )?;
                    }
                }
                MAINTENANCE_SECONDARY_SOURCE_TAG => {
                    if append(
                        secondary,
                        secondary_kind,
                        MAINTENANCE_SECONDARY_SOURCE_TAG,
                        std::ops::Bound::Excluded(key),
                        std::ops::Bound::Unbounded,
                    )? && append(
                        primary,
                        primary_kind,
                        MAINTENANCE_PRIMARY_SOURCE_TAG,
                        std::ops::Bound::Unbounded,
                        std::ops::Bound::Unbounded,
                    )? {
                        append(
                            secondary,
                            secondary_kind,
                            MAINTENANCE_SECONDARY_SOURCE_TAG,
                            std::ops::Bound::Unbounded,
                            std::ops::Bound::Included(key),
                        )?;
                    }
                }
                _ => {
                    return Err(blob_error(BlobStoreError::SchemaInvariant(
                        "Blob maintenance composite cursor has an unknown source tag",
                    )));
                }
            }
        }
    }
    let examined_rows =
        u64::try_from(rows.len()).map_err(|_| StoreError::ItemCountAccountingOverflow)?;
    Ok(MaintenancePage {
        complete: examined_rows == total_rows,
        rows,
        rows_examined: charge.rows,
        bytes: charge.bytes,
        identities: charge.identities,
    })
}

fn validate_maintenance_reference(
    evidence: &MaintenanceReferenceEvidence,
    variant: BlobVariantId,
    owner: lifecycle::VariantReferenceOwner,
    transfer: BlobTransferId,
) -> Result<(), StoreError> {
    if evidence.key != variant_reference_key(variant, owner, transfer) || !evidence.value.is_empty()
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob variant reference is not canonical",
        )));
    }
    Ok(())
}

fn validate_maintenance_publication(
    key: &[u8],
    value: &[u8],
    evidence: &MaintenancePublicationEvidence,
    owner_binding: [u8; 32],
) -> Result<(), StoreError> {
    let transfer = parse_blob_transfer_id("Blob publication table", key)?;
    let publication = decode_blob_metadata(value)?;
    if publication.transfer_id != transfer {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob publication key differs from its exact metadata",
        )));
    }
    let route = publication.header.blob_route.ok_or_else(|| {
        blob_error(BlobStoreError::SchemaInvariant(
            "accepted Blob publication is missing its route commitment",
        ))
    })?;
    let physical_lineage = publication.physical_lineage.ok_or_else(|| {
        blob_error(BlobStoreError::SchemaInvariant(
            "accepted Blob publication is missing authenticated physical lineage",
        ))
    })?;
    match &evidence.physical {
        MaintenancePhysicalEvidence::LegacyImport(import) => {
            depot::audit_publication_import_evidence(
                import,
                publication.variant_id,
                publication.blob_id,
                publication.header.key_epoch,
                publication.manifest_digest,
                route.chunk_count(),
                publication.physical_lineage,
            )?;
        }
        MaintenancePhysicalEvidence::Profile5Pack(pack) => {
            pack_lifecycle::audit_publication_evidence(
                pack,
                publication.variant_id,
                publication.blob_id,
                publication.header.key_epoch,
                publication.manifest_digest,
                route.chunk_count(),
                publication.physical_lineage,
                owner_binding,
            )?;
        }
    }
    lifecycle::validate_maintenance_lineage_evidence(
        physical_lineage,
        owner_binding,
        &evidence.lineage,
    )?;
    validate_maintenance_reference(
        &evidence.reference,
        publication.variant_id,
        lifecycle::VariantReferenceOwner::Publication,
        transfer,
    )?;
    if evidence.marker == 0
        || evidence.conflicting_pending.is_some()
        || BlobTransferId::new(Sha256::digest(&evidence.source).into()) != transfer
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "live Blob publication has contradictory durable roots",
        )));
    }
    let indexed = parse_blob_transfer_id("Blob semantic item table", &evidence.semantic_index)?;
    if indexed != transfer {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "live Blob publication is missing its semantic index",
        )));
    }
    let content = parse_blob_transfer_id("Blob content index", &evidence.content_index)?;
    if content != transfer {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "live Blob publication is missing its content index",
        )));
    }
    let dot = publication.header.stamp.dot;
    let source_len = u64::try_from(evidence.source.len())
        .map_err(|_| StoreError::PayloadByteAccountingOverflow)?;
    lifecycle::validate_maintenance_replay_evidence(
        lifecycle::ReplayFence::new(
            dot.publisher,
            dot.counter,
            publication.semantic_id,
            transfer,
            source_len,
            Sha256::digest(&evidence.source).into(),
        ),
        &evidence.replay,
    )?;
    let accepted = parse_digest32("accepted dot table", &evidence.accepted_dot)?;
    if accepted != *publication.semantic_id.as_bytes() {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob publication accepted-dot authority names another semantic item",
        )));
    }
    if evidence.publisher_high_water < dot.counter {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob publication publisher high-water is missing or behind",
        )));
    }
    if evidence.causal_frontier < dot.counter {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob publication causal frontier is missing or behind",
        )));
    }
    Ok(())
}

fn validate_maintenance_pending_source(
    key: &[u8],
    value: &[u8],
    evidence: &MaintenancePendingEvidence,
    owner_binding: [u8; 32],
) -> Result<PendingBlobSourceRecord, StoreError> {
    let transfer = parse_blob_transfer_id("pending Blob source table", key)?;
    let pending = decode_pending_blob_source(value)?;
    if pending.metadata.transfer_id != transfer
        || pending.metadata.physical_lineage != Some(pending.physical_lineage)
        || evidence.conflicting_publication.is_some()
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "pending Blob source has contradictory durable roots",
        )));
    }
    let import = depot::maintenance_import_projection(
        pending.metadata.variant_id.as_bytes(),
        &evidence.import,
    )?;
    if import.variant_id != pending.metadata.variant_id
        || import.physical_lineage != pending.physical_lineage
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "pending Blob source conflicts with its depot import",
        )));
    }
    lifecycle::validate_maintenance_lineage_evidence(
        pending.physical_lineage,
        owner_binding,
        &evidence.lineage,
    )?;
    validate_maintenance_reference(
        &evidence.reference,
        pending.metadata.variant_id,
        lifecycle::VariantReferenceOwner::PendingSource,
        transfer,
    )?;
    Ok(pending)
}

fn validate_maintenance_carrier_prefix(
    key: &[u8],
    value: &[u8],
    evidence: &MaintenanceCarrierEvidence,
    owner_binding: [u8; 32],
) -> Result<(), StoreError> {
    let key: [u8; BLOB_CARRIER_PREFIX_KEY_BYTES] = key.try_into().map_err(|_| {
        blob_error(BlobStoreError::SchemaInvariant(
            "Blob carrier-prefix key has an invalid length",
        ))
    })?;
    let source = BlobTransferId::new(key[..32].try_into().expect("fixed source key"));
    let object = BlobCarrierObjectId::new(key[32..].try_into().expect("fixed ObjectID key"))
        .map_err(|_| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob carrier-prefix key has an invalid typed identity",
            ))
        })?;
    let prefix = decode_blob_carrier_prefix(value)?;
    if prefix.source != source {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob carrier-prefix key differs from its source",
        )));
    }
    let pending = validate_maintenance_pending_source(
        source.as_bytes().as_slice(),
        &evidence.pending,
        &evidence.pending_evidence,
        owner_binding,
    )?;
    if !pending
        .carriers
        .iter()
        .any(|carrier| carrier.object == object && carrier.total_len == prefix.total_len)
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob carrier prefix conflicts with its pending source",
        )));
    }
    Ok(())
}

fn validate_maintenance_operation(
    key: &[u8],
    value: &[u8],
    publication: &[u8],
) -> Result<(), StoreError> {
    validate_blob_operation_storage_key(key)?;
    let operation = decode_blob_operation_record(value)?;
    let publication = decode_blob_metadata(publication)?;
    if publication.transfer_id != operation.transfer_id {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob lifecycle operation points to contradictory publication metadata",
        )));
    }
    Ok(())
}

fn capture_any_maintenance_reference_read(
    read: &redb::ReadTransaction,
    variant: BlobVariantId,
    charge: &mut MaintenanceCharge,
) -> Result<Result<Option<MaintenanceReferenceEvidence>, ()>, StoreError> {
    if charge.rows >= charge.budget.rows || charge.bytes >= charge.budget.bytes {
        return Ok(Err(()));
    }
    let references = read.open_table(lifecycle::BLOB_VARIANT_REFERENCES)?;
    let start = variant.as_bytes().as_slice();
    let mut upper = start.to_vec();
    let upper = upper
        .iter_mut()
        .rposition(|byte| *byte != u8::MAX)
        .map(|index| {
            upper[index] += 1;
            upper.truncate(index + 1);
            upper
        });
    let bounds = match upper.as_deref() {
        Some(upper) => (
            std::ops::Bound::Included(start),
            std::ops::Bound::Excluded(upper),
        ),
        None => (std::ops::Bound::Included(start), std::ops::Bound::Unbounded),
    };
    let Some((key, value)) = references.range::<&[u8]>(bounds)?.next().transpose()? else {
        return Ok(Ok(None));
    };
    if !charge.charge(key.value(), value.value().len())? {
        return Ok(Err(()));
    }
    Ok(Ok(Some(MaintenanceReferenceEvidence {
        key: key.value().to_vec(),
        value: value.value().to_vec(),
    })))
}

#[derive(Clone, Copy)]
struct MaintenancePhysicalProjection {
    variant_id: BlobVariantId,
    physical_lineage: [u8; 32],
    finalized: bool,
}

fn maintenance_physical_projection(
    key: &[u8],
    value: &[u8],
) -> Result<MaintenancePhysicalProjection, StoreError> {
    if pack_lifecycle::is_pack_evidence(value) {
        let projection = pack_lifecycle::deletion_projection(key, value)?;
        Ok(MaintenancePhysicalProjection {
            variant_id: projection.variant_id,
            physical_lineage: projection.physical_lineage,
            finalized: true,
        })
    } else {
        let projection = depot::maintenance_import_projection(key, value)?;
        Ok(MaintenancePhysicalProjection {
            variant_id: projection.variant_id,
            physical_lineage: projection.physical_lineage,
            finalized: projection.finalized,
        })
    }
}

fn capture_import_maintenance_evidence_read(
    read: &redb::ReadTransaction,
    key: &[u8],
    value: &[u8],
    charge: &mut MaintenanceCharge,
) -> Result<Option<MaintenanceEvidence>, StoreError> {
    if pack_lifecycle::is_pack_evidence(value) && !pack_lifecycle::maintenance_eligible(key, value)?
    {
        // Keep the charged row and its position so bounded scans make progress
        // through valid ineligible states, even when a page contains only these.
        return Ok(Some(MaintenanceEvidence::IneligiblePhysical));
    }
    let import = maintenance_physical_projection(key, value)?;
    if let Some(reference) = upload::pending_pack_reference(
        &read.open_table(upload::BLOB_UPLOAD_PACK_REFERENCES)?,
        import.variant_id,
    )? {
        if !charge.charge(&reference, 0)? {
            return Ok(None);
        }
        return Ok(Some(MaintenanceEvidence::IneligiblePhysical));
    }
    let reference = match capture_any_maintenance_reference_read(read, import.variant_id, charge)? {
        Ok(reference) => reference,
        Err(()) => return Ok(None),
    };
    if charge.rows >= charge.budget.rows {
        return Ok(None);
    }
    let lineage = read.open_table(lifecycle::BLOB_LINEAGE_FENCES)?;
    let lineage = lineage
        .get(import.variant_id.as_bytes().as_slice())?
        .ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "retained Blob physical variant is missing its lineage fence",
            ))
        })?;
    if !charge.charge(import.variant_id.as_bytes(), lineage.value().len())? {
        return Ok(None);
    }
    Ok(Some(MaintenanceEvidence::Import(
        MaintenanceImportEvidence {
            lineage: lineage.value().to_vec(),
            reference,
        },
    )))
}

fn append_import_maintenance_range_read<'a>(
    read: &redb::ReadTransaction,
    lower: std::ops::Bound<&'a [u8]>,
    upper: std::ops::Bound<&'a [u8]>,
    total_rows: u64,
    rows: &mut Vec<MaintenancePageRow>,
    charge: &mut MaintenanceCharge,
) -> Result<bool, StoreError> {
    let imports = read.open_table(BLOB_IMPORTS)?;
    let packs = read.open_table(pack_lifecycle::BLOB_PROFILE5_PACKS)?;
    let mut import_range = imports.range::<&[u8]>((lower, upper))?;
    let mut pack_range = packs.range::<&[u8]>((lower, upper))?;
    let mut next_import = import_range
        .next()
        .transpose()?
        .map(|(key, value)| (key.value().to_vec(), value.value().to_vec()));
    let mut next_pack = pack_range
        .next()
        .transpose()?
        .map(|(key, value)| (key.value().to_vec(), value.value().to_vec()));
    loop {
        if charge.rows >= charge.budget.rows
            || u64::try_from(rows.len()).map_err(|_| StoreError::ItemCountAccountingOverflow)?
                >= total_rows
        {
            return Ok(false);
        }
        let take_import = match (&next_import, &next_pack) {
            (None, None) => return Ok(true),
            (Some(_), None) => true,
            (None, Some(_)) => false,
            (Some((import, _)), Some((pack, _))) => match import.cmp(pack) {
                std::cmp::Ordering::Less => true,
                std::cmp::Ordering::Greater => false,
                std::cmp::Ordering::Equal => {
                    return Err(blob_error(BlobStoreError::SchemaInvariant(
                        "Blob physical variant exists in both legacy and Profile-5 tables",
                    )));
                }
            },
        };
        let (key, value) = if take_import {
            let current = next_import.take().expect("selected legacy import");
            next_import = import_range
                .next()
                .transpose()?
                .map(|(key, value)| (key.value().to_vec(), value.value().to_vec()));
            current
        } else {
            let current = next_pack.take().expect("selected Profile-5 pack");
            next_pack = pack_range
                .next()
                .transpose()?
                .map(|(key, value)| (key.value().to_vec(), value.value().to_vec()));
            current
        };
        if !charge.charge(&key, value.len())? {
            return Ok(false);
        }
        let Some(evidence) = capture_import_maintenance_evidence_read(read, &key, &value, charge)?
        else {
            return Ok(false);
        };
        rows.push(MaintenancePageRow {
            position: key.clone(),
            key,
            value,
            evidence,
        });
    }
}

fn bounded_import_maintenance_page_read(
    read: &redb::ReadTransaction,
    after: Option<&[u8]>,
    budget: BlobMaintenanceBudget,
) -> Result<MaintenancePage, StoreError> {
    let total_rows = read
        .open_table(BLOB_IMPORTS)?
        .len()?
        .checked_add(
            read.open_table(pack_lifecycle::BLOB_PROFILE5_PACKS)?
                .len()?,
        )
        .ok_or(StoreError::ItemCountAccountingOverflow)?;
    let mut rows = Vec::new();
    let mut charge = MaintenanceCharge::new(budget, 0, 0);
    let first_complete = append_import_maintenance_range_read(
        read,
        after.map_or(std::ops::Bound::Unbounded, std::ops::Bound::Excluded),
        std::ops::Bound::Unbounded,
        total_rows,
        &mut rows,
        &mut charge,
    )?;
    if first_complete
        && u64::try_from(rows.len()).map_err(|_| StoreError::ItemCountAccountingOverflow)?
            < total_rows
        && let Some(after) = after
    {
        append_import_maintenance_range_read(
            read,
            std::ops::Bound::Unbounded,
            std::ops::Bound::Included(after),
            total_rows,
            &mut rows,
            &mut charge,
        )?;
    }
    let examined_rows =
        u64::try_from(rows.len()).map_err(|_| StoreError::ItemCountAccountingOverflow)?;
    Ok(MaintenancePage {
        complete: examined_rows == total_rows,
        rows,
        rows_examined: charge.rows,
        bytes: charge.bytes,
        identities: charge.identities,
    })
}

fn bounded_capacity_import_page_read(
    read: &redb::ReadTransaction,
    after: Option<&[u8]>,
    budget: BlobMaintenanceBudget,
) -> Result<MaintenancePage, StoreError> {
    let total_rows = read
        .open_table(BLOB_IMPORTS)?
        .len()?
        .checked_add(
            read.open_table(pack_lifecycle::BLOB_PROFILE5_PACKS)?
                .len()?,
        )
        .ok_or(StoreError::ItemCountAccountingOverflow)?;
    let mut rows = Vec::new();
    let mut charge = MaintenanceCharge::new(budget, 0, 0);
    let complete = append_import_maintenance_range_read(
        read,
        after.map_or(std::ops::Bound::Unbounded, std::ops::Bound::Excluded),
        std::ops::Bound::Unbounded,
        total_rows,
        &mut rows,
        &mut charge,
    )?;
    #[cfg(test)]
    TEST_BLOB_CAPACITY_ADMISSION_PAGES.with(|count| count.set(count.get().saturating_add(1)));
    Ok(MaintenancePage {
        rows,
        rows_examined: charge.rows,
        bytes: charge.bytes,
        identities: charge.identities,
        complete,
    })
}

fn validate_reference_root_read(
    read: &redb::ReadTransaction,
    evidence: &MaintenanceReferenceEvidence,
    variant: BlobVariantId,
) -> Result<(), StoreError> {
    let key: [u8; 65] = evidence.key.as_slice().try_into().map_err(|_| {
        blob_error(BlobStoreError::SchemaInvariant(
            "Blob variant reference is not canonical",
        ))
    })?;
    if key[..32] != variant.as_bytes()[..] || !evidence.value.is_empty() {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob variant reference is not canonical",
        )));
    }
    let owner = lifecycle::VariantReferenceOwner::decode(&key[32..33]).map_err(StoreError::Blob)?;
    let transfer = BlobTransferId::new(key[33..].try_into().expect("fixed transfer key"));
    match owner {
        lifecycle::VariantReferenceOwner::Publication => {
            let publication = read
                .open_table(BLOB_PUBLICATIONS)?
                .get(transfer.as_bytes().as_slice())?
                .map(|value| decode_blob_metadata(value.value()))
                .transpose()?
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob publication reference has no exact publication",
                    ))
                })?;
            if publication.transfer_id != transfer || publication.variant_id != variant {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "Blob publication reference conflicts with its exact publication",
                )));
            }
        }
        lifecycle::VariantReferenceOwner::PendingSource => {
            let pending = read
                .open_table(BLOB_PENDING_SOURCES)?
                .get(transfer.as_bytes().as_slice())?
                .map(|value| decode_pending_blob_source(value.value()))
                .transpose()?
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob pending reference has no exact pending source",
                    ))
                })?;
            if pending.metadata.transfer_id != transfer || pending.metadata.variant_id != variant {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "Blob pending reference conflicts with its exact pending source",
                )));
            }
        }
    }
    Ok(())
}

fn variant_has_valid_reference_write(
    write: &redb::WriteTransaction,
    variant: BlobVariantId,
) -> Result<bool, StoreError> {
    if upload::pack_has_pending_upload_write(write, variant)? {
        return Ok(true);
    }
    let start = variant.as_bytes().as_slice();
    let evidence = {
        let references = write.open_table(lifecycle::BLOB_VARIANT_REFERENCES)?;
        let Some((key, value)) = references.range(start..)?.next().transpose()? else {
            return Ok(false);
        };
        if !key.value().starts_with(start) {
            return Ok(false);
        }
        MaintenanceReferenceEvidence {
            key: key.value().to_vec(),
            value: value.value().to_vec(),
        }
    };
    let key: [u8; 65] = evidence.key.as_slice().try_into().map_err(|_| {
        blob_error(BlobStoreError::SchemaInvariant(
            "Blob variant reference is not canonical",
        ))
    })?;
    if !evidence.value.is_empty() {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob variant reference is not canonical",
        )));
    }
    let owner = lifecycle::VariantReferenceOwner::decode(&key[32..33]).map_err(StoreError::Blob)?;
    let transfer = BlobTransferId::new(key[33..].try_into().expect("fixed transfer key"));
    match owner {
        lifecycle::VariantReferenceOwner::Publication => {
            let publication = write
                .open_table(BLOB_PUBLICATIONS)?
                .get(transfer.as_bytes().as_slice())?
                .map(|value| decode_blob_metadata(value.value()))
                .transpose()?
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob publication reference has no exact publication",
                    ))
                })?;
            if publication.transfer_id != transfer || publication.variant_id != variant {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "Blob publication reference conflicts with its exact publication",
                )));
            }
        }
        lifecycle::VariantReferenceOwner::PendingSource => {
            let pending = write
                .open_table(BLOB_PENDING_SOURCES)?
                .get(transfer.as_bytes().as_slice())?
                .map(|value| decode_pending_blob_source(value.value()))
                .transpose()?
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob pending reference has no exact pending source",
                    ))
                })?;
            if pending.metadata.transfer_id != transfer || pending.metadata.variant_id != variant {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "Blob pending reference conflicts with its exact pending source",
                )));
            }
        }
    }
    Ok(true)
}

#[derive(Debug)]
struct BlobManifestAdmissionCandidate {
    position: Vec<u8>,
    variant: BlobVariantId,
    import: Vec<u8>,
    lineage: Vec<u8>,
    finalized: bool,
}

fn manifest_admission_progress(
    cursor: &lifecycle::BlobMaintenanceCursor,
    page: &MaintenancePage,
    candidate_index: usize,
    variant: BlobVariantId,
    awaiting_later_handler: bool,
) -> BlobMaintenanceProgress {
    let selected = match cursor.class {
        BlobMaintenanceClass::UnreferencedLocalImportStaging => {
            BlobMaintenanceCandidate::UnreferencedLocalImport {
                staging_variant: variant,
            }
        }
        BlobMaintenanceClass::UnreferencedCompletedVariants => {
            BlobMaintenanceCandidate::UnreferencedCompletedVariant { variant }
        }
        _ => unreachable!("manifest admission only runs for import classes"),
    };
    BlobMaintenanceProgress {
        class: cursor.class,
        rows_examined: page.rows_examined,
        files_examined: 0,
        bytes_examined: page.bytes,
        candidates: vec![selected],
        class_has_more_work: awaiting_later_handler
            || !page.complete
            || candidate_index + 1 < page.rows.len(),
        awaiting_later_handler,
    }
}

impl Store {
    fn admit_one_capacity_manifest(
        &self,
        after: Option<&[u8]>,
        rows_budget: u64,
        bytes_budget: u64,
        custody_sample: Option<aster_mesh::CustodySample>,
    ) -> Result<BlobCapacityAdmissionStep, StoreError> {
        let page_rows = rows_budget.min(BLOB_CAPACITY_ADMISSION_PAGE_ROWS);
        let page_bytes = bytes_budget.min(BLOB_CAPACITY_ADMISSION_PAGE_BYTES);
        let read = self.database.begin_read()?;
        let page = bounded_capacity_import_page_read(
            &read,
            after,
            BlobMaintenanceBudget::new(page_rows, 1, page_bytes)?,
        )?;
        let mut candidates = Vec::new();
        for row in &page.rows {
            if matches!(row.evidence, MaintenanceEvidence::IneligiblePhysical) {
                continue;
            }
            let MaintenanceEvidence::Import(evidence) = &row.evidence else {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "Blob capacity import row has wrong evidence",
                )));
            };
            let projection = maintenance_physical_projection(&row.key, &row.value)?;
            lifecycle::validate_maintenance_lineage_evidence(
                projection.physical_lineage,
                self.blob_depot_owner_binding,
                &evidence.lineage,
            )?;
            let manifested =
                deletion::variant_has_deletion_manifest_read(&read, projection.variant_id)?;
            if let Some(reference) = evidence.reference.as_ref() {
                validate_reference_root_read(&read, reference, projection.variant_id)?;
                if manifested {
                    return Err(blob_error(BlobStoreError::SchemaInvariant(
                        "Blob deletion manifest has a live variant reference",
                    )));
                }
                continue;
            }
            if !manifested {
                candidates.push((
                    row.position.clone(),
                    projection.variant_id,
                    row.value.clone(),
                    evidence.lineage.clone(),
                ));
            }
        }
        drop(read);

        for (candidate_position, variant, expected_import, expected_lineage) in candidates {
            let _depot_guard = match self.blob_depot_lock.try_write() {
                Ok(guard) => guard,
                Err(std::sync::TryLockError::WouldBlock) => {
                    return Ok(BlobCapacityAdmissionStep::Blocked {
                        rows_examined: page.rows_examined,
                        bytes_examined: page.bytes,
                    });
                }
                Err(std::sync::TryLockError::Poisoned(_)) => {
                    return Err(blob_error(BlobStoreError::DepotIntegrity(
                        "depot lock is poisoned",
                    )));
                }
            };
            let target = lease::BlobLeaseTarget::Variant(variant);
            let snapshot = self
                .blob_lease_registry
                .snapshot(self.blob_depot_owner_binding, target)
                .map_err(lease::store_error)?;
            let write = self.database.begin_write()?;
            enforce_live_write(&write)?;
            if variant_has_valid_reference_write(&write, variant)?
                || deletion::variant_has_deletion_manifest_write(&write, variant)?
            {
                continue;
            }
            let admission = match self.blob_lease_registry.try_mark_delete_pending(snapshot) {
                Ok(admission) => admission,
                Err(
                    lease::BlobLeaseAcquireError::ActiveLeases
                    | lease::BlobLeaseAcquireError::GenerationChanged
                    | lease::BlobLeaseAcquireError::DeletePending,
                ) => continue,
                Err(error) => return Err(lease::store_error(error)),
            };
            if !deletion::admit_variant_write(
                &write,
                variant,
                &expected_import,
                &expected_lineage,
                self.blob_depot_owner_binding,
                custody_sample,
            )? {
                continue;
            }
            write.commit()?;
            admission.durable_committed().map_err(lease::store_error)?;
            return Ok(BlobCapacityAdmissionStep::Admitted {
                rows_examined: page.rows_examined,
                bytes_examined: page.bytes,
                next_position: candidate_position,
            });
        }
        if page.complete {
            return Ok(BlobCapacityAdmissionStep::Exhausted {
                rows_examined: page.rows_examined,
                bytes_examined: page.bytes,
            });
        }
        let Some(last) = page.rows.last() else {
            return Ok(BlobCapacityAdmissionStep::Blocked {
                rows_examined: page.rows_examined,
                bytes_examined: page.bytes,
            });
        };
        Ok(BlobCapacityAdmissionStep::Continue {
            rows_examined: page.rows_examined,
            bytes_examined: page.bytes,
            next_position: last.position.clone(),
        })
    }

    fn run_one_capacity_physical_unit(
        &self,
        selection_scope: BlobCapacityPhysicalSelection,
        position: Option<&[u8]>,
        rows_budget: u64,
        bytes_budget: u64,
    ) -> Result<BlobCapacityPhysicalStep, StoreError> {
        let read = self.database.begin_read()?;
        let selection = match selection_scope {
            BlobCapacityPhysicalSelection::Global => {
                deletion::select_physical_work_read(&read, position, rows_budget, bytes_budget)?
            }
            BlobCapacityPhysicalSelection::Exact(variant) => {
                deletion::select_exact_physical_work_read(
                    &read,
                    variant,
                    position,
                    rows_budget,
                    bytes_budget,
                )?
            }
        };
        drop(read);
        let work = match selection {
            deletion::BlobDeletionSelection::Work(work) => *work,
            deletion::BlobDeletionSelection::Continue {
                position,
                rows_examined,
                bytes_examined,
            } => {
                if matches!(selection_scope, BlobCapacityPhysicalSelection::Global) {
                    self.require_live()?;
                    let write = self.database.begin_write()?;
                    enforce_live_write(&write)?;
                    deletion::advance_blob_deletion_maintenance_turn(&write)?;
                    write.commit()?;
                }
                return Ok(BlobCapacityPhysicalStep::Continue {
                    rows_examined,
                    bytes_examined,
                    next_position: position,
                });
            }
            deletion::BlobDeletionSelection::Complete {
                rows_examined,
                bytes_examined,
            } => {
                if matches!(selection_scope, BlobCapacityPhysicalSelection::Global) {
                    self.require_live()?;
                    let write = self.database.begin_write()?;
                    enforce_live_write(&write)?;
                    deletion::advance_blob_deletion_maintenance_turn(&write)?;
                    write.commit()?;
                }
                return Ok(BlobCapacityPhysicalStep::Exhausted {
                    rows_examined,
                    bytes_examined,
                });
            }
        };
        let _depot_guard = match self.blob_depot_lock.try_write() {
            Ok(guard) => guard,
            Err(std::sync::TryLockError::WouldBlock) => {
                return Ok(BlobCapacityPhysicalStep::Blocked {
                    rows_examined: work.rows_examined,
                    bytes_examined: work.bytes_examined,
                });
            }
            Err(std::sync::TryLockError::Poisoned(_)) => {
                return Err(blob_error(BlobStoreError::DepotIntegrity(
                    "depot lock is poisoned",
                )));
            }
        };
        self.require_live()?;
        let write = self.database.begin_write()?;
        enforce_live_write(&write)?;
        deletion::revalidate_physical_work_write(&write, &work)?;
        let turn = deletion::advance_blob_deletion_maintenance_turn(&write)?;
        write.commit()?;
        let filesystem = match &work.kind {
            deletion::BlobDeletionWorkKind::Chunk(chunk)
            | deletion::BlobDeletionWorkKind::ReconcileUnmarkedChunk(chunk) => {
                depot::delete_manifest_chunk(
                    &self.path,
                    self.backing_identity,
                    self.blob_depot_owner_token,
                    &work.manifest,
                    chunk,
                )
                .map(|bytes| (1u64, bytes))
            }
            deletion::BlobDeletionWorkKind::AdvanceDirectoryPhase => Ok((0, 0)),
            deletion::BlobDeletionWorkKind::RemoveDirectoryAndFinalize => {
                depot::delete_manifest_variant_directory(
                    &self.path,
                    self.backing_identity,
                    self.blob_depot_owner_token,
                    &work.manifest,
                )
                .map(|()| (1, 0))
            }
        };
        let (files, physical_bytes) = match filesystem {
            Ok(progress) => progress,
            Err(depot::ManifestDeletionError {
                retry: Some(category),
                files_examined,
                bytes_examined,
                ..
            }) => {
                let write = self.database.begin_write()?;
                enforce_live_write(&write)?;
                deletion::record_physical_failure_write(&write, &work, turn, category)?;
                write.commit()?;
                return Ok(BlobCapacityPhysicalStep::Unit(
                    BlobCapacityPhysicalUnitProgress {
                        rows_examined: work.rows_examined,
                        files_examined,
                        bytes_examined: work
                            .bytes_examined
                            .checked_add(bytes_examined)
                            .ok_or(StoreError::PayloadByteAccountingOverflow)?,
                        finalized: false,
                        failed: true,
                        next_position: Some(work.position.clone()),
                    },
                ));
            }
            Err(error) => return Err(*error.error),
        };
        let finalized = matches!(
            work.kind,
            deletion::BlobDeletionWorkKind::RemoveDirectoryAndFinalize
        );
        let next_position = match &work.kind {
            deletion::BlobDeletionWorkKind::AdvanceDirectoryPhase => None,
            _ => Some(work.position.clone()),
        };
        let write = self.database.begin_write()?;
        enforce_live_write(&write)?;
        match work.kind {
            deletion::BlobDeletionWorkKind::Chunk(_) => {
                deletion::mark_chunk_deleted_write(&write, &work)?
            }
            deletion::BlobDeletionWorkKind::ReconcileUnmarkedChunk(_) => {
                deletion::mark_unmarked_reconciled_write(&write, &work)?
            }
            deletion::BlobDeletionWorkKind::AdvanceDirectoryPhase => {
                deletion::advance_directory_phase_write(&write, &work)?
            }
            deletion::BlobDeletionWorkKind::RemoveDirectoryAndFinalize => {
                deletion::finalize_manifest_write(&write, &work)?;
                deletion::manifest_finalization_mutation_boundary()?;
            }
        }
        write.commit()?;
        Ok(BlobCapacityPhysicalStep::Unit(
            BlobCapacityPhysicalUnitProgress {
                rows_examined: work.rows_examined,
                files_examined: files,
                bytes_examined: work
                    .bytes_examined
                    .checked_add(physical_bytes)
                    .ok_or(StoreError::PayloadByteAccountingOverflow)?,
                finalized,
                failed: false,
                next_position,
            },
        ))
    }

    /// Selects and atomically retires lower-priority work only from the exact
    /// rejected capacity partition. Routine maintenance cursors are untouched.
    pub(crate) fn run_blob_pressure_recovery(
        &self,
        demand: pressure::BlobCapacityRecoveryDemand,
        budget: pressure::BlobPressureRecoveryBudget,
        custody_sample: Option<aster_mesh::CustodySample>,
    ) -> Result<pressure::BlobCapacityRecoveryResult, StoreError> {
        self.run_blob_pressure_recovery_with_eligibility(
            demand,
            budget,
            custody_sample,
            BlobContactEligibility::AllVisible,
        )
    }

    fn run_blob_pressure_recovery_with_eligibility(
        &self,
        demand: pressure::BlobCapacityRecoveryDemand,
        budget: pressure::BlobPressureRecoveryBudget,
        custody_sample: Option<aster_mesh::CustodySample>,
        eligibility: BlobContactEligibility,
    ) -> Result<pressure::BlobCapacityRecoveryResult, StoreError> {
        self.require_live()?;
        // A durable-only contact must not checkpoint global finite age before
        // it knows whether the selected pressure candidate is contact eligible.
        // Durable eviction does not need a custody sample, so suppress it for
        // the complete contact recovery transaction.
        let custody_sample = match eligibility {
            BlobContactEligibility::AllVisible | BlobContactEligibility::CustodyV1 => {
                custody_sample
            }
            BlobContactEligibility::DurableOnly => None,
        };
        let _depot_guard = self
            .blob_depot_lock
            .write()
            .map_err(|_| blob_error(BlobStoreError::DepotIntegrity("depot lock is poisoned")))?;
        self.require_live()?;

        if let Some(sample) = custody_sample {
            let write = self.database.begin_write()?;
            enforce_live_write(&write)?;
            custody::observe_continuity_write(&write, sample)?;
            let generation_sync = plan_blob_policy_generation_sync_write(&write)?;
            let policy_unit = generation_sync.needed();
            let maintenance_budget =
                lifecycle::BlobMaintenanceBudget::new(budget.rows, 1, budget.bytes)?;
            let mut charge = MaintenanceCharge::new(maintenance_budget, 0, 0);
            if policy_unit
                && !charge_blob_policy_generation_sync_write(&write, generation_sync, &mut charge)?
            {
                return Ok(pressure::BlobCapacityRecoveryResult::empty(
                    charge.rows,
                    charge.bytes,
                ));
            }
            if policy_unit {
                apply_blob_policy_generation_sync_write(&write, generation_sync)?;
            }
            let pressure_ready = pressure::pressure_ready_write(&write)?;
            write.commit()?;
            if policy_unit || !pressure_ready {
                return Ok(pressure::BlobCapacityRecoveryResult::empty(
                    charge.rows,
                    charge.bytes,
                ));
            }
        }

        let read = self.database.begin_read()?;
        let selection = match eligibility {
            BlobContactEligibility::AllVisible | BlobContactEligibility::CustodyV1 => {
                pressure::select_pressure_candidate_read(&read, demand, budget)?
            }
            BlobContactEligibility::DurableOnly => {
                pressure::select_durable_pressure_candidate_read(&read, demand, budget)?
            }
        };
        drop(read);
        if !selection.proven() {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                selection.rows_examined(),
                selection.bytes_examined(),
            ));
        }
        let Some(candidate) = selection.candidate() else {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                selection.rows_examined(),
                selection.bytes_examined(),
            ));
        };
        let transfer = match candidate {
            pressure::PressureCandidate::Publication(transfer) => transfer,
            pressure::PressureCandidate::PendingSource(transfer) => {
                return self.run_blob_pending_pressure_recovery(
                    transfer,
                    demand,
                    budget,
                    selection,
                    custody_sample,
                    eligibility,
                );
            }
            pressure::PressureCandidate::Variant(variant) => {
                return self.run_blob_variant_pressure_recovery(
                    variant,
                    demand,
                    budget,
                    selection,
                    custody_sample,
                    eligibility,
                );
            }
        };

        let write = self.database.begin_write()?;
        enforce_live_write(&write)?;
        if !pressure::pressure_ready_write(&write)? {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                selection.rows_examined(),
                selection.bytes_examined(),
            ));
        }
        let maintenance_budget =
            lifecycle::BlobMaintenanceBudget::new(budget.rows, 1, budget.bytes)?;
        let mut charge = MaintenanceCharge::new(
            maintenance_budget,
            selection.rows_examined(),
            selection.bytes_examined(),
        );
        let publications = write.open_table(BLOB_PUBLICATIONS)?;
        let publication_record = publications
            .get(transfer.as_bytes().as_slice())?
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob pressure candidate publication disappeared",
                ))
            })?;
        let encoded_publication = publication_record.value().to_vec();
        drop(publication_record);
        drop(publications);
        let publication_record = encoded_publication;
        if lifecycle::publication_record_is_retired(&publication_record).map_err(blob_error)? {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob pressure candidate is already retired",
            )));
        }
        let publication = decode_blob_metadata(&publication_record)?;
        if !eligibility.admits(publication.lifetime) {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                charge.rows,
                charge.bytes,
            ));
        }
        if publication.transfer_id != transfer
            || publication.header.priority >= demand.incoming_priority()
        {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob pressure candidate changed after ordered selection",
            )));
        }
        let Some(pressure_snapshot) = plan_pressure_variant_snapshot_write(
            &write,
            publication.variant_id,
            budget.roots,
            &mut charge,
        )?
        else {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                charge.rows,
                charge.bytes,
            ));
        };
        let final_root = pressure_snapshot.references.len() == 1;
        if final_root
            && pressure_snapshot.references[0]
                != (lifecycle::VariantReferenceOwner::Publication, transfer)
        {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                charge.rows,
                charge.bytes,
            ));
        }
        let mut remaining_operations = budget.operations;
        let continuity = custody::lower_bound_continuity_write(&write)?;
        let retirement_sample = custody_sample.or(continuity.map(|value| value.sample));
        let retirement_reason = if matches!(
            evaluate_blob_lifetime(publication.lifetime, continuity, retirement_sample,)?,
            BlobLifetimeEvaluation::FiniteExpired { .. }
        ) {
            lifecycle::RetirementReason::Expired
        } else {
            lifecycle::RetirementReason::Evicted
        };
        let proven_expired = retirement_reason == lifecycle::RetirementReason::Expired;
        if final_root && !proven_expired && budget.deletion_manifests < 1 {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                charge.rows,
                charge.bytes,
            ));
        }
        let Some(retirement_plan) = plan_blob_publication_retirement_write(
            &write,
            self.blob_lifecycle_limits,
            transfer,
            retirement_reason,
            PublicationPressurePreflight::Snapshot(&pressure_snapshot),
            retirement_sample,
            &mut charge,
            &mut remaining_operations,
        )?
        else {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                charge.rows,
                charge.bytes,
            ));
        };
        let deletion_evidence = if final_root && !proven_expired {
            match deletion::bounded_variant_has_deletion_manifest_write(
                &write,
                publication.variant_id,
                &mut charge,
            )? {
                Some(false) => {}
                Some(true) => {
                    return Err(blob_error(BlobStoreError::SchemaInvariant(
                        "live Blob pressure root already has deletion authority",
                    )));
                }
                None => {
                    return Ok(pressure::BlobCapacityRecoveryResult::empty(
                        charge.rows,
                        charge.bytes,
                    ));
                }
            }
            let Some((import, lineage)) =
                pressure_deletion_evidence_write(&write, publication.variant_id, &mut charge)?
            else {
                return Ok(pressure::BlobCapacityRecoveryResult::empty(
                    charge.rows,
                    charge.bytes,
                ));
            };
            if !pressure_charge_depot_owner_binding(&mut charge)? {
                return Ok(pressure::BlobCapacityRecoveryResult::empty(
                    charge.rows,
                    charge.bytes,
                ));
            }
            let owner = depot::require_depot_owner_binding_write(
                &write,
                &self.path,
                self.backing_identity,
                self.blob_depot_owner_token,
            )?;
            let snapshot = self
                .blob_lease_registry
                .snapshot(
                    self.blob_depot_owner_binding,
                    lease::BlobLeaseTarget::Variant(publication.variant_id),
                )
                .map_err(lease::store_error)?;
            #[cfg(test)]
            if TEST_BLOB_MANIFEST_ADMISSION_GENERATION_CHURN.get() {
                drop(
                    self.blob_lease_registry
                        .acquire(
                            self.blob_depot_owner_binding,
                            lease::BlobLeaseTarget::Variant(publication.variant_id),
                            lease::BlobLeaseKind::InternalChunkWork,
                        )
                        .map_err(lease::store_error)?,
                );
            }
            Some((import, lineage, owner, snapshot))
        } else {
            None
        };
        let source_len = write
            .open_table(BLOB_BYTES)?
            .get(transfer.as_bytes().as_slice())?
            .map(|value| u64::try_from(value.value().len()))
            .transpose()
            .map_err(|_| StoreError::PayloadByteAccountingOverflow)?
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob pressure candidate is missing source bytes",
                ))
            })?;
        let before_items = write
            .open_table(METADATA)?
            .get(BLOB_ITEM_COUNT)?
            .ok_or(StoreError::MissingAccountingMetadata {
                field: BLOB_ITEM_COUNT,
            })?
            .value();
        let before_bytes = write
            .open_table(METADATA)?
            .get(BLOB_TOTAL_BYTES)?
            .ok_or(StoreError::MissingAccountingMetadata {
                field: BLOB_TOTAL_BYTES,
            })?
            .value();
        let deletion_evidence = if let Some((import, lineage, owner, snapshot)) = deletion_evidence
        {
            match self.blob_lease_registry.try_mark_delete_pending(snapshot) {
                Ok(admission) => Some((import, lineage, owner, admission)),
                Err(
                    lease::BlobLeaseAcquireError::ActiveLeases
                    | lease::BlobLeaseAcquireError::GenerationChanged
                    | lease::BlobLeaseAcquireError::DeletePending,
                ) => {
                    return Ok(pressure::BlobCapacityRecoveryResult::empty(
                        charge.rows,
                        charge.bytes,
                    ));
                }
                Err(error) => return Err(lease::store_error(error)),
            }
        } else {
            None
        };
        let deletion_plan = if let Some((import, lineage, owner, _)) = &deletion_evidence {
            let Some(plan) = deletion::plan_variant_admission_write(
                &write,
                publication.variant_id,
                import,
                lineage,
                *owner,
                custody_sample,
                Some(&mut charge),
            )?
            else {
                return Ok(pressure::BlobCapacityRecoveryResult::empty(
                    charge.rows,
                    charge.bytes,
                ));
            };
            Some(plan)
        } else {
            None
        };
        apply_blob_publication_retirement_plan_write(
            &write,
            self.blob_lifecycle_limits,
            retirement_plan,
            if final_root {
                PublicationPressureApply::RemoveRootOnly
            } else {
                PublicationPressureApply::RefreshVariant
            },
        )?;
        if final_root {
            pressure::remove_drained_variant_write(&write, publication.variant_id)?;
        }
        if let Some(plan) = deletion_plan {
            deletion::apply_variant_admission_plan_write(&write, plan)?;
        }
        let after_items = write
            .open_table(METADATA)?
            .get(BLOB_ITEM_COUNT)?
            .ok_or(StoreError::MissingAccountingMetadata {
                field: BLOB_ITEM_COUNT,
            })?
            .value();
        let after_bytes = write
            .open_table(METADATA)?
            .get(BLOB_TOTAL_BYTES)?
            .ok_or(StoreError::MissingAccountingMetadata {
                field: BLOB_TOTAL_BYTES,
            })?
            .value();
        if before_items.checked_sub(after_items) != Some(1)
            || before_bytes.checked_sub(after_bytes) != Some(source_len)
        {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob pressure recovery disagrees with committed accounting delta",
            )));
        }
        let recovered_units = match demand.partition() {
            pressure::BlobCapacityPartition::AggregateItems
            | pressure::BlobCapacityPartition::ContentPublications(_) => 1,
            pressure::BlobCapacityPartition::AggregateBytes => source_len,
            _ => {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "publication pressure selected for another partition",
                )));
            }
        };
        let deletion_admission = deletion_evidence.map(|(_, _, _, admission)| admission);
        write.commit()?;
        if let Some(admission) = deletion_admission {
            admission.durable_committed().map_err(lease::store_error)?;
        }
        Ok(pressure::BlobCapacityRecoveryResult::recovered(
            vec![transfer],
            recovered_units,
            demand.deficit(),
            charge.rows,
            charge.bytes,
        ))
    }

    /// Internal node bridge used after the caller has exhausted the ordinary
    /// cleanup turn for one typed Blob admission failure. This is deliberately
    /// doc-hidden: partitions, ranking state, and pressure budgets remain store
    /// implementation details.
    #[doc(hidden)]
    pub fn run_blob_pressure_recovery_after_cleanup(
        &self,
        error: &StoreError,
        incoming_priority: Priority,
        content: Option<(&Topic, &Scope, BlobId)>,
        incoming_depot_units: (u64, u64),
        budget: BlobMaintenanceBudget,
        custody_sample: Option<aster_mesh::CustodySample>,
    ) -> Result<Option<BlobCapacityRecoveryResult>, StoreError> {
        self.run_blob_pressure_recovery_after_cleanup_with_eligibility(
            error,
            incoming_priority,
            content,
            incoming_depot_units,
            budget,
            custody_sample,
            BlobContactEligibility::AllVisible,
        )
    }

    /// Contact-only pressure recovery. A finite candidate, or a variant with
    /// any finite root, causes clean deferral from the same transaction that
    /// would otherwise retire it.
    #[doc(hidden)]
    pub fn run_durable_blob_pressure_recovery_after_cleanup(
        &self,
        error: &StoreError,
        incoming_priority: Priority,
        content: Option<(&Topic, &Scope, BlobId)>,
        incoming_depot_units: (u64, u64),
        budget: BlobMaintenanceBudget,
        custody_sample: Option<aster_mesh::CustodySample>,
    ) -> Result<Option<BlobCapacityRecoveryResult>, StoreError> {
        self.run_blob_pressure_recovery_after_cleanup_with_eligibility(
            error,
            incoming_priority,
            content,
            incoming_depot_units,
            budget,
            custody_sample,
            BlobContactEligibility::DurableOnly,
        )
    }

    /// Custody-v1 contact pressure recovery. Durable and locally originated
    /// finite rows are eligible, while received finite rows must retain the
    /// exact semantic-v8 BlobRangesStreamV1 provenance.
    #[doc(hidden)]
    pub fn run_custody_blob_pressure_recovery_after_cleanup(
        &self,
        error: &StoreError,
        incoming_priority: Priority,
        content: Option<(&Topic, &Scope, BlobId)>,
        incoming_depot_units: (u64, u64),
        budget: BlobMaintenanceBudget,
        custody_sample: Option<aster_mesh::CustodySample>,
    ) -> Result<Option<BlobCapacityRecoveryResult>, StoreError> {
        self.run_blob_pressure_recovery_after_cleanup_with_eligibility(
            error,
            incoming_priority,
            content,
            incoming_depot_units,
            budget,
            custody_sample,
            BlobContactEligibility::CustodyV1,
        )
    }

    /// Finishes one already-selected depot pressure recovery after the caller
    /// has removed the exact evicted cache claims and released their leases.
    /// This bounded continuation processes only admitted physical deletion
    /// work and never selects or retires another pressure victim.
    #[doc(hidden)]
    pub fn continue_blob_pressure_recovery_after_cache_reconciliation(
        &self,
        mut recovery: BlobCapacityRecoveryResult,
    ) -> Result<BlobCapacityRecoveryResult, StoreError> {
        if recovery.deficit_met() || recovery.evicted_transfer_ids().is_empty() {
            return Ok(recovery);
        }
        let Some(receipt) = recovery.take_physical_recovery_receipt() else {
            return Ok(recovery);
        };
        let progress = self.continue_exact_blob_pressure_physical_recovery(receipt)?;
        let read = self.database.begin_read()?;
        let target_complete =
            !deletion::variant_has_deletion_manifest_read(&read, receipt.variant())?;
        let current = Self::blob_pressure_depot_partition_usage(
            depot::depot_admission_usage_read(&read)?,
            receipt.partition(),
        );
        let released = receipt.baseline().checked_sub(current).ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob pressure physical continuation increased depot usage",
            ))
        })?;
        // A missing authority is not itself proof that this continuation
        // released the measured capacity: an unrelated manifest can finalize
        // after the receipt baseline was captured. Credit the aggregate delta
        // only when this exact bounded continuation observed finalization.
        let verified_released = if progress.manifests_finalized == 1 && target_complete {
            released
        } else {
            recovery.recovered_units()
        };
        recovery.with_physical_recovery(verified_released, receipt.deficit(), progress)
    }

    #[allow(clippy::too_many_arguments)]
    fn run_blob_pressure_recovery_after_cleanup_with_eligibility(
        &self,
        error: &StoreError,
        incoming_priority: Priority,
        content: Option<(&Topic, &Scope, BlobId)>,
        incoming_depot_units: (u64, u64),
        budget: BlobMaintenanceBudget,
        custody_sample: Option<aster_mesh::CustodySample>,
        eligibility: BlobContactEligibility,
    ) -> Result<Option<BlobCapacityRecoveryResult>, StoreError> {
        let (incoming_depot_chunks, incoming_depot_variants) = incoming_depot_units;
        let mut context = pressure::BlobCapacityRecoveryContext::new(incoming_priority)
            .with_depot_units(incoming_depot_chunks, incoming_depot_variants);
        if let Some((topic, scope, blob_id)) = content {
            context = context.with_content(pressure::PressureContentIdentity::new(
                topic, scope, blob_id,
            )?);
        }
        let Some(demand) = pressure::capacity_recovery_demand(error, context)? else {
            return Ok(None);
        };
        let pressure_budget = pressure::BlobPressureRecoveryBudget::new(
            budget.rows(),
            budget.bytes(),
            budget.rows(),
            budget.rows().min(MAX_BLOB_OPERATIONS),
            budget.files(),
        )
        .map_err(blob_error)?;
        let recovery = match eligibility {
            BlobContactEligibility::AllVisible => {
                self.run_blob_pressure_recovery(demand, pressure_budget, custody_sample)?
            }
            BlobContactEligibility::DurableOnly | BlobContactEligibility::CustodyV1 => self
                .run_blob_pressure_recovery_with_eligibility(
                    demand,
                    pressure_budget,
                    custody_sample,
                    eligibility,
                )?,
        };
        if recovery.deficit_met()
            || recovery.evicted_transfer_ids().is_empty()
            || !matches!(
                demand.partition(),
                pressure::BlobCapacityPartition::DepotBytes
                    | pressure::BlobCapacityPartition::DepotChunks
                    | pressure::BlobCapacityPartition::DepotVariants
            )
        {
            return Ok(Some(recovery));
        }
        let baseline = match error {
            StoreError::Blob(BlobStoreError::DepotByteLimitExceeded { current, .. })
                if demand.partition() == pressure::BlobCapacityPartition::DepotBytes =>
            {
                *current
            }
            StoreError::Blob(BlobStoreError::DepotChunkLimitExceeded { current, .. })
                if demand.partition() == pressure::BlobCapacityPartition::DepotChunks =>
            {
                *current
            }
            StoreError::Blob(BlobStoreError::DepotVariantLimitExceeded { current, .. })
                if demand.partition() == pressure::BlobCapacityPartition::DepotVariants =>
            {
                *current
            }
            _ => {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "Blob depot pressure demand lost its typed capacity baseline",
                )));
            }
        };
        let read = self.database.begin_read()?;
        let current = Self::blob_pressure_depot_partition_usage(
            depot::depot_admission_usage_read(&read)?,
            demand.partition(),
        );
        let released = baseline.checked_sub(current).ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob pressure physical recovery increased depot usage",
            ))
        })?;
        let recovery = recovery.with_physical_recovery(
            released,
            demand.deficit(),
            BlobCapacityGcProgress::default(),
        )?;
        if recovery.deficit_met() {
            Ok(Some(recovery))
        } else {
            Ok(Some(recovery.bind_physical_recovery(baseline, budget)))
        }
    }

    fn blob_pressure_depot_partition_usage(
        usage: depot::DepotAdmissionUsage,
        partition: pressure::BlobCapacityPartition,
    ) -> u64 {
        match partition {
            pressure::BlobCapacityPartition::DepotBytes => usage.reserved_bytes,
            pressure::BlobCapacityPartition::DepotChunks => usage.chunks,
            pressure::BlobCapacityPartition::DepotVariants => usage.variants,
            _ => unreachable!("depot partitions were checked before usage projection"),
        }
    }

    fn continue_exact_blob_pressure_physical_recovery(
        &self,
        receipt: pressure::BlobPressurePhysicalRecoveryReceipt,
    ) -> Result<BlobCapacityGcProgress, StoreError> {
        let mut progress = BlobCapacityGcProgress::default();
        let manifest_position =
            lifecycle::deletion_manifest_cursor_position(receipt.variant()).to_vec();
        let mut position = Some(manifest_position.clone());
        while progress.rows_examined < receipt.remaining_rows()
            && progress.files_examined < receipt.remaining_files()
            && progress.bytes_examined < receipt.remaining_bytes()
        {
            let step = self.run_one_capacity_physical_unit(
                BlobCapacityPhysicalSelection::Exact(receipt.variant()),
                position.as_deref(),
                receipt.remaining_rows() - progress.rows_examined,
                receipt.remaining_bytes() - progress.bytes_examined,
            )?;
            match step {
                BlobCapacityPhysicalStep::Unit(unit) => {
                    progress.rows_examined = progress
                        .rows_examined
                        .checked_add(unit.rows_examined)
                        .ok_or(StoreError::ItemCountAccountingOverflow)?;
                    progress.files_examined = progress
                        .files_examined
                        .checked_add(unit.files_examined)
                        .ok_or(StoreError::ItemCountAccountingOverflow)?;
                    progress.bytes_examined = progress
                        .bytes_examined
                        .checked_add(unit.bytes_examined)
                        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
                    progress.manifests_finalized = progress
                        .manifests_finalized
                        .checked_add(u64::from(unit.finalized))
                        .ok_or(StoreError::ItemCountAccountingOverflow)?;
                    position = unit
                        .next_position
                        .or_else(|| Some(manifest_position.clone()));
                    if unit.finalized || unit.failed {
                        break;
                    }
                }
                BlobCapacityPhysicalStep::Continue {
                    rows_examined,
                    bytes_examined,
                    ..
                }
                | BlobCapacityPhysicalStep::Blocked {
                    rows_examined,
                    bytes_examined,
                }
                | BlobCapacityPhysicalStep::Exhausted {
                    rows_examined,
                    bytes_examined,
                } => {
                    progress.rows_examined = progress
                        .rows_examined
                        .checked_add(rows_examined)
                        .ok_or(StoreError::ItemCountAccountingOverflow)?;
                    progress.bytes_examined = progress
                        .bytes_examined
                        .checked_add(bytes_examined)
                        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
                    break;
                }
            }
        }
        Ok(progress)
    }

    fn run_blob_pending_pressure_recovery(
        &self,
        transfer: BlobTransferId,
        demand: pressure::BlobCapacityRecoveryDemand,
        budget: pressure::BlobPressureRecoveryBudget,
        selection: pressure::PressureSelection,
        custody_sample: Option<aster_mesh::CustodySample>,
        eligibility: BlobContactEligibility,
    ) -> Result<pressure::BlobCapacityRecoveryResult, StoreError> {
        let authority = self.require_bound_mission()?;
        let write = self.database.begin_write()?;
        enforce_live_write(&write)?;
        if !pressure::pressure_ready_write(&write)? {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                selection.rows_examined(),
                selection.bytes_examined(),
            ));
        }
        let maintenance_budget =
            lifecycle::BlobMaintenanceBudget::new(budget.rows, 1, budget.bytes)?;
        let mut charge = MaintenanceCharge::new(
            maintenance_budget,
            selection.rows_examined(),
            selection.bytes_examined(),
        );
        let Some(removal) = plan_pending_pressure_removal_write(
            &write,
            authority,
            transfer,
            demand,
            budget.roots,
            &mut charge,
        )?
        else {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                charge.rows,
                charge.bytes,
            ));
        };
        let pending = &removal.authority.pending;
        if !eligibility.admits(pending.metadata.lifetime) {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                charge.rows,
                charge.bytes,
            ));
        }
        let final_root = removal.pressure.references.len() == 1;
        if final_root
            && removal.pressure.references[0]
                != (lifecycle::VariantReferenceOwner::PendingSource, transfer)
        {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                charge.rows,
                charge.bytes,
            ));
        }
        let continuity = custody::lower_bound_continuity_write(&write)?;
        let retirement_sample = custody_sample.or(continuity.map(|value| value.sample));
        let proven_expired = matches!(
            evaluate_blob_lifetime(pending.metadata.lifetime, continuity, retirement_sample)?,
            BlobLifetimeEvaluation::FiniteExpired { .. }
        );
        if final_root && !proven_expired && budget.deletion_manifests < 1 {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                charge.rows,
                charge.bytes,
            ));
        }
        let deletion_evidence = if final_root && !proven_expired {
            match deletion::bounded_variant_has_deletion_manifest_write(
                &write,
                pending.metadata.variant_id,
                &mut charge,
            )? {
                Some(false) => {}
                Some(true) => {
                    return Err(blob_error(BlobStoreError::SchemaInvariant(
                        "live pending Blob pressure root already has deletion authority",
                    )));
                }
                None => {
                    return Ok(pressure::BlobCapacityRecoveryResult::empty(
                        charge.rows,
                        charge.bytes,
                    ));
                }
            }
            let Some((import, lineage)) =
                pressure_deletion_evidence_write(&write, pending.metadata.variant_id, &mut charge)?
            else {
                return Ok(pressure::BlobCapacityRecoveryResult::empty(
                    charge.rows,
                    charge.bytes,
                ));
            };
            if !pressure_charge_depot_owner_binding(&mut charge)? {
                return Ok(pressure::BlobCapacityRecoveryResult::empty(
                    charge.rows,
                    charge.bytes,
                ));
            }
            let owner = depot::require_depot_owner_binding_write(
                &write,
                &self.path,
                self.backing_identity,
                self.blob_depot_owner_token,
            )?;
            let snapshot = self
                .blob_lease_registry
                .snapshot(
                    self.blob_depot_owner_binding,
                    lease::BlobLeaseTarget::Variant(pending.metadata.variant_id),
                )
                .map_err(lease::store_error)?;
            #[cfg(test)]
            if TEST_BLOB_MANIFEST_ADMISSION_GENERATION_CHURN.get() {
                drop(
                    self.blob_lease_registry
                        .acquire(
                            self.blob_depot_owner_binding,
                            lease::BlobLeaseTarget::Variant(pending.metadata.variant_id),
                            lease::BlobLeaseKind::InternalChunkWork,
                        )
                        .map_err(lease::store_error)?,
                );
            }
            match self.blob_lease_registry.try_mark_delete_pending(snapshot) {
                Ok(admission) => Some((import, lineage, owner, admission)),
                Err(
                    lease::BlobLeaseAcquireError::ActiveLeases
                    | lease::BlobLeaseAcquireError::GenerationChanged
                    | lease::BlobLeaseAcquireError::DeletePending,
                ) => {
                    return Ok(pressure::BlobCapacityRecoveryResult::empty(
                        charge.rows,
                        charge.bytes,
                    ));
                }
                Err(error) => return Err(lease::store_error(error)),
            }
        } else {
            None
        };

        let deletion_plan = if let Some((import, lineage, owner, _)) = &deletion_evidence {
            let Some(plan) = deletion::plan_variant_admission_write(
                &write,
                pending.metadata.variant_id,
                import,
                lineage,
                *owner,
                custody_sample,
                Some(&mut charge),
            )?
            else {
                return Ok(pressure::BlobCapacityRecoveryResult::empty(
                    charge.rows,
                    charge.bytes,
                ));
            };
            Some(plan)
        } else {
            None
        };
        lifecycle::remove_variant_reference(
            &write,
            pending.metadata.variant_id,
            lifecycle::VariantReferenceOwner::PendingSource,
            transfer,
        )?;
        apply_pending_removal_authority_write(
            &write,
            &removal.authority,
            removal.authority.staging_before,
            self.blob_lifecycle_limits,
            true,
        )?;
        if final_root {
            pressure::remove_pending_source_root_write(
                &write,
                transfer,
                pending.metadata.variant_id,
            )?;
            pressure::remove_drained_variant_write(&write, pending.metadata.variant_id)?;
        } else {
            pressure::remove_pending_source_write(&write, transfer, pending.metadata.variant_id)?;
        }
        if let Some(plan) = deletion_plan {
            deletion::apply_variant_admission_plan_write(&write, plan)?;
        }
        let after = blob_network_staging_usage_write(&write, authority)?;
        if removal
            .authority
            .staging_before
            .rows
            .checked_sub(after.rows)
            != Some(removal.authority.removed_rows)
            || removal
                .authority
                .staging_before
                .bytes
                .checked_sub(after.bytes)
                != Some(removal.authority.removed_bytes)
        {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob pending pressure recovery disagrees with committed accounting delta",
            )));
        }
        let recovered_units = match demand.partition() {
            pressure::BlobCapacityPartition::NetworkStagingRows => removal.authority.removed_rows,
            pressure::BlobCapacityPartition::NetworkStagingBytes => removal.authority.removed_bytes,
            _ => {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "pending Blob pressure selected for another partition",
                )));
            }
        };
        let deletion_admission = deletion_evidence.map(|(_, _, _, admission)| admission);
        write.commit()?;
        if let Some(admission) = deletion_admission {
            admission.durable_committed().map_err(lease::store_error)?;
        }
        Ok(pressure::BlobCapacityRecoveryResult::recovered(
            vec![transfer],
            recovered_units,
            demand.deficit(),
            charge.rows,
            charge.bytes,
        ))
    }

    fn run_blob_variant_pressure_recovery(
        &self,
        variant: BlobVariantId,
        demand: pressure::BlobCapacityRecoveryDemand,
        budget: pressure::BlobPressureRecoveryBudget,
        selection: pressure::PressureSelection,
        custody_sample: Option<aster_mesh::CustodySample>,
        eligibility: BlobContactEligibility,
    ) -> Result<pressure::BlobCapacityRecoveryResult, StoreError> {
        let authority = self.require_bound_mission()?;
        let write = self.database.begin_write()?;
        enforce_live_write(&write)?;
        if !pressure::pressure_ready_write(&write)? {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                selection.rows_examined(),
                selection.bytes_examined(),
            ));
        }
        let maintenance_budget =
            lifecycle::BlobMaintenanceBudget::new(budget.rows, 1, budget.bytes)?;
        let mut charge = MaintenanceCharge::new(
            maintenance_budget,
            selection.rows_examined(),
            selection.bytes_examined(),
        );
        let before_depot = depot::depot_admission_usage_write(&write)?;
        let Some(pressure_snapshot) =
            plan_pressure_variant_snapshot_write(&write, variant, budget.roots, &mut charge)?
        else {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                charge.rows,
                charge.bytes,
            ));
        };
        if pressure_snapshot.references.is_empty() {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob pressure selected an unrooted variant",
            )));
        }
        let has_publications = pressure_snapshot
            .references
            .iter()
            .any(|(owner, _)| *owner == lifecycle::VariantReferenceOwner::Publication);
        let has_pending = pressure_snapshot
            .references
            .iter()
            .any(|(owner, _)| *owner == lifecycle::VariantReferenceOwner::PendingSource);
        let before_staging = if has_pending {
            if !charge_staging_accounting(&mut charge)? {
                return Ok(pressure::BlobCapacityRecoveryResult::empty(
                    charge.rows,
                    charge.bytes,
                ));
            }
            Some(blob_network_staging_usage_write(&write, authority)?)
        } else {
            None
        };
        let (before_items, before_bytes) = if has_publications {
            if !pressure_charge_u64_rows(
                &mut charge,
                "aster.metadata.v1",
                &[BLOB_ITEM_COUNT, BLOB_TOTAL_BYTES],
            )? {
                return Ok(pressure::BlobCapacityRecoveryResult::empty(
                    charge.rows,
                    charge.bytes,
                ));
            }
            let metadata = write.open_table(METADATA)?;
            let items = metadata
                .get(BLOB_ITEM_COUNT)?
                .ok_or(StoreError::MissingAccountingMetadata {
                    field: BLOB_ITEM_COUNT,
                })?
                .value();
            let bytes = metadata
                .get(BLOB_TOTAL_BYTES)?
                .ok_or(StoreError::MissingAccountingMetadata {
                    field: BLOB_TOTAL_BYTES,
                })?
                .value();
            (Some(items), Some(bytes))
        } else {
            (None, None)
        };
        if !lifecycle::charge_variant_reference_counter(&mut charge)? {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                charge.rows,
                charge.bytes,
            ));
        }
        let mut publication_roots = Vec::new();
        let mut pending_roots = Vec::new();
        let mut all_roots_proven_expired = true;
        let mut remaining_operations = budget.operations;
        let mut publication_bytes = 0u64;
        let mut staging_rows = 0u64;
        let mut staging_bytes = 0u64;
        let continuity = custody::lower_bound_continuity_write(&write)?;
        let retirement_sample = custody_sample.or(continuity.map(|value| value.sample));
        for &(owner, transfer) in &pressure_snapshot.references {
            match owner {
                lifecycle::VariantReferenceOwner::Publication => {
                    let publications = write.open_table(BLOB_PUBLICATIONS)?;
                    let encoded = publications
                        .get(transfer.as_bytes().as_slice())?
                        .ok_or_else(|| {
                            blob_error(BlobStoreError::SchemaInvariant(
                                "Blob variant pressure publication disappeared",
                            ))
                        })?;
                    let publication = decode_blob_metadata(encoded.value())?;
                    drop(encoded);
                    drop(publications);
                    if publication.variant_id != variant
                        || publication.header.priority >= demand.incoming_priority()
                    {
                        return Err(blob_error(BlobStoreError::SchemaInvariant(
                            "Blob variant pressure publication contradicts its summary",
                        )));
                    }
                    if !eligibility.admits(publication.lifetime) {
                        return Ok(pressure::BlobCapacityRecoveryResult::empty(
                            charge.rows,
                            charge.bytes,
                        ));
                    }
                    let proven_expired = matches!(
                        evaluate_blob_lifetime(
                            publication.lifetime,
                            continuity,
                            retirement_sample,
                        )?,
                        BlobLifetimeEvaluation::FiniteExpired { .. }
                    );
                    all_roots_proven_expired &= proven_expired;
                    let Some(retirement_plan) = plan_blob_publication_retirement_write(
                        &write,
                        self.blob_lifecycle_limits,
                        transfer,
                        if proven_expired {
                            lifecycle::RetirementReason::Expired
                        } else {
                            lifecycle::RetirementReason::Evicted
                        },
                        PublicationPressurePreflight::Snapshot(&pressure_snapshot),
                        retirement_sample,
                        &mut charge,
                        &mut remaining_operations,
                    )?
                    else {
                        return Ok(pressure::BlobCapacityRecoveryResult::empty(
                            charge.rows,
                            charge.bytes,
                        ));
                    };
                    let source_len = write
                        .open_table(BLOB_BYTES)?
                        .get(transfer.as_bytes().as_slice())?
                        .map(|value| u64::try_from(value.value().len()))
                        .transpose()
                        .map_err(|_| StoreError::PayloadByteAccountingOverflow)?
                        .ok_or_else(|| {
                            blob_error(BlobStoreError::SchemaInvariant(
                                "Blob variant pressure publication lacks source bytes",
                            ))
                        })?;
                    publication_bytes = publication_bytes
                        .checked_add(source_len)
                        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
                    publication_roots.push((transfer, retirement_plan));
                }
                lifecycle::VariantReferenceOwner::PendingSource => {
                    let pending_sources = write.open_table(BLOB_PENDING_SOURCES)?;
                    let encoded_guard = pending_sources
                        .get(transfer.as_bytes().as_slice())?
                        .ok_or_else(|| {
                            blob_error(BlobStoreError::SchemaInvariant(
                                "Blob variant pressure pending source disappeared",
                            ))
                        })?;
                    let encoded = encoded_guard.value().to_vec();
                    drop(encoded_guard);
                    drop(pending_sources);
                    let pending = decode_pending_blob_source(&encoded)?;
                    if pending.metadata.variant_id != variant
                        || pending.metadata.header.priority >= demand.incoming_priority()
                    {
                        return Err(blob_error(BlobStoreError::SchemaInvariant(
                            "Blob variant pressure pending source contradicts its summary",
                        )));
                    }
                    if !eligibility.admits(pending.metadata.lifetime) {
                        return Ok(pressure::BlobCapacityRecoveryResult::empty(
                            charge.rows,
                            charge.bytes,
                        ));
                    }
                    all_roots_proven_expired &= matches!(
                        evaluate_blob_lifetime(
                            pending.metadata.lifetime,
                            continuity,
                            retirement_sample,
                        )?,
                        BlobLifetimeEvaluation::FiniteExpired { .. }
                    );
                    let Some(authority_plan) = plan_pending_removal_authority_write(
                        &write,
                        authority,
                        transfer,
                        &pending,
                        &mut charge,
                    )?
                    else {
                        return Ok(pressure::BlobCapacityRecoveryResult::empty(
                            charge.rows,
                            charge.bytes,
                        ));
                    };
                    if !lifecycle::charge_policy_ttl_deadline_write(
                        transfer,
                        lifecycle::TtlDeadlineKind::PendingSource,
                        Some(pending.metadata.lifetime),
                        None,
                        &mut charge,
                    )? {
                        return Ok(pressure::BlobCapacityRecoveryResult::empty(
                            charge.rows,
                            charge.bytes,
                        ));
                    }
                    staging_rows = staging_rows
                        .checked_add(authority_plan.removed_rows)
                        .ok_or(StoreError::ItemCountAccountingOverflow)?;
                    staging_bytes = staging_bytes
                        .checked_add(authority_plan.removed_bytes)
                        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
                    pending_roots.push(WholeVariantPendingRemovalPlan {
                        transfer,
                        authority: authority_plan,
                    });
                }
            }
        }

        if charge.rows > budget.rows || charge.bytes > budget.bytes {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                charge.rows,
                charge.bytes,
            ));
        }
        if !all_roots_proven_expired && budget.deletion_manifests < 1 {
            return Ok(pressure::BlobCapacityRecoveryResult::empty(
                charge.rows,
                charge.bytes,
            ));
        }
        let deletion_evidence = if all_roots_proven_expired {
            None
        } else {
            match deletion::bounded_variant_has_deletion_manifest_write(
                &write,
                variant,
                &mut charge,
            )? {
                Some(false) => {}
                Some(true) => {
                    return Err(blob_error(BlobStoreError::SchemaInvariant(
                        "live Blob pressure variant already has deletion authority",
                    )));
                }
                None => {
                    return Ok(pressure::BlobCapacityRecoveryResult::empty(
                        charge.rows,
                        charge.bytes,
                    ));
                }
            }
            let Some((import, lineage)) =
                pressure_deletion_evidence_write(&write, variant, &mut charge)?
            else {
                return Ok(pressure::BlobCapacityRecoveryResult::empty(
                    charge.rows,
                    charge.bytes,
                ));
            };
            if !pressure_charge_depot_owner_binding(&mut charge)? {
                return Ok(pressure::BlobCapacityRecoveryResult::empty(
                    charge.rows,
                    charge.bytes,
                ));
            }
            let owner = depot::require_depot_owner_binding_write(
                &write,
                &self.path,
                self.backing_identity,
                self.blob_depot_owner_token,
            )?;
            let snapshot = self
                .blob_lease_registry
                .snapshot(
                    self.blob_depot_owner_binding,
                    lease::BlobLeaseTarget::Variant(variant),
                )
                .map_err(lease::store_error)?;
            #[cfg(test)]
            if TEST_BLOB_MANIFEST_ADMISSION_GENERATION_CHURN.get() {
                drop(
                    self.blob_lease_registry
                        .acquire(
                            self.blob_depot_owner_binding,
                            lease::BlobLeaseTarget::Variant(variant),
                            lease::BlobLeaseKind::InternalChunkWork,
                        )
                        .map_err(lease::store_error)?,
                );
            }
            let deletion_admission =
                match self.blob_lease_registry.try_mark_delete_pending(snapshot) {
                    Ok(admission) => admission,
                    Err(
                        lease::BlobLeaseAcquireError::ActiveLeases
                        | lease::BlobLeaseAcquireError::GenerationChanged
                        | lease::BlobLeaseAcquireError::DeletePending,
                    ) => {
                        return Ok(pressure::BlobCapacityRecoveryResult::empty(
                            charge.rows,
                            charge.bytes,
                        ));
                    }
                    Err(error) => return Err(lease::store_error(error)),
                };

            let Some(deletion_plan) = deletion::plan_variant_admission_write(
                &write,
                variant,
                &import,
                &lineage,
                owner,
                custody_sample,
                Some(&mut charge),
            )?
            else {
                return Ok(pressure::BlobCapacityRecoveryResult::empty(
                    charge.rows,
                    charge.bytes,
                ));
            };
            Some((deletion_plan, deletion_admission))
        };

        let (deletion_plan, deletion_admission) = match deletion_evidence {
            Some((plan, admission)) => (Some(plan), Some(admission)),
            None => (None, None),
        };
        let plan = WholeVariantRetirementPlan {
            pressure: pressure_snapshot,
            publications: publication_roots,
            pending: pending_roots,
            deletion: deletion_plan,
            publication_bytes,
            staging_rows,
            staging_bytes,
        };
        let WholeVariantRetirementPlan {
            pressure,
            publications,
            pending,
            deletion,
            publication_bytes,
            staging_rows,
            staging_bytes,
        } = plan;
        let admitted_physical_manifest = deletion.is_some();
        if pressure.references.len() != publications.len() + pending.len() {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "whole-variant retirement plan lost a pressure root",
            )));
        }

        let publication_count = u64::try_from(publications.len())
            .map_err(|_| StoreError::ItemCountAccountingOverflow)?;
        let mut evicted = publications
            .iter()
            .map(|(transfer, _)| *transfer)
            .collect::<Vec<_>>();
        for (_, retirement_plan) in publications {
            apply_blob_publication_retirement_plan_write(
                &write,
                self.blob_lifecycle_limits,
                retirement_plan,
                PublicationPressureApply::RemoveRootOnly,
            )?;
        }
        let mut pending_staging =
            before_staging.unwrap_or(BlobNetworkStagingUsage { rows: 0, bytes: 0 });
        for pending_plan in &pending {
            lifecycle::remove_variant_reference(
                &write,
                variant,
                lifecycle::VariantReferenceOwner::PendingSource,
                pending_plan.transfer,
            )?;
            pending_staging = apply_pending_removal_authority_write(
                &write,
                &pending_plan.authority,
                pending_staging,
                self.blob_lifecycle_limits,
                true,
            )?;
            pressure::remove_pending_source_root_write(&write, pending_plan.transfer, variant)?;
        }
        pressure::remove_drained_variant_write(&write, variant)?;
        if let Some(deletion) = deletion {
            deletion::apply_variant_admission_plan_write(&write, deletion)?;
        }
        let after_depot = depot::depot_admission_usage_write(&write)?;
        let after_staging = if has_pending {
            Some(blob_network_staging_usage_write(&write, authority)?)
        } else {
            None
        };
        let (after_items, after_bytes) = if has_publications {
            let metadata = write.open_table(METADATA)?;
            (
                Some(
                    metadata
                        .get(BLOB_ITEM_COUNT)?
                        .ok_or(StoreError::MissingAccountingMetadata {
                            field: BLOB_ITEM_COUNT,
                        })?
                        .value(),
                ),
                Some(
                    metadata
                        .get(BLOB_TOTAL_BYTES)?
                        .ok_or(StoreError::MissingAccountingMetadata {
                            field: BLOB_TOTAL_BYTES,
                        })?
                        .value(),
                ),
            )
        } else {
            (None, None)
        };
        let publication_delta_matches = match (before_items, after_items, before_bytes, after_bytes)
        {
            (Some(before_items), Some(after_items), Some(before_bytes), Some(after_bytes)) => {
                before_items.checked_sub(after_items) == Some(publication_count)
                    && before_bytes.checked_sub(after_bytes) == Some(publication_bytes)
            }
            (None, None, None, None) => publication_count == 0 && publication_bytes == 0,
            _ => false,
        };
        let staging_delta_matches = match (before_staging, after_staging) {
            (Some(before), Some(after)) => {
                before.rows.checked_sub(after.rows) == Some(staging_rows)
                    && before.bytes.checked_sub(after.bytes) == Some(staging_bytes)
            }
            (None, None) => staging_rows == 0 && staging_bytes == 0,
            _ => false,
        };
        if !publication_delta_matches || !staging_delta_matches {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "whole-variant pressure recovery disagrees with logical accounting delta",
            )));
        }
        let recovered_units = match demand.partition() {
            pressure::BlobCapacityPartition::DepotBytes => before_depot
                .reserved_bytes
                .checked_sub(after_depot.reserved_bytes)
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob pressure increased depot admission bytes",
                    ))
                })?,
            pressure::BlobCapacityPartition::DepotChunks => before_depot
                .chunks
                .checked_sub(after_depot.chunks)
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob pressure increased depot admission chunks",
                    ))
                })?,
            pressure::BlobCapacityPartition::DepotVariants => before_depot
                .variants
                .checked_sub(after_depot.variants)
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob pressure increased depot admission variants",
                    ))
                })?,
            _ => {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "whole-variant pressure selected for another partition",
                )));
            }
        };
        evicted.extend(pending.into_iter().map(|plan| plan.transfer));
        evicted.sort_unstable();
        write.commit()?;
        if let Some(deletion_admission) = deletion_admission {
            deletion_admission
                .durable_committed()
                .map_err(lease::store_error)?;
        }
        if admitted_physical_manifest {
            Ok(
                pressure::BlobCapacityRecoveryResult::recovered_with_physical_candidate(
                    evicted,
                    recovered_units,
                    demand,
                    charge.rows,
                    charge.bytes,
                    variant,
                ),
            )
        } else {
            Ok(pressure::BlobCapacityRecoveryResult::recovered(
                evicted,
                recovered_units,
                demand.deficit(),
                charge.rows,
                charge.bytes,
            ))
        }
    }

    /// Reclaims only already-unreferenced exact variants under independent
    /// bounds. This path never opens the routine maintenance-cursor table.
    #[doc(hidden)]
    pub fn run_blob_capacity_gc(
        &self,
        budget: BlobMaintenanceBudget,
        custody_sample: Option<aster_mesh::CustodySample>,
    ) -> Result<BlobCapacityGcProgress, StoreError> {
        self.run_blob_capacity_gc_inner(None, budget, custody_sample)
    }

    /// Runs one cursor-neutral local recovery pass for the exact capacity
    /// partition that rejected admission.
    #[doc(hidden)]
    pub fn run_blob_capacity_gc_for(
        &self,
        target: BlobCapacityGcTarget,
        budget: BlobMaintenanceBudget,
        custody_sample: Option<aster_mesh::CustodySample>,
    ) -> Result<BlobCapacityGcProgress, StoreError> {
        self.run_blob_capacity_gc_inner(Some(target), budget, custody_sample)
    }

    /// Contact-only capacity cleanup performs no lifecycle admission or
    /// expiry. It only reclaims already-authorized physical deletion
    /// manifests under the supplied bounds; pressure recovery below may still
    /// retire an exactly revalidated durable candidate.
    #[doc(hidden)]
    pub fn run_durable_blob_capacity_gc_for(
        &self,
        _target: BlobCapacityGcTarget,
        budget: BlobMaintenanceBudget,
        _custody_sample: Option<aster_mesh::CustodySample>,
    ) -> Result<BlobCapacityGcProgress, StoreError> {
        self.require_live()?;
        let mut progress = BlobCapacityGcProgress::default();
        let mut position = None;
        while progress.rows_examined < budget.rows
            && progress.files_examined < budget.files
            && progress.bytes_examined < budget.bytes
        {
            let step = self.run_one_capacity_physical_unit(
                BlobCapacityPhysicalSelection::Global,
                position.as_deref(),
                budget.rows - progress.rows_examined,
                budget.bytes - progress.bytes_examined,
            )?;
            let (rows, files, bytes) = match &step {
                BlobCapacityPhysicalStep::Unit(unit) => {
                    position = unit.next_position.clone();
                    progress.manifests_finalized = progress
                        .manifests_finalized
                        .checked_add(u64::from(unit.finalized))
                        .ok_or(StoreError::ItemCountAccountingOverflow)?;
                    (unit.rows_examined, unit.files_examined, unit.bytes_examined)
                }
                BlobCapacityPhysicalStep::Continue {
                    rows_examined,
                    bytes_examined,
                    next_position,
                } => {
                    position = next_position.clone();
                    (*rows_examined, 0, *bytes_examined)
                }
                BlobCapacityPhysicalStep::Blocked {
                    rows_examined,
                    bytes_examined,
                }
                | BlobCapacityPhysicalStep::Exhausted {
                    rows_examined,
                    bytes_examined,
                } => (*rows_examined, 0, *bytes_examined),
            };
            progress.rows_examined = progress
                .rows_examined
                .checked_add(rows)
                .ok_or(StoreError::ItemCountAccountingOverflow)?;
            progress.files_examined = progress
                .files_examined
                .checked_add(files)
                .ok_or(StoreError::ItemCountAccountingOverflow)?;
            progress.bytes_examined = progress
                .bytes_examined
                .checked_add(bytes)
                .ok_or(StoreError::PayloadByteAccountingOverflow)?;
            match step {
                BlobCapacityPhysicalStep::Unit(_) => std::thread::yield_now(),
                BlobCapacityPhysicalStep::Continue { .. } if rows != 0 || bytes != 0 => {
                    std::thread::yield_now();
                }
                BlobCapacityPhysicalStep::Continue { .. }
                | BlobCapacityPhysicalStep::Blocked { .. }
                | BlobCapacityPhysicalStep::Exhausted { .. } => break,
            }
        }
        Ok(progress)
    }

    fn run_blob_capacity_gc_inner(
        &self,
        target: Option<BlobCapacityGcTarget>,
        budget: BlobMaintenanceBudget,
        custody_sample: Option<aster_mesh::CustodySample>,
    ) -> Result<BlobCapacityGcProgress, StoreError> {
        self.require_live()?;
        let mut progress = BlobCapacityGcProgress::default();
        // Admission pressure gets at most one deadline-ordered retained-record
        // expiry pass.  It is deliberately cursor-neutral: the normal
        // six-class routine remains the only owner of its durable scheduler.
        // Continue with any remaining page budget so lifecycle-capacity work
        // cannot intercept the pre-existing physical-capacity recovery path.
        let retirement_target = match target {
            Some(BlobCapacityGcTarget::Depot) => None,
            Some(BlobCapacityGcTarget::Operation) => {
                Some(lifecycle::RetentionDeadlineKind::Operation)
            }
            Some(BlobCapacityGcTarget::PublicationLifecycle) => {
                Some(lifecycle::RetentionDeadlineKind::Publication)
            }
            None => None,
        };
        if target != Some(BlobCapacityGcTarget::Depot)
            && let Some(sample) = custody_sample
        {
            let write = self.database.begin_write()?;
            enforce_live_write(&write)?;
            lifecycle::require_maintenance_accounting(&write)?;
            if let Some(expiry) = expire_one_retirement_record_capacity_write(
                &write,
                budget,
                sample,
                retirement_target,
            )? {
                write.commit()?;
                progress.rows_examined = expiry.rows_examined;
                progress.bytes_examined = expiry.bytes_examined;
            }
        }
        let mut physical_position = None;
        let mut admission_position = None;
        while progress.rows_examined < budget.rows
            && progress.files_examined < budget.files
            && progress.bytes_examined < budget.bytes
        {
            let rows_left = budget.rows - progress.rows_examined;
            let bytes_left = budget.bytes - progress.bytes_examined;
            match self.run_one_capacity_physical_unit(
                BlobCapacityPhysicalSelection::Global,
                physical_position.as_deref(),
                rows_left,
                bytes_left,
            )? {
                BlobCapacityPhysicalStep::Unit(unit) => {
                    physical_position = unit.next_position;
                    progress.rows_examined = progress
                        .rows_examined
                        .checked_add(unit.rows_examined)
                        .ok_or(StoreError::ItemCountAccountingOverflow)?;
                    progress.files_examined = progress
                        .files_examined
                        .checked_add(unit.files_examined)
                        .ok_or(StoreError::ItemCountAccountingOverflow)?;
                    progress.bytes_examined = progress
                        .bytes_examined
                        .checked_add(unit.bytes_examined)
                        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
                    progress.manifests_finalized = progress
                        .manifests_finalized
                        .checked_add(u64::from(unit.finalized))
                        .ok_or(StoreError::ItemCountAccountingOverflow)?;
                    std::thread::yield_now();
                    continue;
                }
                BlobCapacityPhysicalStep::Continue {
                    rows_examined,
                    bytes_examined,
                    next_position,
                } => {
                    physical_position = next_position;
                    progress.rows_examined = progress
                        .rows_examined
                        .checked_add(rows_examined)
                        .ok_or(StoreError::ItemCountAccountingOverflow)?;
                    progress.bytes_examined = progress
                        .bytes_examined
                        .checked_add(bytes_examined)
                        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
                    if rows_examined == 0 && bytes_examined == 0 {
                        break;
                    }
                    std::thread::yield_now();
                    continue;
                }
                BlobCapacityPhysicalStep::Blocked {
                    rows_examined,
                    bytes_examined,
                } => {
                    progress.rows_examined = progress
                        .rows_examined
                        .checked_add(rows_examined)
                        .ok_or(StoreError::ItemCountAccountingOverflow)?;
                    progress.bytes_examined = progress
                        .bytes_examined
                        .checked_add(bytes_examined)
                        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
                    break;
                }
                BlobCapacityPhysicalStep::Exhausted {
                    rows_examined,
                    bytes_examined,
                } => {
                    progress.rows_examined = progress
                        .rows_examined
                        .checked_add(rows_examined)
                        .ok_or(StoreError::ItemCountAccountingOverflow)?;
                    progress.bytes_examined = progress
                        .bytes_examined
                        .checked_add(bytes_examined)
                        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
                }
            }
            if progress.rows_examined >= budget.rows || progress.bytes_examined >= budget.bytes {
                break;
            }
            loop {
                let rows_left = budget.rows - progress.rows_examined;
                let bytes_left = budget.bytes - progress.bytes_examined;
                let step = self.admit_one_capacity_manifest(
                    admission_position.as_deref(),
                    rows_left,
                    bytes_left,
                    custody_sample,
                )?;
                let (rows, bytes) = match &step {
                    BlobCapacityAdmissionStep::Admitted {
                        rows_examined,
                        bytes_examined,
                        ..
                    }
                    | BlobCapacityAdmissionStep::Continue {
                        rows_examined,
                        bytes_examined,
                        ..
                    }
                    | BlobCapacityAdmissionStep::Exhausted {
                        rows_examined,
                        bytes_examined,
                    }
                    | BlobCapacityAdmissionStep::Blocked {
                        rows_examined,
                        bytes_examined,
                    } => (*rows_examined, *bytes_examined),
                };
                progress.rows_examined = progress
                    .rows_examined
                    .checked_add(rows)
                    .ok_or(StoreError::ItemCountAccountingOverflow)?;
                progress.bytes_examined = progress
                    .bytes_examined
                    .checked_add(bytes)
                    .ok_or(StoreError::PayloadByteAccountingOverflow)?;
                match step {
                    BlobCapacityAdmissionStep::Admitted { next_position, .. } => {
                        admission_position = Some(next_position);
                        physical_position = None;
                        progress.manifests_admitted = progress
                            .manifests_admitted
                            .checked_add(1)
                            .ok_or(StoreError::ItemCountAccountingOverflow)?;
                        std::thread::yield_now();
                        break;
                    }
                    BlobCapacityAdmissionStep::Continue { next_position, .. } => {
                        admission_position = Some(next_position);
                        if progress.rows_examined >= budget.rows
                            || progress.bytes_examined >= budget.bytes
                        {
                            return Ok(progress);
                        }
                        std::thread::yield_now();
                    }
                    BlobCapacityAdmissionStep::Exhausted { .. }
                    | BlobCapacityAdmissionStep::Blocked { .. } => return Ok(progress),
                }
            }
        }
        Ok(progress)
    }

    fn run_blob_physical_deletion_turn(
        &self,
        cursor: lifecycle::BlobMaintenanceCursor,
        budget: BlobMaintenanceBudget,
    ) -> Result<BlobMaintenanceProgress, StoreError> {
        let read = self.database.begin_read()?;
        if lifecycle::load_maintenance_cursor_read(&read)? != cursor {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob maintenance cursor changed during deletion discovery",
            )));
        }
        let selection = deletion::select_physical_work_read(
            &read,
            cursor.position.as_deref(),
            budget.rows,
            budget.bytes,
        )?;
        drop(read);

        let work = match selection {
            deletion::BlobDeletionSelection::Work(work) => *work,
            deletion::BlobDeletionSelection::Continue {
                position,
                rows_examined,
                bytes_examined,
            } => {
                let write = self.database.begin_write()?;
                enforce_live_write(&write)?;
                lifecycle::require_maintenance_accounting(&write)?;
                if lifecycle::load_maintenance_cursor(&write)? != cursor {
                    return Err(blob_error(BlobStoreError::SchemaInvariant(
                        "Blob maintenance cursor changed after bounded deletion discovery",
                    )));
                }
                deletion::advance_blob_deletion_maintenance_turn(&write)?;
                lifecycle::advance_maintenance_cursor(&write, cursor.class, position.as_deref())?;
                write.commit()?;
                return Ok(BlobMaintenanceProgress {
                    class: cursor.class,
                    rows_examined,
                    files_examined: 0,
                    bytes_examined,
                    candidates: Vec::new(),
                    class_has_more_work: true,
                    awaiting_later_handler: false,
                });
            }
            deletion::BlobDeletionSelection::Complete {
                rows_examined,
                bytes_examined,
            } => {
                let write = self.database.begin_write()?;
                enforce_live_write(&write)?;
                lifecycle::require_maintenance_accounting(&write)?;
                if lifecycle::load_maintenance_cursor(&write)? != cursor {
                    return Err(blob_error(BlobStoreError::SchemaInvariant(
                        "Blob maintenance cursor changed after deletion discovery",
                    )));
                }
                deletion::advance_blob_deletion_maintenance_turn(&write)?;
                lifecycle::advance_maintenance_cursor(&write, cursor.class, None)?;
                write.commit()?;
                return Ok(BlobMaintenanceProgress {
                    class: cursor.class,
                    rows_examined,
                    files_examined: 0,
                    bytes_examined,
                    candidates: Vec::new(),
                    class_has_more_work: false,
                    awaiting_later_handler: false,
                });
            }
        };

        let _depot_guard = match self.blob_depot_lock.try_write() {
            Ok(guard) => guard,
            Err(std::sync::TryLockError::WouldBlock) => {
                return Ok(BlobMaintenanceProgress {
                    class: cursor.class,
                    rows_examined: work.rows_examined,
                    files_examined: 0,
                    bytes_examined: work.bytes_examined,
                    candidates: Vec::new(),
                    class_has_more_work: true,
                    awaiting_later_handler: true,
                });
            }
            Err(std::sync::TryLockError::Poisoned(_)) => {
                return Err(blob_error(BlobStoreError::DepotIntegrity(
                    "depot lock is poisoned",
                )));
            }
        };
        self.require_live()?;

        // Short durable revalidation/turn transaction. It is released before
        // the descriptor-relative filesystem unit begins.
        let write = self.database.begin_write()?;
        enforce_live_write(&write)?;
        lifecycle::require_maintenance_accounting(&write)?;
        if lifecycle::load_maintenance_cursor(&write)? != cursor {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob maintenance cursor changed before deletion work",
            )));
        }
        deletion::revalidate_physical_work_write(&write, &work)?;
        let turn = deletion::advance_blob_deletion_maintenance_turn(&write)?;
        write.commit()?;

        let filesystem = match &work.kind {
            deletion::BlobDeletionWorkKind::Chunk(chunk)
            | deletion::BlobDeletionWorkKind::ReconcileUnmarkedChunk(chunk) => {
                depot::delete_manifest_chunk(
                    &self.path,
                    self.backing_identity,
                    self.blob_depot_owner_token,
                    &work.manifest,
                    chunk,
                )
                .map(|bytes| (1u64, bytes))
            }
            deletion::BlobDeletionWorkKind::AdvanceDirectoryPhase => Ok((0, 0)),
            deletion::BlobDeletionWorkKind::RemoveDirectoryAndFinalize => {
                depot::delete_manifest_variant_directory(
                    &self.path,
                    self.backing_identity,
                    self.blob_depot_owner_token,
                    &work.manifest,
                )
                .map(|()| (1, 0))
            }
        };
        let (files_examined, physical_bytes) = match filesystem {
            Ok(progress) => progress,
            Err(depot::ManifestDeletionError {
                retry: Some(category),
                files_examined,
                bytes_examined: physical_bytes,
                ..
            }) => {
                let write = self.database.begin_write()?;
                enforce_live_write(&write)?;
                deletion::record_physical_failure_write(&write, &work, turn, category)?;
                lifecycle::advance_maintenance_cursor(
                    &write,
                    cursor.class,
                    Some(work.position.as_slice()),
                )?;
                write.commit()?;
                return Ok(BlobMaintenanceProgress {
                    class: cursor.class,
                    rows_examined: work.rows_examined,
                    files_examined,
                    bytes_examined: work
                        .bytes_examined
                        .checked_add(physical_bytes)
                        .ok_or(StoreError::PayloadByteAccountingOverflow)?,
                    candidates: Vec::new(),
                    class_has_more_work: true,
                    awaiting_later_handler: false,
                });
            }
            Err(error) => return Err(*error.error),
        };

        let write = self.database.begin_write()?;
        enforce_live_write(&write)?;
        match work.kind {
            deletion::BlobDeletionWorkKind::Chunk(_) => {
                deletion::mark_chunk_deleted_write(&write, &work)?;
                lifecycle::advance_maintenance_cursor(
                    &write,
                    cursor.class,
                    Some(work.position.as_slice()),
                )?;
            }
            deletion::BlobDeletionWorkKind::ReconcileUnmarkedChunk(_) => {
                deletion::mark_unmarked_reconciled_write(&write, &work)?;
                lifecycle::advance_maintenance_cursor(
                    &write,
                    cursor.class,
                    Some(work.position.as_slice()),
                )?;
            }
            deletion::BlobDeletionWorkKind::AdvanceDirectoryPhase => {
                deletion::advance_directory_phase_write(&write, &work)?;
                lifecycle::advance_maintenance_cursor(&write, cursor.class, None)?;
            }
            deletion::BlobDeletionWorkKind::RemoveDirectoryAndFinalize => {
                deletion::finalize_manifest_write(&write, &work)?;
                lifecycle::advance_maintenance_cursor(
                    &write,
                    cursor.class,
                    Some(work.position.as_slice()),
                )?;
                deletion::manifest_finalization_mutation_boundary()?;
            }
        }
        write.commit()?;
        Ok(BlobMaintenanceProgress {
            class: cursor.class,
            rows_examined: work.rows_examined,
            files_examined,
            bytes_examined: work
                .bytes_examined
                .checked_add(physical_bytes)
                .ok_or(StoreError::PayloadByteAccountingOverflow)?,
            candidates: Vec::new(),
            class_has_more_work: true,
            awaiting_later_handler: false,
        })
    }

    /// Runs one internal, durable, independently bounded maintenance selection
    /// turn.
    #[doc(hidden)]
    pub fn run_blob_maintenance_turn(
        &self,
        budget: BlobMaintenanceBudget,
    ) -> Result<BlobMaintenanceProgress, StoreError> {
        self.run_blob_maintenance_turn_with_sample(budget, None)
    }

    /// Runs one bounded maintenance turn while advancing conservative
    /// monotonic deletion-age continuity from the runtime's mission clock.
    #[doc(hidden)]
    pub fn run_blob_maintenance_turn_with_sample(
        &self,
        budget: BlobMaintenanceBudget,
        custody_sample: Option<aster_mesh::CustodySample>,
    ) -> Result<BlobMaintenanceProgress, StoreError> {
        self.require_live()?;
        if budget.rows == 0 || budget.files == 0 || budget.bytes == 0 {
            return Err(blob_error(BlobStoreError::InvalidMaintenanceBudget));
        }
        let read = self.database.begin_read()?;
        let discovered_cursor = lifecycle::load_maintenance_cursor_read(&read)?;
        let has_uploads = !read.open_table(BLOB_UPLOADS)?.is_empty()?;
        drop(read);
        if let Some(sample) = custody_sample {
            let write = self.database.begin_write()?;
            enforce_live_write(&write)?;
            custody::observe_continuity_write(&write, sample)?;
            let age_progress = deletion::checkpoint_blob_deletion_ages_write(
                &write,
                sample,
                budget.rows,
                budget.bytes,
            )?;
            write.commit()?;
            if age_progress.rows_examined != 0 || age_progress.has_more {
                return Ok(BlobMaintenanceProgress {
                    class: discovered_cursor.class,
                    rows_examined: age_progress.rows_examined,
                    files_examined: 0,
                    bytes_examined: age_progress.bytes_examined,
                    candidates: Vec::new(),
                    class_has_more_work: age_progress.has_more,
                    awaiting_later_handler: false,
                });
            }
        }
        if matches!(
            discovered_cursor.class,
            BlobMaintenanceClass::UnreferencedLocalImportStaging
                | BlobMaintenanceClass::UnreferencedCompletedVariants
        ) {
            return self.run_blob_manifest_admission_turn(
                discovered_cursor,
                budget,
                custody_sample,
            );
        }
        if discovered_cursor.class == BlobMaintenanceClass::ManifestBackedPhysicalDeletion {
            return self.run_blob_physical_deletion_turn(discovered_cursor, budget);
        }
        let upload_pack_root = if discovered_cursor.class
            == BlobMaintenanceClass::ExpiredRetirementRecords
            && has_uploads
        {
            Some(pack::PinnedBlobPackRoot::open(self)?)
        } else {
            None
        };
        // Upload cleanup and writer admission share depot -> redb lock order.
        let _depot_guard = if upload_pack_root.is_some() {
            Some(self.blob_depot_lock.write().map_err(|_| {
                blob_error(BlobStoreError::DepotIntegrity("depot lock is poisoned"))
            })?)
        } else {
            None
        };
        let mut write = self.database.begin_write()?;
        if upload_pack_root.is_some() {
            write.set_durability(Durability::Immediate)?;
        }
        enforce_live_write(&write)?;
        lifecycle::require_maintenance_accounting(&write)?;
        let cursor = lifecycle::load_maintenance_cursor(&write)?;
        let generation_sync = plan_blob_policy_generation_sync_write(&write)?;
        if generation_sync.needed() {
            let (mut charge, cursor_fits) =
                begin_policy_maintenance_charge(&write, budget, cursor.class)?;
            if !cursor_fits
                || !charge_blob_policy_generation_sync_write(&write, generation_sync, &mut charge)?
            {
                return Ok(BlobMaintenanceProgress {
                    class: cursor.class,
                    rows_examined: charge.rows,
                    files_examined: 0,
                    bytes_examined: charge.bytes,
                    candidates: Vec::new(),
                    class_has_more_work: true,
                    awaiting_later_handler: false,
                });
            }
            apply_blob_policy_generation_sync_write(&write, generation_sync)?;
            lifecycle::advance_maintenance_cursor(
                &write,
                cursor.class,
                cursor.position.as_deref(),
            )?;
            let progress = BlobMaintenanceProgress {
                class: cursor.class,
                rows_examined: charge.rows,
                files_examined: 0,
                bytes_examined: charge.bytes,
                candidates: Vec::new(),
                class_has_more_work: true,
                awaiting_later_handler: false,
            };
            write.commit()?;
            return Ok(progress);
        }
        let effective_custody_sample = custody_sample
            .or(custody::lower_bound_continuity_write(&write)?.map(|continuity| continuity.sample));
        if cursor.class == BlobMaintenanceClass::ExpiredPublicationsAndPendingSources
            && let Some((rows_examined, bytes_examined, applied)) =
                apply_one_blob_policy_reanchor_write(
                    &write,
                    self.blob_lifecycle_limits,
                    self.mission_authority,
                    self.blob_depot_owner_binding,
                    budget,
                    effective_custody_sample,
                    cursor.class,
                )?
        {
            if !applied {
                return Ok(BlobMaintenanceProgress {
                    class: cursor.class,
                    rows_examined,
                    files_examined: 0,
                    bytes_examined,
                    candidates: Vec::new(),
                    class_has_more_work: true,
                    awaiting_later_handler: false,
                });
            }
            lifecycle::advance_maintenance_cursor(
                &write,
                cursor.class,
                cursor.position.as_deref(),
            )?;
            write.commit()?;
            return Ok(BlobMaintenanceProgress {
                class: cursor.class,
                rows_examined,
                files_examined: 0,
                bytes_examined,
                candidates: Vec::new(),
                class_has_more_work: true,
                awaiting_later_handler: false,
            });
        }
        if cursor.class == BlobMaintenanceClass::ExpiredPublicationsAndPendingSources
            && !pressure::pressure_ready_write(&write)?
        {
            lifecycle::advance_maintenance_cursor(
                &write,
                cursor.class,
                cursor.position.as_deref(),
            )?;
            write.commit()?;
            return Ok(BlobMaintenanceProgress {
                class: cursor.class,
                rows_examined: 0,
                files_examined: 0,
                bytes_examined: 0,
                candidates: Vec::new(),
                class_has_more_work: true,
                awaiting_later_handler: false,
            });
        }
        if cursor.class == BlobMaintenanceClass::ExpiredPublicationsAndPendingSources
            && let Some((rows_examined, bytes_examined, applied)) = apply_one_blob_ttl_expiry_write(
                &write,
                self.blob_lifecycle_limits,
                self.mission_authority,
                self.blob_depot_owner_binding,
                budget,
                cursor.class,
            )?
        {
            if !applied {
                return Ok(BlobMaintenanceProgress {
                    class: cursor.class,
                    rows_examined,
                    files_examined: 0,
                    bytes_examined,
                    candidates: Vec::new(),
                    class_has_more_work: true,
                    awaiting_later_handler: false,
                });
            }
            lifecycle::advance_maintenance_cursor(
                &write,
                cursor.class,
                cursor.position.as_deref(),
            )?;
            write.commit()?;
            return Ok(BlobMaintenanceProgress {
                class: cursor.class,
                rows_examined,
                files_examined: 0,
                bytes_examined,
                candidates: Vec::new(),
                class_has_more_work: true,
                awaiting_later_handler: false,
            });
        }
        if cursor.class == BlobMaintenanceClass::ExpiredRetirementRecords
            && let Some(root) = upload_pack_root.as_ref()
            && let Some((progress, completed)) = self.maintain_terminal_upload_write(
                &write,
                &cursor,
                budget,
                effective_custody_sample,
                root,
            )?
        {
            write.commit()?;
            if let Some(identity) = completed {
                pack::finish_upload_pack_cleanup(root, &identity)
                    .map_err(upload::upload_pack_store_error)?;
            }
            return Ok(progress);
        }
        if cursor.class == BlobMaintenanceClass::ExpiredRetirementRecords
            && let Some(sample) = effective_custody_sample
            && let Some(progress) =
                expire_one_retirement_record_write(&write, &cursor, budget, sample)?
        {
            write.commit()?;
            return Ok(progress);
        }
        let mut page_charge = MaintenanceCharge::new(budget, 0, 0);
        if !lifecycle::charge_maintenance_cursor_write(&write, cursor.class, &mut page_charge)? {
            return Ok(BlobMaintenanceProgress {
                class: cursor.class,
                rows_examined: page_charge.rows,
                files_examined: 0,
                bytes_examined: page_charge.bytes,
                candidates: Vec::new(),
                class_has_more_work: true,
                awaiting_later_handler: false,
            });
        }
        let page = match cursor.class {
            BlobMaintenanceClass::ExpiredPublicationsAndPendingSources => {
                // Policy retirement is one bounded atomic source unit. Do not
                // pre-read later source rows and consume the budget needed to
                // retire the selected maximum-fanout publication.
                bounded_composite_maintenance_page_with_source_limit_and_charge(
                    &write,
                    BLOB_PUBLICATIONS,
                    MaintenanceRowKind::Publication,
                    BLOB_PENDING_SOURCES,
                    MaintenanceRowKind::Pending,
                    cursor.position.as_deref(),
                    1,
                    page_charge,
                )?
            }
            BlobMaintenanceClass::InvalidPendingWork => {
                bounded_composite_maintenance_page_with_charge(
                    &write,
                    BLOB_PENDING_SOURCES,
                    MaintenanceRowKind::Pending,
                    BLOB_CARRIER_PREFIXES,
                    MaintenanceRowKind::Carrier,
                    cursor.position.as_deref(),
                    page_charge,
                )?
            }
            BlobMaintenanceClass::UnreferencedLocalImportStaging
            | BlobMaintenanceClass::UnreferencedCompletedVariants => {
                unreachable!("import maintenance classes use exact manifest admission")
            }
            BlobMaintenanceClass::ExpiredRetirementRecords => {
                bounded_single_maintenance_page_with_charge(
                    &write,
                    BLOB_OPERATIONS,
                    MaintenanceRowKind::Operation,
                    cursor.position.as_deref(),
                    page_charge,
                )?
            }
            BlobMaintenanceClass::ManifestBackedPhysicalDeletion => {
                unreachable!("physical deletion uses descriptor-relative bounded work")
            }
        };

        let mut candidates = Vec::new();
        let mut retired_position = None;
        let mut retirement_charge = None;
        let mut retirement_blocked = None;
        for row in &page.rows {
            match cursor.class {
                BlobMaintenanceClass::ExpiredPublicationsAndPendingSources => match row.position[0]
                {
                    MAINTENANCE_PRIMARY_SOURCE_TAG => match &row.evidence {
                        MaintenanceEvidence::RetiredPublication => {}
                        MaintenanceEvidence::Publication(evidence) => {
                            validate_maintenance_publication(
                                &row.key,
                                &row.value,
                                evidence,
                                self.blob_depot_owner_binding,
                            )?;
                            let publication = decode_blob_metadata(&row.value)?;
                            if !blob_header_is_current_write(&write, &publication.header)? {
                                let transfer =
                                    parse_blob_transfer_id("Blob retirement candidate", &row.key)?;
                                let mut charge = MaintenanceCharge {
                                    budget,
                                    rows: page.rows_examined,
                                    bytes: page.bytes,
                                    identities: page.identities.clone(),
                                };
                                if !lifecycle::charge_maintenance_cursor_write(
                                    &write,
                                    cursor.class,
                                    &mut charge,
                                )? {
                                    retirement_blocked = Some((charge.rows, charge.bytes));
                                    break;
                                }
                                let Some(retirement_plan) =
                                    invalidated_blob_publication_retirement_plan_write(
                                        &write,
                                        self.blob_lifecycle_limits,
                                        transfer,
                                        effective_custody_sample,
                                        &mut charge,
                                    )?
                                else {
                                    retirement_blocked = Some((charge.rows, charge.bytes));
                                    break;
                                };
                                apply_blob_publication_retirement_plan_write(
                                    &write,
                                    self.blob_lifecycle_limits,
                                    retirement_plan,
                                    PublicationPressureApply::RefreshVariant,
                                )?;
                                retired_position = Some(row.position.clone());
                                retirement_charge = Some((charge.rows, charge.bytes));
                                break;
                            }
                        }
                        _ => {
                            return Err(blob_error(BlobStoreError::SchemaInvariant(
                                "Blob publication maintenance row has wrong evidence",
                            )));
                        }
                    },
                    MAINTENANCE_SECONDARY_SOURCE_TAG => {
                        let MaintenanceEvidence::Pending(evidence) = &row.evidence else {
                            return Err(blob_error(BlobStoreError::SchemaInvariant(
                                "Blob pending maintenance row has wrong evidence",
                            )));
                        };
                        validate_maintenance_pending_source(
                            &row.key,
                            &row.value,
                            evidence,
                            self.blob_depot_owner_binding,
                        )?;
                    }
                    _ => unreachable!("bounded composite page emits known tags"),
                },
                BlobMaintenanceClass::InvalidPendingWork => match row.position[0] {
                    MAINTENANCE_PRIMARY_SOURCE_TAG => {
                        let MaintenanceEvidence::Pending(evidence) = &row.evidence else {
                            return Err(blob_error(BlobStoreError::SchemaInvariant(
                                "Blob pending maintenance row has wrong evidence",
                            )));
                        };
                        validate_maintenance_pending_source(
                            &row.key,
                            &row.value,
                            evidence,
                            self.blob_depot_owner_binding,
                        )?;
                    }
                    MAINTENANCE_SECONDARY_SOURCE_TAG => {
                        let MaintenanceEvidence::Carrier(evidence) = &row.evidence else {
                            return Err(blob_error(BlobStoreError::SchemaInvariant(
                                "Blob carrier maintenance row has wrong evidence",
                            )));
                        };
                        validate_maintenance_carrier_prefix(
                            &row.key,
                            &row.value,
                            evidence,
                            self.blob_depot_owner_binding,
                        )?;
                    }
                    _ => unreachable!("bounded composite page emits known tags"),
                },
                BlobMaintenanceClass::UnreferencedLocalImportStaging
                | BlobMaintenanceClass::UnreferencedCompletedVariants => {
                    let MaintenanceEvidence::Import(evidence) = &row.evidence else {
                        return Err(blob_error(BlobStoreError::SchemaInvariant(
                            "Blob import maintenance row has wrong evidence",
                        )));
                    };
                    let import = maintenance_physical_projection(&row.key, &row.value)?;
                    lifecycle::validate_maintenance_lineage_evidence(
                        import.physical_lineage,
                        self.blob_depot_owner_binding,
                        &evidence.lineage,
                    )?;
                    if let Some(reference) = evidence.reference.as_ref() {
                        if reference.key.len() != 65
                            || !reference.key.starts_with(import.variant_id.as_bytes())
                            || !reference.value.is_empty()
                        {
                            return Err(blob_error(BlobStoreError::SchemaInvariant(
                                "Blob variant reference is not canonical",
                            )));
                        }
                        lifecycle::VariantReferenceOwner::decode(&reference.key[32..33])
                            .map_err(StoreError::Blob)?;
                    } else {
                        match (cursor.class, import.finalized) {
                            (BlobMaintenanceClass::UnreferencedLocalImportStaging, false) => {
                                candidates.push(BlobMaintenanceCandidate::UnreferencedLocalImport {
                                    staging_variant: import.variant_id,
                                })
                            }
                            (BlobMaintenanceClass::UnreferencedCompletedVariants, true) => {
                                candidates.push(
                                    BlobMaintenanceCandidate::UnreferencedCompletedVariant {
                                        variant: import.variant_id,
                                    },
                                )
                            }
                            _ => {}
                        }
                    }
                }
                BlobMaintenanceClass::ExpiredRetirementRecords => match &row.evidence {
                    MaintenanceEvidence::Operation { publication } => {
                        validate_maintenance_operation(&row.key, &row.value, publication)?;
                    }
                    MaintenanceEvidence::RetiredOperation => {}
                    _ => {
                        return Err(blob_error(BlobStoreError::SchemaInvariant(
                            "Blob operation maintenance row has wrong evidence",
                        )));
                    }
                },
                BlobMaintenanceClass::ManifestBackedPhysicalDeletion => {}
            }
        }

        let awaiting_later_handler = !candidates.is_empty();
        if let Some((rows_examined, bytes_examined)) = retirement_blocked {
            return Ok(BlobMaintenanceProgress {
                class: cursor.class,
                rows_examined,
                files_examined: 0,
                bytes_examined,
                candidates,
                class_has_more_work: true,
                awaiting_later_handler: false,
            });
        }
        let next_position = if let Some(position) = retired_position.as_deref() {
            Some(position)
        } else if awaiting_later_handler {
            cursor.position.as_deref()
        } else if let Some(last) = page.rows.last() {
            Some(last.position.as_slice())
        } else if page.complete {
            None
        } else {
            cursor.position.as_deref()
        };
        let cursor_charge = if retirement_charge.is_none() {
            let mut charge = MaintenanceCharge {
                budget,
                rows: page.rows_examined,
                bytes: page.bytes,
                identities: page.identities.clone(),
            };
            if !lifecycle::charge_maintenance_cursor_write(&write, cursor.class, &mut charge)? {
                return Ok(BlobMaintenanceProgress {
                    class: cursor.class,
                    rows_examined: charge.rows,
                    files_examined: 0,
                    bytes_examined: charge.bytes,
                    candidates,
                    class_has_more_work: true,
                    awaiting_later_handler: false,
                });
            }
            Some((charge.rows, charge.bytes))
        } else {
            None
        };
        lifecycle::advance_maintenance_cursor(&write, cursor.class, next_position)?;
        let (rows_examined, bytes_examined) = retirement_charge
            .or(cursor_charge)
            .expect("cursor charge is present");
        let progress = BlobMaintenanceProgress {
            class: cursor.class,
            rows_examined,
            files_examined: 0,
            bytes_examined,
            candidates,
            class_has_more_work: !page.complete
                || awaiting_later_handler
                || retired_position.is_some(),
            awaiting_later_handler,
        };
        write.commit()?;
        Ok(progress)
    }
}

fn validate_blob_reservation(
    reservation: &BlobReservation,
    prepared: &PreparedBlobPublication,
) -> Result<(), StoreError> {
    let header = &prepared.header;
    if header.stamp.dot.publisher != reservation.publisher
        || header.stamp.dot.counter != reservation.counter
        || header.topic != reservation.topic
        || header.scope != reservation.scope
        || header.stamp.context != reservation.context
        || header.ttl_ms != reservation.ttl_ms
    {
        return Err(blob_error(BlobStoreError::InvalidPublication(
            "sealed Blob does not match its durable reservation",
        )));
    }
    Ok(())
}

fn validate_blob_publication_intent(
    intent: &BlobPublicationIntent,
    prepared: &PreparedBlobPublication,
) -> Result<(), StoreError> {
    if prepared.header.stamp.dot.publisher != intent.publisher
        || prepared.header.topic != intent.topic
        || prepared.header.scope != intent.scope
        || prepared.header.priority != intent.priority
        || prepared.blob_id != intent.blob_id
        || prepared.header.ttl_ms != intent.ttl_ms
    {
        return Err(blob_error(BlobStoreError::OperationConflict));
    }
    Ok(())
}

fn enforce_blob_policy_write(
    write: &redb::WriteTransaction,
    authority: NodeId,
    expected: &ControlPolicySnapshot,
    header: &EnvelopeHeader,
) -> Result<(), StoreError> {
    require_control_policy_write(write, authority, expected)?;
    let publisher = header.stamp.dot.publisher;
    if control_principal_revoked_write(write, publisher)? {
        return Err(blob_error(BlobStoreError::PublisherRevoked(publisher)));
    }
    let current_epoch = write
        .open_table(CONTROL_SCOPE_EPOCHS)?
        .get(header.scope.as_str())?
        .map(|value| decode_scope_epoch_index(value.value()))
        .transpose()?
        .map_or(1, |(epoch, _)| epoch);
    if header.key_epoch < current_epoch {
        return Err(blob_error(BlobStoreError::KeyEpochStale {
            current: current_epoch,
            received: header.key_epoch,
        }));
    }
    if header.key_epoch > current_epoch {
        return Err(blob_error(BlobStoreError::KeyEpochNotActive {
            current: current_epoch,
            received: header.key_epoch,
        }));
    }
    Ok(())
}

fn enforce_blob_policy_read(
    read: &redb::ReadTransaction,
    authority: NodeId,
    expected: &ControlPolicySnapshot,
    header: &EnvelopeHeader,
) -> Result<(), StoreError> {
    require_control_policy_read(read, authority, expected)?;
    let publisher = header.stamp.dot.publisher;
    if control_principal_revoked_read(read, publisher)? {
        return Err(blob_error(BlobStoreError::PublisherRevoked(publisher)));
    }
    let current_epoch = read
        .open_table(CONTROL_SCOPE_EPOCHS)?
        .get(header.scope.as_str())?
        .map(|value| decode_scope_epoch_index(value.value()))
        .transpose()?
        .map_or(1, |(epoch, _)| epoch);
    if header.key_epoch < current_epoch {
        return Err(blob_error(BlobStoreError::KeyEpochStale {
            current: current_epoch,
            received: header.key_epoch,
        }));
    }
    if header.key_epoch > current_epoch {
        return Err(blob_error(BlobStoreError::KeyEpochNotActive {
            current: current_epoch,
            received: header.key_epoch,
        }));
    }
    Ok(())
}

fn blob_header_is_current_write(
    write: &redb::WriteTransaction,
    header: &EnvelopeHeader,
) -> Result<bool, StoreError> {
    let current_epoch = write
        .open_table(CONTROL_SCOPE_EPOCHS)?
        .get(header.scope.as_str())?
        .map(|value| decode_scope_epoch_index(value.value()))
        .transpose()?
        .map_or(1, |(epoch, _)| epoch);
    if header.key_epoch > current_epoch {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "live Blob publication has a future scope epoch",
        )));
    }
    if control_principal_revoked_write(write, header.stamp.dot.publisher)? {
        return Ok(false);
    }
    Ok(header.key_epoch == current_epoch)
}

/// Incrementally preflights the complete unique-row work unit for one
/// policy-invalidation retirement. Rows already captured by the bounded
/// publication page are supplied in `charge`; each additional logical row is
/// admitted before it is validated. Returning `None` leaves the transaction
/// uncommitted and reports every row admitted up to the caller's budget.
struct BlobOperationRetirementPlan {
    key: Vec<u8>,
    key_digest: [u8; 32],
    live: Vec<u8>,
    intent_digest: [u8; 32],
}

struct BlobPublicationRetirementPlan {
    transfer: BlobTransferId,
    live_record: Vec<u8>,
    variant_id: BlobVariantId,
    semantic_id: BlobSemanticId,
    source_len: u64,
    marker: u64,
    reason: lifecycle::RetirementReason,
    age: lifecycle::RetirementAge,
    deadline: Option<aster_mesh::CustodySample>,
    operation_bytes_removed: u64,
    operation_bytes_added: u64,
    operations: Vec<BlobOperationRetirementPlan>,
    deliveries: crate::blob_subscription::BlobDeliveryRetirementPlan,
}

/// Typed proof that the complete pressure authority for one variant was
/// bounded, charged, and found internally consistent in this transaction.
///
/// Passing this proof to the central publication-retirement planner transfers
/// ownership of the pressure rows already charged by the bounded snapshot;
/// callers cannot bypass pressure preflight with an unstructured boolean.
struct PressureVariantSnapshot {
    variant_id: BlobVariantId,
    references: Vec<(lifecycle::VariantReferenceOwner, BlobTransferId)>,
}

/// Complete, already-charged logical removal unit for one pending pressure
/// root. The pressure snapshot owns the pending/ref/prefix/root/index rows;
/// this plan owns only the distinct TTL and shared accounting rows.
struct PendingRemovalPlan {
    pressure: PressureVariantSnapshot,
    authority: PendingRemovalAuthorityPlan,
}

struct WholeVariantPendingRemovalPlan {
    transfer: BlobTransferId,
    authority: PendingRemovalAuthorityPlan,
}

/// Exact pending/source-prefix authority admitted before one bounded removal.
///
/// Pressure progress may legitimately observe a durable chunk and skip its
/// still-retained carrier prefix after a crash between depot and redb cleanup.
/// Removal nevertheless deletes that prefix, so this plan independently
/// captures and charges every present prefix that apply can touch.
struct PendingRemovalAuthorityPlan {
    source: BlobTransferId,
    encoded_pending: Vec<u8>,
    pending: PendingBlobSourceRecord,
    prefixes: Vec<([u8; BLOB_CARRIER_PREFIX_KEY_BYTES], Vec<u8>)>,
    staging_before: BlobNetworkStagingUsage,
    removed_rows: u64,
    removed_bytes: u64,
}

/// One admitted whole-variant mutation. The shared pressure snapshot and
/// deletion plan are owned once; child plans contain only their distinct
/// publication or pending authority.
struct WholeVariantRetirementPlan {
    pressure: PressureVariantSnapshot,
    publications: Vec<(BlobTransferId, BlobPublicationRetirementPlan)>,
    pending: Vec<WholeVariantPendingRemovalPlan>,
    deletion: Option<deletion::BlobDeletionAdmissionPlan>,
    publication_bytes: u64,
    staging_rows: u64,
    staging_bytes: u64,
}

impl PressureVariantSnapshot {
    fn contains(&self, owner: lifecycle::VariantReferenceOwner, transfer: BlobTransferId) -> bool {
        self.references.contains(&(owner, transfer))
    }
}

enum PublicationPressurePreflight<'a> {
    Required,
    Snapshot(&'a PressureVariantSnapshot),
}

fn plan_pressure_variant_snapshot_write(
    write: &redb::WriteTransaction,
    variant_id: BlobVariantId,
    root_limit: u64,
    charge: &mut MaintenanceCharge,
) -> Result<Option<PressureVariantSnapshot>, StoreError> {
    let Some(references) =
        pressure::bounded_variant_references_write(write, variant_id, root_limit, charge)?
    else {
        return Ok(None);
    };
    if !pressure::require_variant_with_references_bounded_write(
        write,
        variant_id,
        &references,
        charge,
    )? {
        return Ok(None);
    }
    Ok(Some(PressureVariantSnapshot {
        variant_id,
        references,
    }))
}

fn plan_pending_pressure_removal_write(
    write: &redb::WriteTransaction,
    authority: NodeId,
    transfer: BlobTransferId,
    demand: pressure::BlobCapacityRecoveryDemand,
    root_limit: u64,
    charge: &mut MaintenanceCharge,
) -> Result<Option<PendingRemovalPlan>, StoreError> {
    let encoded = write
        .open_table(BLOB_PENDING_SOURCES)?
        .get(transfer.as_bytes().as_slice())?
        .map(|value| value.value().to_vec())
        .ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob pressure pending candidate disappeared",
            ))
        })?;
    let pending = decode_pending_blob_source(&encoded)?;
    if pending.metadata.transfer_id != transfer
        || pending.metadata.header.priority >= demand.incoming_priority()
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob pressure pending candidate changed after ordered selection",
        )));
    }
    let Some(pressure) = plan_pressure_variant_snapshot_write(
        write,
        pending.metadata.variant_id,
        root_limit,
        charge,
    )?
    else {
        return Ok(None);
    };
    if !pressure.contains(lifecycle::VariantReferenceOwner::PendingSource, transfer) {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob pressure pending candidate lacks its variant reference",
        )));
    }

    let Some(authority) =
        plan_pending_removal_authority_write(write, authority, transfer, &pending, charge)?
    else {
        return Ok(None);
    };
    if !lifecycle::charge_policy_ttl_deadline_write(
        transfer,
        lifecycle::TtlDeadlineKind::PendingSource,
        Some(pending.metadata.lifetime),
        None,
        charge,
    )? || !lifecycle::charge_variant_reference_counter(charge)?
    {
        return Ok(None);
    }
    Ok(Some(PendingRemovalPlan {
        pressure,
        authority,
    }))
}

// One bounded retirement unit carries independent durable authority, budget,
// and operation-cap inputs that must remain explicit at every caller.
#[allow(clippy::too_many_arguments)]
fn plan_blob_publication_retirement_write(
    write: &redb::WriteTransaction,
    limits: BlobLifecycleLimits,
    transfer: BlobTransferId,
    reason: lifecycle::RetirementReason,
    pressure_preflight: PublicationPressurePreflight<'_>,
    custody_sample: Option<aster_mesh::CustodySample>,
    charge: &mut MaintenanceCharge,
    remaining_operations: &mut u64,
) -> Result<Option<BlobPublicationRetirementPlan>, StoreError> {
    fn charged_metadata(
        write: &redb::WriteTransaction,
        field: &'static str,
        charge: &mut MaintenanceCharge,
    ) -> Result<Option<u64>, StoreError> {
        if !charge.charge_row(
            MaintenanceRowIdentity::new("aster.metadata.v1", field.as_bytes()),
            std::mem::size_of::<u64>(),
        )? {
            return Ok(None);
        }
        write
            .open_table(METADATA)?
            .get(field)?
            .map(|value| value.value())
            .ok_or(StoreError::MissingAccountingMetadata { field })
            .map(Some)
    }

    let live_record = write
        .open_table(BLOB_PUBLICATIONS)?
        .get(transfer.as_bytes().as_slice())?
        .map(|value| value.value().to_vec())
        .ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob retirement candidate publication disappeared",
            ))
        })?;
    if lifecycle::publication_record_is_retired(&live_record).map_err(blob_error)? {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob retirement charge points to an already-retired publication",
        )));
    }
    let publication = decode_blob_metadata(&live_record)?;
    if publication.transfer_id != transfer {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob retirement charge differs from its publication key",
        )));
    }
    let pressure_precharged = match pressure_preflight {
        PublicationPressurePreflight::Required => false,
        PublicationPressurePreflight::Snapshot(snapshot) => {
            if snapshot.variant_id != publication.variant_id
                || !snapshot.contains(lifecycle::VariantReferenceOwner::Publication, transfer)
            {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "Blob retirement pressure snapshot names another root",
                )));
            }
            true
        }
    };
    if !lifecycle::charge_policy_ttl_deadline_write(
        transfer,
        lifecycle::TtlDeadlineKind::LivePublication,
        Some(publication.lifetime),
        None,
        charge,
    )? || !lifecycle::charge_variant_reference_counter(charge)?
        || (!pressure_precharged
            && !pressure::preflight_policy_root_mutation_write(
                write,
                publication.variant_id,
                lifecycle::VariantReferenceOwner::Publication,
                transfer,
                policy_root_limit(limits)?,
                false,
                charge,
            )?)
    {
        return Ok(None);
    }
    match reason {
        lifecycle::RetirementReason::Invalidated
            if blob_header_is_current_write(write, &publication.header)? =>
        {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob retirement charge no longer names an invalidated publication",
            )));
        }
        lifecycle::RetirementReason::Invalidated | lifecycle::RetirementReason::Evicted => {}
        lifecycle::RetirementReason::Expired => {
            let continuity = custody::lower_bound_continuity_write(write)?;
            if !matches!(
                evaluate_blob_lifetime(publication.lifetime, continuity, custody_sample)?,
                BlobLifetimeEvaluation::FiniteExpired { .. }
            ) {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "Blob expiry retirement candidate is not provably expired",
                )));
            }
        }
    }
    let source_bytes = write.open_table(BLOB_BYTES)?;
    let source = source_bytes
        .get(transfer.as_bytes().as_slice())?
        .ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob retirement candidate is missing source bytes",
            ))
        })?;
    if !charge.charge_row(
        MaintenanceRowIdentity::new("aster.semantic-blob-bytes.v1", transfer.as_bytes()),
        source.value().len(),
    )? {
        return Ok(None);
    }
    let source_len = u64::try_from(source.value().len())
        .map_err(|_| StoreError::PayloadByteAccountingOverflow)?;
    let marker = write
        .open_table(BLOB_ACCEPTANCE_MARKERS)?
        .get(transfer.as_bytes().as_slice())?
        .map(|value| value.value())
        .ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob retirement candidate is missing its acceptance marker",
            ))
        })?;
    if !charge.charge_row(
        MaintenanceRowIdentity::new(
            "aster.semantic-blob-acceptance-order.v1",
            marker.to_be_bytes(),
        ),
        std::mem::size_of::<[u8; 32]>(),
    )? {
        return Ok(None);
    }
    let acceptance_order = write.open_table(crate::blob_subscription::BLOB_ACCEPTANCE_ORDER)?;
    let ordered_transfer = acceptance_order.get(marker)?.ok_or_else(|| {
        blob_error(BlobStoreError::SchemaInvariant(
            "Blob retirement candidate is missing its acceptance-order row",
        ))
    })?;
    if ordered_transfer.value() != transfer.as_bytes() {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob retirement acceptance-order row names another publication",
        )));
    }

    let age = match custody_sample {
        Some(sample) => lifecycle::RetirementAge::new(0, sample, limits.retain_for_ms()),
        None => lifecycle::RetirementAge::unknown(limits.retain_for_ms()),
    }
    .map_err(blob_error)?;
    let deadline = age.project(custody_sample).map_err(blob_error)?.deadline;

    if !lifecycle::policy_retirement_authority_charge_write(
        write,
        lifecycle::RetentionDeadlineOwner::Publication(transfer),
        &[],
        deadline,
        charge,
    )? {
        return Ok(None);
    }

    let Some(item_count) = charged_metadata(write, BLOB_ITEM_COUNT, charge)? else {
        return Ok(None);
    };
    let Some(total_bytes) = charged_metadata(write, BLOB_TOTAL_BYTES, charge)? else {
        return Ok(None);
    };
    let Some(operation_bytes_before) = charged_metadata(write, BLOB_OPERATION_TOTAL_BYTES, charge)?
    else {
        return Ok(None);
    };
    let mut operation_bytes_after = operation_bytes_before;
    let mut operation_bytes_removed = 0u64;
    let mut operation_bytes_added = 0u64;
    if item_count == 0 || total_bytes < source_len {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob retirement aggregate accounting cannot cover its publication",
        )));
    }

    let (start, end) = lifecycle::inverse_owner_bounds(transfer);
    let owners = write.open_table(lifecycle::BLOB_OPERATION_OWNERS)?;
    let operations = write.open_table(BLOB_OPERATIONS)?;
    let mut operation_rows = 0u64;
    let mut operation_plans = Vec::new();
    for row in owners.range::<&[u8]>((
        std::ops::Bound::Included(start.as_slice()),
        std::ops::Bound::Included(end.as_slice()),
    ))? {
        let (owner_key, operation_key) = row?;
        if !charge.charge(owner_key.value(), operation_key.value().len())? {
            return Ok(None);
        }
        if lifecycle::inverse_owner_key(transfer, operation_key.value()).as_slice()
            != owner_key.value()
        {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob operation inverse owner is not canonical",
            )));
        }
        operation_rows = operation_rows
            .checked_add(1)
            .ok_or(StoreError::ItemCountAccountingOverflow)?;
        let Some(next_remaining) = remaining_operations.checked_sub(1) else {
            // The charged plus-one inverse row proves this atomic candidate
            // exceeds the operation dimension without collecting the fan-out.
            return Ok(None);
        };
        *remaining_operations = next_remaining;
        if operation_rows > MAX_BLOB_OPERATIONS {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob operation inverse-owner fan-out exceeds its structural bound",
            )));
        }
        let active = operations.get(operation_key.value())?.ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob operation owner points to a missing operation",
            ))
        })?;
        if !charge.charge(operation_key.value(), active.value().len())? {
            return Ok(None);
        }
        let operation = decode_blob_operation_record(active.value())?;
        if operation.transfer_id != transfer {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob operation owner points to another publication",
            )));
        }
        let retired = lifecycle::retired_operation_record(
            reason,
            1,
            Sha256::digest(operation_key.value()).into(),
            operation.intent_digest,
            age,
        );
        operation_bytes_after = operation_bytes_after
            .checked_sub(
                u64::try_from(active.value().len())
                    .map_err(|_| StoreError::PayloadByteAccountingOverflow)?,
            )
            .and_then(|value| value.checked_add(u64::try_from(retired.len()).ok()?))
            .ok_or(StoreError::PayloadByteAccountingOverflow)?;
        operation_bytes_removed = operation_bytes_removed
            .checked_add(
                u64::try_from(active.value().len())
                    .map_err(|_| StoreError::PayloadByteAccountingOverflow)?,
            )
            .ok_or(StoreError::PayloadByteAccountingOverflow)?;
        operation_bytes_added = operation_bytes_added
            .checked_add(
                u64::try_from(retired.len())
                    .map_err(|_| StoreError::PayloadByteAccountingOverflow)?,
            )
            .ok_or(StoreError::PayloadByteAccountingOverflow)?;
        let operation_digest = Sha256::digest(operation_key.value()).into();
        if !lifecycle::policy_retirement_authority_charge_write(
            write,
            lifecycle::RetentionDeadlineOwner::Operation(operation_digest),
            operation_key.value(),
            deadline,
            charge,
        )? {
            return Ok(None);
        }
        operation_plans.push(BlobOperationRetirementPlan {
            key: operation_key.value().to_vec(),
            key_digest: operation_digest,
            live: active.value().to_vec(),
            intent_digest: operation.intent_digest,
        });
    }
    if operation_bytes_after > MAX_BLOB_DURABLE_OPERATION_BYTES {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "retired Blob operation usage exceeds its durable safety cap",
        )));
    }

    if !lifecycle::policy_retirement_accounting_charge_write(
        write,
        limits,
        operation_rows,
        deadline.is_some(),
        charge,
    )? {
        return Ok(None);
    }
    let Some(deliveries) = crate::blob_subscription::plan_blob_delivery_retirement_write(
        write,
        transfer,
        publication.semantic_id,
        reason,
        charge,
    )?
    else {
        return Ok(None);
    };
    Ok(Some(BlobPublicationRetirementPlan {
        transfer,
        live_record,
        variant_id: publication.variant_id,
        semantic_id: publication.semantic_id,
        source_len,
        marker,
        reason,
        age,
        deadline,
        operation_bytes_removed,
        operation_bytes_added,
        operations: operation_plans,
        deliveries,
    }))
}

fn invalidated_blob_publication_retirement_plan_write(
    write: &redb::WriteTransaction,
    limits: BlobLifecycleLimits,
    transfer: BlobTransferId,
    custody_sample: Option<aster_mesh::CustodySample>,
    charge: &mut MaintenanceCharge,
) -> Result<Option<BlobPublicationRetirementPlan>, StoreError> {
    let mut remaining_operations = MAX_BLOB_OPERATIONS;
    plan_blob_publication_retirement_write(
        write,
        limits,
        transfer,
        lifecycle::RetirementReason::Invalidated,
        PublicationPressurePreflight::Required,
        custody_sample,
        charge,
        &mut remaining_operations,
    )
}

#[cfg(test)]
fn invalidated_blob_publication_retirement_charge_write(
    write: &redb::WriteTransaction,
    limits: BlobLifecycleLimits,
    transfer: BlobTransferId,
    custody_sample: Option<aster_mesh::CustodySample>,
    charge: &mut MaintenanceCharge,
) -> Result<bool, StoreError> {
    invalidated_blob_publication_retirement_plan_write(
        write,
        limits,
        transfer,
        custody_sample,
        charge,
    )
    .map(|plan| plan.is_some())
}

fn apply_blob_publication_retirement_plan_write(
    write: &redb::WriteTransaction,
    limits: BlobLifecycleLimits,
    plan: BlobPublicationRetirementPlan,
    pressure_apply: PublicationPressureApply,
) -> Result<(), StoreError> {
    let BlobPublicationRetirementPlan {
        transfer,
        live_record,
        variant_id,
        semantic_id,
        source_len,
        marker,
        reason,
        age,
        deadline,
        operation_bytes_removed,
        operation_bytes_added,
        operations,
        deliveries,
    } = plan;
    let current_publication = write
        .open_table(BLOB_PUBLICATIONS)?
        .get(transfer.as_bytes().as_slice())?
        .map(|value| value.value().to_vec())
        .ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob retirement candidate publication disappeared",
            ))
        })?;
    if current_publication != live_record {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "planned Blob retirement publication changed before apply",
        )));
    }
    lifecycle::replace_policy_ttl_deadline_write(
        write,
        transfer,
        lifecycle::TtlDeadlineKind::LivePublication,
        Some(decode_blob_metadata(&live_record)?.lifetime),
        None,
        limits,
    )?;
    pressure::require_publication_write(write, transfer)?;
    if matches!(pressure_apply, PublicationPressureApply::RefreshVariant) {
        pressure::require_variant_write(write, variant_id)?;
    }
    lifecycle::require_variant_reference(
        write,
        variant_id,
        lifecycle::VariantReferenceOwner::Publication,
        transfer,
    )?;
    let generation = lifecycle::allocate_retirement_generation(write)?;
    crate::blob_subscription::apply_blob_delivery_retirement_plan_write(
        write,
        deliveries,
        semantic_id,
        generation,
    )?;

    let retired_publication =
        lifecycle::retired_publication_record(&live_record, marker, reason, generation, age)?;
    write.open_table(BLOB_PUBLICATIONS)?.insert(
        transfer.as_bytes().as_slice(),
        retired_publication.as_slice(),
    )?;
    let removed_source_len = {
        let mut sources = write.open_table(BLOB_BYTES)?;
        let removed = sources
            .remove(transfer.as_bytes().as_slice())?
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob retirement lost exact source bytes",
                ))
            })?;
        u64::try_from(removed.value().len())
            .map_err(|_| StoreError::PayloadByteAccountingOverflow)?
    };
    if removed_source_len != source_len {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "planned Blob retirement source bytes changed before apply",
        )));
    }
    let removed_marker = {
        let mut markers = write.open_table(BLOB_ACCEPTANCE_MARKERS)?;
        markers
            .remove(transfer.as_bytes().as_slice())?
            .map(|value| value.value())
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob retirement lost its acceptance marker",
                ))
            })?
    };
    if removed_marker != marker {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "planned Blob retirement marker changed before apply",
        )));
    }
    let removed_order = {
        let mut order = write.open_table(crate::blob_subscription::BLOB_ACCEPTANCE_ORDER)?;
        order
            .remove(marker)?
            .map(|value| value.value().to_vec())
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob retirement lost its acceptance-order row",
                ))
            })?
    };
    if removed_order.as_slice() != transfer.as_bytes() {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "planned Blob retirement acceptance order changed before apply",
        )));
    }
    lifecycle::remove_variant_reference(
        write,
        variant_id,
        lifecycle::VariantReferenceOwner::Publication,
        transfer,
    )?;
    lifecycle::record_publication_retirement(write)?;
    lifecycle::insert_retirement_resolver(
        write,
        limits,
        lifecycle::RetentionDeadlineOwner::Publication(transfer),
        None,
    )?;
    if let Some(deadline) = deadline {
        lifecycle::insert_retention_deadline(
            write,
            limits,
            deadline,
            lifecycle::RetentionDeadlineOwner::Publication(transfer),
        )?;
    }

    for operation in operations {
        let current = write
            .open_table(BLOB_OPERATIONS)?
            .get(operation.key.as_slice())?
            .map(|value| value.value().to_vec())
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "planned Blob operation disappeared before retirement",
                ))
            })?;
        if current != operation.live {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "planned Blob operation changed before retirement",
            )));
        }
        let retired = lifecycle::retired_operation_record(
            reason,
            generation,
            operation.key_digest,
            operation.intent_digest,
            age,
        );
        write
            .open_table(BLOB_OPERATIONS)?
            .insert(operation.key.as_slice(), retired.as_slice())?;
        lifecycle::remove_operation_owner(write, transfer, &operation.key)?;
        lifecycle::record_operation_retirement(write)?;
        lifecycle::insert_retirement_resolver(
            write,
            limits,
            lifecycle::RetentionDeadlineOwner::Operation(operation.key_digest),
            Some(&operation.key),
        )?;
        if let Some(deadline) = deadline {
            lifecycle::insert_retention_deadline(
                write,
                limits,
                deadline,
                lifecycle::RetentionDeadlineOwner::Operation(operation.key_digest),
            )?;
        }
    }
    let mut metadata = write.open_table(METADATA)?;
    let current_items = metadata
        .get(BLOB_ITEM_COUNT)?
        .ok_or(StoreError::MissingAccountingMetadata {
            field: BLOB_ITEM_COUNT,
        })?
        .value();
    let current_bytes = metadata
        .get(BLOB_TOTAL_BYTES)?
        .ok_or(StoreError::MissingAccountingMetadata {
            field: BLOB_TOTAL_BYTES,
        })?
        .value();
    let current_operation_bytes = metadata
        .get(BLOB_OPERATION_TOTAL_BYTES)?
        .ok_or(StoreError::MissingAccountingMetadata {
            field: BLOB_OPERATION_TOTAL_BYTES,
        })?
        .value();
    let operation_bytes_after = current_operation_bytes
        .checked_sub(operation_bytes_removed)
        .and_then(|bytes| bytes.checked_add(operation_bytes_added))
        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
    if operation_bytes_after > MAX_BLOB_DURABLE_OPERATION_BYTES {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "retired Blob operation usage exceeds its durable safety cap",
        )));
    }
    metadata.insert(
        BLOB_ITEM_COUNT,
        current_items.checked_sub(1).ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob item count underflows on retirement",
            ))
        })?,
    )?;
    metadata.insert(
        BLOB_TOTAL_BYTES,
        current_bytes.checked_sub(source_len).ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob byte count underflows on retirement",
            ))
        })?,
    )?;
    metadata.insert(BLOB_OPERATION_TOTAL_BYTES, operation_bytes_after)?;
    drop(metadata);
    match pressure_apply {
        PublicationPressureApply::RefreshVariant => {
            pressure::remove_publication_write(write, transfer, variant_id)?;
        }
        PublicationPressureApply::RemoveRootOnly => {
            pressure::remove_publication_root_write(write, transfer, variant_id)?;
        }
    }
    Ok(())
}

#[derive(Clone, Copy)]
enum PublicationPressureApply {
    RefreshVariant,
    /// A parent whole/final-variant plan removes the shared summary/index only
    /// after all child roots have committed.
    RemoveRootOnly,
}

fn blob_header_is_current_read(
    read: &redb::ReadTransaction,
    header: &EnvelopeHeader,
) -> Result<bool, StoreError> {
    if control_principal_revoked_read(read, header.stamp.dot.publisher)? {
        return Ok(false);
    }
    let current_epoch = read
        .open_table(CONTROL_SCOPE_EPOCHS)?
        .get(header.scope.as_str())?
        .map(|value| decode_scope_epoch_index(value.value()))
        .transpose()?
        .map_or(1, |(epoch, _)| epoch);
    Ok(header.key_epoch == current_epoch)
}

fn durable_blob_source_shape_read(
    read: &redb::ReadTransaction,
    metadata: &BlobMetadata,
    completed: bool,
) -> Result<depot::BlobSourceShape, StoreError> {
    let route = metadata.header.blob_route.ok_or_else(|| {
        blob_error(BlobStoreError::SchemaInvariant(
            "retained Blob source is missing its authenticated route commitment",
        ))
    })?;
    let physical_lineage = metadata
        .physical_lineage
        .ok_or_else(|| blob_error(BlobStoreError::PhysicalLineageMigrationRequired))?;
    depot::blob_source_shape_read(
        read,
        metadata.variant_id,
        metadata.blob_id,
        metadata.header.key_epoch,
        physical_lineage,
        metadata.manifest_digest,
        route.chunk_count(),
        completed,
    )
}

fn require_blob_apply_capacity_read(
    read: &redb::ReadTransaction,
    limits: StoreLimits,
    metadata: &BlobMetadata,
    incoming: u64,
) -> Result<(), StoreError> {
    let frontier_prefix = event_domain_prefix(&metadata.header.topic, &metadata.header.scope)?;
    let frontier_upper = blob_content_prefix_upper_bound(&frontier_prefix)?;
    let frontier = read.open_table(CAUSAL_FRONTIER)?;
    let mut direct_publishers = 0usize;
    let mut incoming_present = false;
    for row in frontier.range::<&[u8]>((
        std::ops::Bound::<&[u8]>::Included(frontier_prefix.as_slice()),
        std::ops::Bound::<&[u8]>::Excluded(frontier_upper.as_slice()),
    ))? {
        let (key, value) = row?;
        let key = key.value();
        if key.len() != frontier_prefix.len() + 32 || value.value() == 0 {
            return Err(StoreError::SemanticInvariant(
                "causal frontier contains an invalid row",
            ));
        }
        direct_publishers = direct_publishers
            .checked_add(1)
            .ok_or(StoreError::ItemCountAccountingOverflow)?;
        if key[frontier_prefix.len()..] == metadata.header.stamp.dot.publisher {
            incoming_present = true;
        }
    }
    if direct_publishers > MAX_CAUSAL_CONTEXT_ENTRIES {
        return Err(StoreError::SemanticInvariant(
            "causal frontier exceeds the proven context bound",
        ));
    }
    if !incoming_present && direct_publishers == MAX_CAUSAL_CONTEXT_ENTRIES {
        return Err(blob_error(BlobStoreError::CausalFrontierLimitExceeded {
            current: direct_publishers,
            limit: MAX_CAUSAL_CONTEXT_ENTRIES,
        }));
    }

    let content_prefix = blob_content_prefix(
        &metadata.header.topic,
        &metadata.header.scope,
        metadata.blob_id,
    )?;
    let content_upper = blob_content_prefix_upper_bound(&content_prefix)?;
    let content = read.open_table(BLOB_CONTENT_INDEX)?;
    let mut publication_count = 0usize;
    for row in content.range::<&[u8]>((
        std::ops::Bound::<&[u8]>::Included(content_prefix.as_slice()),
        std::ops::Bound::<&[u8]>::Excluded(content_upper.as_slice()),
    ))? {
        let (_, value) = row?;
        #[cfg(test)]
        TEST_BLOB_CAPACITY_CONTENT_ROWS_VISITED
            .with(|count| count.set(count.get().saturating_add(1)));
        let transfer = parse_blob_transfer_id("Blob content index", value.value())?;
        let publication = read
            .open_table(BLOB_PUBLICATIONS)?
            .get(transfer.as_bytes().as_slice())?
            .map(|value| value.value().to_vec())
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob content index points to a missing publication",
                ))
            })?;
        if lifecycle::publication_record_is_retired(&publication).map_err(blob_error)? {
            continue;
        }
        publication_count = publication_count
            .checked_add(1)
            .ok_or(StoreError::ItemCountAccountingOverflow)?;
        if publication_count >= MAX_BLOB_PUBLICATIONS_PER_CONTENT {
            break;
        }
    }
    if publication_count >= MAX_BLOB_PUBLICATIONS_PER_CONTENT {
        return Err(blob_error(BlobStoreError::PublicationLimitExceeded {
            current: publication_count,
            limit: MAX_BLOB_PUBLICATIONS_PER_CONTENT,
        }));
    }

    let aggregate = read.open_table(METADATA)?;
    let total = aggregate_usage_read(read, &aggregate)?;
    if total
        .items
        .checked_add(1)
        .ok_or(StoreError::ItemCountAccountingOverflow)?
        > limits.max_items()
    {
        return Err(StoreError::ItemLimitExceeded {
            current: total.items,
            limit: limits.max_items(),
        });
    }
    if total
        .bytes
        .checked_add(incoming)
        .ok_or(StoreError::PayloadByteAccountingOverflow)?
        > limits.max_total_payload_bytes()
    {
        return Err(StoreError::PayloadByteLimitExceeded {
            current: total.bytes,
            incoming,
            limit: limits.max_total_payload_bytes(),
        });
    }
    let control = CustodyUsage {
        items: aggregate
            .get(CONTROL_ITEM_COUNT)?
            .map_or(0, |value| value.value()),
        bytes: aggregate
            .get(CONTROL_TOTAL_BYTES)?
            .map_or(0, |value| value.value())
            .checked_add(
                aggregate
                    .get(CONTROL_PUBLICATION_INTENT_TOTAL_BYTES)?
                    .map_or(0, |value| value.value()),
            )
            .ok_or(StoreError::PayloadByteAccountingOverflow)?,
    };
    let tombstone_payload = custody::selected_tombstone_payload_usage_read(read)?;
    let tombstone = CustodyUsage {
        items: tombstone_payload
            .items
            .checked_add(
                aggregate
                    .get(EVENT_TOMBSTONE_OPERATION_COUNT)?
                    .map_or(0, |value| value.value()),
            )
            .ok_or(StoreError::ItemCountAccountingOverflow)?,
        bytes: tombstone_payload
            .bytes
            .checked_add(
                aggregate
                    .get(EVENT_TOMBSTONE_OPERATION_TOTAL_BYTES)?
                    .map_or(0, |value| value.value()),
            )
            .ok_or(StoreError::PayloadByteAccountingOverflow)?,
    };
    let ordinary = CustodyUsage {
        items: total
            .items
            .checked_sub(control.items)
            .and_then(|value| value.checked_sub(tombstone.items))
            .ok_or(StoreError::SemanticInvariant(
                "classified aggregate item accounting exceeds total usage",
            ))?,
        bytes: total
            .bytes
            .checked_sub(control.bytes)
            .and_then(|value| value.checked_sub(tombstone.bytes))
            .ok_or(StoreError::SemanticInvariant(
                "classified aggregate byte accounting exceeds total usage",
            ))?,
    };
    let (item_reserve, byte_reserve) = custody::custody_emergency_reserve(limits);
    let max_items = limits
        .max_items()
        .checked_sub(item_reserve)
        .ok_or(StoreError::ItemCountAccountingOverflow)?;
    if ordinary
        .items
        .checked_add(1)
        .ok_or(StoreError::ItemCountAccountingOverflow)?
        > max_items
    {
        return Err(StoreError::ItemLimitExceeded {
            current: ordinary.items,
            limit: max_items,
        });
    }
    let max_bytes = limits
        .max_total_payload_bytes()
        .checked_sub(byte_reserve)
        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
    if ordinary
        .bytes
        .checked_add(incoming)
        .ok_or(StoreError::PayloadByteAccountingOverflow)?
        > max_bytes
    {
        return Err(StoreError::PayloadByteLimitExceeded {
            current: ordinary.bytes,
            incoming,
            limit: max_bytes,
        });
    }
    Ok(())
}

fn blob_source_projection(
    metadata: &BlobMetadata,
    sealed_len: u64,
    shape: depot::BlobSourceShape,
) -> Result<BlobSourceProjection, StoreError> {
    let route_lineage = metadata
        .route_lineage
        .ok_or_else(|| blob_error(BlobStoreError::PhysicalLineageMigrationRequired))?;
    let physical_lineage = metadata
        .physical_lineage
        .ok_or_else(|| blob_error(BlobStoreError::PhysicalLineageMigrationRequired))?;
    let route = metadata.header.blob_route.ok_or_else(|| {
        blob_error(BlobStoreError::SchemaInvariant(
            "retained Blob source is missing its authenticated route commitment",
        ))
    })?;
    let expected_chunks = shape
        .total_len
        .checked_add(u64::from(shape.chunk_size).saturating_sub(1))
        .filter(|_| shape.chunk_size != 0)
        .map(|bytes| bytes / u64::from(shape.chunk_size));
    if (shape.chunk_size != SELECTED_BLOB_CHUNK_SIZE
        && shape.chunk_size != aster_mesh::BLOB_STREAM_SEGMENT_BYTES as u32)
        || shape.chunk_count != route.chunk_count()
        || expected_chunks != Some(shape.chunk_count)
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "retained Blob source has a noncanonical durable content shape",
        )));
    }
    let encoded = encode_blob_metadata(metadata.clone())?;
    let mut digest = Sha256::new();
    digest.update(BLOB_SOURCE_PROJECTION_DOMAIN);
    digest.update(&encoded);
    digest.update(sealed_len.to_be_bytes());
    digest.update(shape.total_len.to_be_bytes());
    digest.update(shape.chunk_size.to_be_bytes());
    digest.update(shape.chunk_count.to_be_bytes());
    Ok(BlobSourceProjection {
        transfer_id: metadata.transfer_id,
        semantic_id: metadata.semantic_id,
        publisher: metadata.header.stamp.dot.publisher,
        topic: metadata.header.topic.clone(),
        scope: metadata.header.scope.clone(),
        epoch: metadata.header.key_epoch,
        sealed_len,
        route_lineage,
        physical_lineage,
        manifest_digest: metadata.manifest_digest,
        blob_id: metadata.blob_id,
        total_len: shape.total_len,
        chunk_size: shape.chunk_size,
        chunk_count: shape.chunk_count,
        metadata_fingerprint: digest.finalize().into(),
    })
}

fn verified_blob_source_projection(
    blob: &ContentVerifiedBlobEnvelope,
    sealed_len: u64,
    lifetime: BlobLifetime,
) -> Result<BlobSourceProjection, StoreError> {
    let metadata = BlobMetadata {
        transfer_id: BlobTransferId::new(blob.envelope_id()),
        semantic_id: BlobSemanticId::new(blob.item_id()),
        blob_id: blob.blob_id(),
        variant_id: blob_variant_id(
            blob.blob_id(),
            blob.manifest().content_group(),
            blob.manifest().content_epoch(),
        ),
        manifest_digest: *blob.manifest_digest(),
        route_lineage: Some(*blob.route_lineage().binding()),
        physical_lineage: Some(*blob.physical_lineage().binding()),
        lifetime,
        header: blob.header().clone(),
    };
    blob_source_projection(
        &metadata,
        sealed_len,
        depot::BlobSourceShape {
            total_len: blob.manifest().total_len(),
            chunk_size: blob.manifest().chunk_size(),
            chunk_count: blob.manifest().chunk_count(),
        },
    )
}

fn blob_replay_fence(
    metadata: &BlobMetadata,
    sealed: &[u8],
) -> Result<lifecycle::ReplayFence, StoreError> {
    let source_len =
        u64::try_from(sealed.len()).map_err(|_| StoreError::PayloadByteAccountingOverflow)?;
    let dot = metadata.header.stamp.dot;
    Ok(lifecycle::ReplayFence::new(
        dot.publisher,
        dot.counter,
        metadata.semantic_id,
        metadata.transfer_id,
        source_len,
        Sha256::digest(sealed).into(),
    ))
}

fn insert_blob_operation(
    write: &redb::WriteTransaction,
    limits: StoreLimits,
    request: &BlobOperationRequest<'_>,
    transfer_id: BlobTransferId,
) -> Result<(), StoreError> {
    let owner_key = blob_operation_owner_key(&blob_operation_owner_for_request(request))?;
    let encoded = encode_blob_operation_record(BlobOperationRecord {
        transfer_id,
        intent_digest: request.intent.digest(),
    });
    let encoded = lifecycle::active_operation_record(write, &encoded)?;
    let incoming = owner_key
        .len()
        .checked_add(encoded.len())
        .and_then(|value| u64::try_from(value).ok())
        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
    let mut metadata = write.open_table(METADATA)?;
    let current_count = metadata
        .get(BLOB_OPERATION_COUNT)?
        .map_or(0, |value| value.value());
    let next_count = current_count
        .checked_add(1)
        .ok_or(StoreError::ItemCountAccountingOverflow)?;
    if next_count > MAX_BLOB_OPERATIONS {
        return Err(blob_error(BlobStoreError::OperationLimitExceeded {
            current: current_count,
            limit: MAX_BLOB_OPERATIONS,
        }));
    }
    let current_bytes = metadata
        .get(BLOB_OPERATION_TOTAL_BYTES)?
        .map_or(0, |value| value.value());
    let next_bytes = current_bytes
        .checked_add(incoming)
        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
    let next_byte_limit = MAX_BLOB_OPERATION_BYTES
        .checked_add(
            next_count
                .checked_mul(BLOB_OPERATION_OWNER_KEY_PREFIX_BYTES as u64)
                .ok_or(StoreError::PayloadByteAccountingOverflow)?,
        )
        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
    if next_bytes > next_byte_limit {
        return Err(blob_error(BlobStoreError::OperationByteLimitExceeded {
            current: current_bytes,
            incoming,
            limit: next_byte_limit,
        }));
    }
    let aggregate_incoming = incoming
        .checked_add(MAX_BLOB_OPERATION_RETIREMENT_GROWTH_BYTES)
        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
    require_ordinary_aggregate_capacity(write, &metadata, limits, 1, aggregate_incoming)?;
    metadata.insert(BLOB_OPERATION_COUNT, next_count)?;
    metadata.insert(BLOB_OPERATION_TOTAL_BYTES, next_bytes)?;
    drop(metadata);
    write
        .open_table(BLOB_OPERATIONS)?
        .insert(owner_key.as_slice(), encoded.as_slice())?;
    lifecycle::insert_operation_owner(write, transfer_id, &owner_key)?;
    Ok(())
}

fn blob_read_plan_read(
    read: &redb::ReadTransaction,
    policy: ControlPolicySnapshot,
    topic: &Topic,
    scope: &Scope,
    blob_id: BlobId,
) -> Result<BlobReadPlan, StoreError> {
    let prefix = blob_content_prefix(topic, scope, blob_id)?;
    let upper = blob_content_prefix_upper_bound(&prefix)?;
    let content = read.open_table(BLOB_CONTENT_INDEX)?;
    let mut rows = Vec::new();
    let mut saw_retired = false;
    for row in content.range::<&[u8]>((
        std::ops::Bound::<&[u8]>::Included(prefix.as_slice()),
        std::ops::Bound::<&[u8]>::Excluded(upper.as_slice()),
    ))? {
        let (key, value) = row?;
        #[cfg(test)]
        TEST_BLOB_READ_PLAN_ROWS_VISITED.with(|count| count.set(count.get().saturating_add(1)));
        if rows.len() >= MAX_BLOB_PUBLICATIONS_PER_CONTENT {
            return Err(blob_error(BlobStoreError::PublicationLimitExceeded {
                current: rows.len() + 1,
                limit: MAX_BLOB_PUBLICATIONS_PER_CONTENT,
            }));
        }
        let transfer = parse_blob_transfer_id("Blob content index", value.value())?;
        let publication = read
            .open_table(BLOB_PUBLICATIONS)?
            .get(transfer.as_bytes().as_slice())?
            .map(|value| value.value().to_vec())
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob content index points to a missing publication",
                ))
            })?;
        if lifecycle::publication_record_is_retired(&publication).map_err(blob_error)? {
            let (metadata, _) = decode_retired_blob_metadata(&publication)?.ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "retired Blob publication is missing lookup metadata",
                ))
            })?;
            if metadata.transfer_id != transfer
                || blob_content_key(
                    &metadata.header.topic,
                    &metadata.header.scope,
                    metadata.blob_id,
                    metadata.semantic_id,
                )? != key.value()
            {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "retired Blob content lookup disagrees with its publication",
                )));
            }
            saw_retired = true;
            continue;
        }
        let metadata = decode_blob_metadata(&publication)?;
        if !blob_lifetime_is_visible_read(read, metadata.lifetime)? {
            saw_retired = true;
            continue;
        }
        rows.push(blob_read_candidate_projection_read(
            read,
            transfer,
            key.value(),
        )?);
    }
    if rows.is_empty() && saw_retired {
        return Err(blob_error(BlobStoreError::ExpiredOrRetired));
    }
    if rows.is_empty() {
        return Err(blob_error(BlobStoreError::NotFound));
    }
    rows.sort_by_key(|candidate| candidate.projection.semantic_id);
    let current_epoch = read
        .open_table(CONTROL_SCOPE_EPOCHS)?
        .get(scope.as_str())?
        .map(|value| decode_scope_epoch_index(value.value()))
        .transpose()?
        .map_or(1, |(epoch, _)| epoch);
    let mut active = Vec::with_capacity(rows.len());
    for candidate in &rows {
        active.push(
            candidate.projection.epoch == current_epoch
                && !control_principal_revoked_read(read, candidate.projection.publisher)?,
        );
    }
    let selected = rows
        .iter()
        .zip(&active)
        .filter(|(_, active)| **active)
        .map(|(candidate, _)| candidate.projection.semantic_id)
        .max();
    let candidates = rows
        .into_iter()
        .zip(active)
        .map(|(mut candidate, active)| {
            candidate.disposition = if !active {
                None
            } else if Some(candidate.projection.semantic_id) == selected {
                Some(BlobPublicationDisposition::Current)
            } else {
                Some(BlobPublicationDisposition::Alternate)
            };
            candidate
        })
        .collect();
    Ok(BlobReadPlan {
        control_policy: policy,
        topic: topic.clone(),
        scope: scope.clone(),
        blob_id,
        candidates,
    })
}

fn blob_read_candidate_projection_read(
    read: &redb::ReadTransaction,
    transfer_id: BlobTransferId,
    indexed_content_key: &[u8],
) -> Result<BlobReadCandidate, StoreError> {
    let metadata = read
        .open_table(BLOB_PUBLICATIONS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| decode_blob_metadata(value.value()))
        .transpose()?
        .ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob content index points to a missing publication",
            ))
        })?;
    if metadata.transfer_id != transfer_id
        || blob_content_key(
            &metadata.header.topic,
            &metadata.header.scope,
            metadata.blob_id,
            metadata.semantic_id,
        )? != indexed_content_key
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob content index disagrees with its exact publication",
        )));
    }
    let sealed_len = {
        let bytes = read.open_table(BLOB_BYTES)?;
        let sealed = bytes
            .get(transfer_id.as_bytes().as_slice())?
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob publication is missing exact source bytes",
                ))
            })?;
        u64::try_from(sealed.value().len())
            .map_err(|_| StoreError::PayloadByteAccountingOverflow)?
    };
    let acceptance_marker = read
        .open_table(BLOB_ACCEPTANCE_MARKERS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| value.value())
        .ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob publication is missing its acceptance marker",
            ))
        })?;
    if acceptance_marker == 0 {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob publication has an invalid acceptance marker",
        )));
    }
    let shape = durable_blob_source_shape_read(read, &metadata, true)?;
    Ok(BlobReadCandidate {
        projection: blob_source_projection(&metadata, sealed_len, shape)?,
        acceptance_marker,
        disposition: None,
    })
}

fn completed_blob_range_source_snapshot_read(
    read: &redb::ReadTransaction,
    transfer_id: BlobTransferId,
) -> Result<Option<CompletedBlobRangeSourceSnapshot>, StoreError> {
    let Some(encoded) = read
        .open_table(BLOB_PUBLICATIONS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| value.value().to_vec())
    else {
        return Ok(None);
    };
    if lifecycle::publication_record_is_retired(&encoded).map_err(blob_error)? {
        return Err(blob_error(BlobStoreError::ExpiredOrRetired));
    }
    let metadata = decode_blob_metadata(&encoded)?;
    if metadata.transfer_id != transfer_id {
        return Err(blob_error(BlobStoreError::CompletionMismatch));
    }
    let sealed_len = {
        let bytes = read.open_table(BLOB_BYTES)?;
        let sealed = bytes
            .get(transfer_id.as_bytes().as_slice())?
            .ok_or_else(|| blob_error(BlobStoreError::CompletionMismatch))?;
        if BlobTransferId::new(Sha256::digest(sealed.value()).into()) != transfer_id {
            return Err(blob_error(BlobStoreError::CompletionMismatch));
        }
        u64::try_from(sealed.value().len())
            .map_err(|_| StoreError::PayloadByteAccountingOverflow)?
    };
    let acceptance_marker = read
        .open_table(BLOB_ACCEPTANCE_MARKERS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| value.value())
        .filter(|marker| *marker != 0)
        .ok_or_else(|| blob_error(BlobStoreError::CompletionMismatch))?;
    let shape = durable_blob_source_shape_read(read, &metadata, true)?;
    Ok(Some(CompletedBlobRangeSourceSnapshot {
        projection: blob_source_projection(&metadata, sealed_len, shape)?,
        metadata,
        acceptance_marker,
    }))
}

fn completed_blob_range_source_postcheck_read(
    read: &redb::ReadTransaction,
    initial: &CompletedBlobRangeSourceSnapshot,
) -> Result<bool, StoreError> {
    let transfer_id = initial.metadata.transfer_id;
    let Some(encoded) = read
        .open_table(BLOB_PUBLICATIONS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| value.value().to_vec())
    else {
        return Ok(false);
    };
    if lifecycle::publication_record_is_retired(&encoded).map_err(blob_error)? {
        let Some((acceptance_marker, payload)) =
            lifecycle::retired_publication_payload(&encoded).map_err(blob_error)?
        else {
            return Ok(false);
        };
        return Ok(acceptance_marker == initial.acceptance_marker
            && blob_metadata_immutable_identity_eq(
                &decode_blob_metadata(payload)?,
                &initial.metadata,
            ));
    }
    let Some(current) = completed_blob_range_source_snapshot_read(read, transfer_id)? else {
        return Ok(false);
    };
    Ok(current.acceptance_marker == initial.acceptance_marker
        && blob_source_projection_immutable_identity_eq(&current.projection, &initial.projection)
        && blob_metadata_immutable_identity_eq(&current.metadata, &initial.metadata))
}

fn blob_source_projection_immutable_identity_eq(
    left: &BlobSourceProjection,
    right: &BlobSourceProjection,
) -> bool {
    left.transfer_id == right.transfer_id
        && left.semantic_id == right.semantic_id
        && left.publisher == right.publisher
        && left.topic == right.topic
        && left.scope == right.scope
        && left.epoch == right.epoch
        && left.sealed_len == right.sealed_len
        && left.route_lineage == right.route_lineage
        && left.physical_lineage == right.physical_lineage
        && left.manifest_digest == right.manifest_digest
        && left.blob_id == right.blob_id
        && left.total_len == right.total_len
        && left.chunk_size == right.chunk_size
        && left.chunk_count == right.chunk_count
}

fn blob_metadata_immutable_identity_eq(left: &BlobMetadata, right: &BlobMetadata) -> bool {
    left.transfer_id == right.transfer_id
        && left.semantic_id == right.semantic_id
        && left.blob_id == right.blob_id
        && left.variant_id == right.variant_id
        && left.manifest_digest == right.manifest_digest
        && left.route_lineage == right.route_lineage
        && left.physical_lineage == right.physical_lineage
        && left.header == right.header
}

fn load_blob_from_read(
    read: &redb::ReadTransaction,
    transfer_id: BlobTransferId,
) -> Result<Option<StoredBlob>, StoreError> {
    let encoded = read
        .open_table(BLOB_PUBLICATIONS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| value.value().to_vec());
    let metadata = match encoded {
        Some(encoded)
            if lifecycle::publication_record_is_retired(&encoded).map_err(blob_error)? =>
        {
            return Err(blob_error(BlobStoreError::ExpiredOrRetired));
        }
        Some(encoded) => {
            let metadata = decode_blob_metadata(&encoded)?;
            require_blob_lifetime_visible_read(read, metadata.lifetime)?;
            Some(metadata)
        }
        None => None,
    };
    metadata
        .map(|metadata| {
            let sealed = read
                .open_table(BLOB_BYTES)?
                .get(transfer_id.as_bytes().as_slice())?
                .map(|value| {
                    #[cfg(test)]
                    TEST_BLOB_SOURCE_BYTES_LOADED
                        .with(|count| count.set(count.get().saturating_add(1)));
                    value.value().to_vec()
                })
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob publication is missing exact source bytes",
                    ))
                })?;
            let marker = read
                .open_table(BLOB_ACCEPTANCE_MARKERS)?
                .get(transfer_id.as_bytes().as_slice())?
                .map(|value| value.value())
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob publication is missing its acceptance marker",
                    ))
                })?;
            Ok(StoredBlob {
                transfer_id,
                semantic_id: metadata.semantic_id,
                blob_id: metadata.blob_id,
                variant_id: metadata.variant_id,
                manifest_digest: metadata.manifest_digest,
                route_lineage: metadata.route_lineage,
                physical_lineage: metadata.physical_lineage,
                header: metadata.header,
                sealed,
                acceptance_marker: marker,
            })
        })
        .transpose()
}

fn load_blob_from_write(
    write: &redb::WriteTransaction,
    transfer_id: BlobTransferId,
) -> Result<Option<StoredBlob>, StoreError> {
    let encoded = write
        .open_table(BLOB_PUBLICATIONS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| value.value().to_vec());
    let metadata = match encoded {
        Some(encoded)
            if lifecycle::publication_record_is_retired(&encoded).map_err(blob_error)? =>
        {
            return Err(blob_error(BlobStoreError::ExpiredOrRetired));
        }
        Some(encoded) => {
            let metadata = decode_blob_metadata(&encoded)?;
            Some(metadata)
        }
        None => None,
    };
    let blob = metadata
        .map(|metadata| -> Result<StoredBlob, StoreError> {
            let sealed = write
                .open_table(BLOB_BYTES)?
                .get(transfer_id.as_bytes().as_slice())?
                .map(|value| value.value().to_vec())
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob publication is missing exact source bytes",
                    ))
                })?;
            let marker = write
                .open_table(BLOB_ACCEPTANCE_MARKERS)?
                .get(transfer_id.as_bytes().as_slice())?
                .map(|value| value.value())
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob publication is missing its acceptance marker",
                    ))
                })?;
            Ok(StoredBlob {
                transfer_id,
                semantic_id: metadata.semantic_id,
                blob_id: metadata.blob_id,
                variant_id: metadata.variant_id,
                manifest_digest: metadata.manifest_digest,
                route_lineage: metadata.route_lineage,
                physical_lineage: metadata.physical_lineage,
                header: metadata.header,
                sealed,
                acceptance_marker: marker,
            })
        })
        .transpose()?;
    if let Some(blob) = blob.as_ref() {
        require_blob_causal_authority_write(write, blob)?;
    }
    Ok(blob)
}

pub(crate) fn require_blob_publication_visible_write(
    write: &redb::WriteTransaction,
    transfer_id: BlobTransferId,
) -> Result<(), StoreError> {
    let encoded = write
        .open_table(BLOB_PUBLICATIONS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| value.value().to_vec())
        .ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob visibility check points to a missing publication",
            ))
        })?;
    if lifecycle::publication_record_is_retired(&encoded).map_err(blob_error)? {
        return Err(blob_error(BlobStoreError::ExpiredOrRetired));
    }
    require_blob_lifetime_visible_write(write, decode_blob_metadata(&encoded)?.lifetime)
}

/// Point-checks the exact causal authority required by one live publication.
/// High-water and frontier values may be ahead because later publications
/// advance them, but neither may be absent or behind the publication's dot.
fn require_blob_causal_authority_write(
    write: &redb::WriteTransaction,
    blob: &StoredBlob,
) -> Result<(), StoreError> {
    let dot = blob.header.stamp.dot;
    let dot_key = accepted_dot_key(dot);
    let accepted = write
        .open_table(ACCEPTED_DOTS)?
        .get(dot_key.as_slice())?
        .map(|value| parse_digest32("accepted dot table", value.value()))
        .transpose()?
        .ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob publication is missing its accepted-dot authority",
            ))
        })?;
    if accepted != *blob.semantic_id.as_bytes() {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob publication accepted-dot authority names another semantic item",
        )));
    }
    if write
        .open_table(PUBLISHER_HIGH_WATER)?
        .get(dot.publisher.as_slice())?
        .map_or(0, |value| value.value())
        < dot.counter
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob publication publisher high-water is missing or behind",
        )));
    }
    let frontier_key = causal_frontier_key(
        &blob.header.topic,
        &blob.header.scope,
        blob.header.stamp.dot.publisher,
    )?;
    if write
        .open_table(CAUSAL_FRONTIER)?
        .get(frontier_key.as_slice())?
        .map_or(0, |value| value.value())
        < dot.counter
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob publication causal frontier is missing or behind",
        )));
    }
    Ok(())
}

/// Compact publication identity used by the durable application-delivery ledger.
///
/// This deliberately excludes source bytes and depot/provider details.
#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct BlobSubscriptionIdentity {
    pub transfer_id: BlobTransferId,
    pub semantic_id: BlobSemanticId,
    pub blob_id: BlobId,
    pub publisher: NodeId,
    pub publisher_counter: u64,
    pub topic: Topic,
    pub scope: Scope,
    pub priority: Priority,
    pub ttl_ms: Option<u64>,
    pub acceptance_marker: u64,
}

fn blob_subscription_identity_from_metadata(
    metadata: &BlobMetadata,
    acceptance_marker: u64,
) -> Result<BlobSubscriptionIdentity, StoreError> {
    if acceptance_marker == 0 {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob subscription identity has a zero acceptance marker",
        )));
    }
    Ok(BlobSubscriptionIdentity {
        transfer_id: metadata.transfer_id,
        semantic_id: metadata.semantic_id,
        blob_id: metadata.blob_id,
        publisher: metadata.header.stamp.dot.publisher,
        publisher_counter: metadata.header.stamp.dot.counter,
        topic: metadata.header.topic.clone(),
        scope: metadata.header.scope.clone(),
        priority: metadata.header.priority,
        ttl_ms: metadata.header.ttl_ms,
        acceptance_marker,
    })
}

pub(crate) fn blob_subscription_identity_for_transfer_write(
    write: &redb::WriteTransaction,
    transfer_id: BlobTransferId,
) -> Result<Option<BlobSubscriptionIdentity>, StoreError> {
    let Some(encoded) = write
        .open_table(BLOB_PUBLICATIONS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| value.value().to_vec())
    else {
        return Ok(None);
    };
    let retired = decode_retired_blob_metadata(&encoded)?;
    let (metadata, marker) = match retired {
        Some(value) => value,
        None => {
            let metadata = decode_blob_metadata(&encoded)?;
            let marker = write
                .open_table(BLOB_ACCEPTANCE_MARKERS)?
                .get(transfer_id.as_bytes().as_slice())?
                .map(|value| value.value())
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob subscription identity is missing its acceptance marker",
                    ))
                })?;
            (metadata, marker)
        }
    };
    if metadata.transfer_id != transfer_id {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob subscription identity differs from its publication key",
        )));
    }
    if write
        .open_table(BLOB_SEMANTIC_ITEMS)?
        .get(metadata.semantic_id.as_bytes().as_slice())?
        .map(|value| value.value().to_vec())
        .as_deref()
        != Some(transfer_id.as_bytes().as_slice())
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob subscription identity differs from its semantic index",
        )));
    }
    Ok(Some(blob_subscription_identity_from_metadata(
        &metadata, marker,
    )?))
}

pub(crate) fn blob_subscription_identity_write(
    write: &redb::WriteTransaction,
    semantic_id: BlobSemanticId,
) -> Result<Option<BlobSubscriptionIdentity>, StoreError> {
    let transfer = write
        .open_table(BLOB_SEMANTIC_ITEMS)?
        .get(semantic_id.as_bytes().as_slice())?
        .map(|value| parse_blob_transfer_id("Blob semantic item table", value.value()))
        .transpose()?;
    transfer
        .map(|transfer| blob_subscription_identity_for_transfer_write(write, transfer))
        .transpose()
        .map(Option::flatten)
}

pub(crate) fn blob_subscription_retirement_write(
    write: &redb::WriteTransaction,
    transfer_id: BlobTransferId,
) -> Result<Option<(lifecycle::RetirementReason, u64)>, StoreError> {
    write
        .open_table(BLOB_PUBLICATIONS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| {
            lifecycle::publication_retirement(value.value())
                .map_err(blob_error)
                .map(|retirement| retirement.map(|(reason, generation, _)| (reason, generation)))
        })
        .transpose()
        .map(Option::flatten)
}

pub(crate) fn blob_subscription_identity_read(
    read: &redb::ReadTransaction,
    semantic_id: BlobSemanticId,
) -> Result<Option<BlobSubscriptionIdentity>, StoreError> {
    let Some(transfer) = read
        .open_table(BLOB_SEMANTIC_ITEMS)?
        .get(semantic_id.as_bytes().as_slice())?
        .map(|value| parse_blob_transfer_id("Blob semantic item table", value.value()))
        .transpose()?
    else {
        return Ok(None);
    };
    let encoded = read
        .open_table(BLOB_PUBLICATIONS)?
        .get(transfer.as_bytes().as_slice())?
        .map(|value| value.value().to_vec())
        .ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob semantic index points to a missing publication",
            ))
        })?;
    let retired = decode_retired_blob_metadata(&encoded)?;
    let (metadata, marker) = match retired {
        Some(value) => value,
        None => {
            let metadata = decode_blob_metadata(&encoded)?;
            let marker = read
                .open_table(BLOB_ACCEPTANCE_MARKERS)?
                .get(transfer.as_bytes().as_slice())?
                .map(|value| value.value())
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob subscription identity is missing its acceptance marker",
                    ))
                })?;
            (metadata, marker)
        }
    };
    if metadata.transfer_id != transfer || metadata.semantic_id != semantic_id {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob semantic index differs from its publication",
        )));
    }
    Ok(Some(blob_subscription_identity_from_metadata(
        &metadata, marker,
    )?))
}

pub(crate) fn blob_subscription_retirement_generation_read(
    read: &redb::ReadTransaction,
    transfer_id: BlobTransferId,
) -> Result<Option<u64>, StoreError> {
    read.open_table(BLOB_PUBLICATIONS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| {
            lifecycle::publication_retirement(value.value())
                .map_err(blob_error)
                .map(|retirement| retirement.map(|(_, generation, _)| generation))
        })
        .transpose()
        .map(Option::flatten)
}

pub(crate) fn blob_subscription_retirement_read(
    read: &redb::ReadTransaction,
    transfer_id: BlobTransferId,
) -> Result<Option<(lifecycle::RetirementReason, u64)>, StoreError> {
    read.open_table(BLOB_PUBLICATIONS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| {
            lifecycle::publication_retirement(value.value())
                .map_err(blob_error)
                .map(|retirement| retirement.map(|(reason, generation, _)| (reason, generation)))
        })
        .transpose()
        .map(Option::flatten)
}

pub(crate) fn blob_subscription_lifetime_hidden_read(
    read: &redb::ReadTransaction,
    transfer_id: BlobTransferId,
) -> Result<bool, StoreError> {
    let Some(encoded) = read
        .open_table(BLOB_PUBLICATIONS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| value.value().to_vec())
    else {
        return Ok(false);
    };
    if lifecycle::publication_record_is_retired(&encoded).map_err(blob_error)? {
        return Ok(false);
    }
    let metadata = decode_blob_metadata(&encoded)?;
    if metadata.transfer_id != transfer_id {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob subscription lifetime lookup differs from its publication key",
        )));
    }
    blob_lifetime_is_visible_read(read, metadata.lifetime).map(|visible| !visible)
}

pub(crate) fn blob_subscription_lifetime_hidden_write(
    write: &redb::WriteTransaction,
    transfer_id: BlobTransferId,
) -> Result<bool, StoreError> {
    let Some(encoded) = write
        .open_table(BLOB_PUBLICATIONS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| value.value().to_vec())
    else {
        return Ok(false);
    };
    if lifecycle::publication_record_is_retired(&encoded).map_err(blob_error)? {
        return Ok(false);
    }
    let metadata = decode_blob_metadata(&encoded)?;
    if metadata.transfer_id != transfer_id {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob subscription lifetime lookup differs from its publication key",
        )));
    }
    blob_lifetime_is_visible_write(write, metadata.lifetime).map(|visible| !visible)
}

pub(crate) fn blob_subscription_projection_read(
    read: &redb::ReadTransaction,
    transfer_id: BlobTransferId,
) -> Result<Option<(BlobSourceProjection, u64)>, StoreError> {
    let Some(encoded) = read
        .open_table(BLOB_PUBLICATIONS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| value.value().to_vec())
    else {
        return Ok(None);
    };
    if lifecycle::publication_record_is_retired(&encoded).map_err(blob_error)? {
        return Ok(None);
    }
    let metadata = decode_blob_metadata(&encoded)?;
    if metadata.transfer_id != transfer_id {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob subscription projection differs from its publication key",
        )));
    }
    if !blob_lifetime_is_visible_read(read, metadata.lifetime)? {
        return Ok(None);
    }
    let content_key = blob_content_key(
        &metadata.header.topic,
        &metadata.header.scope,
        metadata.blob_id,
        metadata.semantic_id,
    )?;
    if read
        .open_table(BLOB_CONTENT_INDEX)?
        .get(content_key.as_slice())?
        .map(|value| value.value().to_vec())
        .as_deref()
        != Some(transfer_id.as_bytes().as_slice())
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob subscription projection differs from its content index",
        )));
    }
    let candidate = blob_read_candidate_projection_read(read, transfer_id, &content_key)?;
    Ok(Some((candidate.projection, candidate.acceptance_marker)))
}

pub(crate) fn blob_subscription_projection_matches_write(
    write: &redb::WriteTransaction,
    transfer_id: BlobTransferId,
    acceptance_marker: u64,
    projection: &BlobSourceProjection,
) -> Result<bool, StoreError> {
    let Some(metadata) = write
        .open_table(BLOB_PUBLICATIONS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| decode_blob_metadata(value.value()))
        .transpose()?
    else {
        return Ok(false);
    };
    if metadata.transfer_id != transfer_id {
        return Ok(false);
    }
    if !blob_lifetime_is_visible_write(write, metadata.lifetime)? {
        return Ok(false);
    }
    let Some(sealed_len) = write
        .open_table(BLOB_BYTES)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| u64::try_from(value.value().len()))
        .transpose()
        .map_err(|_| StoreError::PayloadByteAccountingOverflow)?
    else {
        return Ok(false);
    };
    if write
        .open_table(BLOB_SEMANTIC_ITEMS)?
        .get(metadata.semantic_id.as_bytes().as_slice())?
        .map(|value| value.value().to_vec())
        .as_deref()
        != Some(transfer_id.as_bytes().as_slice())
    {
        return Ok(false);
    }
    let content_key = blob_content_key(
        &metadata.header.topic,
        &metadata.header.scope,
        metadata.blob_id,
        metadata.semantic_id,
    )?;
    if write
        .open_table(BLOB_CONTENT_INDEX)?
        .get(content_key.as_slice())?
        .map(|value| value.value().to_vec())
        .as_deref()
        != Some(transfer_id.as_bytes().as_slice())
    {
        return Ok(false);
    }
    if write
        .open_table(BLOB_ACCEPTANCE_MARKERS)?
        .get(transfer_id.as_bytes().as_slice())?
        .map(|value| value.value())
        != Some(acceptance_marker)
    {
        return Ok(false);
    }
    let route = metadata.header.blob_route.ok_or_else(|| {
        blob_error(BlobStoreError::SchemaInvariant(
            "retained Blob source is missing its authenticated route commitment",
        ))
    })?;
    let physical_lineage = metadata
        .physical_lineage
        .ok_or_else(|| blob_error(BlobStoreError::PhysicalLineageMigrationRequired))?;
    let shape = depot::blob_source_shape_write(
        write,
        metadata.variant_id,
        metadata.blob_id,
        metadata.header.key_epoch,
        physical_lineage,
        metadata.manifest_digest,
        route.chunk_count(),
        true,
    )?;
    Ok(blob_source_projection(&metadata, sealed_len, shape)? == *projection)
}

pub(crate) fn blob_subscription_exact_source_matches_write(
    write: &redb::WriteTransaction,
    transfer_id: BlobTransferId,
) -> Result<bool, StoreError> {
    let bytes = write.open_table(BLOB_BYTES)?;
    let Some(sealed) = bytes.get(transfer_id.as_bytes().as_slice())? else {
        return Ok(false);
    };
    Ok(BlobTransferId::new(Sha256::digest(sealed.value()).into()) == transfer_id)
}

fn transfer_id_exists_outside_blob(
    write: &redb::WriteTransaction,
    id: &[u8; 32],
) -> Result<bool, StoreError> {
    Ok(write.open_table(EVENTS)?.get(id.as_slice())?.is_some()
        || write.open_table(STATES)?.get(id.as_slice())?.is_some()
        || write.open_table(RECORDS)?.get(id.as_slice())?.is_some()
        || write.open_table(ROUTE_CACHE)?.get(id.as_slice())?.is_some()
        || write
            .open_table(CONTROL_RECORDS)?
            .get(id.as_slice())?
            .is_some())
}

fn semantic_id_exists_outside_blob(
    write: &redb::WriteTransaction,
    id: &[u8; 32],
) -> Result<bool, StoreError> {
    if write
        .open_table(SEMANTIC_ITEMS)?
        .get(id.as_slice())?
        .is_some()
        || write
            .open_table(STATE_SEMANTIC_ITEMS)?
            .get(id.as_slice())?
            .is_some()
        || write
            .open_table(RECORD_SEMANTIC_ITEMS)?
            .get(id.as_slice())?
            .is_some()
    {
        return Ok(true);
    }
    if custody::retired_route_semantic_exists_write(write, id)? {
        return Ok(true);
    }
    for row in write.open_table(ROUTE_CACHE_CLAIMS)?.iter()? {
        let (_, claim) = row?;
        if decode_event_metadata(claim.value())?.semantic_id.as_bytes() == id {
            return Ok(true);
        }
    }
    Ok(false)
}

fn extend_shared_with_expired_blob_replay_authority<
    R: ReadableTable<&'static [u8], &'static [u8]>,
    A: ReadableTable<&'static [u8], &'static [u8]>,
    H: ReadableTable<&'static [u8], u64>,
>(
    replays: &R,
    accepted_dots: &A,
    publisher_high: &H,
    publication_transfers: &BTreeSet<Vec<u8>>,
    mut causal_fences: BTreeMap<Vec<u8>, [u8; 32]>,
    shared: &mut StateAuditSnapshot,
) -> Result<(), StoreError> {
    for row in replays.iter()? {
        let (key, value) = row?;
        let key = key.value().to_vec();
        if key.len() != 40 {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob replay fence has an invalid publisher-dot key",
            )));
        }
        let fence = lifecycle::ReplayFence::decode(value.value()).map_err(blob_error)?;
        let dot = fence.dot();
        if accepted_dot_key(dot).as_slice() != key.as_slice() {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob replay fence key differs from its publisher dot",
            )));
        }
        if publication_transfers.contains(fence.transfer_id().as_bytes().as_slice()) {
            if causal_fences.remove(&key).is_some() {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "live or retained Blob replay fence has expired causal evidence",
                )));
            }
            continue;
        }
        let accepted = accepted_dots
            .get(key.as_slice())?
            .map(|value| parse_digest32("accepted dot table", value.value()))
            .transpose()?;
        let Some(causal_hash) = causal_fences.remove(&key) else {
            // Pre-lifecycle standalone replay fences have never represented an
            // accepted Blob publication, so they carry neither shared causal
            // rows nor a retirement-expiry causal binding.  They remain valid
            // permanent source authority.  An accepted dot without the
            // binding, however, is a missing expiry record and fails closed.
            if accepted.is_none() {
                continue;
            }
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "expired Blob replay fence is missing permanent causal evidence",
            )));
        };
        if shared
            .expected_dots
            .insert(key.clone(), *fence.semantic_id().as_bytes())
            .is_some()
        {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "multiple semantic classes claim one accepted causal dot",
            )));
        }
        let accepted = accepted.ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "expired Blob replay fence is missing its accepted-dot row",
            ))
        })?;
        if accepted != *fence.semantic_id().as_bytes() {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "expired Blob replay fence accepted-dot authority conflicts",
            )));
        }
        let durable_high = publisher_high
            .get(dot.publisher.as_slice())?
            .map_or(0, |value| value.value());
        if durable_high < dot.counter {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "expired Blob replay fence is ahead of publisher high-water",
            )));
        }
        shared
            .expected_publisher_high
            .entry(dot.publisher.to_vec())
            .and_modify(|current| *current = (*current).max(dot.counter))
            .or_insert(dot.counter);
        shared
            .historical_frontier
            .entry(causal_hash)
            .and_modify(|current| *current = (*current).max(dot.counter))
            .or_insert(dot.counter);
    }
    if !causal_fences.is_empty() {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob expired causal evidence has no matching permanent replay fence",
        )));
    }
    Ok(())
}

pub(crate) fn blob_schema_present_write(
    write: &redb::WriteTransaction,
) -> Result<bool, StoreError> {
    let tables = blob_table_names();
    let stream_tables = stream_blob_table_names();
    let multimap_tables = write
        .list_multimap_tables()?
        .map(|table| table.name().to_owned())
        .collect::<BTreeSet<_>>();
    if multimap_tables.contains(OBSOLETE_PROFILE5_RECEIPT_TABLE_NAME) {
        return Err(blob_error(
            BlobStoreError::UnsupportedLegacyProfile5ReceiptSchema,
        ));
    }
    if multimap_tables
        .iter()
        .any(|table| tables.contains(&table.as_str()) || stream_tables.contains(&table.as_str()))
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "mission-scoped Blob schema has the wrong table kind",
        )));
    }
    let existing = write
        .list_tables()?
        .map(|table| table.name().to_owned())
        .collect::<BTreeSet<_>>();
    if existing.contains(OBSOLETE_PROFILE5_RECEIPT_TABLE_NAME) {
        return Err(blob_error(
            BlobStoreError::UnsupportedLegacyProfile5ReceiptSchema,
        ));
    }
    let legacy = legacy_blob_table_names();
    let legacy_present = legacy
        .iter()
        .filter(|table| existing.contains(**table))
        .count();
    let network = network_blob_table_names();
    let network_present = network
        .iter()
        .filter(|table| existing.contains(**table))
        .count();
    let network_current = network_present == network.len();
    let stream_present = stream_tables
        .iter()
        .filter(|table| existing.contains(**table))
        .count();
    let upload_present = existing.contains(BLOB_UPLOADS.name());
    let pack_present = existing.contains(pack_lifecycle::BLOB_PROFILE5_PACKS.name());
    let extension_group_supported = matches!(
        (network_present, upload_present, pack_present),
        (0, false, false) | (4, false, false) | (4, true, true)
    );
    #[cfg(test)]
    let schema_migration_required = stream_present != 0 || !upload_present;
    let metadata = write.open_table(METADATA)?;
    let global = blob_global_metadata_fields();
    let global_present = global
        .iter()
        .map(|field| metadata.get(*field).map(|value| value.is_some()))
        .collect::<Result<Vec<_>, _>>()?;
    drop(metadata);
    if stream_present != 0 && stream_present != stream_tables.len() {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "mission-scoped Blob schema group is incomplete",
        )));
    }
    let stream_complete_empty = if stream_present == stream_tables.len() {
        let empty = write.open_table(BLOB_STREAM_RESERVATIONS)?.len()? == 0
            && write.open_table(BLOB_STREAM_OPERATIONS)?.len()? == 0
            && write.open_table(BLOB_STREAM_PUBLICATIONS)?.len()? == 0
            && write.open_table(BLOB_STREAM_CONFLICTS)?.len()? == 0
            && write.open_table(BLOB_STREAM_VARIANTS)?.len()? == 0
            && write.open_table(BLOB_STREAM_RETIREMENTS)?.len()? == 0;
        if !empty {
            return Err(blob_error(
                BlobStoreError::UnsupportedExperimentalBlobStreamSchema,
            ));
        }
        true
    } else {
        false
    };
    if legacy_present == 0
        && network_present == 0
        && !upload_present
        && !pack_present
        && global_present.iter().all(|present| !present)
        && stream_complete_empty
    {
        lifecycle::require_blob_lifecycle_absent_write(write)?;
        deletion::require_blob_deletion_absent_write(write)?;
        for table in [
            BLOB_STREAM_RESERVATIONS,
            BLOB_STREAM_OPERATIONS,
            BLOB_STREAM_PUBLICATIONS,
            BLOB_STREAM_CONFLICTS,
            BLOB_STREAM_VARIANTS,
            BLOB_STREAM_RETIREMENTS,
        ] {
            if !write.delete_table(table)? {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "experimental Blob stream schema changed during migration",
                )));
            }
        }
        #[cfg(test)]
        if TEST_BLOB_SCHEMA_MIGRATION_FAULT.get() == 1 {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "injected Blob schema cleanup abort",
            )));
        }
        return Ok(false);
    }
    if legacy_present == 0
        && network_present == 0
        && stream_present == 0
        && !upload_present
        && !pack_present
        && global_present.iter().all(|present| !present)
    {
        lifecycle::require_blob_lifecycle_absent_write(write)?;
        deletion::require_blob_deletion_absent_write(write)?;
        return Ok(false);
    }
    if legacy_present != legacy.len()
        || !(network_present == 0 || network_current)
        || !extension_group_supported
        || global_present.iter().any(|present| !present)
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "mission-scoped Blob schema group is incomplete",
        )));
    }
    if stream_complete_empty {
        for table in [
            BLOB_STREAM_RESERVATIONS,
            BLOB_STREAM_OPERATIONS,
            BLOB_STREAM_PUBLICATIONS,
            BLOB_STREAM_CONFLICTS,
            BLOB_STREAM_VARIANTS,
            BLOB_STREAM_RETIREMENTS,
        ] {
            if !write.delete_table(table)? {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "experimental Blob stream schema changed during migration",
                )));
            }
        }
        #[cfg(test)]
        if TEST_BLOB_SCHEMA_MIGRATION_FAULT.get() == 1 {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "injected Blob schema cleanup abort",
            )));
        }
    }
    if network_present == 0 {
        initialize_blob_network_schema(write)?;
    }
    if !upload_present {
        let _ = write.open_table(BLOB_UPLOADS)?;
    }
    if !pack_present {
        let _ = write.open_table(pack_lifecycle::BLOB_PROFILE5_PACKS)?;
    }
    #[cfg(test)]
    if schema_migration_required && TEST_BLOB_SCHEMA_MIGRATION_FAULT.get() == 2 {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "injected Blob schema extension abort",
        )));
    }
    Ok(true)
}

/// Blob acceptance markers are an allocation high-water, not a count of
/// currently retained or permanent records.  Retiring a record deliberately
/// leaves a gap, so strict audit accepts a durable value ahead of the largest
/// still-retained marker but never behind it.
fn audit_or_initialize_blob_marker_high_water(
    metadata: &mut redb::Table<'_, &str, u64>,
    reconstructed_minimum: u64,
) -> Result<u64, StoreError> {
    let durable = metadata
        .get(LAST_BLOB_ACCEPTANCE_MARKER)?
        .map(|value| value.value());
    match durable {
        Some(durable) if durable < reconstructed_minimum => Err(StoreError::AccountingMismatch {
            field: LAST_BLOB_ACCEPTANCE_MARKER,
            durable,
            reconstructed: reconstructed_minimum,
        }),
        Some(durable) => Ok(durable),
        None => {
            metadata.insert(LAST_BLOB_ACCEPTANCE_MARKER, reconstructed_minimum)?;
            Ok(reconstructed_minimum)
        }
    }
}

type BlobOperationRetirement = (
    lifecycle::RetirementReason,
    u64,
    [u8; 32],
    [u8; 32],
    lifecycle::RetirementAge,
);

struct BlobOperationOwnershipMigration {
    old_key: Vec<u8>,
    new_key: Vec<u8>,
    value: Vec<u8>,
    active_transfer: Option<BlobTransferId>,
    retired: Option<BlobOperationRetirement>,
}

fn blob_intent_digest_for_metadata(metadata: &BlobMetadata) -> Result<[u8; 32], StoreError> {
    BlobPublicationIntent::new_with_ttl(
        metadata.header.stamp.dot.publisher,
        metadata.header.topic.clone(),
        metadata.header.scope.clone(),
        metadata.header.priority,
        metadata.blob_id,
        metadata.header.ttl_ms,
    )
    .map(|intent| intent.digest())
}

fn predecessor_operation_publisher(
    publications: &impl ReadableTable<&'static [u8], &'static [u8]>,
    publication_encoding: lifecycle::PublicationEncodingGeneration,
    value: &[u8],
) -> Result<(NodeId, Option<BlobTransferId>), StoreError> {
    if let Some((reason, generation, _, intent_digest, _)) =
        lifecycle::operation_retirement(value).map_err(blob_error)?
    {
        let matched = predecessor_retired_operation_publisher(
            publications,
            publication_encoding,
            reason,
            generation,
            intent_digest,
        )?;
        return matched.map(|publisher| (publisher, None)).ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "retired Blob operation has no exact publication owner",
            ))
        });
    }

    let operation = decode_blob_operation_record(value)?;
    let publication = publications
        .get(operation.transfer_id.as_bytes().as_slice())?
        .ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob operation points to a missing publication",
            ))
        })?;
    if lifecycle::publication_record_is_retired_for_encoding(
        publication.value(),
        publication_encoding,
    )
    .map_err(blob_error)?
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "active Blob operation points to a retired publication",
        )));
    }
    let metadata = decode_blob_metadata_for_encoding(publication.value(), publication_encoding)?;
    if blob_intent_digest_for_metadata(&metadata)? != operation.intent_digest {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob operation intent differs from its publication",
        )));
    }
    Ok((
        metadata.header.stamp.dot.publisher,
        Some(operation.transfer_id),
    ))
}

fn predecessor_retired_operation_publisher(
    publications: &impl ReadableTable<&'static [u8], &'static [u8]>,
    publication_encoding: lifecycle::PublicationEncodingGeneration,
    reason: lifecycle::RetirementReason,
    generation: u64,
    intent_digest: [u8; 32],
) -> Result<Option<NodeId>, StoreError> {
    let mut matched = None;
    for row in publications.iter()? {
        let (_, publication) = row?;
        let Some((publication_reason, publication_generation, _)) =
            lifecycle::publication_retirement(publication.value()).map_err(blob_error)?
        else {
            continue;
        };
        if publication_reason != reason || publication_generation != generation {
            continue;
        }
        let (metadata, _) =
            decode_retired_blob_metadata_for_encoding(publication.value(), publication_encoding)?
                .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "retired Blob operation publication lacks exact lookup metadata",
                ))
            })?;
        if blob_intent_digest_for_metadata(&metadata)? != intent_digest {
            continue;
        }
        if matched
            .replace(metadata.header.stamp.dot.publisher)
            .is_some()
        {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "retired Blob operation has ambiguous publication ownership",
            )));
        }
    }
    Ok(matched)
}

fn audit_retired_operation_owner(
    publications: &impl ReadableTable<&'static [u8], &'static [u8]>,
    publication_encoding: lifecycle::PublicationEncodingGeneration,
    owner: &BlobOperationOwner,
    value: &[u8],
) -> Result<(), StoreError> {
    let (reason, generation, _, intent_digest, _) = lifecycle::operation_retirement(value)
        .map_err(blob_error)?
        .ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "retired Blob operation audit received an active operation",
            ))
        })?;
    let mut matched = None;
    for row in publications.iter()? {
        let (_, publication) = row?;
        let Some((publication_reason, publication_generation, _)) =
            lifecycle::publication_retirement(publication.value()).map_err(blob_error)?
        else {
            continue;
        };
        if publication_generation != generation {
            continue;
        }
        let (metadata, _) =
            decode_retired_blob_metadata_for_encoding(publication.value(), publication_encoding)?
                .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "retired Blob operation publication lacks exact lookup metadata",
                ))
            })?;
        let publication_intent = blob_intent_digest_for_metadata(&metadata)?;
        if publication_reason != reason || publication_intent != intent_digest {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "retired Blob operation disagrees with its surviving publication",
            )));
        }
        let publication_publisher = metadata.header.stamp.dot.publisher;
        if owner.publisher != publication_publisher {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "retired Blob operation owner differs from its publication publisher",
            )));
        }
        if matched.replace(publication_publisher).is_some() {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "retired Blob operation has ambiguous publication ownership",
            )));
        }
    }
    if matched.is_some() {
        return Ok(());
    }

    // A surviving retirement generation is authoritative. Only in its absence
    // may the independently bound intent reveal contradictory surviving state.
    for row in publications.iter()? {
        let (_, publication) = row?;
        let retirement =
            lifecycle::publication_retirement(publication.value()).map_err(blob_error)?;
        let metadata = if retirement.is_some() {
            decode_retired_blob_metadata_for_encoding(publication.value(), publication_encoding)?
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "retired Blob operation publication lacks exact lookup metadata",
                    ))
                })?
                .0
        } else {
            decode_blob_metadata_for_encoding(publication.value(), publication_encoding)?
        };
        if blob_intent_digest_for_metadata(&metadata)? != intent_digest {
            continue;
        }
        if owner.publisher != metadata.header.stamp.dot.publisher {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "retired Blob operation owner differs from its publication publisher",
            )));
        }
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "retired Blob operation disagrees with its surviving publication",
        )));
    }
    // Current owner-qualified operation keys remain hash-bound by lifecycle
    // audit after their independently expiring publication evidence is gone.
    Ok(())
}

fn migrate_blob_operation_ownership_write(
    write: &redb::WriteTransaction,
    publication_encoding: lifecycle::PublicationEncodingGeneration,
) -> Result<(), StoreError> {
    let schema = write
        .open_table(METADATA)?
        .get(BLOB_OPERATION_KEY_SCHEMA_VERSION_FIELD)?
        .map(|value| value.value());
    match schema {
        Some(BLOB_OPERATION_KEY_SCHEMA_VERSION) => {
            for row in write.open_table(BLOB_OPERATIONS)?.iter()? {
                let (key, _) = row?;
                decode_blob_operation_owner_key(key.value())?;
            }
            return Ok(());
        }
        Some(_) => {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob operation ownership schema version is unknown",
            )));
        }
        None => {}
    }

    let publications = write.open_table(BLOB_PUBLICATIONS)?;
    let operations = write.open_table(BLOB_OPERATIONS)?;
    let old_keys = operations
        .iter()?
        .map(|row| row.map(|(key, _)| key.value().to_vec()))
        .collect::<Result<BTreeSet<_>, redb::StorageError>>()?;
    let mut new_keys = BTreeSet::new();
    let mut migrations = Vec::new();
    let mut operation_bytes = 0u64;
    for row in operations.iter()? {
        let (key, value) = row?;
        let operation = BlobOperationKey::new(key.value().to_vec())?;
        let (publisher, active_transfer) =
            predecessor_operation_publisher(&publications, publication_encoding, value.value())?;
        let owner = BlobOperationOwner::new(publisher, operation);
        let new_key = blob_operation_owner_key(&owner)?;
        if !new_keys.insert(new_key.clone())
            || (old_keys.contains(&new_key) && new_key.as_slice() != key.value())
        {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob operation ownership migration is ambiguous",
            )));
        }
        let retired = lifecycle::operation_retirement(value.value()).map_err(blob_error)?;
        let predecessor_digest: [u8; 32] = Sha256::digest(key.value()).into();
        if let Some((_, _, old_digest, _, _)) = retired
            && old_digest != predecessor_digest
        {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "retired Blob operation digest differs from its predecessor key",
            )));
        }
        operation_bytes = operation_bytes
            .checked_add(
                u64::try_from(new_key.len() + value.value().len())
                    .map_err(|_| StoreError::PayloadByteAccountingOverflow)?,
            )
            .ok_or(StoreError::PayloadByteAccountingOverflow)?;
        migrations.push(BlobOperationOwnershipMigration {
            old_key: key.value().to_vec(),
            new_key,
            value: value.value().to_vec(),
            active_transfer,
            retired,
        });
    }
    drop(operations);
    drop(publications);
    if operation_bytes > MAX_BLOB_DURABLE_OPERATION_BYTES {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "owner-qualified Blob operation usage exceeds its durable safety cap",
        )));
    }

    let lifecycle_current = write
        .list_tables()?
        .any(|table| table.name() == lifecycle::BLOB_LIFECYCLE_METADATA.name())
        && write
            .open_table(lifecycle::BLOB_LIFECYCLE_METADATA)?
            .get("schema_version")?
            .map(|value| value.value())
            == Some(5);
    for migration in &migrations {
        if lifecycle_current {
            if let Some(transfer) = migration.active_transfer {
                lifecycle::remove_operation_owner(write, transfer, &migration.old_key)?;
                lifecycle::insert_operation_owner(write, transfer, &migration.new_key)?;
            } else if let Some((_, _, old_digest, _, age)) = migration.retired {
                let deadline = age
                    .project(age.checkpoint_sample())
                    .map_err(blob_error)?
                    .deadline;
                lifecycle::replace_operation_retirement_authority(
                    write,
                    old_digest,
                    &migration.old_key,
                    Sha256::digest(&migration.new_key).into(),
                    &migration.new_key,
                    deadline,
                )?;
            }
        }
        write
            .open_table(BLOB_OPERATIONS)?
            .remove(migration.old_key.as_slice())?;
    }
    for migration in migrations {
        let value = if let Some((reason, generation, _, intent_digest, age)) = migration.retired {
            lifecycle::retired_operation_record(
                reason,
                generation,
                Sha256::digest(&migration.new_key).into(),
                intent_digest,
                age,
            )
        } else {
            migration.value
        };
        write
            .open_table(BLOB_OPERATIONS)?
            .insert(migration.new_key.as_slice(), value.as_slice())?;
    }
    let mut metadata = write.open_table(METADATA)?;
    metadata.insert(BLOB_OPERATION_TOTAL_BYTES, operation_bytes)?;
    metadata.insert(
        BLOB_OPERATION_KEY_SCHEMA_VERSION_FIELD,
        BLOB_OPERATION_KEY_SCHEMA_VERSION,
    )?;
    Ok(())
}

pub(crate) fn audit_blob_tables_write(
    write: &redb::WriteTransaction,
    shared: &mut StateAuditSnapshot,
) -> Result<BlobAuditSnapshot, StoreError> {
    if !blob_schema_present_write(write)? {
        initialize_blob_schema(write)?;
    }
    pack_lifecycle::audit_write(write)?;
    upload::audit_blob_uploads_write(write)?;
    upload::extend_profile5_reserved_publisher_high_write(
        write,
        &mut shared.expected_publisher_high,
    )?;
    let publication_encoding = lifecycle::publication_encoding_migration_write(write)?;
    migrate_blob_operation_ownership_write(write, publication_encoding)?;
    let deletion_owner_binding = depot::depot_owner_binding_if_present_write(write)?;
    let (deletion_schema_migrated, deletion_audit) =
        deletion::audit_or_migrate_blob_deletion_write(write, deletion_owner_binding)?;
    let publications = write.open_table(BLOB_PUBLICATIONS)?;
    let bytes = write.open_table(BLOB_BYTES)?;
    let markers = write.open_table(BLOB_ACCEPTANCE_MARKERS)?;
    let semantic_items = write.open_table(BLOB_SEMANTIC_ITEMS)?;
    let content = write.open_table(BLOB_CONTENT_INDEX)?;
    let operations = write.open_table(BLOB_OPERATIONS)?;
    let accepted_dots = write.open_table(ACCEPTED_DOTS)?;
    let publisher_high = write.open_table(PUBLISHER_HIGH_WATER)?;
    let frontier = write.open_table(CAUSAL_FRONTIER)?;
    let mut stats = BlobStoreStats::default();
    let mut marker_values = BTreeSet::new();
    let mut expected_content = BTreeMap::new();
    let mut content_counts = BTreeMap::<Vec<u8>, usize>::new();
    let mut retired_publications = 0u64;
    let mut publication_transfers = BTreeSet::new();

    for row in publications.iter()? {
        let (key, value) = row?;
        let transfer_id = parse_blob_transfer_id("Blob publication table", key.value())?;
        publication_transfers.insert(transfer_id.as_bytes().to_vec());
        if transfer_id_exists_outside_blob(write, transfer_id.as_bytes())? {
            return Err(StoreError::TransferNamespaceCollision {
                transfer_id: *transfer_id.as_bytes(),
            });
        }
        if lifecycle::publication_record_is_retired_for_encoding(
            value.value(),
            publication_encoding,
        )
        .map_err(blob_error)?
        {
            let (publication, marker) =
                decode_retired_blob_metadata_for_encoding(value.value(), publication_encoding)?
                    .ok_or_else(|| {
                        blob_error(BlobStoreError::SchemaInvariant(
                            "retired Blob publication is missing lookup metadata",
                        ))
                    })?;
            if publication.transfer_id != transfer_id
                || marker == 0
                || !marker_values.insert(marker)
            {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "retired Blob publication lookup metadata is inconsistent",
                )));
            }
            if semantic_id_exists_outside_blob(write, publication.semantic_id.as_bytes())? {
                return Err(StoreError::SemanticNamespaceCollision {
                    semantic_id: *publication.semantic_id.as_bytes(),
                });
            }
            let indexed = semantic_items
                .get(publication.semantic_id.as_bytes().as_slice())?
                .map(|value| parse_blob_transfer_id("Blob semantic item table", value.value()))
                .transpose()?
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "retired Blob publication is missing its semantic lookup",
                    ))
                })?;
            if indexed != transfer_id {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "retired Blob semantic lookup points to another publication",
                )));
            }
            let content_key = blob_content_key(
                &publication.header.topic,
                &publication.header.scope,
                publication.blob_id,
                publication.semantic_id,
            )?;
            if expected_content.insert(content_key, transfer_id).is_some() {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "multiple Blob publications claim one content index key",
                )));
            }
            let dot = publication.header.stamp.dot;
            let dot_key = accepted_dot_key(dot).to_vec();
            if shared
                .expected_dots
                .insert(dot_key.clone(), *publication.semantic_id.as_bytes())
                .is_some()
            {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "multiple semantic classes claim one accepted causal dot",
                )));
            }
            let accepted = accepted_dots
                .get(dot_key.as_slice())?
                .map(|value| parse_digest32("accepted dot table", value.value()))
                .transpose()?
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "retired Blob publication is missing its accepted-dot row",
                    ))
                })?;
            if accepted != *publication.semantic_id.as_bytes() {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "accepted-dot ledger points to another semantic publication",
                )));
            }
            let durable_high = publisher_high
                .get(dot.publisher.as_slice())?
                .map_or(0, |value| value.value());
            if durable_high < dot.counter {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "publisher high-water is behind an accepted Blob dot",
                )));
            }
            shared
                .expected_publisher_high
                .entry(dot.publisher.to_vec())
                .and_modify(|current| *current = (*current).max(dot.counter))
                .or_insert(dot.counter);
            let frontier_key = causal_frontier_key(
                &publication.header.topic,
                &publication.header.scope,
                dot.publisher,
            )?;
            if frontier
                .get(frontier_key.as_slice())?
                .map_or(0, |value| value.value())
                < dot.counter
            {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "causal frontier is behind an accepted Blob dot",
                )));
            }
            shared
                .expected_frontier
                .entry(frontier_key)
                .and_modify(|current| *current = (*current).max(dot.counter))
                .or_insert(dot.counter);
            shared
                .domain_publishers
                .entry(event_domain_prefix(
                    &publication.header.topic,
                    &publication.header.scope,
                )?)
                .or_default()
                .insert(dot.publisher);
            stats.last_acceptance_marker = stats.last_acceptance_marker.max(marker);
            retired_publications = retired_publications
                .checked_add(1)
                .ok_or(StoreError::ItemCountAccountingOverflow)?;
            continue;
        }
        let publication = decode_blob_metadata_for_encoding(value.value(), publication_encoding)?;
        if publication.transfer_id != transfer_id {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob metadata transfer identity differs from its key",
            )));
        }
        let route = publication.header.blob_route.ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "accepted Blob publication is missing its route commitment",
            ))
        })?;
        depot::audit_publication_import_write(
            write,
            publication.variant_id,
            publication.blob_id,
            publication.header.key_epoch,
            publication.manifest_digest,
            route.chunk_count(),
            publication.physical_lineage,
        )?;
        if semantic_id_exists_outside_blob(write, publication.semantic_id.as_bytes())? {
            return Err(StoreError::SemanticNamespaceCollision {
                semantic_id: *publication.semantic_id.as_bytes(),
            });
        }
        let exact = bytes.get(key.value())?.ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob metadata is missing exact source bytes",
            ))
        })?;
        if BlobTransferId::new(Sha256::digest(exact.value()).into()) != transfer_id {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob source bytes fail exact transfer identity audit",
            )));
        }
        let marker = markers
            .get(key.value())?
            .map(|value| value.value())
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob metadata is missing its acceptance marker",
                ))
            })?;
        if marker == 0 || !marker_values.insert(marker) {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob acceptance markers must be nonzero and unique",
            )));
        }
        let indexed = semantic_items
            .get(publication.semantic_id.as_bytes().as_slice())?
            .map(|value| parse_blob_transfer_id("Blob semantic item table", value.value()))
            .transpose()?
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob publication is missing its semantic index",
                ))
            })?;
        if indexed != transfer_id {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob semantic index points to another publication",
            )));
        }
        let content_key = blob_content_key(
            &publication.header.topic,
            &publication.header.scope,
            publication.blob_id,
            publication.semantic_id,
        )?;
        if expected_content.insert(content_key, transfer_id).is_some() {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "multiple Blob publications claim one content index key",
            )));
        }
        let content_prefix = blob_content_prefix(
            &publication.header.topic,
            &publication.header.scope,
            publication.blob_id,
        )?;
        let content_count = content_counts.entry(content_prefix).or_default();
        *content_count = content_count
            .checked_add(1)
            .ok_or(StoreError::ItemCountAccountingOverflow)?;
        if *content_count > MAX_BLOB_PUBLICATIONS_PER_CONTENT {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob content publication count exceeds its durable safety cap",
            )));
        }
        let dot = publication.header.stamp.dot;
        let dot_key = accepted_dot_key(dot).to_vec();
        if shared
            .expected_dots
            .insert(dot_key.clone(), *publication.semantic_id.as_bytes())
            .is_some()
        {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "multiple semantic classes claim one accepted causal dot",
            )));
        }
        let accepted = accepted_dots
            .get(dot_key.as_slice())?
            .map(|value| parse_digest32("accepted dot table", value.value()))
            .transpose()?
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob publication is missing its accepted-dot row",
                ))
            })?;
        if accepted != *publication.semantic_id.as_bytes() {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "accepted-dot ledger points to another semantic publication",
            )));
        }
        let durable_high = publisher_high
            .get(dot.publisher.as_slice())?
            .map_or(0, |value| value.value());
        if durable_high < dot.counter {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "publisher high-water is behind an accepted Blob dot",
            )));
        }
        shared
            .expected_publisher_high
            .entry(dot.publisher.to_vec())
            .and_modify(|current| *current = (*current).max(dot.counter))
            .or_insert(dot.counter);
        let frontier_key = causal_frontier_key(
            &publication.header.topic,
            &publication.header.scope,
            dot.publisher,
        )?;
        if frontier
            .get(frontier_key.as_slice())?
            .map_or(0, |value| value.value())
            < dot.counter
        {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "causal frontier is behind an accepted Blob dot",
            )));
        }
        shared
            .expected_frontier
            .entry(frontier_key)
            .and_modify(|current| *current = (*current).max(dot.counter))
            .or_insert(dot.counter);
        shared
            .domain_publishers
            .entry(event_domain_prefix(
                &publication.header.topic,
                &publication.header.scope,
            )?)
            .or_default()
            .insert(dot.publisher);
        stats.publications = stats
            .publications
            .checked_add(1)
            .ok_or(StoreError::ItemCountAccountingOverflow)?;
        stats.total_sealed_bytes = stats
            .total_sealed_bytes
            .checked_add(
                u64::try_from(exact.value().len())
                    .map_err(|_| StoreError::PayloadByteAccountingOverflow)?,
            )
            .ok_or(StoreError::PayloadByteAccountingOverflow)?;
        stats.last_acceptance_marker = stats.last_acceptance_marker.max(marker);
    }
    let lifecycle_table_names = write
        .list_tables()?
        .map(|table| table.name().to_owned())
        .collect::<BTreeSet<_>>();
    if write
        .list_multimap_tables()?
        .any(|table| table.name() == lifecycle::BLOB_REPLAY_CAUSAL_FENCES.name())
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob replay causal-fence table has the wrong table kind",
        )));
    }
    if lifecycle_table_names.contains(lifecycle::BLOB_REPLAY_FENCES.name()) {
        let mut causal_fences = BTreeMap::new();
        if lifecycle_table_names.contains(lifecycle::BLOB_REPLAY_CAUSAL_FENCES.name()) {
            for row in write
                .open_table(lifecycle::BLOB_REPLAY_CAUSAL_FENCES)?
                .iter()?
            {
                let (key, value) = row?;
                let digest: [u8; 32] = value.value().try_into().map_err(|_| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob replay causal fence has an invalid digest length",
                    ))
                })?;
                if key.value().len() != 40
                    || causal_fences.insert(key.value().to_vec(), digest).is_some()
                {
                    return Err(blob_error(BlobStoreError::SchemaInvariant(
                        "Blob replay causal fence key is not canonical",
                    )));
                }
            }
        }
        let replays = write.open_table(lifecycle::BLOB_REPLAY_FENCES)?;
        extend_shared_with_expired_blob_replay_authority(
            &replays,
            &accepted_dots,
            &publisher_high,
            &publication_transfers,
            causal_fences,
            shared,
        )?;
    }
    let lifecycle_publications = stats
        .publications
        .checked_add(retired_publications)
        .ok_or(StoreError::ItemCountAccountingOverflow)?;
    stats.acceptance_markers = markers.len()?;
    if bytes.len()? != stats.publications
        || markers.len()? != stats.publications
        || semantic_items.len()? != lifecycle_publications
        || content.len()? != lifecycle_publications
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob publication schema has missing or orphan rows",
        )));
    }
    for row in content.iter()? {
        let (key, value) = row?;
        let transfer = parse_blob_transfer_id("Blob content index", value.value())?;
        if expected_content.get(key.value()) != Some(&transfer) {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob content index contains an orphan or mismatched row",
            )));
        }
    }
    let mut active_equivalent_operation_bytes = 0u64;
    for row in operations.iter()? {
        let (key, value) = row?;
        let owner = decode_blob_operation_owner_key(key.value())?;
        let retired = lifecycle::operation_record_is_retired(value.value()).map_err(blob_error)?;
        if retired {
            audit_retired_operation_owner(
                &publications,
                publication_encoding,
                &owner,
                value.value(),
            )?;
        }
        if !retired {
            let operation = decode_blob_operation_record(value.value())?;
            let publication = publications
                .get(operation.transfer_id.as_bytes().as_slice())?
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob operation points to a missing publication",
                    ))
                })?;
            if lifecycle::publication_record_is_retired(publication.value()).map_err(blob_error)? {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "active Blob operation points to a retired publication",
                )));
            }
            let publication =
                decode_blob_metadata_for_encoding(publication.value(), publication_encoding)?;
            if owner.publisher != publication.header.stamp.dot.publisher {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "Blob operation owner differs from its publication publisher",
                )));
            }
        }
        stats.operations = stats
            .operations
            .checked_add(1)
            .ok_or(StoreError::ItemCountAccountingOverflow)?;
        let entry_bytes = key
            .value()
            .len()
            .checked_add(value.value().len())
            .and_then(|value| u64::try_from(value).ok())
            .ok_or(StoreError::PayloadByteAccountingOverflow)?;
        stats.operation_bytes = stats
            .operation_bytes
            .checked_add(entry_bytes)
            .ok_or(StoreError::PayloadByteAccountingOverflow)?;
        let active_equivalent_entry = if retired {
            entry_bytes
                .checked_sub(MAX_BLOB_OPERATION_RETIREMENT_GROWTH_BYTES)
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "retired Blob operation is shorter than its fixed growth",
                    ))
                })?
        } else {
            entry_bytes
        };
        active_equivalent_operation_bytes = active_equivalent_operation_bytes
            .checked_add(active_equivalent_entry)
            .ok_or(StoreError::PayloadByteAccountingOverflow)?;
    }
    let active_operation_byte_limit = MAX_BLOB_OPERATION_BYTES
        .checked_add(
            stats
                .operations
                .checked_mul(BLOB_OPERATION_OWNER_KEY_PREFIX_BYTES as u64)
                .ok_or(StoreError::PayloadByteAccountingOverflow)?,
        )
        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
    if stats.operations > MAX_BLOB_OPERATIONS
        || active_equivalent_operation_bytes > active_operation_byte_limit
        || stats.operation_bytes > MAX_BLOB_DURABLE_OPERATION_BYTES
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob operation usage exceeds its durable safety caps",
        )));
    }
    let depot_stats = depot::audit_depot_metadata_write(write, &deletion_audit)?;
    let pack_capacity = pack_lifecycle::active_capacity_usage_write(write)?;
    stats.variants = depot_stats
        .variants
        .checked_add(pack_capacity.variants)
        .ok_or(StoreError::ItemCountAccountingOverflow)?;
    stats.finalized_variants = depot_stats
        .finalized_variants
        .checked_add(pack_capacity.variants)
        .ok_or(StoreError::ItemCountAccountingOverflow)?;
    stats.committed_chunks = depot_stats
        .committed_chunks
        .checked_add(pack_capacity.chunks)
        .ok_or(StoreError::ItemCountAccountingOverflow)?;
    stats.committed_file_bytes = depot_stats
        .committed_file_bytes
        .checked_add(pack_lifecycle::active_committed_file_bytes_write(write)?)
        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
    stats.reserved_file_bytes = depot_stats
        .reserved_file_bytes
        .checked_add(pack_capacity.bytes)
        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
    let network = audit_blob_network_tables_write_with_publications(
        write,
        read_mission_binding(write)?,
        deletion_owner_binding,
        &publications,
        pending_blob_encoding_for_publication_encoding(publication_encoding),
        publication_encoding,
    )?;
    stats.pending_sources = network.pending_sources;
    stats.carrier_prefixes = network.carrier_prefixes;
    stats.network_staging_bytes = network.staging.bytes;
    stats.carrier_fetch_cursors = network.carrier_cursors;
    let mut metadata = write.open_table(METADATA)?;
    audit_or_initialize_counter(&mut metadata, BLOB_ITEM_COUNT, stats.publications)?;
    audit_or_initialize_counter(&mut metadata, BLOB_TOTAL_BYTES, stats.total_sealed_bytes)?;
    stats.last_acceptance_marker =
        audit_or_initialize_blob_marker_high_water(&mut metadata, stats.last_acceptance_marker)?;
    audit_or_initialize_counter(&mut metadata, BLOB_OPERATION_COUNT, stats.operations)?;
    audit_or_initialize_counter(
        &mut metadata,
        BLOB_OPERATION_TOTAL_BYTES,
        stats.operation_bytes,
    )?;
    drop(metadata);
    drop(publications);
    drop(markers);
    Ok(BlobAuditSnapshot {
        stats,
        deletion_schema_migrated,
    })
}

pub(crate) fn inspect_blob_tables_read(
    read: &redb::ReadTransaction,
) -> Result<BlobAuditSnapshot, StoreError> {
    let tables = blob_table_names();
    let stream_tables = stream_blob_table_names();
    let multimap_tables = read
        .list_multimap_tables()?
        .map(|table| table.name().to_owned())
        .collect::<BTreeSet<_>>();
    if multimap_tables.contains(OBSOLETE_PROFILE5_RECEIPT_TABLE_NAME) {
        return Err(blob_error(
            BlobStoreError::UnsupportedLegacyProfile5ReceiptSchema,
        ));
    }
    if multimap_tables
        .iter()
        .any(|table| tables.contains(&table.as_str()) || stream_tables.contains(&table.as_str()))
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "mission-scoped Blob schema has the wrong table kind",
        )));
    }
    let existing = read
        .list_tables()?
        .map(|table| table.name().to_owned())
        .collect::<BTreeSet<_>>();
    if existing.contains(OBSOLETE_PROFILE5_RECEIPT_TABLE_NAME) {
        return Err(blob_error(
            BlobStoreError::UnsupportedLegacyProfile5ReceiptSchema,
        ));
    }
    let legacy = legacy_blob_table_names();
    let legacy_present = legacy
        .iter()
        .filter(|table| existing.contains(**table))
        .count();
    let network = network_blob_table_names();
    let network_present = network
        .iter()
        .filter(|table| existing.contains(**table))
        .count();
    let network_current = network_present == network.len();
    let upload_present = existing.contains(BLOB_UPLOADS.name());
    let pack_present = existing.contains(pack_lifecycle::BLOB_PROFILE5_PACKS.name());
    let extension_group_supported = matches!(
        (network_present, upload_present, pack_present),
        (0, false, false) | (4, false, false) | (4, true, true)
    );
    let stream_present = stream_tables
        .iter()
        .filter(|table| existing.contains(**table))
        .count();
    let metadata = read.open_table(METADATA)?;
    let global = blob_global_metadata_fields();
    let global_present = global
        .iter()
        .map(|field| metadata.get(*field).map(|value| value.is_some()))
        .collect::<Result<Vec<_>, _>>()?;
    let operation_ownership_current = match metadata
        .get(BLOB_OPERATION_KEY_SCHEMA_VERSION_FIELD)?
        .map(|value| value.value())
    {
        Some(BLOB_OPERATION_KEY_SCHEMA_VERSION) => true,
        None => false,
        Some(_) => {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob operation ownership schema version is unknown",
            )));
        }
    };
    if stream_present != 0 && stream_present != stream_tables.len() {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "mission-scoped Blob schema group is incomplete",
        )));
    }
    let stream_complete_empty = if stream_present == stream_tables.len() {
        let empty = read.open_table(BLOB_STREAM_RESERVATIONS)?.len()? == 0
            && read.open_table(BLOB_STREAM_OPERATIONS)?.len()? == 0
            && read.open_table(BLOB_STREAM_PUBLICATIONS)?.len()? == 0
            && read.open_table(BLOB_STREAM_CONFLICTS)?.len()? == 0
            && read.open_table(BLOB_STREAM_VARIANTS)?.len()? == 0
            && read.open_table(BLOB_STREAM_RETIREMENTS)?.len()? == 0;
        if !empty {
            return Err(blob_error(
                BlobStoreError::UnsupportedExperimentalBlobStreamSchema,
            ));
        }
        true
    } else {
        false
    };
    if legacy_present == 0
        && network_present == 0
        && (stream_present == 0 || stream_complete_empty)
        && !upload_present
        && !pack_present
        && global_present.iter().all(|present| !present)
    {
        lifecycle::require_blob_lifecycle_absent_read(read)?;
        deletion::require_blob_deletion_absent_read(read)?;
        return Ok(BlobAuditSnapshot::default());
    }
    if legacy_present != legacy.len()
        || !(network_present == 0 || network_current)
        || !extension_group_supported
        || global_present.iter().any(|present| !present)
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "mission-scoped Blob schema group is incomplete",
        )));
    }
    if !upload_present {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob predecessor schema requires writable Profile-5 extension",
        )));
    }
    drop(metadata);
    pack_lifecycle::audit_read(read)?;
    upload::audit_blob_uploads_read(read)?;
    let deletion_owner_binding = depot::depot_owner_binding_if_present_read(read)?;
    let deletion_audit = deletion::inspect_blob_deletion_read(read, deletion_owner_binding)?;
    let publication_encoding = lifecycle::publication_encoding_migration_read(read)?;

    // The read-only audit uses a temporary shared snapshot and verifies Blob
    // rows directly; the caller later checks the complete shared ledgers after
    // combining Event, State, Record, and Blob expectations.
    let publications = read.open_table(BLOB_PUBLICATIONS)?;
    let bytes = read.open_table(BLOB_BYTES)?;
    let markers = read.open_table(BLOB_ACCEPTANCE_MARKERS)?;
    let semantic = read.open_table(BLOB_SEMANTIC_ITEMS)?;
    let content = read.open_table(BLOB_CONTENT_INDEX)?;
    let operations = read.open_table(BLOB_OPERATIONS)?;
    let mut stats = BlobStoreStats::default();
    let mut marker_values = BTreeSet::new();
    let mut expected_content = BTreeMap::new();
    let mut content_counts = BTreeMap::<Vec<u8>, usize>::new();
    let mut retired_publications = 0u64;
    for row in publications.iter()? {
        let (key, value) = row?;
        let transfer = parse_blob_transfer_id("Blob publication table", key.value())?;
        if lifecycle::publication_record_is_retired_for_encoding(
            value.value(),
            publication_encoding,
        )
        .map_err(blob_error)?
        {
            let (publication, marker) =
                decode_retired_blob_metadata_for_encoding(value.value(), publication_encoding)?
                    .ok_or_else(|| {
                        blob_error(BlobStoreError::SchemaInvariant(
                            "retired Blob publication is missing lookup metadata",
                        ))
                    })?;
            if publication.transfer_id != transfer || !marker_values.insert(marker) {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "retired Blob publication lookup metadata is inconsistent",
                )));
            }
            let indexed = semantic
                .get(publication.semantic_id.as_bytes().as_slice())?
                .map(|value| parse_blob_transfer_id("Blob semantic item table", value.value()))
                .transpose()?
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "retired Blob publication is missing its semantic lookup",
                    ))
                })?;
            if indexed != transfer {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "retired Blob semantic lookup points to another publication",
                )));
            }
            expected_content.insert(
                blob_content_key(
                    &publication.header.topic,
                    &publication.header.scope,
                    publication.blob_id,
                    publication.semantic_id,
                )?,
                transfer,
            );
            stats.last_acceptance_marker = stats.last_acceptance_marker.max(marker);
            retired_publications = retired_publications
                .checked_add(1)
                .ok_or(StoreError::ItemCountAccountingOverflow)?;
            continue;
        }
        let publication = decode_blob_metadata_for_encoding(value.value(), publication_encoding)?;
        if publication.transfer_id != transfer {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob metadata transfer identity differs from its key",
            )));
        }
        let route = publication.header.blob_route.ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "accepted Blob publication is missing its route commitment",
            ))
        })?;
        depot::audit_publication_import_read(
            read,
            publication.variant_id,
            publication.blob_id,
            publication.header.key_epoch,
            publication.manifest_digest,
            route.chunk_count(),
            publication.physical_lineage,
        )?;
        let exact = bytes.get(key.value())?.ok_or_else(|| {
            blob_error(BlobStoreError::SchemaInvariant(
                "Blob metadata is missing exact source bytes",
            ))
        })?;
        if BlobTransferId::new(Sha256::digest(exact.value()).into()) != transfer {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob source bytes fail exact transfer identity audit",
            )));
        }
        let marker = markers
            .get(key.value())?
            .map(|value| value.value())
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob metadata is missing its acceptance marker",
                ))
            })?;
        if marker == 0 || !marker_values.insert(marker) {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob acceptance markers must be nonzero and unique",
            )));
        }
        let indexed = semantic
            .get(publication.semantic_id.as_bytes().as_slice())?
            .map(|value| parse_blob_transfer_id("Blob semantic item table", value.value()))
            .transpose()?
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob publication is missing its semantic index",
                ))
            })?;
        if indexed != transfer {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob semantic index points to another publication",
            )));
        }
        expected_content.insert(
            blob_content_key(
                &publication.header.topic,
                &publication.header.scope,
                publication.blob_id,
                publication.semantic_id,
            )?,
            transfer,
        );
        let content_prefix = blob_content_prefix(
            &publication.header.topic,
            &publication.header.scope,
            publication.blob_id,
        )?;
        let content_count = content_counts.entry(content_prefix).or_default();
        *content_count = content_count
            .checked_add(1)
            .ok_or(StoreError::ItemCountAccountingOverflow)?;
        if *content_count > MAX_BLOB_PUBLICATIONS_PER_CONTENT {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob content publication count exceeds its durable safety cap",
            )));
        }
        stats.publications += 1;
        stats.total_sealed_bytes = stats
            .total_sealed_bytes
            .checked_add(
                u64::try_from(exact.value().len())
                    .map_err(|_| StoreError::PayloadByteAccountingOverflow)?,
            )
            .ok_or(StoreError::PayloadByteAccountingOverflow)?;
        stats.last_acceptance_marker = stats.last_acceptance_marker.max(marker);
    }
    stats.acceptance_markers = markers.len()?;
    let lifecycle_publications = stats
        .publications
        .checked_add(retired_publications)
        .ok_or(StoreError::ItemCountAccountingOverflow)?;
    if bytes.len()? != stats.publications
        || markers.len()? != stats.publications
        || semantic.len()? != lifecycle_publications
        || content.len()? != lifecycle_publications
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob publication schema has missing, orphan, or noncontiguous rows",
        )));
    }
    for row in content.iter()? {
        let (key, value) = row?;
        let transfer = parse_blob_transfer_id("Blob content index", value.value())?;
        if expected_content.get(key.value()) != Some(&transfer) {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "Blob content index contains an orphan or mismatched row",
            )));
        }
    }
    let mut active_equivalent_operation_bytes = 0u64;
    for row in operations.iter()? {
        let (key, value) = row?;
        let owner = if operation_ownership_current {
            decode_blob_operation_owner_key(key.value())?
        } else {
            let operation = BlobOperationKey::new(key.value().to_vec())?;
            let (publisher, _) = predecessor_operation_publisher(
                &publications,
                publication_encoding,
                value.value(),
            )?;
            BlobOperationOwner::new(publisher, operation)
        };
        let retired = lifecycle::operation_record_is_retired(value.value()).map_err(blob_error)?;
        if retired && operation_ownership_current {
            audit_retired_operation_owner(
                &publications,
                publication_encoding,
                &owner,
                value.value(),
            )?;
        }
        if !retired {
            let operation = decode_blob_operation_record(value.value())?;
            let publication = publications
                .get(operation.transfer_id.as_bytes().as_slice())?
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob operation points to a missing publication",
                    ))
                })?;
            if lifecycle::publication_record_is_retired(publication.value()).map_err(blob_error)? {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "active Blob operation points to a retired publication",
                )));
            }
            let publication =
                decode_blob_metadata_for_encoding(publication.value(), publication_encoding)?;
            if owner.publisher != publication.header.stamp.dot.publisher {
                return Err(blob_error(BlobStoreError::SchemaInvariant(
                    "Blob operation owner differs from its publication publisher",
                )));
            }
        }
        stats.operations += 1;
        let entry_bytes = key
            .value()
            .len()
            .checked_add(value.value().len())
            .and_then(|value| u64::try_from(value).ok())
            .ok_or(StoreError::PayloadByteAccountingOverflow)?;
        stats.operation_bytes = stats
            .operation_bytes
            .checked_add(entry_bytes)
            .ok_or(StoreError::PayloadByteAccountingOverflow)?;
        let active_equivalent_entry = if retired {
            entry_bytes
                .checked_sub(MAX_BLOB_OPERATION_RETIREMENT_GROWTH_BYTES)
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "retired Blob operation is shorter than its fixed growth",
                    ))
                })?
        } else {
            entry_bytes
        };
        active_equivalent_operation_bytes = active_equivalent_operation_bytes
            .checked_add(active_equivalent_entry)
            .ok_or(StoreError::PayloadByteAccountingOverflow)?;
    }
    let active_operation_byte_limit = if operation_ownership_current {
        MAX_BLOB_OPERATION_BYTES
            .checked_add(
                stats
                    .operations
                    .checked_mul(BLOB_OPERATION_OWNER_KEY_PREFIX_BYTES as u64)
                    .ok_or(StoreError::PayloadByteAccountingOverflow)?,
            )
            .ok_or(StoreError::PayloadByteAccountingOverflow)?
    } else {
        MAX_BLOB_OPERATION_BYTES
    };
    if stats.operations > MAX_BLOB_OPERATIONS
        || active_equivalent_operation_bytes > active_operation_byte_limit
        || stats.operation_bytes > MAX_BLOB_DURABLE_OPERATION_BYTES
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob operation usage exceeds its durable safety caps",
        )));
    }
    let depot_stats = depot::inspect_depot_metadata_read(read, &deletion_audit)?;
    let pack_capacity = pack_lifecycle::active_capacity_usage_read(read)?;
    stats.variants = depot_stats
        .variants
        .checked_add(pack_capacity.variants)
        .ok_or(StoreError::ItemCountAccountingOverflow)?;
    stats.finalized_variants = depot_stats
        .finalized_variants
        .checked_add(pack_capacity.variants)
        .ok_or(StoreError::ItemCountAccountingOverflow)?;
    stats.committed_chunks = depot_stats
        .committed_chunks
        .checked_add(pack_capacity.chunks)
        .ok_or(StoreError::ItemCountAccountingOverflow)?;
    stats.committed_file_bytes = depot_stats
        .committed_file_bytes
        .checked_add(pack_lifecycle::active_committed_file_bytes_read(read)?)
        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
    stats.reserved_file_bytes = depot_stats
        .reserved_file_bytes
        .checked_add(pack_capacity.bytes)
        .ok_or(StoreError::PayloadByteAccountingOverflow)?;
    if network_current {
        let network = inspect_blob_network_tables_read_with_publications(
            read,
            deletion_owner_binding,
            &publications,
            pending_blob_encoding_for_publication_encoding(publication_encoding),
            publication_encoding,
        )?;
        stats.pending_sources = network.pending_sources;
        stats.carrier_prefixes = network.carrier_prefixes;
        stats.network_staging_bytes = network.staging.bytes;
        stats.carrier_fetch_cursors = network.carrier_cursors;
    }
    let lifecycle_usage = lifecycle::inspect_blob_lifecycle_read(read)?;
    let metadata = read.open_table(METADATA)?;
    let durable_marker = metadata
        .get(LAST_BLOB_ACCEPTANCE_MARKER)?
        .ok_or(StoreError::MissingAccountingMetadata {
            field: LAST_BLOB_ACCEPTANCE_MARKER,
        })?
        .value();
    if durable_marker < stats.last_acceptance_marker {
        return Err(StoreError::AccountingMismatch {
            field: LAST_BLOB_ACCEPTANCE_MARKER,
            durable: durable_marker,
            reconstructed: stats.last_acceptance_marker,
        });
    }
    stats.last_acceptance_marker = durable_marker;
    for (field, reconstructed) in [
        (BLOB_ITEM_COUNT, stats.publications),
        (BLOB_TOTAL_BYTES, stats.total_sealed_bytes),
        (BLOB_OPERATION_COUNT, stats.operations),
        (BLOB_OPERATION_TOTAL_BYTES, stats.operation_bytes),
    ] {
        let durable = metadata
            .get(field)?
            .ok_or(StoreError::MissingAccountingMetadata { field })?
            .value();
        if durable != reconstructed {
            return Err(StoreError::AccountingMismatch {
                field,
                durable,
                reconstructed,
            });
        }
    }
    lifecycle_usage.apply_to_stats(&mut stats);
    drop(publications);
    drop(markers);
    pressure::inspect_pressure_read(read, lifecycle::lifecycle_generation_is_current_read(read)?)?;
    Ok(BlobAuditSnapshot {
        stats,
        deletion_schema_migrated: false,
    })
}

/// Extends the exact shared causal-ledger reconstruction used by strict inspection.
pub(crate) fn inspect_blob_tables_read_with_shared(
    read: &redb::ReadTransaction,
    shared: &mut StateAuditSnapshot,
) -> Result<BlobAuditSnapshot, StoreError> {
    let snapshot = inspect_blob_tables_read(read)?;
    let table_names = read
        .list_tables()?
        .map(|table| table.name().to_owned())
        .collect::<BTreeSet<_>>();
    if table_names.contains(BLOB_UPLOADS.name()) {
        upload::extend_profile5_reserved_publisher_high_read(
            read,
            &mut shared.expected_publisher_high,
        )?;
    }
    if !table_names.contains(BLOB_PUBLICATIONS.name()) {
        return Ok(snapshot);
    }
    let publications = read.open_table(BLOB_PUBLICATIONS)?;
    let publication_encoding = lifecycle::publication_encoding_migration_read(read)?;
    let accepted_dots = table_names
        .contains(ACCEPTED_DOTS.name())
        .then(|| read.open_table(ACCEPTED_DOTS))
        .transpose()?;
    let publisher_high = table_names
        .contains(PUBLISHER_HIGH_WATER.name())
        .then(|| read.open_table(PUBLISHER_HIGH_WATER))
        .transpose()?;
    let frontier = table_names
        .contains(CAUSAL_FRONTIER.name())
        .then(|| read.open_table(CAUSAL_FRONTIER))
        .transpose()?;
    let events = table_names
        .contains(EVENTS.name())
        .then(|| read.open_table(EVENTS))
        .transpose()?;
    let states = table_names
        .contains(STATES.name())
        .then(|| read.open_table(STATES))
        .transpose()?;
    let records = table_names
        .contains(RECORDS.name())
        .then(|| read.open_table(RECORDS))
        .transpose()?;
    let route_cache = table_names
        .contains(ROUTE_CACHE.name())
        .then(|| read.open_table(ROUTE_CACHE))
        .transpose()?;
    let controls = table_names
        .contains(CONTROL_RECORDS.name())
        .then(|| read.open_table(CONTROL_RECORDS))
        .transpose()?;
    let event_semantic = table_names
        .contains(SEMANTIC_ITEMS.name())
        .then(|| read.open_table(SEMANTIC_ITEMS))
        .transpose()?;
    let state_semantic = table_names
        .contains(STATE_SEMANTIC_ITEMS.name())
        .then(|| read.open_table(STATE_SEMANTIC_ITEMS))
        .transpose()?;
    let record_semantic = table_names
        .contains(RECORD_SEMANTIC_ITEMS.name())
        .then(|| read.open_table(RECORD_SEMANTIC_ITEMS))
        .transpose()?;
    let route_semantic_ids = if table_names.contains(ROUTE_CACHE_CLAIMS.name()) {
        read.open_table(ROUTE_CACHE_CLAIMS)?
            .iter()?
            .map(|row| {
                let (_, claim) = row?;
                Ok(*decode_event_metadata(claim.value())?.semantic_id.as_bytes())
            })
            .collect::<Result<BTreeSet<_>, StoreError>>()?
    } else {
        BTreeSet::new()
    };
    let mut publication_transfers = BTreeSet::new();
    for row in publications.iter()? {
        let (key, value) = row?;
        let transfer = parse_blob_transfer_id("Blob publication table", key.value())?;
        publication_transfers.insert(transfer.as_bytes().to_vec());
        if events
            .as_ref()
            .map(|table| table.get(key.value()))
            .transpose()?
            .flatten()
            .is_some()
            || states
                .as_ref()
                .map(|table| table.get(key.value()))
                .transpose()?
                .flatten()
                .is_some()
            || records
                .as_ref()
                .map(|table| table.get(key.value()))
                .transpose()?
                .flatten()
                .is_some()
            || route_cache
                .as_ref()
                .map(|table| table.get(key.value()))
                .transpose()?
                .flatten()
                .is_some()
            || controls
                .as_ref()
                .map(|table| table.get(key.value()))
                .transpose()?
                .flatten()
                .is_some()
        {
            return Err(StoreError::TransferNamespaceCollision {
                transfer_id: *transfer.as_bytes(),
            });
        }
        let publication = if lifecycle::publication_record_is_retired_for_encoding(
            value.value(),
            publication_encoding,
        )
        .map_err(blob_error)?
        {
            decode_retired_blob_metadata_for_encoding(value.value(), publication_encoding)?
                .map(|(publication, _)| publication)
                .ok_or_else(|| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "retired Blob publication is missing lookup metadata",
                    ))
                })?
        } else {
            decode_blob_metadata_for_encoding(value.value(), publication_encoding)?
        };
        let semantic = publication.semantic_id.as_bytes().as_slice();
        if event_semantic
            .as_ref()
            .map(|table| table.get(semantic))
            .transpose()?
            .flatten()
            .is_some()
            || state_semantic
                .as_ref()
                .map(|table| table.get(semantic))
                .transpose()?
                .flatten()
                .is_some()
            || record_semantic
                .as_ref()
                .map(|table| table.get(semantic))
                .transpose()?
                .flatten()
                .is_some()
            || route_semantic_ids.contains(publication.semantic_id.as_bytes())
        {
            return Err(StoreError::SemanticNamespaceCollision {
                semantic_id: *publication.semantic_id.as_bytes(),
            });
        }
        let dot = publication.header.stamp.dot;
        let dot_key = accepted_dot_key(dot).to_vec();
        if shared
            .expected_dots
            .insert(dot_key.clone(), *publication.semantic_id.as_bytes())
            .is_some()
        {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "multiple semantic classes claim one accepted causal dot",
            )));
        }
        let accepted = accepted_dots
            .as_ref()
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob publications exist without the shared accepted-dot ledger",
                ))
            })?
            .get(dot_key.as_slice())?
            .map(|value| parse_digest32("accepted dot table", value.value()))
            .transpose()?
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob publication is missing its accepted-dot row",
                ))
            })?;
        if accepted != *publication.semantic_id.as_bytes() {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "accepted-dot ledger points to another semantic publication",
            )));
        }
        if publisher_high
            .as_ref()
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob publications exist without the shared publisher high-water ledger",
                ))
            })?
            .get(dot.publisher.as_slice())?
            .map_or(0, |value| value.value())
            < dot.counter
        {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "publisher high-water is behind an accepted Blob dot",
            )));
        }
        shared
            .expected_publisher_high
            .entry(dot.publisher.to_vec())
            .and_modify(|current| *current = (*current).max(dot.counter))
            .or_insert(dot.counter);
        let frontier_key = causal_frontier_key(
            &publication.header.topic,
            &publication.header.scope,
            dot.publisher,
        )?;
        if frontier
            .as_ref()
            .ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob publications exist without the shared causal frontier",
                ))
            })?
            .get(frontier_key.as_slice())?
            .map_or(0, |value| value.value())
            < dot.counter
        {
            return Err(blob_error(BlobStoreError::SchemaInvariant(
                "causal frontier is behind an accepted Blob dot",
            )));
        }
        shared
            .expected_frontier
            .entry(frontier_key)
            .and_modify(|current| *current = (*current).max(dot.counter))
            .or_insert(dot.counter);
        shared
            .domain_publishers
            .entry(event_domain_prefix(
                &publication.header.topic,
                &publication.header.scope,
            )?)
            .or_default()
            .insert(dot.publisher);
    }
    if read
        .list_multimap_tables()?
        .any(|table| table.name() == lifecycle::BLOB_REPLAY_CAUSAL_FENCES.name())
    {
        return Err(blob_error(BlobStoreError::SchemaInvariant(
            "Blob replay causal-fence table has the wrong table kind",
        )));
    }
    if table_names.contains(lifecycle::BLOB_REPLAY_FENCES.name()) {
        let mut causal_fences = BTreeMap::new();
        if table_names.contains(lifecycle::BLOB_REPLAY_CAUSAL_FENCES.name()) {
            for row in read
                .open_table(lifecycle::BLOB_REPLAY_CAUSAL_FENCES)?
                .iter()?
            {
                let (key, value) = row?;
                let digest: [u8; 32] = value.value().try_into().map_err(|_| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob replay causal fence has an invalid digest length",
                    ))
                })?;
                if key.value().len() != 40
                    || causal_fences.insert(key.value().to_vec(), digest).is_some()
                {
                    return Err(blob_error(BlobStoreError::SchemaInvariant(
                        "Blob replay causal fence key is not canonical",
                    )));
                }
            }
        }
        let replays = read.open_table(lifecycle::BLOB_REPLAY_FENCES)?;
        extend_shared_with_expired_blob_replay_authority(
            &replays,
            accepted_dots.as_ref().ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob replay fences exist without the shared accepted-dot ledger",
                ))
            })?,
            publisher_high.as_ref().ok_or_else(|| {
                blob_error(BlobStoreError::SchemaInvariant(
                    "Blob replay fences exist without the shared publisher high-water ledger",
                ))
            })?,
            &publication_transfers,
            causal_fences,
            shared,
        )?;
    }
    Ok(snapshot)
}

fn initialize_blob_schema(write: &redb::WriteTransaction) -> Result<(), StoreError> {
    let _ = write.open_table(BLOB_PUBLICATIONS)?;
    let _ = write.open_table(BLOB_BYTES)?;
    let _ = write.open_table(BLOB_SEMANTIC_ITEMS)?;
    let _ = write.open_table(BLOB_CONTENT_INDEX)?;
    let _ = write.open_table(BLOB_ACCEPTANCE_MARKERS)?;
    let _ = write.open_table(BLOB_OPERATIONS)?;
    let _ = write.open_table(BLOB_UPLOADS)?;
    let _ = write.open_table(upload::BLOB_UPLOAD_PACK_REFERENCES)?;
    let _ = write.open_table(pack_lifecycle::BLOB_PROFILE5_PACKS)?;
    let _ = write.open_table(BLOB_IMPORTS)?;
    let _ = write.open_table(BLOB_CHUNKS)?;
    {
        let owner_token = generate_depot_owner_token()?;
        let mut depot = write.open_table(BLOB_DEPOT_METADATA)?;
        depot.insert(DEPOT_SCHEMA_VERSION, BLOB_DEPOT_SCHEMA_VERSION)?;
        depot.insert(DEPOT_VARIANT_COUNT, 0)?;
        depot.insert(DEPOT_COMMITTED_CHUNK_COUNT, 0)?;
        depot.insert(DEPOT_COMMITTED_FILE_BYTES, 0)?;
        depot.insert(DEPOT_RESERVED_FILE_BYTES, 0)?;
        for (field, chunk) in depot_owner_token_fields()
            .into_iter()
            .zip(owner_token.chunks_exact(8))
        {
            depot.insert(
                field,
                u64::from_be_bytes(chunk.try_into().map_err(|_| {
                    blob_error(BlobStoreError::SchemaInvariant(
                        "Blob depot owner token chunk has invalid length",
                    ))
                })?),
            )?;
        }
    }
    let mut metadata = write.open_table(METADATA)?;
    for field in blob_global_metadata_fields() {
        metadata.insert(field, 0)?;
    }
    metadata.insert(
        BLOB_OPERATION_KEY_SCHEMA_VERSION_FIELD,
        BLOB_OPERATION_KEY_SCHEMA_VERSION,
    )?;
    initialize_blob_network_schema(write)?;
    Ok(())
}

fn initialize_blob_network_schema(write: &redb::WriteTransaction) -> Result<(), StoreError> {
    let _ = write.open_table(BLOB_PENDING_SOURCES)?;
    let _ = write.open_table(BLOB_CARRIER_PREFIXES)?;
    let _ = write.open_table(BLOB_CARRIER_FETCH_CURSORS)?;
    let mut metadata = write.open_table(BLOB_NETWORK_METADATA)?;
    if metadata.get(BLOB_NETWORK_SCHEMA_VERSION_FIELD)?.is_none() {
        metadata.insert(
            BLOB_NETWORK_SCHEMA_VERSION_FIELD,
            BLOB_NETWORK_SCHEMA_VERSION,
        )?;
        metadata.insert(BLOB_NETWORK_STAGING_ROWS, 0)?;
        metadata.insert(BLOB_NETWORK_STAGING_BYTES, 0)?;
    }
    Ok(())
}

fn legacy_blob_table_names() -> [&'static str; 9] {
    [
        BLOB_PUBLICATIONS.name(),
        BLOB_BYTES.name(),
        BLOB_SEMANTIC_ITEMS.name(),
        BLOB_CONTENT_INDEX.name(),
        BLOB_ACCEPTANCE_MARKERS.name(),
        BLOB_OPERATIONS.name(),
        BLOB_IMPORTS.name(),
        BLOB_CHUNKS.name(),
        BLOB_DEPOT_METADATA.name(),
    ]
}

fn network_blob_table_names() -> [&'static str; 4] {
    [
        BLOB_PENDING_SOURCES.name(),
        BLOB_CARRIER_PREFIXES.name(),
        BLOB_NETWORK_METADATA.name(),
        BLOB_CARRIER_FETCH_CURSORS.name(),
    ]
}

fn stream_blob_table_names() -> [&'static str; 6] {
    [
        BLOB_STREAM_RESERVATIONS.name(),
        BLOB_STREAM_OPERATIONS.name(),
        BLOB_STREAM_PUBLICATIONS.name(),
        BLOB_STREAM_CONFLICTS.name(),
        BLOB_STREAM_VARIANTS.name(),
        BLOB_STREAM_RETIREMENTS.name(),
    ]
}

