    fn blob_lifecycle_tables_present(path: &Path) -> BTreeSet<String> {
        let database = redb::Builder::new()
            .open_read_only(path)
            .expect("read lifecycle table names");
        database
            .begin_read()
            .expect("lifecycle table-name transaction")
            .list_tables()
            .expect("lifecycle table names")
            .map(|table| table.name().to_owned())
            .filter(|name| {
                [
                    lifecycle::BLOB_LIFECYCLE_METADATA.name(),
                    lifecycle::BLOB_VARIANT_REFERENCES.name(),
                    lifecycle::BLOB_LINEAGE_FENCES.name(),
                    lifecycle::BLOB_REPLAY_FENCES.name(),
                    lifecycle::BLOB_MAINTENANCE_CURSORS.name(),
                    lifecycle::BLOB_OPERATION_OWNERS.name(),
                    lifecycle::BLOB_DELIVERY_OWNERS.name(),
                    lifecycle::BLOB_RETENTION_DEADLINES.name(),
                    lifecycle::BLOB_TTL_DEADLINES.name(),
                    lifecycle::BLOB_TTL_EXPIRY_CURSORS.name(),
                    lifecycle::BLOB_RETIREMENT_RESOLVERS.name(),
                ]
                .contains(&name.as_str())
            })
            .collect()
    }

    fn with_blob_lifecycle_predecessor_setup<T>(setup: impl FnOnce() -> T) -> T {
        lifecycle::TEST_BLOB_LIFECYCLE_MIGRATION_DISABLED.set(true);
        let output = setup();
        lifecycle::TEST_BLOB_LIFECYCLE_MIGRATION_DISABLED.set(false);
        output
    }

    fn downgrade_blob_metadata_to_v2_for_test(encoded: &[u8]) -> Vec<u8> {
        assert_eq!(encoded.first().copied(), Some(BLOB_METADATA_VERSION));
        let mut lifetime_offset = 1 + 5 * 32;
        match encoded.get(lifetime_offset).copied() {
            Some(0) => lifetime_offset += 1,
            Some(1) => lifetime_offset += 1 + 2 * 32,
            _ => panic!("current Blob metadata lineage flag"),
        }
        let lifetime_len = usize::from(u16::from_be_bytes(
            encoded[lifetime_offset..lifetime_offset + 2]
                .try_into()
                .expect("lifetime length"),
        ));
        assert_eq!(
            &encoded[lifetime_offset + 2..lifetime_offset + 2 + lifetime_len],
            &[0],
            "historical predecessor fixtures can only erase durable lifetime state",
        );
        let mut predecessor = Vec::with_capacity(encoded.len() - 3);
        predecessor.extend_from_slice(&encoded[..lifetime_offset]);
        predecessor[0] = BLOB_METADATA_VERSION_V2;
        predecessor.extend_from_slice(&encoded[lifetime_offset + 2 + lifetime_len..]);
        predecessor
    }

    fn mutate_current_pending_metadata_for_test(
        encoded: &[u8],
        rebind: bool,
        mutate: impl FnOnce(&mut BlobMetadata),
    ) -> Vec<u8> {
        let mut pending = decode_pending_blob_source(encoded).expect("current pending source");
        mutate(&mut pending.metadata);
        if rebind {
            pending.authenticated_source_binding =
                pending_blob_authenticated_source_binding(&pending.metadata, &pending.sealed)
                    .expect("recompute test binding");
            return encode_pending_blob_source(&pending).expect("re-encode rebound pending source");
        }

        let metadata_length_offset = 1 + 8 + 2 * 32;
        let metadata_offset = metadata_length_offset + 4;
        let metadata_len = usize::try_from(u32::from_be_bytes(
            encoded[metadata_length_offset..metadata_offset]
                .try_into()
                .expect("pending metadata length"),
        ))
        .expect("pending metadata length fits usize");
        let metadata = encode_blob_metadata(pending.metadata).expect("encode tampered metadata");
        assert_eq!(metadata.len(), metadata_len, "tamper must remain same-size");
        let mut tampered = encoded.to_vec();
        tampered[metadata_offset..metadata_offset + metadata_len].copy_from_slice(&metadata);
        tampered
    }

    fn rewrite_pending_row_for_test(path: &Path, transfer: BlobTransferId, encoded: &[u8]) {
        let database = Database::open(path).expect("pending tamper database");
        let write = database.begin_write().expect("pending tamper write");
        write
            .open_table(BLOB_PENDING_SOURCES)
            .expect("pending tamper table")
            .insert(transfer.as_bytes().as_slice(), encoded)
            .expect("rewrite pending tamper row");
        write.commit().expect("commit pending tamper row");
    }

    fn downgrade_blob_publication_for_test(encoded: &[u8], wrapper: u8) -> Vec<u8> {
        let payload_offset = match encoded.get(1).copied() {
            Some(lifecycle::PUBLICATION_STATE_LIVE_TAG) => 2,
            Some(lifecycle::PUBLICATION_STATE_RETIRED_TAG) => {
                match lifecycle::retired_publication_payload(encoded)
                    .expect("retired publication payload")
                {
                    Some((_, payload)) => encoded.len() - payload.len(),
                    None => {
                        let mut compact = encoded.to_vec();
                        compact[0] = wrapper;
                        return compact;
                    }
                }
            }
            _ => panic!("current publication state"),
        };
        let payload = downgrade_blob_metadata_to_v2_for_test(&encoded[payload_offset..]);
        let mut predecessor = encoded[..payload_offset].to_vec();
        predecessor[0] = wrapper;
        predecessor.extend_from_slice(&payload);
        predecessor
    }

    fn downgrade_pending_sources_to_v2_for_test(write: &redb::WriteTransaction) {
        let rows = write
            .open_table(BLOB_PENDING_SOURCES)
            .expect("current pending sources")
            .iter()
            .expect("current pending rows")
            .map(|row| {
                let (key, value) = row.expect("current pending row");
                (key.value().to_vec(), value.value().to_vec())
            })
            .collect::<Vec<_>>();
        let mut table = write
            .open_table(BLOB_PENDING_SOURCES)
            .expect("rewrite pending predecessors");
        let mut removed_bytes = 0u64;
        for (key, encoded) in rows {
            assert_eq!(encoded.first().copied(), Some(PENDING_BLOB_SOURCE_VERSION));
            let metadata_length_offset = 1 + 8 + 2 * 32;
            let metadata_offset = metadata_length_offset + 4;
            let metadata_len = usize::try_from(u32::from_be_bytes(
                encoded[metadata_length_offset..metadata_offset]
                    .try_into()
                    .expect("pending metadata length"),
            ))
            .expect("pending metadata length fits usize");
            let metadata = downgrade_blob_metadata_to_v2_for_test(
                &encoded[metadata_offset..metadata_offset + metadata_len],
            );
            let mut predecessor = encoded[..metadata_length_offset].to_vec();
            predecessor[0] = PENDING_BLOB_SOURCE_VERSION_V2;
            predecessor.extend_from_slice(
                &u32::try_from(metadata.len())
                    .expect("predecessor metadata length")
                    .to_be_bytes(),
            );
            predecessor.extend_from_slice(&metadata);
            predecessor.extend_from_slice(&encoded[metadata_offset + metadata_len + 32..]);
            removed_bytes = removed_bytes
                .checked_add(
                    u64::try_from(encoded.len() - predecessor.len())
                        .expect("pending predecessor byte delta fits u64"),
                )
                .expect("pending predecessor byte delta does not overflow");
            table
                .insert(key.as_slice(), predecessor.as_slice())
                .expect("write pending predecessor");
        }
        drop(table);
        if removed_bytes != 0 {
            let mut metadata = write
                .open_table(BLOB_NETWORK_METADATA)
                .expect("network metadata for pending predecessor");
            let staging_bytes = metadata
                .get(BLOB_NETWORK_STAGING_BYTES)
                .expect("read predecessor staging bytes")
                .expect("predecessor staging bytes exist")
                .value();
            metadata
                .insert(
                    BLOB_NETWORK_STAGING_BYTES,
                    staging_bytes
                        .checked_sub(removed_bytes)
                        .expect("pending predecessor staging bytes cover downgrade"),
                )
                .expect("update predecessor staging bytes");
        }
    }

    fn downgrade_pressure_pending_roots_to_v3_for_test(write: &redb::WriteTransaction) {
        let rows = write
            .open_table(pressure::BLOB_PRESSURE_PENDING_ROOTS)
            .expect("current pressure pending roots")
            .iter()
            .expect("current pressure pending-root rows")
            .map(|row| {
                let (key, value) = row.expect("current pressure pending-root row");
                (key.value().to_vec(), value.value().to_vec())
            })
            .collect::<Vec<_>>();
        let mut table = write
            .open_table(pressure::BLOB_PRESSURE_PENDING_ROOTS)
            .expect("rewrite pressure-v3 pending roots");
        for (key, encoded) in rows {
            let root = pressure::decode_pending_root(&encoded)
                .expect("decode current pressure pending root");
            let predecessor = pressure::encode_pending_root_for_generation(
                &root,
                pressure::PressurePendingRootEncodingGeneration::PressureV3,
            )
            .expect("encode pressure-v3 pending root");
            assert_eq!(encoded.len() - predecessor.len(), 32);
            table
                .insert(key.as_slice(), predecessor.as_slice())
                .expect("write pressure-v3 pending root");
        }
    }

    fn downgrade_blob_policy_to_v4_for_test(path: &Path) {
        let database = Database::open(path).expect("raw Blob policy-v4 database");
        let write = database.begin_write().expect("raw Blob policy-v4 write");
        pressure::downgrade_pressure_v5_to_v4_for_test(&write)
            .expect("downgrade pressure-v5 to v4");
        lifecycle::downgrade_lifecycle_v5_to_v4_for_test(&write)
            .expect("downgrade lifecycle-v5 to v4");
        write.commit().expect("commit Blob policy-v4 predecessor");
    }

    fn strip_blob_lifecycle_schema_for_test(path: &Path) {
        let database = Database::open(path).expect("raw lifecycle predecessor database");
        let write = database
            .begin_write()
            .expect("raw lifecycle predecessor write");
        if write
            .list_tables()
            .expect("predecessor pressure table names")
            .any(|table| table.name() == pressure::BLOB_PRESSURE_REANCHOR_CURSORS.name())
        {
            lifecycle::TEST_BLOB_LIFECYCLE_MIGRATION_DISABLED.set(true);
            let downgrade = pressure::downgrade_pressure_v5_to_v4_for_test(&write);
            lifecycle::TEST_BLOB_LIFECYCLE_MIGRATION_DISABLED.set(false);
            downgrade.expect("downgrade pressure before stripping lifecycle");
        }
        let existing = write
            .list_tables()
            .expect("predecessor table names")
            .map(|table| table.name().to_owned())
            .collect::<BTreeSet<_>>();
        if existing.contains(lifecycle::BLOB_LIFECYCLE_METADATA.name()) {
            write
                .delete_table(lifecycle::BLOB_LIFECYCLE_METADATA)
                .expect("delete lifecycle metadata");
        }
        if existing.contains(lifecycle::BLOB_VARIANT_REFERENCES.name()) {
            write
                .delete_table(lifecycle::BLOB_VARIANT_REFERENCES)
                .expect("delete lifecycle references");
        }
        if existing.contains(lifecycle::BLOB_LINEAGE_FENCES.name()) {
            write
                .delete_table(lifecycle::BLOB_LINEAGE_FENCES)
                .expect("delete lifecycle lineage fences");
        }
        if existing.contains(lifecycle::BLOB_REPLAY_FENCES.name()) {
            write
                .delete_table(lifecycle::BLOB_REPLAY_FENCES)
                .expect("delete lifecycle replay fences");
        }
        if existing.contains(lifecycle::BLOB_MAINTENANCE_CURSORS.name()) {
            write
                .delete_table(lifecycle::BLOB_MAINTENANCE_CURSORS)
                .expect("delete lifecycle cursors");
        }
        if existing.contains(lifecycle::BLOB_TTL_DEADLINES.name()) {
            write
                .delete_table(lifecycle::BLOB_TTL_DEADLINES)
                .expect("delete lifecycle TTL deadlines");
        }
        if existing.contains(lifecycle::BLOB_TTL_EXPIRY_CURSORS.name()) {
            write
                .delete_table(lifecycle::BLOB_TTL_EXPIRY_CURSORS)
                .expect("delete lifecycle TTL cursors");
        }
        if existing.contains(lifecycle::BLOB_OPERATION_OWNERS.name()) {
            write
                .delete_table(lifecycle::BLOB_OPERATION_OWNERS)
                .expect("delete lifecycle operation owners");
        }
        if existing.contains(lifecycle::BLOB_DELIVERY_OWNERS.name()) {
            write
                .delete_table(lifecycle::BLOB_DELIVERY_OWNERS)
                .expect("delete lifecycle delivery owners");
        }
        if existing.contains(lifecycle::BLOB_RETENTION_DEADLINES.name()) {
            write
                .delete_table(lifecycle::BLOB_RETENTION_DEADLINES)
                .expect("delete lifecycle retention deadlines");
        }
        if existing.contains(lifecycle::BLOB_RETIREMENT_RESOLVERS.name()) {
            write
                .delete_table(lifecycle::BLOB_RETIREMENT_RESOLVERS)
                .expect("delete lifecycle retirement resolvers");
        }

        let publications = write
            .open_table(BLOB_PUBLICATIONS)
            .expect("predecessor publications");
        let publication_rows = publications
            .iter()
            .expect("predecessor publication rows")
            .map(|row| {
                let (key, value) = row.expect("predecessor publication row");
                (key.value().to_vec(), value.value().to_vec())
            })
            .collect::<Vec<_>>();
        drop(publications);
        let mut publications = write
            .open_table(BLOB_PUBLICATIONS)
            .expect("rewrite predecessor publications");
        for (key, value) in publication_rows {
            if value.first().copied() == Some(BLOB_METADATA_VERSION) {
                let predecessor = downgrade_blob_metadata_to_v2_for_test(&value);
                publications
                    .insert(key.as_slice(), predecessor.as_slice())
                    .expect("downgrade raw predecessor publication");
            } else if value.len() >= 3
                && matches!(value[0], 3..=5)
                && value[1] == 1
                && matches!(value[2], 1..=3)
            {
                let predecessor = downgrade_blob_metadata_to_v2_for_test(&value[2..]);
                publications
                    .insert(key.as_slice(), predecessor.as_slice())
                    .expect("unwrap predecessor publication");
            }
        }
        drop(publications);

        let operations = write
            .open_table(BLOB_OPERATIONS)
            .expect("predecessor operations");
        let operation_rows = operations
            .iter()
            .expect("predecessor operation rows")
            .map(|row| {
                let (key, value) = row.expect("predecessor operation row");
                (key.value().to_vec(), value.value().to_vec())
            })
            .collect::<Vec<_>>();
        drop(operations);
        let mut operations = write
            .open_table(BLOB_OPERATIONS)
            .expect("rewrite predecessor operations");
        for (key, value) in operation_rows {
            if value.len() >= 3 && value[0] == 2 && value[1] == 1 && value[2] == 1 {
                operations
                    .insert(key.as_slice(), &value[2..])
                    .expect("unwrap predecessor operation");
            }
        }
        drop(operations);
        downgrade_pending_sources_to_v2_for_test(&write);
        downgrade_pressure_pending_roots_to_v3_for_test(&write);
        write
            .open_table(pressure::BLOB_PRESSURE_METADATA)
            .expect("predecessor pressure metadata")
            .insert(
                pressure::PRESSURE_SCHEMA_VERSION_FIELD,
                pressure::PREVIOUS_PRESSURE_SCHEMA_VERSION,
            )
            .expect("downgrade predecessor pressure schema");
        write.commit().expect("commit lifecycle predecessor");
    }

