    #[test]
    fn blob_maintenance_wrong_kind_carrier_cursor_fails_turn_and_restart() {
        // Break caught: a composite cursor is typed durable state, not merely
        // a tag plus a byte string of the right length.
        for mode in ["turn", "restart"] {
            let root = BlobTestRoot::new(&format!("maintenance-wrong-kind-cursor-{mode}"));
            let services = blob_services(if mode == "turn" { 0x5e } else { 0x5f });
            let store = Store::open_for_mission(&root.database, services.authority)
                .expect("wrong-kind cursor store");
            let mut position = vec![MAINTENANCE_SECONDARY_SOURCE_TAG];
            position.extend_from_slice(&[0x77; 32]);
            position.extend_from_slice(&[0x01; BLOB_CARRIER_OBJECT_ID_BYTES]);
            set_maintenance_cursor(
                &store,
                lifecycle::BlobMaintenanceClass::InvalidPendingWork,
                Some(&position),
            );
            let before = blob_current_admission_digest(&store);
            if mode == "turn" {
                assert_blob_schema_invariant(
                    &store
                        .run_blob_maintenance_turn(maintenance_budget(1))
                        .expect_err("wrong-kind cursor fails the turn"),
                );
                assert_eq!(blob_current_admission_digest(&store), before);
            } else {
                drop(store);
                match Store::open_for_mission(&root.database, services.authority) {
                    Ok(_) => panic!("wrong-kind cursor passed startup audit"),
                    Err(error) => assert_blob_schema_invariant(&error),
                }
            }
        }
    }

    #[test]
    fn blob_maintenance_malformed_cursors_and_impossible_accounting_fail_closed() {
        // Break caught: damaged durable progress or impossible lifecycle
        // counters must not silently restart scheduling at class one.
        for (label, corrupt) in [("class", 0u8), ("key", 1u8), ("accounting", 2u8)] {
            let root = BlobTestRoot::new(&format!("maintenance-corrupt-{label}"));
            let services = blob_services(0x60 + corrupt);
            let store = Store::open_for_mission(&root.database, services.authority)
                .expect("maintenance corruption store");
            let write = store
                .database
                .begin_write()
                .expect("maintenance corruption transaction");
            match corrupt {
                0 => {
                    write
                        .open_table(lifecycle::BLOB_MAINTENANCE_CURSORS)
                        .expect("maintenance cursors")
                        .insert(0, [1, 7].as_slice())
                        .expect("corrupt next class");
                }
                1 => {
                    let mut cursors = write
                        .open_table(lifecycle::BLOB_MAINTENANCE_CURSORS)
                        .expect("maintenance cursors");
                    cursors
                        .insert(0, [1, 3].as_slice())
                        .expect("select staging class");
                    cursors
                        .insert(3, [1, 1, 0].as_slice())
                        .expect("corrupt staging cursor key");
                }
                2 => {
                    write
                        .open_table(lifecycle::BLOB_LIFECYCLE_METADATA)
                        .expect("lifecycle metadata")
                        .insert("publication_rows", 1)
                        .expect("corrupt publication accounting");
                }
                _ => unreachable!(),
            }
            write.commit().expect("commit maintenance corruption");
            let before = blob_current_admission_digest(&store);
            assert_blob_schema_invariant(
                &store
                    .run_blob_maintenance_turn(maintenance_budget(1))
                    .expect_err("maintenance corruption fails closed"),
            );
            assert_eq!(blob_current_admission_digest(&store), before);
        }
    }

    #[test]
    fn blob_maintenance_admits_manifests_without_physical_mutation() {
        // Break caught: metadata admission may move exact chunk authority, but
        // this increment must perform no physical deletion.
        let root = BlobTestRoot::new("maintenance-nondestructive");
        let source_root = BlobTestRoot::new("maintenance-nondestructive-source");
        let mut services = blob_services(0x6a);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("non-destructive maintenance store");
        let source = Store::open_for_mission(&source_root.database, services.authority)
            .expect("non-destructive maintenance source");
        let published_plaintext = vec![0x31; SELECTED_BLOB_CHUNK_SIZE as usize + 17];
        let prepared = prepared_blob(&published_plaintext);
        publish_blob(
            &store,
            &mut services,
            &prepared,
            &published_plaintext,
            1,
            b"maintenance-nondestructive-operation",
        );
        publish_blob(
            &source,
            &mut services,
            &prepared,
            &published_plaintext,
            1,
            b"maintenance-nondestructive-source-operation",
        );
        stage_pending_source_for_maintenance(
            &source,
            &store,
            &mut services,
            &vec![0x42; SELECTED_BLOB_CHUNK_SIZE as usize + 23],
            1,
            true,
        );
        let staging_variant = install_unreferenced_variant(
            &store,
            &services,
            b"unreferenced local staging",
            1,
            false,
        );
        let completed_variant = install_unreferenced_variant(
            &store,
            &services,
            b"unreferenced completed variant",
            1,
            true,
        );
        let before_stats = store.blob_stats().expect("maintenance before stats");
        let before_files = depot_file_snapshot(&root.depot());
        let budget = maintenance_budget(64);
        set_maintenance_next_class(
            &store,
            lifecycle::BlobMaintenanceClass::UnreferencedLocalImportStaging,
        );
        let staging_progress = store
            .run_blob_maintenance_turn(budget)
            .expect("non-destructive staging admission turn");
        assert_eq!(staging_progress.files_examined, 0);
        assert!(!staging_progress.awaiting_later_handler);
        set_maintenance_next_class(
            &store,
            lifecycle::BlobMaintenanceClass::UnreferencedCompletedVariants,
        );
        let completed_progress = store
            .run_blob_maintenance_turn(budget)
            .expect("non-destructive completed admission turn");
        assert_eq!(completed_progress.files_examined, 0);
        assert!(!completed_progress.awaiting_later_handler);
        assert!(staging_progress.candidates.contains(
            &lifecycle::BlobMaintenanceCandidate::UnreferencedLocalImport { staging_variant }
        ));
        assert!(completed_progress.candidates.contains(
            &lifecycle::BlobMaintenanceCandidate::UnreferencedCompletedVariant {
                variant: completed_variant,
            }
        ));
        assert_eq!(
            store.blob_stats().expect("maintenance after stats"),
            before_stats
        );
        deletion_manifest_for_test(&store, staging_variant);
        deletion_manifest_for_test(&store, completed_variant);
        assert_eq!(depot_file_snapshot(&root.depot()), before_files);
    }

    #[test]
    fn blob_maintenance_structural_contradiction_fails_before_cursor_advance() {
        // Break caught: maintenance must preserve contradictory evidence and
        // leave both class and per-class progress at the failing position.
        let root = BlobTestRoot::new("maintenance-structural-contradiction");
        let mut services = blob_services(0x72);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("maintenance contradiction store");
        let plaintext = b"maintenance contradiction publication".to_vec();
        let prepared = prepared_blob(&plaintext);
        let (stored, _, _) = publish_blob(
            &store,
            &mut services,
            &prepared,
            &plaintext,
            1,
            b"maintenance-contradiction-operation",
        );
        synchronize_blob_policy_for_maintenance_test(&store);
        {
            let write = store
                .database
                .begin_write()
                .expect("contradict maintenance authority");
            let mut key = Vec::with_capacity(65);
            key.extend_from_slice(stored.variant_id.as_bytes());
            key.push(1);
            key.extend_from_slice(stored.transfer_id.as_bytes());
            write
                .open_table(lifecycle::BLOB_VARIANT_REFERENCES)
                .expect("variant references")
                .remove(key.as_slice())
                .expect("remove publication reference")
                .expect("publication reference exists");
            write
                .open_table(lifecycle::BLOB_LIFECYCLE_METADATA)
                .expect("lifecycle metadata")
                .insert("reference_rows", 0)
                .expect("adjust reference accounting");
            write.commit().expect("commit maintenance contradiction");
        }
        set_maintenance_next_class(
            &store,
            lifecycle::BlobMaintenanceClass::ExpiredPublicationsAndPendingSources,
        );
        let before = blob_current_admission_digest(&store);
        assert_blob_schema_invariant(
            &store
                .run_blob_maintenance_turn(maintenance_budget(6))
                .expect_err("structural contradiction fails maintenance"),
        );
        assert_eq!(blob_current_admission_digest(&store), before);
    }

    #[test]
    fn blob_deletion_manifest_audit_reproduces_exact_variant_chunks_root_and_charge() {
        let root = BlobTestRoot::new("deletion-exact-audit");
        let services = blob_services(0xa1);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("deletion audit store");
        let plaintext = vec![0x41; SELECTED_BLOB_CHUNK_SIZE as usize + 7];
        let prepared = prepared_blob(&plaintext);
        finish_variant(&store, &services.publisher, &prepared, &plaintext, 1)
            .expect("finish unreferenced deletion variant");
        let stats = store.blob_stats().expect("pre-deletion depot stats");
        let variant = {
            let read = store.database.begin_read().expect("read deletion import");
            let imports = read.open_table(BLOB_IMPORTS).expect("deletion imports");
            let (key, _) = imports
                .iter()
                .expect("deletion import rows")
                .next()
                .expect("one deletion import")
                .expect("deletion import row");
            BlobVariantId::from_bytes(key.value().try_into().expect("variant key"))
        };
        let chunk_files_before = (0..2)
            .map(|index| {
                std::fs::read(root.chunk_path(variant, index))
                    .expect("read protected deletion chunk before audit")
            })
            .collect::<Vec<_>>();

        let write = store
            .database
            .begin_write()
            .expect("begin deletion audit fixture");
        let staged = deletion::move_finalized_variant_to_manifest_for_test(&write, variant)
            .expect("move exact variant into deletion authority");
        let audited =
            deletion::audit_blob_deletion_write(&write, Some(store.blob_depot_owner_binding))
                .expect("audit exact deletion authority");
        let reproduced = audited
            .manifests
            .get(&variant)
            .expect("audited deletion manifest");
        assert_eq!(reproduced, &staged);
        assert_eq!(reproduced.totals.chunks, 2);
        assert_eq!(reproduced.totals.queued, 2);
        assert_eq!(reproduced.totals.deleted, 0);
        assert_eq!(reproduced.totals.charged_variants, 1);
        assert_eq!(reproduced.totals.charged_files, 2);
        assert!(reproduced.finalized_root.is_some());
        assert_eq!(audited.stats.manifests, 1);
        assert_eq!(audited.stats.chunks, 2);
        assert_eq!(
            audited.stats.charged_committed_bytes,
            stats.committed_file_bytes
        );
        assert_eq!(
            audited.stats.charged_reserved_bytes,
            stats.reserved_file_bytes
        );
        depot::audit_depot_write(
            &write,
            &store.path,
            store.backing_identity,
            store.blob_depot_owner_token,
            stats,
        )
        .expect("queued deletion files pass manifest-first physical audit");
        for (index, before) in chunk_files_before.iter().enumerate() {
            assert_eq!(
                std::fs::read(
                    root.chunk_path(variant, u64::try_from(index).expect("chunk index"),)
                )
                .expect("protected queued deletion chunk survives generic cleanup"),
                *before,
            );
        }
        write.commit().expect("commit exact deletion fixture");
    }

    #[test]
    fn blob_gc_status_reports_sanitized_pending_files_bytes_retries() {
        // Break caught: deletion manifests that still own physical charge must
        // be visible without exposing a variant, lineage, or filesystem path.
        let root = BlobTestRoot::new("gc-status-pending");
        let services = blob_services(0xb1);
        let store =
            Store::open_for_mission(&root.database, services.authority).expect("GC status store");
        let variant = install_unreferenced_variant(
            &store,
            &services,
            &vec![0x51; SELECTED_BLOB_CHUNK_SIZE as usize + 9],
            1,
            true,
        );
        store
            .test_admit_blob_deletion_manifest(variant)
            .expect("admit GC status manifest");
        let read = store.database.begin_read().expect("select retry fixture");
        let deletion::BlobDeletionSelection::Work(work) =
            deletion::select_physical_work_read(&read, None, u64::MAX, u64::MAX)
                .expect("select retry work")
        else {
            panic!("pending manifest must select physical work");
        };
        drop(read);
        let write = store.database.begin_write().expect("record retry fixture");
        let turn = deletion::advance_blob_deletion_maintenance_turn(&write)
            .expect("advance retry fixture turn");
        deletion::record_physical_failure_write(
            &write,
            &work,
            turn,
            deletion::BlobDeletionFailureCategory::ChunkUnlink,
        )
        .expect("record sanitized retry");
        write.commit().expect("commit retry fixture");

        let status = store
            .blob_gc_status(Some(CustodySample {
                clock_id: [0x11; 16],
                tick_ms: 40,
            }))
            .expect("GC status");
        assert_eq!(status.deletion_pending_files, 2);
        assert!(status.deletion_pending_bytes > 0);
        assert_eq!(status.retry_attempts, 1);
        assert_eq!(status.next_retry_turn, Some(2));
        assert_eq!(status.retry_state, BlobGcRetryState::Ready);
        assert_eq!(
            status.last_failure,
            Some(BlobGcFailureCategory::ChunkUnlink)
        );
        assert_eq!(status.oldest_pending_age_ms, Some(0));
    }

    #[test]
    fn blob_gc_status_reports_security_fence_and_publication_lifecycle_usage_and_caps() {
        // Break caught: status must not describe reclaimable bulk bytes while
        // omitting the permanent security authorities that GC cannot recover.
        let root = BlobTestRoot::new("gc-status-security-capacity");
        let services = blob_services(0xb2);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("GC capacity status store");
        let status = store.blob_gc_status(None).expect("empty GC status");
        let limits = store.blob_lifecycle_limits();
        assert_eq!(status.lineage_fence_rows, 0);
        assert_eq!(status.lineage_fence_row_cap, limits.max_lineage_rows());
        assert_eq!(status.lineage_fence_byte_cap, limits.max_lineage_bytes());
        assert_eq!(status.replay_fence_rows, 0);
        assert_eq!(status.replay_fence_row_cap, limits.max_replay_rows());
        assert_eq!(status.replay_fence_byte_cap, limits.max_replay_bytes());
        assert_eq!(status.publication_lifecycle_rows, 0);
        assert_eq!(
            status.publication_lifecycle_row_cap,
            limits.max_publication_rows()
        );
    }

    #[test]
    fn blob_gc_oldest_pending_age_is_conservative_across_clock_domain_loss() {
        // Break caught: loss of monotonic-domain continuity must preserve the
        // accumulated lower bound and mark it conservative, never synthesize
        // elapsed wall-clock time.
        let root = BlobTestRoot::new("gc-status-age-domain-loss");
        let services = blob_services(0xb5);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("GC age status store");
        let variant =
            install_unreferenced_variant(&store, &services, b"pending deletion age", 1, true);
        store
            .test_admit_blob_deletion_manifest(variant)
            .expect("admit deletion-age manifest");
        let first = CustodySample {
            clock_id: [0x31; 16],
            tick_ms: 10,
        };
        let write = store.database.begin_write().expect("age fixture write");
        let continuity = deletion::observe_blob_deletion_continuity_write(&write, first)
            .expect("initial deletion continuity");
        deletion::set_blob_deletion_age_for_test(
            &write,
            variant,
            deletion::BlobDeletionAge {
                cumulative_age_ms: 7,
                checkpoint: Some(first),
                continuity_generation: continuity.generation,
                continuity_lost: false,
            },
            Some(continuity),
        )
        .expect("set deletion age");
        write.commit().expect("commit deletion age");

        let same = store
            .blob_gc_status(Some(CustodySample {
                clock_id: first.clock_id,
                tick_ms: 43,
            }))
            .expect("same-domain deletion age");
        assert_eq!(same.oldest_pending_age_ms, Some(40));
        assert!(!same.oldest_pending_age_is_lower_bound);
        let lost = store
            .blob_gc_status(Some(CustodySample {
                clock_id: [0x32; 16],
                tick_ms: 9_999_999,
            }))
            .expect("lost-domain deletion age");
        assert_eq!(lost.oldest_pending_age_ms, Some(7));
        assert!(lost.oldest_pending_age_is_lower_bound);
    }

