    #[test]
    fn blob_delete_pending_remains_uncancellable_through_every_deletion_phase() {
        let root = BlobTestRoot::new("delete-pending-all-phases");
        let mut services = blob_services(0xac);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("delete-pending phase store");
        let plaintext = b"delete-pending phase fixture".to_vec();
        let prepared = prepared_blob(&plaintext);
        let proof = prepare_blob_proof(&store, &mut services, &prepared, &plaintext, 1);
        let variant = proof.completion.variant_id();
        let transfer = BlobTransferId::new([0x6d; 32]);
        let write = store.database.begin_write().expect("begin phase fixture");
        deletion::move_finalized_variant_to_manifest_for_test(&write, variant)
            .expect("admit phase fixture");
        write.commit().expect("commit phase fixture");

        for (index, (phase, retry)) in [
            (
                deletion::BlobDeletionPhase::DeletingChunks,
                deletion::BlobDeletionRetry::default(),
            ),
            (
                deletion::BlobDeletionPhase::DeletingChunks,
                deletion::BlobDeletionRetry {
                    category: Some(deletion::BlobDeletionFailureCategory::ChunkUnlink),
                    attempts: 1,
                    next_retry_turn: 2,
                },
            ),
            (
                deletion::BlobDeletionPhase::DirectoryDeletePending,
                deletion::BlobDeletionRetry::default(),
            ),
        ]
        .into_iter()
        .enumerate()
        {
            let write = store
                .database
                .begin_write()
                .expect("begin phase transition");
            deletion::set_blob_deletion_phase_for_test(&write, variant, phase, retry)
                .expect("set exact deletion phase");
            assert!(matches!(
                lifecycle::insert_variant_reference(
                    &write,
                    variant,
                    lifecycle::VariantReferenceOwner::Publication,
                    transfer,
                ),
                Err(StoreError::Blob(BlobStoreError::VariantDeleting))
            ));
            write.commit().expect("commit phase transition");
            assert!(matches!(
                store.blob_depot_for_authenticated_read(&proof.completion),
                Err(StoreError::Blob(BlobStoreError::VariantDeleting))
            ));
            let operation =
                BlobOperationKey::new(format!("delete-pending-phase-{index}").into_bytes())
                    .expect("phase operation key");
            let (mut depot, _attempt) = store
                .blob_depot_for_local_publish_with_operation(&operation, false)
                .expect("phase local-import attempt");
            assert!(matches!(
                CoreBlobStore::begin_blob_with_lineage(
                    &mut depot,
                    proof.blob.manifest(),
                    proof.blob.physical_lineage(),
                ),
                Err(StoreError::Blob(BlobStoreError::VariantDeleting))
            ));
        }
    }

    #[test]
    fn blob_deletion_depot_audit_accepts_absent_sparse_expected_only_staging_directory() {
        // Break caught: an expected-only staging row reserves quota but proves
        // no committed file ever existed, so GC may audit it without a variant
        // directory even when the retained row indices are sparse.
        let root = BlobTestRoot::new("deletion-sparse-expected-only");
        let source_root = BlobTestRoot::new("deletion-sparse-expected-only-source");
        let mut services = blob_services(0xa2);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("sparse expected-only target");
        let source = Store::open_for_mission(&source_root.database, services.authority)
            .expect("sparse expected-only source");
        let plaintext = vec![0x42; SELECTED_BLOB_CHUNK_SIZE as usize * 2 + 9];
        let prepared = prepared_blob(&plaintext);
        let proof = prepare_blob_proof(&source, &mut services, &prepared, &plaintext, 1);
        let plan = proof
            .blob
            .transfer_plan(&proof.manifest_bytes)
            .expect("sparse expected-only plan");
        let variant = BlobVariantId::for_content(
            plan.manifest().id(),
            plan.manifest().content_group(),
            plan.manifest().content_epoch(),
        );
        {
            let mut depot = store.blob_depot().expect("sparse expected-only depot");
            CoreBlobStore::begin_blob_with_lineage(
                &mut depot,
                plan.manifest(),
                plan.physical_lineage(),
            )
            .expect("begin sparse expected-only import");
            CoreBlobStore::put_expected_chunk_record(
                &mut depot,
                plan.manifest().id(),
                1,
                plan.chunk_records()[1],
            )
            .expect("stage only the middle expected chunk");
        }
        let variant_directory = root.depot().join(test_hex32(variant.as_bytes()));
        std::fs::remove_dir(&variant_directory)
            .expect("remove empty expected-only staging directory");
        assert!(!variant_directory.exists());
        let stats = store.blob_stats().expect("sparse expected-only stats");
        let write = store
            .database
            .begin_write()
            .expect("begin sparse expected-only deletion fixture");
        let manifest = deletion::move_variant_to_manifest_for_test(&write, variant)
            .expect("move sparse expected-only staging into deletion authority");
        assert_eq!(manifest.totals.chunks, 1);
        assert_eq!(manifest.chunks[0].index, 1);
        assert_eq!(manifest.totals.charged_files, 0);
        depot::audit_depot_write(
            &write,
            &store.path,
            store.backing_identity,
            store.blob_depot_owner_token,
            stats,
        )
        .expect("absent directory is canonical for sparse expected-only staging");
        write
            .commit()
            .expect("commit sparse expected-only deletion fixture");
    }

    #[test]
    fn blob_deletion_audit_rejects_manifest_storage_or_accounting_mismatch() {
        for (index, corruption) in [
            "root",
            "accounting",
            "deleted-file-present",
            "live-reference",
        ]
        .into_iter()
        .enumerate()
        {
            let root = BlobTestRoot::new(&format!("deletion-{corruption}"));
            let services = blob_services(0xb1 + u8::try_from(index).expect("fixture seed"));
            let store = Store::open_for_mission(&root.database, services.authority)
                .expect("deletion corruption store");
            let plaintext = vec![0x51 + u8::try_from(index).expect("fixture byte"); 4_097];
            let prepared = prepared_blob(&plaintext);
            finish_variant(&store, &services.publisher, &prepared, &plaintext, 1)
                .expect("finish deletion corruption variant");
            let stats = store.blob_stats().expect("deletion corruption stats");
            let variant = {
                let read = store.database.begin_read().expect("read corruption import");
                let imports = read.open_table(BLOB_IMPORTS).expect("corruption imports");
                let (key, _) = imports
                    .iter()
                    .expect("corruption import rows")
                    .next()
                    .expect("one corruption import")
                    .expect("corruption import row");
                BlobVariantId::from_bytes(key.value().try_into().expect("variant key"))
            };
            let write = store
                .database
                .begin_write()
                .expect("begin deletion corruption fixture");
            deletion::move_finalized_variant_to_manifest_for_test(&write, variant)
                .expect("move corruption variant into deletion authority");
            deletion::corrupt_blob_deletion_for_test(&write, variant, corruption)
                .expect("apply typed deletion corruption");

            if corruption == "deleted-file-present" {
                deletion::audit_blob_deletion_write(&write, Some(store.blob_depot_owner_binding))
                    .expect("storage-only corruption remains structurally canonical");
                assert_depot_integrity(
                    &depot::audit_depot_write(
                        &write,
                        &store.path,
                        store.backing_identity,
                        store.blob_depot_owner_token,
                        stats,
                    )
                    .expect_err("durably deleted manifest file must be absent"),
                );
            } else {
                assert_blob_schema_invariant(
                    &deletion::audit_blob_deletion_write(
                        &write,
                        Some(store.blob_depot_owner_binding),
                    )
                    .expect_err("manifest, root, or accounting mismatch must fail closed"),
                );
            }
        }
    }

    #[test]
    fn blob_deletion_age_audit_requires_exact_durable_continuity() {
        // Break caught: durable deletion age cannot claim a checkpoint from a
        // missing/future/currently mismatched clock authority. Older-generation
        // checkpoints remain conservative after an A->B->A clock sequence.
        let clock_a = [0xd1; 16];
        let clock_b = [0xd2; 16];
        for (index, label, age, continuity, valid) in [
            (
                0u8,
                "missing",
                deletion::BlobDeletionAge {
                    cumulative_age_ms: 7,
                    checkpoint: Some(CustodySample {
                        clock_id: clock_a,
                        tick_ms: 10,
                    }),
                    continuity_generation: 1,
                    continuity_lost: false,
                },
                None,
                false,
            ),
            (
                1,
                "future-generation",
                deletion::BlobDeletionAge {
                    cumulative_age_ms: 7,
                    checkpoint: Some(CustodySample {
                        clock_id: clock_a,
                        tick_ms: 10,
                    }),
                    continuity_generation: 2,
                    continuity_lost: false,
                },
                Some(deletion::BlobDeletionContinuity {
                    generation: 1,
                    last_sample: CustodySample {
                        clock_id: clock_a,
                        tick_ms: 20,
                    },
                }),
                false,
            ),
            (
                2,
                "current-clock-mismatch",
                deletion::BlobDeletionAge {
                    cumulative_age_ms: 7,
                    checkpoint: Some(CustodySample {
                        clock_id: clock_a,
                        tick_ms: 10,
                    }),
                    continuity_generation: 1,
                    continuity_lost: false,
                },
                Some(deletion::BlobDeletionContinuity {
                    generation: 1,
                    last_sample: CustodySample {
                        clock_id: clock_b,
                        tick_ms: 20,
                    },
                }),
                false,
            ),
            (
                3,
                "current-tick-regression",
                deletion::BlobDeletionAge {
                    cumulative_age_ms: 7,
                    checkpoint: Some(CustodySample {
                        clock_id: clock_a,
                        tick_ms: 21,
                    }),
                    continuity_generation: 1,
                    continuity_lost: false,
                },
                Some(deletion::BlobDeletionContinuity {
                    generation: 1,
                    last_sample: CustodySample {
                        clock_id: clock_a,
                        tick_ms: 20,
                    },
                }),
                false,
            ),
            (
                4,
                "old-generation-a-b-a",
                deletion::BlobDeletionAge {
                    cumulative_age_ms: 7,
                    checkpoint: Some(CustodySample {
                        clock_id: clock_a,
                        tick_ms: 21,
                    }),
                    continuity_generation: 1,
                    continuity_lost: true,
                },
                Some(deletion::BlobDeletionContinuity {
                    generation: 3,
                    last_sample: CustodySample {
                        clock_id: clock_a,
                        tick_ms: 5,
                    },
                }),
                true,
            ),
        ] {
            let root = BlobTestRoot::new(&format!("deletion-age-{label}"));
            let services = blob_services(0xd3 + index);
            let store = Store::open_for_mission(&root.database, services.authority)
                .expect("deletion-age store");
            let plaintext = vec![0x71 + index; 4_097];
            let prepared = prepared_blob(&plaintext);
            finish_variant(&store, &services.publisher, &prepared, &plaintext, 1)
                .expect("finish deletion-age variant");
            let variant = {
                let read = store
                    .database
                    .begin_read()
                    .expect("read deletion-age import");
                let imports = read.open_table(BLOB_IMPORTS).expect("deletion-age imports");
                let (key, _) = imports
                    .iter()
                    .expect("deletion-age import rows")
                    .next()
                    .expect("one deletion-age import")
                    .expect("deletion-age import row");
                BlobVariantId::from_bytes(key.value().try_into().expect("variant key"))
            };
            let write = store
                .database
                .begin_write()
                .expect("begin deletion-age fixture");
            deletion::move_finalized_variant_to_manifest_for_test(&write, variant)
                .expect("move deletion-age variant");
            deletion::set_blob_deletion_age_for_test(&write, variant, age, continuity)
                .expect("set deletion-age continuity fixture");
            let result =
                deletion::audit_blob_deletion_write(&write, Some(store.blob_depot_owner_binding));
            if valid {
                result.expect("old-generation checkpoint remains conservative");
            } else {
                assert_blob_schema_invariant(
                    &result.expect_err("invalid deletion-age continuity must fail closed"),
                );
            }
        }
    }

    #[test]
    fn blob_post_gc_restart_preserves_lineage_acceptance_and_conflict() {
        let root = BlobTestRoot::new("deletion-permanent-fence");
        let services = blob_services(0xc1);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("permanent-fence store");
        let plaintext = vec![0x61; 4_097];
        let prepared = prepared_blob(&plaintext);
        finish_variant(&store, &services.publisher, &prepared, &plaintext, 1)
            .expect("finish permanent-fence variant");
        let variant = {
            let read = store.database.begin_read().expect("read fence import");
            let imports = read.open_table(BLOB_IMPORTS).expect("fence imports");
            let (key, _) = imports
                .iter()
                .expect("fence import rows")
                .next()
                .expect("one fence import")
                .expect("fence import row");
            BlobVariantId::from_bytes(key.value().try_into().expect("variant key"))
        };
        let before = store.blob_gc_status(None).expect("before production GC");
        let progress = store
            .run_blob_capacity_gc(
                BlobMaintenanceBudget::new(128, 16, 16 * 1024 * 1024)
                    .expect("production GC budget"),
                Some(CustodySample {
                    clock_id: [0x61; 16],
                    tick_ms: 1,
                }),
            )
            .expect("production manifest admission and physical GC");
        assert_eq!(progress.manifests_admitted, 1);
        assert_eq!(progress.manifests_finalized, 1);
        assert!(progress.rows_examined <= 128);
        assert!(progress.files_examined <= 16);
        assert!(progress.bytes_examined <= 16 * 1024 * 1024);
        let after = store.blob_gc_status(None).expect("after production GC");
        assert_eq!(after.lineage_fence_rows, before.lineage_fence_rows);
        assert_eq!(after.lineage_fence_bytes, before.lineage_fence_bytes);
        assert!(!root.depot().join(test_hex32(variant.as_bytes())).exists());
        drop(store);

        let reopened = Store::open_for_mission(&root.database, services.authority)
            .expect("canonical permanent fence survives finalized reclamation");
        let stats = reopened.blob_stats().expect("permanent-fence stats");
        assert_eq!(stats.variants, 0);
        assert_eq!(stats.committed_chunks, 0);
        assert_eq!(stats.lineage_fences, 1);
        {
            let read = reopened
                .database
                .begin_read()
                .expect("read permanent fence");
            let fences = read
                .open_table(lifecycle::BLOB_LINEAGE_FENCES)
                .expect("permanent lineage fences");
            let encoded = fences
                .get(variant.as_bytes().as_slice())
                .expect("read retained fence")
                .expect("retained fence exists");
            assert!(
                lifecycle::LineageFence::decode(encoded.value())
                    .expect("decode reclaimed lineage fence")
                    .bulk_reclamation_observed()
            );
        }

        let depot = reopened.blob_depot().expect("matching reimport depot");
        let mut service = services
            .publisher
            .blob_service_with_store(&blob_scope(), &blob_topic(), 1, depot)
            .expect("matching reimport service");
        service
            .install_prepared(&prepared)
            .expect("matching reimport coexists with reclaimed fence");
        let read = reopened
            .database
            .begin_read()
            .expect("read reimported fence");
        let fences = read
            .open_table(lifecycle::BLOB_LINEAGE_FENCES)
            .expect("reimported lineage fences");
        let encoded = fences
            .get(variant.as_bytes().as_slice())
            .expect("read reimported fence")
            .expect("reimported fence exists");
        assert!(
            lifecycle::LineageFence::decode(encoded.value())
                .expect("decode reimported lineage fence")
                .bulk_reclamation_observed(),
            "matching reimport must not clear reclamation authorization",
        );
        let import = read
            .open_table(BLOB_IMPORTS)
            .expect("reimported imports")
            .get(variant.as_bytes().as_slice())
            .expect("read reimported import")
            .expect("reimported import exists")
            .value()
            .to_vec();
        let mut conflicting_lineage =
            depot::maintenance_import_projection(variant.as_bytes().as_slice(), &import)
                .expect("decode reimported import")
                .physical_lineage;
        conflicting_lineage[0] ^= 1;
        drop(read);
        let write = reopened
            .database
            .begin_write()
            .expect("conflicting lineage check");
        assert!(matches!(
            lifecycle::ensure_lineage_fence(
                &write,
                reopened.blob_lifecycle_limits,
                variant,
                conflicting_lineage,
                reopened.blob_depot_owner_binding,
            ),
            Err(StoreError::Blob(BlobStoreError::PhysicalLineageConflict))
        ));
    }

    #[test]
    fn blob_deletion_audit_rejects_fabricated_non_reclaimed_orphan_lineage_fence() {
        // Break caught: canonical encoding and owner binding alone must not
        // authorize a lineage fence after its import authority disappears.
        let root = BlobTestRoot::new("deletion-fabricated-orphan-fence");
        let services = blob_services(0xc2);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("fabricated-orphan store");
        let plaintext = vec![0x62; 4_097];
        let prepared = prepared_blob(&plaintext);
        finish_variant(&store, &services.publisher, &prepared, &plaintext, 1)
            .expect("finish fabricated-orphan variant");
        let variant = {
            let read = store.database.begin_read().expect("read orphan import");
            let imports = read.open_table(BLOB_IMPORTS).expect("orphan imports");
            let (key, _) = imports
                .iter()
                .expect("orphan import rows")
                .next()
                .expect("one orphan import")
                .expect("orphan import row");
            BlobVariantId::from_bytes(key.value().try_into().expect("variant key"))
        };
        drop(store);

        std::fs::remove_file(root.chunk_path(variant, 0)).expect("remove orphan chunk file");
        std::fs::remove_dir(root.depot().join(test_hex32(variant.as_bytes())))
            .expect("remove orphan variant directory");
        {
            let database = Database::open(&root.database).expect("open orphan metadata");
            let write = database.begin_write().expect("begin orphan metadata");
            write
                .open_table(BLOB_IMPORTS)
                .expect("orphan imports")
                .remove(variant.as_bytes().as_slice())
                .expect("remove orphan import")
                .expect("orphan import exists");
            write
                .open_table(BLOB_CHUNKS)
                .expect("orphan chunks")
                .remove(depot::test_chunk_key(variant, 0).as_slice())
                .expect("remove orphan chunk")
                .expect("orphan chunk exists");
            let mut metadata = write
                .open_table(BLOB_DEPOT_METADATA)
                .expect("orphan depot metadata");
            for field in [
                DEPOT_VARIANT_COUNT,
                DEPOT_COMMITTED_CHUNK_COUNT,
                DEPOT_COMMITTED_FILE_BYTES,
                DEPOT_RESERVED_FILE_BYTES,
            ] {
                metadata.insert(field, 0).expect("clear orphan charge");
            }
            drop(metadata);
            write.commit().expect("commit fabricated orphan fixture");
        }

        match Store::open_for_mission(&root.database, services.authority) {
            Ok(_) => panic!("unmarked orphan lineage fence must fail closed"),
            Err(error) => assert_blob_schema_invariant(&error),
        }
    }

    fn pressure_database_digest(path: &Path) -> [u8; 32] {
        let database = redb::Builder::new()
            .open_read_only(path)
            .expect("read pressure database");
        let read = database.begin_read().expect("pressure digest read");
        let mut digest = Sha256::new();
        let tables = read
            .list_tables()
            .expect("pressure digest table names")
            .map(|table| table.name().to_owned())
            .collect::<BTreeSet<_>>();
        for table in pressure::pressure_table_names_for_test() {
            digest.update(table.as_bytes());
            digest.update([u8::from(tables.contains(table))]);
        }
        for table in [
            pressure::BLOB_PRESSURE_PUBLICATION_ROOTS,
            pressure::BLOB_PRESSURE_PENDING_ROOTS,
            pressure::BLOB_PRESSURE_VARIANT_SUMMARIES,
            pressure::BLOB_PRESSURE_PUBLICATIONS,
            pressure::BLOB_PRESSURE_CONTENT_PUBLICATIONS,
        ] {
            if tables.contains(table.name()) {
                for row in read
                    .open_table(table)
                    .expect("pressure digest table")
                    .iter()
                    .expect("pressure digest rows")
                {
                    let (key, value) = row.expect("pressure digest row");
                    digest.update(key.value());
                    digest.update(value.value());
                }
            }
        }
        if tables.contains(pressure::BLOB_PRESSURE_PENDING_SOURCES.name()) {
            for row in read
                .open_table(pressure::BLOB_PRESSURE_PENDING_SOURCES)
                .expect("pending pressure digest table")
                .iter()
                .expect("pending pressure digest rows")
            {
                let (key, value) = row.expect("pending pressure digest row");
                digest.update(key.value());
                digest.update(value.value());
            }
        }
        if tables.contains(pressure::BLOB_PRESSURE_VARIANTS.name()) {
            for row in read
                .open_table(pressure::BLOB_PRESSURE_VARIANTS)
                .expect("variant pressure digest table")
                .iter()
                .expect("variant pressure digest rows")
            {
                let (key, value) = row.expect("variant pressure digest row");
                digest.update(key.value());
                digest.update(value.value());
            }
        }
        if tables.contains(pressure::BLOB_PRESSURE_METADATA.name()) {
            for row in read
                .open_table(pressure::BLOB_PRESSURE_METADATA)
                .expect("pressure metadata")
                .iter()
                .expect("pressure metadata rows")
            {
                let (key, value) = row.expect("pressure metadata row");
                digest.update(key.value().as_bytes());
                digest.update(value.value().to_be_bytes());
            }
        }
        if tables.contains(pressure::BLOB_PRESSURE_REANCHOR_CURSORS.name()) {
            for row in read
                .open_table(pressure::BLOB_PRESSURE_REANCHOR_CURSORS)
                .expect("pressure reanchor cursor table")
                .iter()
                .expect("pressure reanchor cursor rows")
            {
                let (key, value) = row.expect("pressure reanchor cursor row");
                digest.update([key.value()]);
                digest.update(value.value());
            }
        }
        for table in [
            pressure::BLOB_PRESSURE_DURABLE_PUBLICATIONS,
            pressure::BLOB_PRESSURE_DURABLE_CONTENT_PUBLICATIONS,
        ] {
            if tables.contains(table.name()) {
                for row in read
                    .open_table(table)
                    .expect("durable pressure digest table")
                    .iter()
                    .expect("durable pressure digest rows")
                {
                    let (key, value) = row.expect("durable pressure digest row");
                    digest.update(key.value());
                    digest.update(value.value());
                }
            }
        }
        if tables.contains(pressure::BLOB_PRESSURE_DURABLE_PENDING_SOURCES.name()) {
            for row in read
                .open_table(pressure::BLOB_PRESSURE_DURABLE_PENDING_SOURCES)
                .expect("durable pending pressure digest table")
                .iter()
                .expect("durable pending pressure digest rows")
            {
                let (key, value) = row.expect("durable pending pressure digest row");
                digest.update(key.value());
                digest.update(value.value());
            }
        }
        if tables.contains(pressure::BLOB_PRESSURE_DURABLE_VARIANTS.name()) {
            for row in read
                .open_table(pressure::BLOB_PRESSURE_DURABLE_VARIANTS)
                .expect("durable variant pressure digest table")
                .iter()
                .expect("durable variant pressure digest rows")
            {
                let (key, value) = row.expect("durable variant pressure digest row");
                digest.update(key.value());
                digest.update(value.value());
            }
        }
        digest.finalize().into()
    }

    fn retain_durable_pressure_tables_for_test(path: &Path, retained: u8) {
        let database = Database::open(path).expect("raw durable pressure layout database");
        let write = database
            .begin_write()
            .expect("durable pressure layout write");
        if retained & 0b0001 == 0 {
            write
                .delete_table(pressure::BLOB_PRESSURE_DURABLE_PUBLICATIONS)
                .expect("delete durable publication index");
        }
        if retained & 0b0010 == 0 {
            write
                .delete_table(pressure::BLOB_PRESSURE_DURABLE_CONTENT_PUBLICATIONS)
                .expect("delete durable content-publication index");
        }
        if retained & 0b0100 == 0 {
            write
                .delete_table(pressure::BLOB_PRESSURE_DURABLE_PENDING_SOURCES)
                .expect("delete durable pending-source index");
        }
        if retained & 0b1000 == 0 {
            write
                .delete_table(pressure::BLOB_PRESSURE_DURABLE_VARIANTS)
                .expect("delete durable variant index");
        }
        write.commit().expect("commit durable pressure layout");
    }

    fn rewrite_pressure_v5_as_pre_task5_for_test(path: &Path) {
        const FINITE_ROOT_MASK: u64 = 1 << 63;

        let database = Database::open(path).expect("raw pre-Task-5 pressure-v5 database");
        let write = database
            .begin_write()
            .expect("pre-Task-5 pressure-v5 write");

        let summaries = {
            let table = write
                .open_table(pressure::BLOB_PRESSURE_VARIANT_SUMMARIES)
                .expect("current pressure variant summaries");
            table
                .iter()
                .expect("current pressure variant summary rows")
                .map(|row| {
                    let (key, value) = row.expect("current pressure variant summary row");
                    let mut value = value.value().to_vec();
                    let encoded_roots = u64::from_be_bytes(
                        value[27..35]
                            .try_into()
                            .expect("pressure variant summary root count"),
                    );
                    value[27..35]
                        .copy_from_slice(&(encoded_roots & !FINITE_ROOT_MASK).to_be_bytes());
                    (key.value().to_vec(), value)
                })
                .collect::<Vec<_>>()
        };
        {
            let mut table = write
                .open_table(pressure::BLOB_PRESSURE_VARIANT_SUMMARIES)
                .expect("pre-Task-5 pressure variant summaries");
            for (key, value) in summaries {
                table
                    .insert(key.as_slice(), value.as_slice())
                    .expect("rewrite raw pre-Task-5 variant summary");
            }
        }

        let variants = {
            let table = write
                .open_table(pressure::BLOB_PRESSURE_VARIANTS)
                .expect("current pressure variants");
            table
                .iter()
                .expect("current pressure variant rows")
                .map(|row| {
                    let (key, value) = row.expect("current pressure variant row");
                    let mut key = key.value();
                    let encoded_roots = u64::from_be_bytes(
                        key[68..76]
                            .try_into()
                            .expect("pressure variant index root count"),
                    );
                    key[68..76].copy_from_slice(&(encoded_roots & !FINITE_ROOT_MASK).to_be_bytes());
                    (key, value.value().to_vec())
                })
                .collect::<Vec<_>>()
        };
        {
            let mut table = write
                .open_table(pressure::BLOB_PRESSURE_VARIANTS)
                .expect("pre-Task-5 pressure variants");
            let keys = table
                .iter()
                .expect("pre-Task-5 pressure variant keys")
                .map(|row| row.expect("pre-Task-5 pressure variant key").0.value())
                .collect::<Vec<_>>();
            for key in keys {
                table
                    .remove(&key)
                    .expect("remove current pressure variant index");
            }
            for (key, value) in variants {
                table
                    .insert(&key, value.as_slice())
                    .expect("insert raw pre-Task-5 pressure variant index");
            }
        }

        write
            .delete_table(pressure::BLOB_PRESSURE_DURABLE_PUBLICATIONS)
            .expect("delete pre-Task-5 durable publication index");
        write
            .delete_table(pressure::BLOB_PRESSURE_DURABLE_CONTENT_PUBLICATIONS)
            .expect("delete pre-Task-5 durable content-publication index");
        write
            .delete_table(pressure::BLOB_PRESSURE_DURABLE_PENDING_SOURCES)
            .expect("delete pre-Task-5 durable pending-source index");
        write
            .delete_table(pressure::BLOB_PRESSURE_DURABLE_VARIANTS)
            .expect("delete pre-Task-5 durable variant index");
        write
            .commit()
            .expect("commit genuine pre-Task-5 pressure-v5 layout");
    }

    fn strip_blob_pressure_schema_for_test(path: &Path) {
        let database = Database::open(path).expect("raw pressure predecessor database");
        let write = database.begin_write().expect("pressure predecessor write");
        write
            .delete_table(pressure::BLOB_PRESSURE_METADATA)
            .expect("delete pressure metadata");
        for table in [
            pressure::BLOB_PRESSURE_PUBLICATION_ROOTS,
            pressure::BLOB_PRESSURE_PENDING_ROOTS,
            pressure::BLOB_PRESSURE_VARIANT_SUMMARIES,
            pressure::BLOB_PRESSURE_PUBLICATIONS,
            pressure::BLOB_PRESSURE_CONTENT_PUBLICATIONS,
        ] {
            write.delete_table(table).expect("delete pressure table");
        }
        write
            .delete_table(pressure::BLOB_PRESSURE_PENDING_SOURCES)
            .expect("delete pending pressure table");
        write
            .delete_table(pressure::BLOB_PRESSURE_VARIANTS)
            .expect("delete variant pressure table");
        for table in [
            pressure::BLOB_PRESSURE_DURABLE_PUBLICATIONS,
            pressure::BLOB_PRESSURE_DURABLE_CONTENT_PUBLICATIONS,
        ] {
            write
                .delete_table(table)
                .expect("delete durable pressure table");
        }
        write
            .delete_table(pressure::BLOB_PRESSURE_DURABLE_PENDING_SOURCES)
            .expect("delete durable pending pressure table");
        write
            .delete_table(pressure::BLOB_PRESSURE_DURABLE_VARIANTS)
            .expect("delete durable variant pressure table");
        write
            .delete_table(pressure::BLOB_PRESSURE_REANCHOR_CURSORS)
            .expect("delete pressure reanchor cursors");
        write.commit().expect("commit pressure predecessor");
    }

    #[test]
    fn blob_pressure_schema_requires_writable_atomic_idempotent_migration() {
        let root = BlobTestRoot::new("pressure-schema-migration");
        drop(Store::open(&root.database).expect("current pressure schema"));
        downgrade_blob_lifecycle_to_v3_for_test(&root.database);
        strip_blob_pressure_schema_for_test(&root.database);

        assert_blob_schema_invariant(
            &Store::inspect_existing(&root.database)
                .expect_err("read-only predecessor must not migrate"),
        );
        pressure::TEST_PRESSURE_MIGRATION_FAULT.set(true);
        let interrupted = match Store::open(&root.database) {
            Ok(_) => panic!("interrupted migration must roll back"),
            Err(error) => error,
        };
        assert_blob_schema_invariant(&interrupted);
        pressure::TEST_PRESSURE_MIGRATION_FAULT.set(false);
        let database = redb::Builder::new()
            .open_read_only(&root.database)
            .expect("read rolled-back predecessor");
        let tables = database
            .begin_read()
            .expect("rolled-back predecessor read")
            .list_tables()
            .expect("rolled-back predecessor tables")
            .map(|table| table.name().to_owned())
            .collect::<BTreeSet<_>>();
        assert!(!tables.contains(pressure::BLOB_PRESSURE_METADATA.name()));

        drop(database);
        drop(Store::open(&root.database).expect("writable pressure migration"));
        let first = pressure_database_digest(&root.database);
        Store::inspect_existing(&root.database).expect("inspect migrated pressure schema");
        drop(Store::open(&root.database).expect("idempotent pressure reopen"));
        assert_eq!(pressure_database_digest(&root.database), first);
    }

    #[test]
    fn blob_pressure_writable_migration_rebuilds_previous_expiry_order() {
        let root = BlobTestRoot::new("pressure-expiry-order-migration");
        let mut services = blob_services(0xd7);
        let plaintext = b"previous pressure expiry order".to_vec();
        let prepared = prepared_blob(&plaintext);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("previous expiry-order store");
        let (publication, _, _) = publish_blob(
            &store,
            &mut services,
            &prepared,
            &plaintext,
            1,
            b"previous-expiry-order",
        );
        drop(store);
        downgrade_blob_lifecycle_to_v3_for_test(&root.database);
        let database = Database::open(&root.database).unwrap();
        let write = database.begin_write().unwrap();
        write
            .open_table(pressure::BLOB_PRESSURE_METADATA)
            .unwrap()
            .insert("schema_version", 2)
            .unwrap();
        write.commit().unwrap();
        drop(database);
        let predecessor = blob_database_digest(&root.database);
        Store::inspect_existing(&root.database)
            .expect("read-only previous order is audited without migration");
        assert_eq!(blob_database_digest(&root.database), predecessor);
        drop(
            Store::open_for_mission(&root.database, services.authority)
                .expect("writable previous order rebuild"),
        );
        Store::inspect_existing(&root.database).expect("inspect rebuilt expiry order");
        let database = Database::open(&root.database).unwrap();
        let read = database.begin_read().unwrap();
        assert_eq!(
            read.open_table(pressure::BLOB_PRESSURE_METADATA)
                .unwrap()
                .get("schema_version")
                .unwrap()
                .unwrap()
                .value(),
            5
        );
        let summary = pressure::decode_variant_summary(
            read.open_table(pressure::BLOB_PRESSURE_VARIANT_SUMMARIES)
                .unwrap()
                .get(publication.variant_id.as_bytes().as_slice())
                .unwrap()
                .unwrap()
                .value(),
        )
        .unwrap();
        assert!(!summary.has_finite_roots);
        let indexed = read
            .open_table(pressure::BLOB_PRESSURE_VARIANTS)
            .unwrap()
            .iter()
            .unwrap()
            .find_map(|row| {
                let (key, _) = row.unwrap();
                let (candidate, variant) =
                    pressure::decode_variant_index_key(&key.value()).unwrap();
                (variant == publication.variant_id).then_some(candidate)
            })
            .expect("migrated finite variant index");
        assert_eq!(indexed, summary);
    }

    #[test]
    fn finite_pressure_v2_and_v4_audit_then_migrate_to_current_indexes() {
        for (label, pressure_version) in [("finite-pressure-v2", 2), ("finite-pressure-v4", 4)] {
            let root = BlobTestRoot::new(label);
            let mut services = blob_services(pressure_version as u8);
            let plaintext = format!("{label} migration fixture").into_bytes();
            let prepared = prepared_blob(&plaintext);
            let store = Store::open_for_mission(&root.database, services.authority)
                .expect("finite pressure predecessor store");
            let (publication, operation, _) = publish_blob(
                &store,
                &mut services,
                &prepared,
                &plaintext,
                1,
                label.as_bytes(),
            );
            rewrite_live_blob_as_finite_for_retirement_test(
                &store,
                &publication,
                Some(&operation),
                50_000,
                100,
                CustodySample {
                    clock_id: [pressure_version as u8; 16],
                    tick_ms: 10_000,
                },
            );
            drop(store);

            if pressure_version == 2 {
                downgrade_blob_policy_to_v4_for_test(&root.database);
                let database = Database::open(&root.database).unwrap();
                let write = database.begin_write().unwrap();
                write
                    .open_table(pressure::BLOB_PRESSURE_METADATA)
                    .unwrap()
                    .insert(pressure::PRESSURE_SCHEMA_VERSION_FIELD, 2)
                    .unwrap();
                write.commit().unwrap();
            } else {
                downgrade_blob_policy_to_v4_for_test(&root.database);
            }

            let database = Database::open(&root.database).unwrap();
            let read = database.begin_read().unwrap();
            let encoded = read
                .open_table(pressure::BLOB_PRESSURE_VARIANT_SUMMARIES)
                .unwrap()
                .get(publication.variant_id.as_bytes().as_slice())
                .unwrap()
                .unwrap()
                .value()
                .to_vec();
            assert_eq!(encoded[27] & 0x80, 0, "historical count must be raw");
            assert!(
                !pressure::decode_variant_summary(&encoded)
                    .unwrap()
                    .has_finite_roots,
                "historical generations must not decode a v5 aggregate"
            );
            drop(read);
            drop(database);

            let predecessor = blob_database_digest(&root.database);
            Store::inspect_existing(&root.database).expect("read-only finite predecessor audit");
            assert_eq!(blob_database_digest(&root.database), predecessor);

            drop(
                Store::open_for_mission(&root.database, services.authority)
                    .expect("writable finite pressure migration"),
            );
            Store::inspect_existing(&root.database).expect("inspect migrated finite pressure");
            let database = Database::open(&root.database).unwrap();
            let read = database.begin_read().unwrap();
            let encoded = read
                .open_table(pressure::BLOB_PRESSURE_VARIANT_SUMMARIES)
                .unwrap()
                .get(publication.variant_id.as_bytes().as_slice())
                .unwrap()
                .unwrap()
                .value()
                .to_vec();
            assert_ne!(encoded[27] & 0x80, 0, "v5 aggregate must mark finite roots");
            assert!(
                pressure::decode_variant_summary(&encoded)
                    .unwrap()
                    .has_finite_roots
            );
            assert!(
                read.open_table(pressure::BLOB_PRESSURE_DURABLE_PUBLICATIONS)
                    .unwrap()
                    .iter()
                    .unwrap()
                    .next()
                    .is_none()
            );
            assert!(
                read.open_table(pressure::BLOB_PRESSURE_DURABLE_VARIANTS)
                    .unwrap()
                    .iter()
                    .unwrap()
                    .next()
                    .is_none()
            );
            drop(read);
            drop(database);
            let migrated = pressure_database_digest(&root.database);
            drop(Store::open(&root.database).expect("idempotent finite pressure reopen"));
            assert_eq!(pressure_database_digest(&root.database), migrated);
        }
    }

    #[test]
    fn exact_old_v5_pressure_layout_audits_then_populates_only_durable_indexes() {
        let target_root = BlobTestRoot::new("pressure-old-v5-upgrade-target");
        let source_root = BlobTestRoot::new("pressure-old-v5-upgrade-source");
        let mut services = blob_services(0x65);
        let mut pending_services = blob_services_with_nodes(0x65, 3, 4);
        assert_eq!(services.authority, pending_services.authority);
        let source = Store::open_for_mission(&source_root.database, services.authority)
            .expect("old-v5 source store");
        let target = Store::open_for_mission(&target_root.database, services.authority)
            .expect("old-v5 target store");

        let durable_plaintext = b"old-v5 durable publication".to_vec();
        let durable_prepared = prepared_blob(&durable_plaintext);
        let (durable_publication, _, _) = publish_blob(
            &target,
            &mut services,
            &durable_prepared,
            &durable_plaintext,
            1,
            b"old-v5-durable-publication",
        );

        let finite_only_plaintext = b"old-v5 finite-only publication".to_vec();
        let finite_only_prepared = prepared_blob(&finite_only_plaintext);
        let (finite_only_publication, finite_only_operation, _) = publish_blob(
            &target,
            &mut services,
            &finite_only_prepared,
            &finite_only_plaintext,
            1,
            b"old-v5-finite-only-publication",
        );

        let mixed_plaintext = b"old-v5 mixed finite and durable variant".to_vec();
        let mixed_prepared = prepared_blob(&mixed_plaintext);
        let (finite_publication, finite_operation, _) = publish_blob(
            &target,
            &mut services,
            &mixed_prepared,
            &mixed_plaintext,
            1,
            b"old-v5-finite-publication",
        );
        let (mixed_durable_publication, _, _) = publish_blob(
            &target,
            &mut services,
            &mixed_prepared,
            &mixed_plaintext,
            1,
            b"old-v5-mixed-durable-publication",
        );
        assert_eq!(
            finite_publication.variant_id,
            mixed_durable_publication.variant_id
        );
        let checkpoint = CustodySample {
            clock_id: [0x65; 16],
            tick_ms: 10_000,
        };
        rewrite_live_blob_as_finite_for_retirement_test(
            &target,
            &finite_only_publication,
            Some(&finite_only_operation),
            50_000,
            100,
            checkpoint,
        );
        rewrite_live_blob_as_finite_for_retirement_test(
            &target,
            &finite_publication,
            Some(&finite_operation),
            50_000,
            100,
            checkpoint,
        );

        let finite_pending_plaintext = b"old-v5 finite pending source".to_vec();
        let finite_pending_prepared = prepared_blob(&finite_pending_plaintext);
        let finite_pending_proof = prepare_blob_proof_with_lifetime(
            &source,
            &mut pending_services,
            &finite_pending_prepared,
            &finite_pending_plaintext,
            1,
            Priority::Immediate,
            Some(50_000),
        );
        let finite_pending_plan = finite_pending_proof
            .blob
            .transfer_plan(&finite_pending_proof.manifest_bytes)
            .expect("old-v5 finite pending plan");
        let finite_pending = BlobTransferId::new(finite_pending_proof.blob.envelope_id());
        let policy = target.control_policy_snapshot().expect("old-v5 policy");
        assert_eq!(
            target
                .test_stage_verified_finite_blob_source_with_policy(
                    &policy,
                    &finite_pending_proof.blob,
                    &finite_pending_proof.sealed,
                    &finite_pending_plan,
                    100,
                    checkpoint,
                )
                .expect("stage old-v5 finite pending source"),
            BlobSourceStageOutcome::Inserted
        );

        let durable_pending_plaintext = b"old-v5 durable pending source".to_vec();
        let durable_pending_prepared = prepared_blob(&durable_pending_plaintext);
        let durable_pending_proof = prepare_blob_proof(
            &source,
            &mut pending_services,
            &durable_pending_prepared,
            &durable_pending_plaintext,
            1,
        );
        let durable_pending_plan = durable_pending_proof
            .blob
            .transfer_plan(&durable_pending_proof.manifest_bytes)
            .expect("old-v5 durable pending plan");
        let durable_pending = BlobTransferId::new(durable_pending_proof.blob.envelope_id());
        assert_eq!(
            target
                .stage_verified_blob_source_with_lifetime(
                    &policy,
                    &durable_pending_proof.blob,
                    &durable_pending_proof.sealed,
                    &durable_pending_plan,
                    None,
                )
                .expect("stage old-v5 durable pending source"),
            BlobSourceStageOutcome::Inserted
        );
        drop(target);
        drop(source);

        let database = Database::open(&target_root.database).unwrap();
        let read = database.begin_read().unwrap();
        let durable_publication_transfers = BTreeSet::from([
            durable_publication.transfer_id,
            mixed_durable_publication.transfer_id,
        ]);
        let expected_publications = read
            .open_table(pressure::BLOB_PRESSURE_PUBLICATIONS)
            .unwrap()
            .iter()
            .unwrap()
            .filter_map(|row| {
                let (key, _) = row.unwrap();
                let candidate = pressure::decode_publication_key(key.value()).unwrap();
                durable_publication_transfers
                    .contains(&candidate.transfer_id)
                    .then(|| key.value().to_vec())
            })
            .collect::<BTreeSet<_>>();
        assert_eq!(expected_publications.len(), 2);
        let expected_content_publications = read
            .open_table(pressure::BLOB_PRESSURE_CONTENT_PUBLICATIONS)
            .unwrap()
            .iter()
            .unwrap()
            .filter_map(|row| {
                let (key, _) = row.unwrap();
                let candidate = pressure::decode_content_publication_key(key.value()).unwrap();
                durable_publication_transfers
                    .contains(&candidate.publication.transfer_id)
                    .then(|| key.value().to_vec())
            })
            .collect::<BTreeSet<_>>();
        assert_eq!(expected_content_publications.len(), 2);
        let expected_pending = read
            .open_table(pressure::BLOB_PRESSURE_PENDING_SOURCES)
            .unwrap()
            .iter()
            .unwrap()
            .find_map(|row| {
                let (key, _) = row.unwrap();
                let candidate = pressure::decode_pending_index_key(&key.value()).unwrap();
                (candidate.transfer_id == durable_pending).then_some(key.value())
            })
            .expect("durable pending canonical key");
        let finite_pending_variant = pressure::decode_pending_root(
            read.open_table(pressure::BLOB_PRESSURE_PENDING_ROOTS)
                .unwrap()
                .get(finite_pending.as_bytes().as_slice())
                .unwrap()
                .unwrap()
                .value(),
        )
        .unwrap()
        .variant_id;
        let durable_pending_variant = pressure::decode_pending_root(
            read.open_table(pressure::BLOB_PRESSURE_PENDING_ROOTS)
                .unwrap()
                .get(durable_pending.as_bytes().as_slice())
                .unwrap()
                .unwrap()
                .value(),
        )
        .unwrap()
        .variant_id;
        let durable_variants =
            BTreeSet::from([durable_publication.variant_id, durable_pending_variant]);
        let expected_variants = read
            .open_table(pressure::BLOB_PRESSURE_VARIANTS)
            .unwrap()
            .iter()
            .unwrap()
            .filter_map(|row| {
                let (key, _) = row.unwrap();
                let (_, variant) = pressure::decode_variant_index_key(&key.value()).unwrap();
                durable_variants.contains(&variant).then_some(key.value())
            })
            .collect::<BTreeSet<_>>();
        assert_eq!(expected_variants.len(), 2);
        assert_ne!(finite_pending, durable_pending);
        drop(read);
        drop(database);

        rewrite_pressure_v5_as_pre_task5_for_test(&target_root.database);
        let database = Database::open(&target_root.database).unwrap();
        let read = database.begin_read().unwrap();
        for (variant, expected_publication_roots) in [
            (finite_only_publication.variant_id, 1),
            (finite_publication.variant_id, 2),
            (finite_pending_variant, 0),
        ] {
            let summary_bytes = read
                .open_table(pressure::BLOB_PRESSURE_VARIANT_SUMMARIES)
                .unwrap()
                .get(variant.as_bytes().as_slice())
                .unwrap()
                .unwrap()
                .value()
                .to_vec();
            let raw_publication_roots =
                u64::from_be_bytes(summary_bytes[27..35].try_into().unwrap());
            assert_eq!(
                raw_publication_roots, expected_publication_roots,
                "pre-Task-5 v5 summary stores the raw publication-root count"
            );
            assert_eq!(
                raw_publication_roots & (1 << 63),
                0,
                "pre-Task-5 v5 summary has no finite-root aggregate"
            );
            assert!(
                !pressure::decode_variant_summary(&summary_bytes)
                    .unwrap()
                    .has_finite_roots
            );
            let variant_key = read
                .open_table(pressure::BLOB_PRESSURE_VARIANTS)
                .unwrap()
                .iter()
                .unwrap()
                .find_map(|row| {
                    let (key, _) = row.unwrap();
                    let (_, indexed_variant) =
                        pressure::decode_variant_index_key(&key.value()).unwrap();
                    (indexed_variant == variant).then_some(key.value())
                })
                .expect("pre-Task-5 v5 variant index");
            assert_eq!(
                u64::from_be_bytes(variant_key[68..76].try_into().unwrap()),
                expected_publication_roots,
                "pre-Task-5 v5 index stores the raw publication-root count"
            );
        }
        drop(read);
        drop(database);
        let old_v5 = pressure_database_digest(&target_root.database);
        Store::inspect_existing(&target_root.database)
            .expect("read-only exact old-v5 audit without durable tables");
        assert_eq!(pressure_database_digest(&target_root.database), old_v5);

        pressure::TEST_PRESSURE_MIGRATION_FAULT.set(true);
        let interrupted = match Store::open_for_mission(&target_root.database, services.authority) {
            Ok(_) => panic!("interrupted exact old-v5 upgrade must roll back"),
            Err(error) => error,
        };
        assert_blob_schema_invariant(&interrupted);
        pressure::TEST_PRESSURE_MIGRATION_FAULT.set(false);
        assert_eq!(
            pressure_database_digest(&target_root.database),
            old_v5,
            "old-v5 canonical bytes and table layout roll back atomically"
        );
        Store::inspect_existing(&target_root.database)
            .expect("rolled-back exact old-v5 image remains byte-exact and auditable");

        drop(
            Store::open_for_mission(&target_root.database, services.authority)
                .expect("writable exact old-v5 durable-index upgrade"),
        );
        Store::inspect_existing(&target_root.database).expect("post-upgrade current-v5 full audit");
        let database = Database::open(&target_root.database).unwrap();
        let read = database.begin_read().unwrap();
        for variant in [
            finite_only_publication.variant_id,
            finite_publication.variant_id,
            finite_pending_variant,
        ] {
            let summary_bytes = read
                .open_table(pressure::BLOB_PRESSURE_VARIANT_SUMMARIES)
                .unwrap()
                .get(variant.as_bytes().as_slice())
                .unwrap()
                .unwrap()
                .value()
                .to_vec();
            assert_ne!(
                u64::from_be_bytes(summary_bytes[27..35].try_into().unwrap()) & (1 << 63),
                0,
                "current v5 summary restores the finite-root aggregate"
            );
            assert!(
                pressure::decode_variant_summary(&summary_bytes)
                    .unwrap()
                    .has_finite_roots
            );
            let variant_key = read
                .open_table(pressure::BLOB_PRESSURE_VARIANTS)
                .unwrap()
                .iter()
                .unwrap()
                .find_map(|row| {
                    let (key, _) = row.unwrap();
                    let (summary, indexed_variant) =
                        pressure::decode_variant_index_key(&key.value()).unwrap();
                    (indexed_variant == variant).then_some((key.value(), summary))
                })
                .expect("current v5 finite variant index");
            assert_ne!(
                u64::from_be_bytes(variant_key.0[68..76].try_into().unwrap()) & (1 << 63),
                0,
                "current v5 index restores the finite-root aggregate"
            );
            assert!(variant_key.1.has_finite_roots);
        }
        let actual_publications = read
            .open_table(pressure::BLOB_PRESSURE_DURABLE_PUBLICATIONS)
            .unwrap()
            .iter()
            .unwrap()
            .map(|row| row.unwrap().0.value().to_vec())
            .collect::<BTreeSet<_>>();
        let actual_content_publications = read
            .open_table(pressure::BLOB_PRESSURE_DURABLE_CONTENT_PUBLICATIONS)
            .unwrap()
            .iter()
            .unwrap()
            .map(|row| row.unwrap().0.value().to_vec())
            .collect::<BTreeSet<_>>();
        let actual_pending = read
            .open_table(pressure::BLOB_PRESSURE_DURABLE_PENDING_SOURCES)
            .unwrap()
            .iter()
            .unwrap()
            .map(|row| row.unwrap().0.value())
            .collect::<BTreeSet<_>>();
        let actual_variants = read
            .open_table(pressure::BLOB_PRESSURE_DURABLE_VARIANTS)
            .unwrap()
            .iter()
            .unwrap()
            .map(|row| row.unwrap().0.value())
            .collect::<BTreeSet<_>>();
        assert_eq!(actual_publications, expected_publications);
        assert_eq!(actual_content_publications, expected_content_publications);
        assert_eq!(actual_pending, BTreeSet::from([expected_pending]));
        assert_eq!(actual_variants, expected_variants);
        drop(read);
        drop(database);
        let upgraded = pressure_database_digest(&target_root.database);
        drop(Store::open(&target_root.database).expect("idempotent current-v5 reopen"));
        assert_eq!(pressure_database_digest(&target_root.database), upgraded);
    }

    #[test]
    fn blob_pressure_schema_rejects_partial_current_without_repair() {
        let root = BlobTestRoot::new("pressure-schema-partial");
        drop(Store::open(&root.database).expect("current pressure schema"));
        let database = Database::open(&root.database).expect("partial pressure database");
        let write = database.begin_write().expect("partial pressure write");
        write
            .delete_table(pressure::BLOB_PRESSURE_VARIANTS)
            .expect("delete one pressure table");
        write.commit().expect("commit partial pressure schema");
        drop(database);
        assert_blob_schema_invariant(
            &Store::inspect_existing(&root.database)
                .expect_err("read-only partial pressure schema must fail"),
        );
        let writable = match Store::open(&root.database) {
            Ok(_) => panic!("writable partial pressure schema must fail"),
            Err(error) => error,
        };
        assert_blob_schema_invariant(&writable);

        let missing_old_v5 = BlobTestRoot::new("pressure-old-v5-missing-canonical");
        drop(Store::open(&missing_old_v5.database).expect("create current pressure schema"));
        rewrite_pressure_v5_as_pre_task5_for_test(&missing_old_v5.database);
        let database = Database::open(&missing_old_v5.database).unwrap();
        let write = database.begin_write().unwrap();
        write
            .delete_table(pressure::BLOB_PRESSURE_VARIANTS)
            .expect("delete old-v5 canonical variant table");
        write.commit().unwrap();
        drop(database);
        let before = pressure_database_digest(&missing_old_v5.database);
        assert_blob_schema_invariant(
            &Store::inspect_existing(&missing_old_v5.database)
                .expect_err("old-v5 layout missing a canonical table must fail read-only"),
        );
        let writable = Store::open(&missing_old_v5.database)
            .err()
            .expect("old-v5 layout missing a canonical table must fail writable");
        assert_blob_schema_invariant(&writable);
        assert_eq!(pressure_database_digest(&missing_old_v5.database), before);

        for retained in 1..0b1111 {
            let partial = BlobTestRoot::new(&format!("partial-durable-pressure-{retained:04b}"));
            drop(Store::open(&partial.database).expect("create complete current pressure schema"));
            retain_durable_pressure_tables_for_test(&partial.database, retained);
            let before = pressure_database_digest(&partial.database);
            assert_blob_schema_invariant(
                &Store::inspect_existing(&partial.database)
                    .expect_err("partial durable-only table set must fail read-only"),
            );
            let writable = Store::open(&partial.database)
                .err()
                .expect("partial durable-only table set must fail writable");
            assert_blob_schema_invariant(&writable);
            assert_eq!(
                pressure_database_digest(&partial.database),
                before,
                "partial durable-only table set must not be repaired"
            );
        }

        for (label, lifecycle_version, pressure_version) in
            [("current-old", 4, 3), ("old-current", 3, 4)]
        {
            let mixed = BlobTestRoot::new(label);
            drop(Store::open(&mixed.database).expect("create complete current schema"));
            let database = Database::open(&mixed.database).expect("mixed-schema database");
            let write = database.begin_write().expect("mixed-schema write");
            write
                .open_table(lifecycle::BLOB_LIFECYCLE_METADATA)
                .expect("lifecycle metadata")
                .insert("schema_version", lifecycle_version)
                .expect("set lifecycle generation");
            write
                .open_table(pressure::BLOB_PRESSURE_METADATA)
                .expect("pressure metadata")
                .insert(pressure::PRESSURE_SCHEMA_VERSION_FIELD, pressure_version)
                .expect("set pressure generation");
            write.commit().expect("commit mixed schema");
            drop(database);
            let before = blob_database_digest(&mixed.database);
            assert_blob_schema_invariant(
                &Store::inspect_existing(&mixed.database)
                    .expect_err("read-only mixed schema must fail closed"),
            );
            let writable = Store::open(&mixed.database)
                .err()
                .expect("writable mixed schema must fail closed");
            assert_blob_schema_invariant(&writable);
            assert_eq!(
                blob_database_digest(&mixed.database),
                before,
                "mixed schema must remain byte-identical"
            );
        }
    }

    #[test]
    fn blob_pressure_audit_rejects_orphaned_index_rows_without_repair() {
        let root = BlobTestRoot::new("pressure-orphan-index");
        drop(Store::open(&root.database).expect("current pressure schema"));
        let database = Database::open(&root.database).expect("pressure corruption database");
        let write = database.begin_write().expect("pressure corruption write");
        write
            .open_table(pressure::BLOB_PRESSURE_PENDING_SOURCES)
            .expect("pending pressure index")
            .insert(&[1u8; 68], &[] as &[u8])
            .expect("insert orphan pressure index");
        write.commit().expect("commit pressure corruption");
        drop(database);
        assert_blob_schema_invariant(
            &Store::inspect_existing(&root.database)
                .expect_err("read-only pressure audit must reject orphan index"),
        );
        let writable = match Store::open(&root.database) {
            Ok(_) => panic!("writable pressure audit must not repair orphan index"),
            Err(error) => error,
        };
        assert_blob_schema_invariant(&writable);

        let old_v5_corrupt = BlobTestRoot::new("pressure-old-v5-canonical-corruption");
        drop(Store::open(&old_v5_corrupt.database).expect("current old-v5 source schema"));
        let database = Database::open(&old_v5_corrupt.database).unwrap();
        let write = database.begin_write().unwrap();
        write
            .open_table(pressure::BLOB_PRESSURE_PENDING_SOURCES)
            .unwrap()
            .insert(&[3u8; 68], &[] as &[u8])
            .unwrap();
        write.commit().unwrap();
        drop(database);
        rewrite_pressure_v5_as_pre_task5_for_test(&old_v5_corrupt.database);
        let before = pressure_database_digest(&old_v5_corrupt.database);
        assert_blob_schema_invariant(
            &Store::inspect_existing(&old_v5_corrupt.database)
                .expect_err("corrupt old-v5 canonical image must fail read-only"),
        );
        let writable = Store::open(&old_v5_corrupt.database)
            .err()
            .expect("corrupt old-v5 canonical image must fail before upgrade");
        assert_blob_schema_invariant(&writable);
        assert_eq!(pressure_database_digest(&old_v5_corrupt.database), before);

        let durable_root = BlobTestRoot::new("pressure-orphan-durable-index");
        drop(Store::open(&durable_root.database).expect("current durable pressure schema"));
        let database = Database::open(&durable_root.database).unwrap();
        let write = database.begin_write().unwrap();
        write
            .open_table(pressure::BLOB_PRESSURE_DURABLE_PENDING_SOURCES)
            .unwrap()
            .insert(&[2u8; 68], &[] as &[u8])
            .unwrap();
        write.commit().unwrap();
        drop(database);
        assert_blob_schema_invariant(
            &Store::inspect_existing(&durable_root.database)
                .expect_err("orphan durable-only pressure index must fail the audit"),
        );
        let writable = match Store::open(&durable_root.database) {
            Ok(_) => panic!("writable audit must not repair an orphan durable-only index"),
            Err(error) => error,
        };
        assert_blob_schema_invariant(&writable);

        // The aggregate and index can agree with each other while lying about
        // the authoritative roots.  The full audit must still reject that
        // corruption rather than admitting the variant to durable selection.
        let aggregate_root = BlobTestRoot::new("pressure-finite-root-aggregate-corruption");
        let mut services = blob_services(0xd4);
        let store = Store::open_for_mission(&aggregate_root.database, services.authority)
            .expect("aggregate corruption store");
        let plaintext = b"finite root aggregate audit".to_vec();
        let prepared = prepared_blob(&plaintext);
        let (publication, operation, _) = publish_blob(
            &store,
            &mut services,
            &prepared,
            &plaintext,
            1,
            b"finite-root-aggregate-audit",
        );
        rewrite_live_blob_as_finite_for_retirement_test(
            &store,
            &publication,
            Some(&operation),
            50_000,
            100,
            CustodySample {
                clock_id: [0xd4; 16],
                tick_ms: 10_000,
            },
        );
        drop(store);

        let database = Database::open(&aggregate_root.database).unwrap();
        let write = database.begin_write().unwrap();
        let encoded = write
            .open_table(pressure::BLOB_PRESSURE_VARIANT_SUMMARIES)
            .unwrap()
            .get(publication.variant_id.as_bytes().as_slice())
            .unwrap()
            .unwrap()
            .value()
            .to_vec();
        let summary = pressure::decode_variant_summary(&encoded).unwrap();
        assert!(summary.has_finite_roots);
        let old_key = write
            .open_table(pressure::BLOB_PRESSURE_VARIANTS)
            .unwrap()
            .iter()
            .unwrap()
            .find_map(|row| {
                let (key, _) = row.unwrap();
                let key = key.value();
                let (_, variant) = pressure::decode_variant_index_key(&key).unwrap();
                (variant == publication.variant_id).then_some(key)
            })
            .expect("finite aggregate index key");
        write
            .open_table(pressure::BLOB_PRESSURE_VARIANTS)
            .unwrap()
            .remove(&old_key)
            .unwrap()
            .expect("finite aggregate index");
        let contradictory = pressure::PressureVariantSummary {
            has_finite_roots: false,
            ..summary
        };
        let encoded = pressure::encode_variant_summary(contradictory);
        write
            .open_table(pressure::BLOB_PRESSURE_VARIANT_SUMMARIES)
            .unwrap()
            .insert(
                publication.variant_id.as_bytes().as_slice(),
                encoded.as_slice(),
            )
            .unwrap();
        let mut key = old_key;
        key[68] &= 0x7f;
        write
            .open_table(pressure::BLOB_PRESSURE_VARIANTS)
            .unwrap()
            .insert(&key, &[] as &[u8])
            .unwrap();
        write.commit().unwrap();
        drop(database);
        assert_blob_schema_invariant(
            &Store::inspect_existing(&aggregate_root.database)
                .expect_err("root-contradictory aggregate must fail the pressure audit"),
        );
    }

    #[test]
    fn blob_pressure_equivalent_fraction_index_substitution_fails_closed_without_repair() {
        let source_root = BlobTestRoot::new("pressure-equivalent-fraction-source");
        let target_root = BlobTestRoot::new("pressure-equivalent-fraction-target");
        let mut services = blob_services(0xd5);
        let source = Store::open_for_mission(&source_root.database, services.authority)
            .expect("equivalent-fraction source store");
        let target = Store::open_for_mission(&target_root.database, services.authority)
            .expect("equivalent-fraction target store");
        let policy = target
            .control_policy_snapshot()
            .expect("equivalent-fraction policy");
        let plaintext = vec![0x51; SELECTED_BLOB_CHUNK_SIZE as usize + 13];
        let prepared = prepared_blob(&plaintext);
        let proof = prepare_blob_proof(&source, &mut services, &prepared, &plaintext, 1);
        let plan = proof
            .blob
            .transfer_plan(&proof.manifest_bytes)
            .expect("equivalent-fraction plan");
        let transfer = BlobTransferId::new(proof.blob.envelope_id());
        target
            .stage_verified_blob_source_with_policy(&policy, &proof.blob, &proof.sealed, &plan)
            .expect("stage equivalent-fraction source");

        let read = target
            .database
            .begin_read()
            .expect("read canonical pressure root");
        let encoded_root = read
            .open_table(pressure::BLOB_PRESSURE_PENDING_ROOTS)
            .expect("pending pressure roots")
            .get(transfer.as_bytes().as_slice())
            .expect("read pending pressure root")
            .expect("pending pressure root exists")
            .value()
            .to_vec();
        drop(read);
        let root = pressure::decode_pending_root(&encoded_root).expect("decode pending root");
        let canonical = pressure::encode_pending_index_key(root.clone(), transfer);
        let equivalent = pressure::encode_pending_index_key(
            pressure::PressurePendingRoot {
                completion: pressure::PressureFraction::new(
                    root.completion
                        .numerator()
                        .checked_mul(2)
                        .expect("small numerator"),
                    root.completion
                        .denominator()
                        .checked_mul(2)
                        .expect("small denominator"),
                )
                .expect("equivalent completion"),
                ..root
            },
            transfer,
        );
        assert_ne!(canonical, equivalent);
        let write = target
            .database
            .begin_write()
            .expect("substitute equivalent pressure key");
        let mut pending = write
            .open_table(pressure::BLOB_PRESSURE_PENDING_SOURCES)
            .expect("pending pressure index");
        pending
            .remove(&canonical)
            .expect("remove canonical pressure key")
            .expect("canonical pressure key exists");
        pending
            .insert(&equivalent, &[] as &[u8])
            .expect("insert equivalent pressure key");
        drop(pending);
        write.commit().expect("commit equivalent key substitution");

        let mut source_depot = source.blob_depot().expect("source transfer depot");
        CoreBlobStore::begin_blob_with_lineage(
            &mut source_depot,
            plan.manifest(),
            plan.physical_lineage(),
        )
        .expect("activate source transfer plan");
        let carrier = plan
            .build_carrier(&mut source_depot, 0)
            .expect("build first transfer carrier");
        let object = BlobCarrierObjectId::new(carrier.object_id().wire_bytes())
            .expect("typed first carrier");
        let total_len = u64::try_from(carrier.bytes().len()).expect("carrier length");
        assert_blob_schema_invariant(
            &target
                .append_blob_carrier_prefix_with_policy(
                    &policy,
                    transfer,
                    object,
                    total_len,
                    0,
                    &carrier.bytes()[..carrier.bytes().len().min(MAX_BLOB_NETWORK_RANGE_BYTES)],
                )
                .expect_err("equivalent fraction substitution must fail before mutation"),
        );
        let read = target
            .database
            .begin_read()
            .expect("read rejected equivalent key");
        let stored = read
            .open_table(pressure::BLOB_PRESSURE_PENDING_SOURCES)
            .expect("pending pressure index")
            .iter()
            .expect("pending pressure keys")
            .map(|row| row.expect("pending pressure row").0.value())
            .collect::<Vec<_>>();
        assert!(stored.contains(&equivalent));
        assert!(!stored.contains(&canonical));
        drop(read);
        drop(target);

        assert_blob_schema_invariant(
            &Store::inspect_existing(&target_root.database)
                .expect_err("read-only audit must reject equivalent fraction substitution"),
        );
        let writable = match Store::open_for_mission(&target_root.database, services.authority) {
            Ok(_) => panic!("writable audit must not repair equivalent fraction substitution"),
            Err(error) => error,
        };
        assert_blob_schema_invariant(&writable);
        let database = redb::Builder::new()
            .open_read_only(&target_root.database)
            .expect("read unrepaired equivalent key");
        let read = database.begin_read().expect("unrepaired pressure read");
        let stored = read
            .open_table(pressure::BLOB_PRESSURE_PENDING_SOURCES)
            .expect("unrepaired pending pressure index")
            .iter()
            .expect("unrepaired pending pressure keys")
            .map(|row| row.expect("unrepaired pending pressure row").0.value())
            .collect::<Vec<_>>();
        assert!(stored.contains(&equivalent));
        assert!(!stored.contains(&canonical));
    }

    #[test]
    fn blob_pressure_migration_preflights_pending_order_growth_against_staging_cap() {
        let source_root = BlobTestRoot::new("pressure-cap-source");
        let target_root = BlobTestRoot::new("pressure-cap-target");
        let mut services = blob_services(0xd6);
        let source = Store::open_for_mission(&source_root.database, services.authority)
            .expect("pressure-cap source store");
        let target = Store::open_for_mission(&target_root.database, services.authority)
            .expect("pressure-cap target store");
        let plaintext = vec![0x61; 4_103];
        let prepared = prepared_blob(&plaintext);
        let proof = prepare_blob_proof(&source, &mut services, &prepared, &plaintext, 1);
        let plan = proof
            .blob
            .transfer_plan(&proof.manifest_bytes)
            .expect("pressure-cap plan");
        let policy = target
            .control_policy_snapshot()
            .expect("pressure-cap policy");
        target
            .stage_verified_blob_source_with_policy(&policy, &proof.blob, &proof.sealed, &plan)
            .expect("stage pressure-cap source");
        let transfer = BlobTransferId::new(proof.blob.envelope_id());
        drop(target);
        downgrade_blob_lifecycle_to_v3_for_test(&target_root.database);

        let exact_legacy_bytes = {
            let database = Database::open(&target_root.database).expect("pressure-cap database");
            let write = database
                .begin_write()
                .expect("pressure-cap predecessor write");
            let mut pending = write
                .open_table(BLOB_PENDING_SOURCES)
                .expect("pressure-cap pending sources");
            let current = pending
                .get(transfer.as_bytes().as_slice())
                .expect("read pressure-cap pending source")
                .expect("pressure-cap pending source exists")
                .value()
                .to_vec();
            let mut legacy = Vec::with_capacity(current.len() - 8);
            legacy.push(LEGACY_PENDING_BLOB_SOURCE_VERSION);
            legacy.extend_from_slice(&current[9..]);
            pending
                .insert(transfer.as_bytes().as_slice(), legacy.as_slice())
                .expect("write pressure-cap legacy source");
            drop(pending);
            let mut metadata = write
                .open_table(BLOB_NETWORK_METADATA)
                .expect("pressure-cap network metadata");
            let exact = metadata
                .get(BLOB_NETWORK_STAGING_BYTES)
                .expect("read pressure-cap staging bytes")
                .expect("pressure-cap staging bytes exist")
                .value()
                .checked_sub(8)
                .expect("legacy pending source is eight bytes smaller");
            metadata
                .insert(BLOB_NETWORK_STAGING_BYTES, exact)
                .expect("store exact pressure-cap legacy bytes");
            drop(metadata);
            write.commit().expect("commit pressure-cap predecessor");
            exact
        };
        strip_blob_pressure_schema_for_test(&target_root.database);

        let database = Database::open(&target_root.database).expect("open pressure-cap boundary");
        let boundary = MAX_BLOB_NETWORK_STAGING_BYTES - 7;
        let write = database.begin_write().expect("set pressure-cap boundary");
        write
            .open_table(BLOB_NETWORK_METADATA)
            .expect("pressure-cap metadata")
            .insert(BLOB_NETWORK_STAGING_BYTES, boundary)
            .expect("store pressure-cap boundary");
        write.commit().expect("commit pressure-cap boundary");

        let write = database
            .begin_write()
            .expect("attempt pressure-cap migration");
        let error = pressure::audit_or_migrate_pressure_write(&write)
            .expect_err("pending-order growth beyond staging cap must fail before mutation");
        assert!(matches!(
            error,
            StoreError::Blob(BlobStoreError::NetworkStagingByteLimitExceeded {
                current,
                incoming: 8,
                limit: MAX_BLOB_NETWORK_STAGING_BYTES,
            }) if current == boundary
        ));
        drop(write);

        let read = database
            .begin_read()
            .expect("read rolled-back pressure-cap state");
        assert_eq!(
            read.open_table(BLOB_NETWORK_METADATA)
                .expect("rolled-back pressure-cap metadata")
                .get(BLOB_NETWORK_STAGING_BYTES)
                .expect("read rolled-back pressure-cap bytes")
                .expect("rolled-back pressure-cap bytes exist")
                .value(),
            boundary
        );
        let legacy = read
            .open_table(BLOB_PENDING_SOURCES)
            .expect("rolled-back pressure-cap pending sources")
            .get(transfer.as_bytes().as_slice())
            .expect("read rolled-back pending source")
            .expect("rolled-back pending source exists")
            .value()
            .to_vec();
        assert_eq!(legacy[0], LEGACY_PENDING_BLOB_SOURCE_VERSION);
        assert!(
            !read
                .list_tables()
                .expect("rolled-back pressure-cap tables")
                .any(|table| table.name() == pressure::BLOB_PRESSURE_METADATA.name())
        );
        drop(read);

        let write = database
            .begin_write()
            .expect("restore exact legacy byte count");
        write
            .open_table(BLOB_NETWORK_METADATA)
            .expect("restore pressure-cap metadata")
            .insert(BLOB_NETWORK_STAGING_BYTES, exact_legacy_bytes)
            .expect("restore exact legacy bytes");
        write.commit().expect("commit exact legacy bytes");
        drop(database);

        drop(
            Store::open_for_mission(&target_root.database, services.authority)
                .expect("retry pressure migration after restoring capacity"),
        );
        Store::inspect_existing(&target_root.database)
            .expect("reopen successfully migrated pressure-cap store");
    }

    #[test]
    fn blob_pressure_migration_orders_legacy_pending_sources_by_transfer_identity() {
        let source_root = BlobTestRoot::new("pressure-order-source");
        let target_root = BlobTestRoot::new("pressure-order-target");
        let mut services = blob_services(0xd4);
        let source = Store::open_for_mission(&source_root.database, services.authority)
            .expect("pressure order source");
        let target = Store::open_for_mission(&target_root.database, services.authority)
            .expect("pressure order target");
        let first_plaintext = vec![0x41; 4_097];
        let second_plaintext = vec![0x42; 4_099];
        let first_prepared = prepared_blob(&first_plaintext);
        let second_prepared = prepared_blob(&second_plaintext);
        let first =
            prepare_blob_proof(&source, &mut services, &first_prepared, &first_plaintext, 1);
        let second = prepare_blob_proof(
            &source,
            &mut services,
            &second_prepared,
            &second_plaintext,
            1,
        );
        let first_plan = first
            .blob
            .transfer_plan(&first.manifest_bytes)
            .expect("first pressure plan");
        let second_plan = second
            .blob
            .transfer_plan(&second.manifest_bytes)
            .expect("second pressure plan");
        let policy = target.control_policy_snapshot().expect("pressure policy");
        let mut sources = [
            (
                BlobTransferId::new(first.blob.envelope_id()),
                &first,
                &first_plan,
            ),
            (
                BlobTransferId::new(second.blob.envelope_id()),
                &second,
                &second_plan,
            ),
        ];
        sources.sort_unstable_by_key(|(transfer, _, _)| *transfer);
        for (_, proof, plan) in sources.iter().rev() {
            assert_eq!(
                target
                    .stage_verified_blob_source_with_policy(
                        &policy,
                        &proof.blob,
                        &proof.sealed,
                        plan,
                    )
                    .expect("stage pressure source"),
                BlobSourceStageOutcome::Inserted
            );
        }
        drop(target);
        downgrade_blob_lifecycle_to_v3_for_test(&target_root.database);
        {
            let database = Database::open(&target_root.database).expect("legacy pending database");
            let write = database.begin_write().expect("legacy pending write");
            let mut table = write
                .open_table(BLOB_PENDING_SOURCES)
                .expect("legacy pending sources");
            for (transfer, _, _) in &sources {
                let current = table
                    .get(transfer.as_bytes().as_slice())
                    .expect("read current pending source")
                    .expect("current pending source exists")
                    .value()
                    .to_vec();
                let mut legacy = Vec::with_capacity(current.len() - 8);
                legacy.push(LEGACY_PENDING_BLOB_SOURCE_VERSION);
                legacy.extend_from_slice(&current[9..]);
                table
                    .insert(transfer.as_bytes().as_slice(), legacy.as_slice())
                    .expect("write legacy pending source");
            }
            drop(table);
            let mut metadata = write
                .open_table(BLOB_NETWORK_METADATA)
                .expect("legacy network metadata");
            let staging_bytes = metadata
                .get(BLOB_NETWORK_STAGING_BYTES)
                .expect("read legacy staging bytes")
                .expect("legacy staging bytes exist")
                .value();
            metadata
                .insert(
                    BLOB_NETWORK_STAGING_BYTES,
                    staging_bytes
                        .checked_sub(8 * u64::try_from(sources.len()).expect("small source count"))
                        .expect("legacy encoding shrinks staging rows"),
                )
                .expect("adjust legacy staging bytes");
            drop(metadata);
            write.commit().expect("commit legacy pending sources");
        }
        strip_blob_pressure_schema_for_test(&target_root.database);
        assert!(
            Store::inspect_existing(&target_root.database).is_err(),
            "legacy pending pressure state needs writable migration"
        );
        let target = Store::open_for_mission(&target_root.database, services.authority)
            .expect("migrate pending pressure orders");
        let read = target.database.begin_read().expect("read pending orders");
        let roots = read
            .open_table(pressure::BLOB_PRESSURE_PENDING_ROOTS)
            .expect("pending pressure roots");
        let authoritative = read
            .open_table(BLOB_PENDING_SOURCES)
            .expect("authoritative pending sources");
        for (index, (transfer, _, _)) in sources.iter().enumerate() {
            let expected_order = u64::try_from(index + 1).expect("small order");
            let encoded = roots
                .get(transfer.as_bytes().as_slice())
                .expect("read pending pressure root")
                .expect("pending pressure root exists");
            assert_eq!(
                pressure::decode_pending_root(encoded.value())
                    .expect("decode pending pressure root")
                    .acceptance_order,
                expected_order
            );
            assert_eq!(
                decode_pending_blob_source(
                    authoritative
                        .get(transfer.as_bytes().as_slice())
                        .expect("read authoritative pending source")
                        .expect("authoritative pending source exists")
                        .value(),
                )
                .expect("decode authoritative pending source")
                .pending_acceptance_order,
                expected_order,
            );
        }
        let metadata = read
            .open_table(pressure::BLOB_PRESSURE_METADATA)
            .expect("pressure metadata");
        assert_eq!(
            metadata
                .get(pressure::NEXT_PENDING_ACCEPTANCE_ORDER)
                .expect("read next pending order")
                .expect("next pending order exists")
                .value(),
            3
        );
        drop(metadata);
        drop(authoritative);
        drop(roots);
        drop(read);

        let (_, proof, plan) = &sources[0];
        assert_eq!(
            target
                .stage_verified_blob_source_with_policy(&policy, &proof.blob, &proof.sealed, plan,)
                .expect("retry migrated pending source"),
            BlobSourceStageOutcome::Duplicate
        );

        let migrated_eviction = target
            .run_blob_pressure_recovery(
                pressure::BlobCapacityRecoveryDemand::new(
                    pressure::BlobCapacityPartition::NetworkStagingRows,
                    Priority::Flash,
                    1,
                )
                .unwrap(),
                pressure::BlobPressureRecoveryBudget::new(
                    MAX_BLOB_PRESSURE_FINAL_ROOT_ROWS,
                    MAX_BLOB_PRESSURE_FINAL_ROOT_BYTES,
                    1,
                    1,
                    1,
                )
                .unwrap(),
                None,
            )
            .expect("evict oldest migrated pending source");
        assert_eq!(migrated_eviction.evicted_transfer_ids(), &[sources[0].0]);
        assert!(target.pending_blob_source(sources[0].0).unwrap().is_none());
        assert!(target.pending_blob_source(sources[1].0).unwrap().is_some());

        let write = target
            .database
            .begin_write()
            .expect("seed pending-order overflow");
        write
            .open_table(pressure::BLOB_PRESSURE_METADATA)
            .expect("pressure metadata")
            .insert(pressure::NEXT_PENDING_ACCEPTANCE_ORDER, u64::MAX)
            .expect("set pending-order overflow");
        write.commit().expect("commit pending-order overflow");
        let overflow_plaintext = vec![0x43; 4_101];
        let overflow_prepared = prepared_blob(&overflow_plaintext);
        let overflow = prepare_blob_proof(
            &source,
            &mut services,
            &overflow_prepared,
            &overflow_plaintext,
            1,
        );
        let overflow_plan = overflow
            .blob
            .transfer_plan(&overflow.manifest_bytes)
            .expect("overflow pressure plan");
        let overflow_transfer = BlobTransferId::new(overflow.blob.envelope_id());
        assert_blob_schema_invariant(
            &target
                .stage_verified_blob_source_with_policy(
                    &policy,
                    &overflow.blob,
                    &overflow.sealed,
                    &overflow_plan,
                )
                .expect_err("pending-order overflow must reject before commit"),
        );
        assert!(
            target
                .pending_blob_source(overflow_transfer)
                .expect("overflow source lookup")
                .is_none()
        );
        drop(target);
        Store::inspect_existing(&target_root.database)
            .expect("retry retains migrated pressure order");
    }

    #[test]
    fn blob_pressure_shared_publications_have_hand_derived_summary_and_reopen() {
        let root = BlobTestRoot::new("pressure-shared-publications");
        let mut services = blob_services(0xe4);
        let plaintext = vec![0x64; SELECTED_BLOB_CHUNK_SIZE as usize + 17];
        let prepared = prepared_blob(&plaintext);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("pressure shared store");
        let first_proof = prepare_blob_proof_with_priority(
            &store,
            &mut services,
            &prepared,
            &plaintext,
            1,
            Priority::Routine,
        );
        let first = commit_blob_proof(&store, &services, &first_proof, b"pressure-shared-first")
            .0
            .blob()
            .clone();
        let second_proof = prepare_blob_proof_with_priority(
            &store,
            &mut services,
            &prepared,
            &plaintext,
            1,
            Priority::Immediate,
        );
        let second = commit_blob_proof(&store, &services, &second_proof, b"pressure-shared-second")
            .0
            .blob()
            .clone();
        assert_eq!(first.variant_id, second.variant_id);
        assert_ne!(first.transfer_id, second.transfer_id);
        let expected_order = first.acceptance_marker.min(second.acceptance_marker);
        let read = store.database.begin_read().expect("pressure summary read");
        let summaries = read
            .open_table(pressure::BLOB_PRESSURE_VARIANT_SUMMARIES)
            .expect("pressure summaries");
        assert_eq!(summaries.len().expect("pressure summary count"), 1);
        let encoded = summaries
            .get(first.variant_id.as_bytes().as_slice())
            .expect("read pressure summary")
            .expect("shared pressure summary");
        let summary = pressure::decode_variant_summary(encoded.value())
            .expect("decode shared pressure summary");
        assert_eq!(summary.effective_priority, Priority::Immediate);
        assert_eq!(summary.minimum_root_acceptance_order, expected_order);
        assert_eq!(summary.publication_roots, 2);
        assert_eq!(summary.pending_roots, 0);
        assert!(summary.finalized);
        assert_eq!(
            summary.committed_progress.numerator(),
            plaintext.len() as u64
        );
        assert_eq!(
            summary.committed_progress.denominator(),
            plaintext.len() as u64
        );
        drop(encoded);
        drop(summaries);
        drop(read);
        drop(store);

        let reopened = Store::open_for_mission(&root.database, services.authority)
            .expect("reopen shared pressure store");
        assert_eq!(
            reopened.blob_inventory().expect("reopened inventory").len(),
            2
        );
    }

    #[test]
    fn blob_pressure_evicts_lower_priority_shared_publication_metadata_only() {
        // Break caught: pressure retirement used to require policy invalidity
        // and could either spare the best candidate or delete shared content.
        let root = BlobTestRoot::new("pressure-shared-metadata-only");
        let mut services = blob_services(0xb1);
        let plaintext = b"shared pressure content remains for the protected root".to_vec();
        let prepared = prepared_blob(&plaintext);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("pressure shared metadata store");
        let low_proof = prepare_blob_proof_with_priority(
            &store,
            &mut services,
            &prepared,
            &plaintext,
            1,
            Priority::Routine,
        );
        let (low_outcome, low_operation, low_intent) =
            commit_blob_proof(&store, &services, &low_proof, b"pressure-low-shared");
        let low = low_outcome.blob().clone();
        let high_proof = prepare_blob_proof_with_priority(
            &store,
            &mut services,
            &prepared,
            &plaintext,
            1,
            Priority::Immediate,
        );
        let high = commit_blob_proof(&store, &services, &high_proof, b"pressure-high-shared")
            .0
            .blob()
            .clone();
        assert_eq!(low.variant_id, high.variant_id);
        store
            .run_blob_maintenance_turn(maintenance_budget(1))
            .expect("ordinary cleanup precedes pressure");
        let before_cursors = blob_maintenance_cursor_rows(&store);
        let before_stats = store.blob_stats().expect("before pressure stats");

        let recovery = store
            .run_blob_pressure_recovery(
                pressure::BlobCapacityRecoveryDemand::new(
                    pressure::BlobCapacityPartition::AggregateItems,
                    Priority::Immediate,
                    2,
                )
                .unwrap(),
                pressure::BlobPressureRecoveryBudget::new(
                    MAX_BLOB_POLICY_RETIREMENT_ROWS,
                    MAX_BLOB_POLICY_RETIREMENT_BYTES,
                    2,
                    4,
                    1,
                )
                .unwrap(),
                None,
            )
            .expect("shared pressure recovery");
        assert_eq!(recovery.evicted_transfer_ids(), &[low.transfer_id]);
        assert_eq!(recovery.recovered_units(), 1);
        assert!(!recovery.deficit_met());
        assert_eq!(blob_maintenance_cursor_rows(&store), before_cursors);
        assert!(matches!(
            store.get_blob(low.transfer_id),
            Err(StoreError::Blob(BlobStoreError::ExpiredOrRetired))
        ));
        assert_eq!(
            store
                .get_blob(high.transfer_id)
                .expect("protected shared publication read")
                .expect("protected shared publication exists")
                .sealed,
            high.sealed
        );
        assert!(matches!(
            store.blob_for_operation_with_policy(
                &store.control_policy_snapshot().expect("pressure policy"),
                &BlobOperationRequest::new(&low_operation, &low_intent),
            ),
            Err(StoreError::Blob(BlobStoreError::ExpiredOrRetired))
        ));
        let read = store
            .database
            .begin_read()
            .expect("pressure retirement read");
        let encoded = read
            .open_table(BLOB_PUBLICATIONS)
            .expect("pressure publication table")
            .get(low.transfer_id.as_bytes().as_slice())
            .expect("pressure publication lookup")
            .expect("retired pressure publication");
        assert_eq!(
            lifecycle::publication_retirement(encoded.value())
                .expect("decode pressure retirement")
                .expect("pressure retirement state")
                .0,
            lifecycle::RetirementReason::Evicted
        );
        assert!(
            !deletion::variant_has_deletion_manifest_read(&read, low.variant_id)
                .expect("shared pressure manifest state")
        );
        let dot = low.header.stamp.dot;
        let dot_key = accepted_dot_key(dot);
        assert!(
            read.open_table(ACCEPTED_DOTS)
                .unwrap()
                .get(dot_key.as_slice())
                .unwrap()
                .is_some()
        );
        assert!(
            read.open_table(lifecycle::BLOB_REPLAY_FENCES)
                .unwrap()
                .get(dot_key.as_slice())
                .unwrap()
                .is_some()
        );
        let frontier_key = causal_frontier_key(&low.header.topic, &low.header.scope, dot.publisher)
            .expect("pressure causal-frontier key");
        assert!(
            read.open_table(CAUSAL_FRONTIER)
                .unwrap()
                .get(frontier_key.as_slice())
                .unwrap()
                .is_some()
        );
        drop(encoded);
        drop(read);
        let after_stats = store.blob_stats().expect("after pressure stats");
        assert_eq!(after_stats.lineage_fences, before_stats.lineage_fences);
        assert_eq!(after_stats.replay_fences, before_stats.replay_fences);
        assert_eq!(
            before_stats
                .publications
                .checked_sub(after_stats.publications),
            Some(1)
        );
        assert_eq!(
            after_stats.publication_lifecycle_rows,
            before_stats.publication_lifecycle_rows
        );
    }

    #[test]
    fn blob_pressure_retires_an_expired_finite_candidate_as_expired() {
        // Mutation caught: v5 expiry-first pressure ordering must not convert
        // a provably expired finite root into an eviction tombstone merely
        // because capacity recovery selected the bounded unit.
        let root = BlobTestRoot::new("pressure-expired-finite-reason");
        let mut services = blob_services(0xb7);
        let plaintext = b"shared content keeps pressure expiry metadata-only".to_vec();
        let prepared = prepared_blob(&plaintext);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("expired finite pressure store");
        let low_proof = prepare_blob_proof_with_priority(
            &store,
            &mut services,
            &prepared,
            &plaintext,
            1,
            Priority::Routine,
        );
        let (low_outcome, low_operation, _) =
            commit_blob_proof(&store, &services, &low_proof, b"pressure-expired-low");
        let low = low_outcome.blob().clone();
        let high_proof = prepare_blob_proof_with_priority(
            &store,
            &mut services,
            &prepared,
            &plaintext,
            1,
            Priority::Immediate,
        );
        let high = commit_blob_proof(&store, &services, &high_proof, b"pressure-expired-high")
            .0
            .blob()
            .clone();
        assert_eq!(low.variant_id, high.variant_id);
        let checkpoint = CustodySample {
            clock_id: [0xb8; 16],
            tick_ms: 100,
        };
        rewrite_live_blob_as_finite_for_retirement_test(
            &store,
            &low,
            Some(&low_operation),
            100,
            50,
            checkpoint,
        );
        let deadline = CustodySample {
            clock_id: checkpoint.clock_id,
            tick_ms: 150,
        };
        let write = store
            .database
            .begin_write()
            .expect("persist pressure expiry continuity");
        custody::observe_continuity_write(&write, deadline)
            .expect("advance pressure expiry continuity");
        synchronize_blob_policy_generation_write(&write)
            .expect("synchronize pressure expiry policy");
        write.commit().expect("commit pressure expiry continuity");

        let recovery = store
            .run_blob_pressure_recovery(
                pressure::BlobCapacityRecoveryDemand::new(
                    pressure::BlobCapacityPartition::AggregateItems,
                    Priority::Immediate,
                    1,
                )
                .expect("expired finite pressure demand"),
                pressure::BlobPressureRecoveryBudget::new(
                    MAX_BLOB_POLICY_RETIREMENT_ROWS,
                    MAX_BLOB_POLICY_RETIREMENT_BYTES,
                    2,
                    4,
                    1,
                )
                .expect("expired finite pressure budget"),
                None,
            )
            .expect("recover expired finite pressure root");
        assert_eq!(recovery.evicted_transfer_ids(), &[low.transfer_id]);
        assert!(store.get_blob(high.transfer_id).unwrap().is_some());
        let read = store.database.begin_read().expect("expired pressure read");
        let encoded = read
            .open_table(BLOB_PUBLICATIONS)
            .expect("expired pressure publications")
            .get(low.transfer_id.as_bytes().as_slice())
            .expect("expired pressure lookup")
            .expect("retained expired pressure publication")
            .value()
            .to_vec();
        assert_eq!(
            lifecycle::publication_retirement(&encoded)
                .expect("decode expired pressure retirement")
                .expect("expired pressure retirement exists")
                .0,
            lifecycle::RetirementReason::Expired
        );
        assert!(
            !deletion::variant_has_deletion_manifest_read(&read, low.variant_id)
                .expect("shared expired pressure manifest")
        );
    }

    #[test]
    fn blob_pressure_observes_discontinuous_sample_before_candidate_selection() {
        // Break caught: selecting from a clean clock-A pressure index before
        // observing clock B can retire the A-ranked root as Evicted even though
        // the generation change must first establish a fenced reanchor pass.
        let root = BlobTestRoot::new("pressure-sample-before-selection");
        let mut services = blob_services(0xba);
        let plaintext = b"shared pressure content crosses one clock discontinuity".to_vec();
        let prepared = prepared_blob(&plaintext);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("pressure discontinuity store");
        let low_proof = prepare_blob_proof_with_priority(
            &store,
            &mut services,
            &prepared,
            &plaintext,
            1,
            Priority::Routine,
        );
        let (low_outcome, low_operation, _) =
            commit_blob_proof(&store, &services, &low_proof, b"pressure-clock-a-low");
        let low = low_outcome.blob().clone();
        let high_proof = prepare_blob_proof_with_priority(
            &store,
            &mut services,
            &prepared,
            &plaintext,
            1,
            Priority::Immediate,
        );
        let high = commit_blob_proof(&store, &services, &high_proof, b"pressure-clock-a-high")
            .0
            .blob()
            .clone();
        assert_eq!(low.variant_id, high.variant_id);
        let clock_a = CustodySample {
            clock_id: [0xba; 16],
            tick_ms: 100,
        };
        rewrite_live_blob_as_finite_for_retirement_test(
            &store,
            &low,
            Some(&low_operation),
            100,
            50,
            clock_a,
        );
        let clock_b = CustodySample {
            clock_id: [0xbb; 16],
            tick_ms: 1,
        };
        let demand = pressure::BlobCapacityRecoveryDemand::new(
            pressure::BlobCapacityPartition::AggregateItems,
            Priority::Immediate,
            1,
        )
        .expect("pressure discontinuity demand");
        let pressure_budget = |rows, bytes| {
            pressure::BlobPressureRecoveryBudget::new(rows, bytes, 2, 4, 1)
                .expect("pressure discontinuity budget")
        };
        let publication_is_live = |transfer: BlobTransferId| {
            let read = store
                .database
                .begin_read()
                .expect("pressure discontinuity publication read");
            let encoded = read
                .open_table(BLOB_PUBLICATIONS)
                .expect("pressure discontinuity publications")
                .get(transfer.as_bytes().as_slice())
                .expect("pressure discontinuity publication lookup")
                .expect("pressure discontinuity publication exists")
                .value()
                .to_vec();
            lifecycle::publication_retirement(&encoded)
                .expect("decode pressure discontinuity publication")
                .is_none()
        };
        let before_continuity = {
            let read = store
                .database
                .begin_read()
                .expect("clock-A continuity read");
            custody::lower_bound_continuity_read(&read)
                .expect("clock-A continuity")
                .expect("clock-A continuity exists")
        };
        let (sync_rows, sync_bytes) = {
            let write = store
                .database
                .begin_write()
                .expect("pressure sync charge writer");
            custody::observe_continuity_write(&write, clock_b).expect("project clock-B continuity");
            let plan = plan_blob_policy_generation_sync_write(&write)
                .expect("plan pressure discontinuity sync");
            assert!(plan.reset_pressure_reanchor);
            let mut charge = MaintenanceCharge::new(maintenance_budget(u64::MAX), 0, 0);
            assert!(
                charge_blob_policy_generation_sync_write(&write, plan, &mut charge)
                    .expect("charge pressure discontinuity sync")
            );
            (charge.rows, charge.bytes)
        };
        assert!(sync_rows > 0 && sync_bytes > 0);
        let before_short = blob_complete_logical_digest(&store);
        for budget in [
            pressure_budget(sync_rows - 1, sync_bytes),
            pressure_budget(sync_rows, sync_bytes - 1),
        ] {
            let short = store
                .run_blob_pressure_recovery(demand, budget, Some(clock_b))
                .expect("bounded pressure sync refusal");
            assert!(short.evicted_transfer_ids().is_empty());
            assert_eq!(blob_complete_logical_digest(&store), before_short);
            let read = store
                .database
                .begin_read()
                .expect("short pressure continuity read");
            assert_eq!(
                custody::lower_bound_continuity_read(&read).expect("short pressure continuity"),
                Some(before_continuity)
            );
        }

        let synchronized = store
            .run_blob_pressure_recovery(
                demand,
                pressure_budget(sync_rows, sync_bytes),
                Some(clock_b),
            )
            .expect("observe and synchronize pressure discontinuity");
        assert!(synchronized.evicted_transfer_ids().is_empty());
        assert!(publication_is_live(low.transfer_id));
        assert!(store.get_blob(high.transfer_id).unwrap().is_some());
        {
            let read = store
                .database
                .begin_read()
                .expect("synchronized pressure read");
            let continuity = custody::lower_bound_continuity_read(&read)
                .expect("synchronized continuity")
                .expect("synchronized continuity exists");
            assert_eq!(continuity.generation, before_continuity.generation + 1);
            assert_eq!(continuity.sample, clock_b);
            let metadata = read
                .open_table(pressure::BLOB_PRESSURE_METADATA)
                .expect("synchronized pressure metadata");
            assert_eq!(
                metadata
                    .get("reanchor_target_generation")
                    .expect("pressure target read")
                    .expect("pressure target exists")
                    .value(),
                continuity.generation
            );
            assert_eq!(
                metadata
                    .get("reanchor_dirty")
                    .expect("pressure dirty read")
                    .expect("pressure dirty exists")
                    .value(),
                1
            );
        }
        let gated = store
            .run_blob_pressure_recovery(
                demand,
                pressure_budget(
                    MAX_BLOB_POLICY_RETIREMENT_ROWS,
                    MAX_BLOB_POLICY_RETIREMENT_BYTES,
                ),
                Some(clock_b),
            )
            .expect("dirty pressure remains gated");
        assert!(gated.evicted_transfer_ids().is_empty());
        assert!(publication_is_live(low.transfer_id));

        synchronize_blob_policy_for_maintenance_test(&store);
        let recovered = store
            .run_blob_pressure_recovery(
                demand,
                pressure_budget(
                    MAX_BLOB_POLICY_RETIREMENT_ROWS,
                    MAX_BLOB_POLICY_RETIREMENT_BYTES,
                ),
                Some(clock_b),
            )
            .expect("same-generation pressure recovery");
        assert_eq!(recovered.evicted_transfer_ids(), &[low.transfer_id]);
        assert!(store.get_blob(high.transfer_id).unwrap().is_some());
    }

    fn assert_expired_final_publication_pressure_is_lease_independent(
        label: &str,
        partition: pressure::BlobCapacityPartition,
        expected_recovered_units: u64,
    ) {
        let root = BlobTestRoot::new(label);
        let mut services = blob_services(0xbc);
        let plaintext = format!("{label} finite final pressure root").into_bytes();
        let prepared = prepared_blob(&plaintext);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("finite final pressure store");
        let proof = prepare_blob_proof_with_priority(
            &store,
            &mut services,
            &prepared,
            &plaintext,
            1,
            Priority::Routine,
        );
        let (outcome, operation, _) =
            commit_blob_proof(&store, &services, &proof, label.as_bytes());
        let stored = outcome.blob().clone();
        let checkpoint = CustodySample {
            clock_id: [0xbc; 16],
            tick_ms: 100,
        };
        rewrite_live_blob_as_finite_for_retirement_test(
            &store,
            &stored,
            Some(&operation),
            100,
            50,
            checkpoint,
        );
        let deadline = CustodySample {
            clock_id: checkpoint.clock_id,
            tick_ms: 150,
        };
        {
            let write = store
                .database
                .begin_write()
                .expect("finite final deadline writer");
            custody::observe_continuity_write(&write, deadline)
                .expect("advance finite final deadline");
            synchronize_blob_policy_generation_write(&write)
                .expect("synchronize finite final policy");
            write.commit().expect("commit finite final deadline");
        }
        let lease = store
            .test_acquire_blob_lease(stored.variant_id, lease::BlobLeaseKind::ApplicationPageRead)
            .expect("active finite final publication lease");
        let recovery = store
            .run_blob_pressure_recovery(
                pressure::BlobCapacityRecoveryDemand::new(partition, Priority::Immediate, 1)
                    .expect("finite final pressure demand"),
                pressure::BlobPressureRecoveryBudget::new(
                    MAX_BLOB_PRESSURE_FINAL_ROOT_ROWS,
                    MAX_BLOB_PRESSURE_FINAL_ROOT_BYTES,
                    1,
                    2,
                    0,
                )
                .expect("finite final pressure budget"),
                None,
            )
            .expect("finite final pressure recovery");
        assert_eq!(recovery.evicted_transfer_ids(), &[stored.transfer_id]);
        assert_eq!(recovery.recovered_units(), expected_recovered_units);
        assert_eq!(recovery.deficit_met(), expected_recovered_units >= 1);
        {
            let read = store
                .database
                .begin_read()
                .expect("finite final retirement read");
            let encoded = read
                .open_table(BLOB_PUBLICATIONS)
                .expect("finite final publications")
                .get(stored.transfer_id.as_bytes().as_slice())
                .expect("finite final publication lookup")
                .expect("finite final retained retirement")
                .value()
                .to_vec();
            assert!(matches!(
                lifecycle::publication_retirement(&encoded)
                    .expect("decode finite final retirement"),
                Some((lifecycle::RetirementReason::Expired, _, _))
            ));
            assert!(
                !deletion::variant_has_deletion_manifest_read(&read, stored.variant_id)
                    .expect("finite final manifest before maintenance")
            );
        }
        drop(lease);
        drop(store);

        let reopened = Store::open_for_mission(&root.database, services.authority)
            .expect("reopen finite final retirement");
        assert!(matches!(
            reopened.get_blob(stored.transfer_id),
            Err(StoreError::Blob(BlobStoreError::ExpiredOrRetired))
        ));
        {
            let read = reopened.database.begin_read().unwrap();
            assert!(
                !deletion::variant_has_deletion_manifest_read(&read, stored.variant_id)
                    .expect("reopened finite final manifest before maintenance")
            );
        }
        drive_maintenance_class_until(
            &reopened,
            lifecycle::BlobMaintenanceClass::UnreferencedCompletedVariants,
            Some(deadline),
            |store| {
                let read = store.database.begin_read().expect("later manifest read");
                deletion::variant_has_deletion_manifest_read(&read, stored.variant_id)
                    .expect("later manifest state")
            },
        )
        .expect("later finite final manifest admission");
    }

