    #[test]
    fn blob_pressure_expired_final_pending_retires_with_active_lease() {
        let source_root = BlobTestRoot::new("pressure-expired-pending-source");
        let target_root = BlobTestRoot::new("pressure-expired-pending-target");
        let mut services = blob_services(0xbd);
        let source = Store::open_for_mission(&source_root.database, services.authority)
            .expect("finite pending source store");
        let target = Store::open_for_mission(&target_root.database, services.authority)
            .expect("finite pending target store");
        let checkpoint = CustodySample {
            clock_id: [0xbd; 16],
            tick_ms: 100,
        };
        let continuity = {
            let write = target
                .database
                .begin_write()
                .expect("finite pending continuity writer");
            let continuity = custody::observe_continuity_write(&write, checkpoint)
                .expect("finite pending continuity");
            pressure::synchronize_reanchor_state_write(&write)
                .expect("finite pending pressure target");
            write.commit().expect("commit finite pending continuity");
            continuity
        };
        let plaintext = b"finite pending final root waits for later deletion".to_vec();
        let prepared = prepared_blob(&plaintext);
        let proof = prepare_blob_proof_with_lifetime(
            &source,
            &mut services,
            &prepared,
            &plaintext,
            1,
            Priority::Routine,
            Some(100),
        );
        let plan = proof
            .blob
            .transfer_plan(&proof.manifest_bytes)
            .expect("finite pending plan");
        let policy = target
            .control_policy_snapshot()
            .expect("finite pending policy");
        let transfer = BlobTransferId::new(proof.blob.envelope_id());
        assert_eq!(
            target
                .stage_verified_blob_source_with_lifetime(
                    &policy,
                    &proof.blob,
                    &proof.sealed,
                    &plan,
                    Some(VerifiedFiniteBlobAdmission::for_test(
                        proof.blob.envelope_id(),
                        u64::try_from(proof.sealed.len()).expect("finite pending source length"),
                        proof.blob.item_id(),
                        proof.blob.blob_id(),
                        proof.blob.priority(),
                        100,
                        50,
                        checkpoint,
                    )),
                )
                .expect("stage finite pending root"),
            BlobSourceStageOutcome::Inserted
        );
        let deadline = CustodySample {
            clock_id: checkpoint.clock_id,
            tick_ms: 150,
        };
        {
            let write = target
                .database
                .begin_write()
                .expect("finite pending deadline writer");
            let observed = custody::observe_continuity_write(&write, deadline)
                .expect("advance finite pending deadline");
            assert_eq!(observed.generation(), continuity.generation());
            synchronize_blob_policy_generation_write(&write)
                .expect("synchronize finite pending policy");
            write.commit().expect("commit finite pending deadline");
        }
        let variant = proof.completion.variant_id();
        let lease = target
            .test_acquire_blob_lease(variant, lease::BlobLeaseKind::ApplicationPageRead)
            .expect("active finite pending lease");
        let recovery = target
            .run_blob_pressure_recovery(
                pressure::BlobCapacityRecoveryDemand::new(
                    pressure::BlobCapacityPartition::NetworkStagingRows,
                    Priority::Immediate,
                    1,
                )
                .expect("finite pending pressure demand"),
                pressure::BlobPressureRecoveryBudget::new(
                    MAX_BLOB_PRESSURE_FINAL_ROOT_ROWS,
                    MAX_BLOB_PRESSURE_FINAL_ROOT_BYTES,
                    1,
                    1,
                    0,
                )
                .expect("finite pending pressure budget"),
                None,
            )
            .expect("finite pending pressure recovery");
        assert_eq!(recovery.evicted_transfer_ids(), &[transfer]);
        assert_eq!(recovery.recovered_units(), 1);
        assert!(recovery.deficit_met());
        assert!(target.pending_blob_source(transfer).unwrap().is_none());
        {
            let read = target.database.begin_read().unwrap();
            assert!(
                !deletion::variant_has_deletion_manifest_read(&read, variant)
                    .expect("finite pending manifest before maintenance")
            );
        }
        drop(lease);
        drop(source);
        drop(target);

        let reopened = Store::open_for_mission(&target_root.database, services.authority)
            .expect("reopen finite pending retirement");
        assert!(reopened.pending_blob_source(transfer).unwrap().is_none());
        {
            let read = reopened.database.begin_read().unwrap();
            assert!(
                !deletion::variant_has_deletion_manifest_read(&read, variant)
                    .expect("reopened finite pending manifest before maintenance")
            );
        }
        drive_maintenance_class_until(
            &reopened,
            lifecycle::BlobMaintenanceClass::UnreferencedLocalImportStaging,
            Some(deadline),
            |store| {
                let read = store
                    .database
                    .begin_read()
                    .expect("later pending manifest read");
                deletion::variant_has_deletion_manifest_read(&read, variant)
                    .expect("later pending manifest state")
            },
        )
        .expect("later finite pending manifest admission");
    }

    #[test]
    fn blob_pressure_final_root_is_lease_fenced_and_commits_deletion_manifest() {
        // Break caught: retiring a final root before fencing readers leaves a
        // live lease over deleting files, while retiring without a manifest
        // falsely claims physical recovery.
        let root = BlobTestRoot::new("pressure-final-root-manifest");
        let mut services = blob_services(0xb2);
        let plaintext = b"one final pressure root enters resumable deletion".to_vec();
        let prepared = prepared_blob(&plaintext);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("pressure final-root store");
        let proof = prepare_blob_proof_with_priority(
            &store,
            &mut services,
            &prepared,
            &plaintext,
            1,
            Priority::Routine,
        );
        let stored = commit_blob_proof(&store, &services, &proof, b"pressure-final-root-operation")
            .0
            .blob()
            .clone();
        let demand = pressure::BlobCapacityRecoveryDemand::new(
            pressure::BlobCapacityPartition::AggregateItems,
            Priority::Immediate,
            1,
        )
        .unwrap();
        let budget = pressure::BlobPressureRecoveryBudget::new(
            MAX_BLOB_PRESSURE_FINAL_ROOT_ROWS,
            MAX_BLOB_PRESSURE_FINAL_ROOT_BYTES,
            1,
            2,
            1,
        )
        .unwrap();
        let no_manifest_budget = pressure::BlobPressureRecoveryBudget::new(
            MAX_BLOB_PRESSURE_FINAL_ROOT_ROWS,
            MAX_BLOB_PRESSURE_FINAL_ROOT_BYTES,
            1,
            2,
            0,
        )
        .unwrap();
        let before_no_manifest = blob_complete_logical_digest(&store);
        let no_manifest = store
            .run_blob_pressure_recovery(demand, no_manifest_budget, None)
            .expect("manifest-budget refusal");
        assert!(no_manifest.evicted_transfer_ids().is_empty());
        assert_eq!(blob_complete_logical_digest(&store), before_no_manifest);
        TEST_BLOB_MANIFEST_ADMISSION_GENERATION_CHURN.set(true);
        let generation_race = store
            .run_blob_pressure_recovery(demand, budget, None)
            .expect("lease-generation race defers pressure");
        TEST_BLOB_MANIFEST_ADMISSION_GENERATION_CHURN.set(false);
        assert!(generation_race.evicted_transfer_ids().is_empty());
        assert_eq!(blob_complete_logical_digest(&store), before_no_manifest);
        let lease = store
            .test_acquire_blob_lease(stored.variant_id, lease::BlobLeaseKind::ApplicationPageRead)
            .expect("pressure active read lease");
        let before = blob_complete_logical_digest(&store);
        let blocked = store
            .run_blob_pressure_recovery(demand, budget, None)
            .expect("lease-blocked pressure recovery");
        assert!(blocked.evicted_transfer_ids().is_empty());
        assert_eq!(blob_complete_logical_digest(&store), before);
        assert!(store.get_blob(stored.transfer_id).unwrap().is_some());
        drop(lease);

        let recovered = store
            .run_blob_pressure_recovery(demand, budget, None)
            .expect("final-root pressure recovery");
        assert_eq!(recovered.evicted_transfer_ids(), &[stored.transfer_id]);
        assert_eq!(recovered.recovered_units(), 1);
        assert!(recovered.deficit_met());
        let read = store.database.begin_read().expect("pressure manifest read");
        assert!(
            deletion::variant_has_deletion_manifest_read(&read, stored.variant_id)
                .expect("pressure manifest state")
        );
        drop(read);
        assert!(matches!(
            store.get_blob(stored.transfer_id),
            Err(StoreError::Blob(BlobStoreError::ExpiredOrRetired))
        ));
        depot::inject_test_fault(
            &root.path,
            depot::DepotFaultPoint::ManifestChunkBeforeUnlink,
        );
        run_physical_deletion_turn_result(&store)
            .expect("pressure manifest records retryable deletion failure");
        assert_eq!(
            deletion_manifest_for_test(&store, stored.variant_id)
                .retry
                .attempts,
            1
        );
        drop(store);

        let reopened = Store::open_for_mission(&root.database, services.authority)
            .expect("reopen pressure final-root store");
        assert_eq!(
            deletion_manifest_for_test(&reopened, stored.variant_id)
                .retry
                .attempts,
            1
        );
        assert!(matches!(
            reopened.get_blob(stored.transfer_id),
            Err(StoreError::Blob(BlobStoreError::ExpiredOrRetired))
        ));
        for _ in 0..4 {
            run_physical_deletion_turn_result(&reopened)
                .expect("resume pressure deletion after reopen");
        }
        let read = reopened.database.begin_read().unwrap();
        assert!(!deletion::variant_has_deletion_manifest_read(&read, stored.variant_id).unwrap());
    }

    #[test]
    fn blob_pressure_staging_evicts_pending_source_and_exact_prefix_units() {
        // Break caught: publication or variant scans cannot prove how many
        // staging rows/bytes one pending-source retirement actually releases.
        let source_root = BlobTestRoot::new("pressure-staging-source");
        let target_root = BlobTestRoot::new("pressure-staging-target");
        let mut services = blob_services(0xb3);
        let source = Store::open_for_mission(&source_root.database, services.authority)
            .expect("pressure staging source");
        let target = Store::open_for_mission(&target_root.database, services.authority)
            .expect("pressure staging target");
        let plaintext = b"pending pressure source with one durable carrier prefix".to_vec();
        let prepared = prepared_blob(&plaintext);
        let proof = prepare_blob_proof_with_priority(
            &source,
            &mut services,
            &prepared,
            &plaintext,
            1,
            Priority::Routine,
        );
        let plan = proof
            .blob
            .transfer_plan(&proof.manifest_bytes)
            .expect("pressure staging plan");
        let policy = target
            .control_policy_snapshot()
            .expect("target pressure policy");
        let transfer = BlobTransferId::new(proof.blob.envelope_id());
        target
            .stage_verified_blob_source_with_policy(&policy, &proof.blob, &proof.sealed, &plan)
            .expect("stage pressure pending source");
        let carrier = {
            let mut depot = source.blob_depot().expect("pressure source depot");
            CoreBlobStore::begin_blob_with_lineage(
                &mut depot,
                plan.manifest(),
                plan.physical_lineage(),
            )
            .expect("activate pressure source plan");
            plan.build_carrier(&mut depot, 0)
                .expect("build pressure carrier")
        };
        let object = BlobCarrierObjectId::new(carrier.object_id().wire_bytes())
            .expect("pressure carrier identity");
        target
            .append_blob_carrier_prefix_with_policy(
                &policy,
                transfer,
                object,
                u64::try_from(carrier.bytes().len()).unwrap(),
                0,
                &carrier.bytes()[..carrier.bytes().len().min(MAX_BLOB_NETWORK_RANGE_BYTES)],
            )
            .expect("append pressure carrier prefix");
        // Reproduce the valid crash boundary after the depot chunk commits
        // but before the redb prefix cleanup commits. Pressure progress sees
        // the durable chunk; pending removal must still charge and remove the
        // surviving prefix row.
        {
            let mut depot = BlobDepot::open_network_mutation(&target, false)
                .expect("open crash-shape target depot");
            CoreBlobStore::begin_blob_with_lineage(
                &mut depot,
                plan.manifest(),
                plan.physical_lineage(),
            )
            .expect("activate crash-shape target plan");
            let verified = plan
                .verify_carrier(object.as_bytes(), carrier.bytes())
                .expect("verify crash-shape carrier");
            plan.install_verified_carrier(&mut depot, &verified)
                .expect("commit crash-shape carrier without prefix cleanup");
            CoreBlobStore::finalize_blob(&mut depot, plan.manifest().id(), *plan.manifest_digest())
                .expect("finalize crash-shape target variant");
        }
        let before = target.blob_stats().expect("before staging pressure stats");
        assert_eq!(before.pending_sources, 1);
        assert_eq!(before.carrier_prefixes, 1);

        let pending = {
            let read = target.database.begin_read().unwrap();
            let encoded = read
                .open_table(BLOB_PENDING_SOURCES)
                .unwrap()
                .get(transfer.as_bytes().as_slice())
                .unwrap()
                .unwrap()
                .value()
                .to_vec();
            decode_pending_blob_source(&encoded).unwrap()
        };
        let (exact_rows, exact_bytes) = {
            let write = target.database.begin_write().unwrap();
            let mut charge = MaintenanceCharge::new(
                lifecycle::BlobMaintenanceBudget::new(u64::MAX, 1, u64::MAX).unwrap(),
                0,
                0,
            );
            let authority = plan_pending_removal_authority_write(
                &write,
                services.authority,
                transfer,
                &pending,
                &mut charge,
            )
            .unwrap()
            .expect("exact crash-shape pending-removal authority");
            assert_eq!(authority.prefixes.len(), 1);
            assert!(charge.identities.contains_key(&MaintenanceRowIdentity::new(
                "aster.pending-blob-carrier-prefixes.v1",
                blob_carrier_prefix_key(transfer, object),
            )));
            (charge.rows, charge.bytes)
        };
        assert_eq!(
            exact_rows, 5,
            "pending row, retained prefix, and three staging metadata rows"
        );
        let before_short = blob_complete_logical_digest(&target);
        for budget in [
            lifecycle::BlobMaintenanceBudget::new(exact_rows - 1, 1, exact_bytes).unwrap(),
            lifecycle::BlobMaintenanceBudget::new(exact_rows, 1, exact_bytes - 1).unwrap(),
        ] {
            let write = target.database.begin_write().unwrap();
            let mut charge = MaintenanceCharge::new(budget, 0, 0);
            assert!(
                plan_pending_removal_authority_write(
                    &write,
                    services.authority,
                    transfer,
                    &pending,
                    &mut charge,
                )
                .unwrap()
                .is_none()
            );
        }
        assert_eq!(blob_complete_logical_digest(&target), before_short);

        let recovered = target
            .run_blob_pressure_recovery(
                pressure::BlobCapacityRecoveryDemand::new(
                    pressure::BlobCapacityPartition::NetworkStagingRows,
                    Priority::Immediate,
                    2,
                )
                .unwrap(),
                pressure::BlobPressureRecoveryBudget::new(
                    MAX_BLOB_PRESSURE_FINAL_ROOT_ROWS,
                    MAX_BLOB_PRESSURE_FINAL_ROOT_BYTES,
                    1,
                    1,
                    1,
                )
                .unwrap(),
                None,
            )
            .expect("pending staging pressure recovery");
        assert_eq!(recovered.evicted_transfer_ids(), &[transfer]);
        assert_eq!(recovered.recovered_units(), 2);
        assert!(recovered.deficit_met());
        assert!(target.pending_blob_source(transfer).unwrap().is_none());
        let after = target.blob_stats().expect("after staging pressure stats");
        assert_eq!(after.pending_sources, 0);
        assert_eq!(after.carrier_prefixes, 0);
        assert_eq!(after.lineage_fences, before.lineage_fences);
        let read = target.database.begin_read().expect("staging manifest read");
        assert!(
            deletion::variant_has_deletion_manifest_read(&read, proof.completion.variant_id())
                .expect("staging pressure manifest")
        );
    }

    #[test]
    fn blob_pressure_depot_evicts_every_shared_root_as_one_atomic_variant() {
        // Break caught: depot pressure used to return no candidate after the
        // ordered whole-variant index had selected an eligible shared variant.
        let root = BlobTestRoot::new("pressure-depot-whole-variant");
        let mut services = blob_services(0xb4);
        let plaintext = vec![0xb4; SELECTED_BLOB_CHUNK_SIZE as usize + 37];
        let prepared = prepared_blob(&plaintext);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("whole-variant pressure store");
        let routine_proof = prepare_blob_proof_with_priority(
            &store,
            &mut services,
            &prepared,
            &plaintext,
            1,
            Priority::Routine,
        );
        let routine = commit_blob_proof(
            &store,
            &services,
            &routine_proof,
            b"pressure-variant-routine",
        )
        .0
        .blob()
        .clone();
        let priority_proof = prepare_blob_proof_with_priority(
            &store,
            &mut services,
            &prepared,
            &plaintext,
            1,
            Priority::Priority,
        );
        let priority = commit_blob_proof(
            &store,
            &services,
            &priority_proof,
            b"pressure-variant-priority",
        )
        .0
        .blob()
        .clone();
        assert_eq!(routine.variant_id, priority.variant_id);
        let before = store.blob_stats().expect("before whole-variant pressure");

        let equal_priority = store
            .run_blob_pressure_recovery(
                pressure::BlobCapacityRecoveryDemand::new(
                    pressure::BlobCapacityPartition::DepotVariants,
                    Priority::Priority,
                    1,
                )
                .unwrap(),
                pressure::BlobPressureRecoveryBudget::new(
                    MAX_BLOB_PRESSURE_FINAL_ROOT_ROWS * 2,
                    MAX_BLOB_PRESSURE_FINAL_ROOT_BYTES * 2,
                    2,
                    4,
                    1,
                )
                .unwrap(),
                None,
            )
            .expect("equal-priority depot pressure");
        assert!(equal_priority.evicted_transfer_ids().is_empty());
        assert_eq!(store.blob_stats().unwrap(), before);

        let recovered = store
            .run_blob_pressure_recovery(
                pressure::BlobCapacityRecoveryDemand::new(
                    pressure::BlobCapacityPartition::DepotVariants,
                    Priority::Immediate,
                    1,
                )
                .unwrap(),
                pressure::BlobPressureRecoveryBudget::new(
                    MAX_BLOB_PRESSURE_FINAL_ROOT_ROWS * 2,
                    MAX_BLOB_PRESSURE_FINAL_ROOT_BYTES * 2,
                    2,
                    4,
                    1,
                )
                .unwrap(),
                None,
            )
            .expect("eligible whole-variant pressure");
        let mut evicted = recovered.evicted_transfer_ids().to_vec();
        evicted.sort_unstable();
        let mut expected = vec![routine.transfer_id, priority.transfer_id];
        expected.sort_unstable();
        assert_eq!(evicted, expected);
        assert_eq!(recovered.recovered_units(), 0);
        assert!(!recovered.deficit_met());
        assert!(matches!(
            store.get_blob(routine.transfer_id),
            Err(StoreError::Blob(BlobStoreError::ExpiredOrRetired))
        ));
        assert!(matches!(
            store.get_blob(priority.transfer_id),
            Err(StoreError::Blob(BlobStoreError::ExpiredOrRetired))
        ));
        let read = store
            .database
            .begin_read()
            .expect("whole-variant manifest read");
        assert!(
            deletion::variant_has_deletion_manifest_read(&read, routine.variant_id)
                .expect("whole-variant pressure manifest")
        );
        drop(read);
        let committed_manifest = deletion_manifest_for_test(&store, routine.variant_id);
        assert_eq!(committed_manifest.totals.chunks, 2);
        let after = store.blob_stats().expect("after whole-variant pressure");
        assert_eq!(after.lineage_fences, before.lineage_fences);
        assert_eq!(after.replay_fences, before.replay_fences);
        assert_eq!(before.publications.checked_sub(after.publications), Some(2));
        drop(store);
        let reopened = Store::open_for_mission(&root.database, services.authority)
            .expect("reopen whole-variant pressure manifest");
        assert_eq!(
            deletion_manifest_for_test(&reopened, routine.variant_id),
            committed_manifest
        );
    }

    #[test]
    fn blob_durable_capacity_gc_finalizes_existing_orphan_and_enables_transfer() {
        // Break caught: contact-safe cleanup must reclaim already-authorized
        // orphan physical data so a durable transfer can proceed, without
        // borrowing lifecycle expiry or manifest-admission authority.
        let root = BlobTestRoot::new("pressure-depot-admission-recovery");
        let mut services = blob_services(0xb6);
        let first_plaintext = vec![0xb6; 512];
        let first_prepared = prepared_blob(&first_plaintext);
        let reserved_limit = 153 + 16 + u64::try_from(first_plaintext.len()).unwrap();
        let store = Store::open_with_limits_and_blob_depot_limits_for_mission(
            &root.database,
            StoreLimits::default(),
            BlobDepotLimits::new(reserved_limit, 1, 1)
                .expect("one active variant, chunk, and file reservation"),
            services.authority,
        )
        .expect("pressure admission-recovery store");
        let first_proof = prepare_blob_proof_with_priority(
            &store,
            &mut services,
            &first_prepared,
            &first_plaintext,
            1,
            Priority::Routine,
        );
        let first = commit_blob_proof(&store, &services, &first_proof, b"pressure-admission-first")
            .0
            .blob()
            .clone();
        let recovered = store
            .run_blob_pressure_recovery(
                pressure::BlobCapacityRecoveryDemand::new(
                    pressure::BlobCapacityPartition::DepotVariants,
                    Priority::Immediate,
                    1,
                )
                .unwrap(),
                pressure::BlobPressureRecoveryBudget::new(
                    MAX_BLOB_PRESSURE_FINAL_ROOT_ROWS,
                    MAX_BLOB_PRESSURE_FINAL_ROOT_BYTES,
                    1,
                    2,
                    1,
                )
                .unwrap(),
                None,
            )
            .expect("recover one depot variant");
        assert!(!recovered.deficit_met());
        assert_eq!(recovered.recovered_units(), 0);
        deletion_manifest_for_test(&store, first.variant_id);

        let second_plaintext = vec![0xb7; 512];
        let second_prepared = prepared_blob(&second_plaintext);
        let error = finish_variant(
            &store,
            &services.publisher,
            &second_prepared,
            &second_plaintext,
            2,
        )
        .expect_err("pending physical deletion retains depot capacity charge");
        assert!(
            error.contains("durable import rows"),
            "unexpected retained-charge error: {error}"
        );
        let progress = store
            .run_durable_blob_capacity_gc_for(
                BlobCapacityGcTarget::Depot,
                BlobMaintenanceBudget::new(64, 16, 128 * 1024 * 1024)
                    .expect("physical finalization budget"),
                None,
            )
            .expect("physically finalize pressure deletion");
        assert_eq!(progress.manifests_finalized, 1);
        let second = finish_variant(
            &store,
            &services.publisher,
            &second_prepared,
            &second_plaintext,
            2,
        )
        .expect("physical finalization releases admission capacity");
        assert_ne!(second.id(), first.blob_id);
        let read = store
            .database
            .begin_read()
            .expect("finalized manifest read");
        assert!(
            !deletion::variant_has_deletion_manifest_read(&read, first.variant_id)
                .expect("finalized deletion authority")
        );
    }

    #[test]
    fn blob_pressure_cache_reconciliation_continues_only_the_selected_manifest() {
        // Break caught: the post-cache continuation must not scan the global
        // deletion queue and prove the selected pressure deficit by finalizing
        // an unrelated manifest that sorts first.
        let root = BlobTestRoot::new("pressure-exact-post-cache-continuation");
        let mut services = blob_services(0xb7);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("exact post-cache continuation store");
        let first_plaintext = b"exact continuation candidate one".to_vec();
        let second_plaintext = b"exact continuation candidate two".to_vec();
        let first_prepared = prepared_blob(&first_plaintext);
        let second_prepared = prepared_blob(&second_plaintext);
        let first_proof = prepare_blob_proof_with_priority(
            &store,
            &mut services,
            &first_prepared,
            &first_plaintext,
            1,
            Priority::Routine,
        );
        let unrelated =
            commit_blob_proof(&store, &services, &first_proof, b"pressure-exact-unrelated")
                .0
                .blob()
                .clone();
        let second_proof = prepare_blob_proof_with_priority(
            &store,
            &mut services,
            &second_prepared,
            &second_plaintext,
            1,
            Priority::Routine,
        );
        let selected =
            commit_blob_proof(&store, &services, &second_proof, b"pressure-exact-selected")
                .0
                .blob()
                .clone();
        let selected_shared_proof = prepare_blob_proof_with_priority(
            &store,
            &mut services,
            &second_prepared,
            &second_plaintext,
            1,
            Priority::Routine,
        );
        let selected_shared = commit_blob_proof(
            &store,
            &services,
            &selected_shared_proof,
            b"pressure-exact-selected-shared",
        )
        .0
        .blob()
        .clone();
        assert_eq!(selected_shared.variant_id, selected.variant_id);
        assert!(unrelated.variant_id < selected.variant_id);
        let pressure_budget = pressure::BlobPressureRecoveryBudget::new(
            MAX_BLOB_PRESSURE_FINAL_ROOT_ROWS,
            MAX_BLOB_PRESSURE_FINAL_ROOT_BYTES,
            1,
            1,
            1,
        )
        .expect("single-root pressure budget");
        let demand = pressure::BlobCapacityRecoveryDemand::new(
            pressure::BlobCapacityPartition::DepotVariants,
            Priority::Immediate,
            1,
        )
        .expect("one-variant pressure demand");
        let unrelated_recovery = store
            .run_blob_pressure_recovery(demand, pressure_budget, None)
            .expect("admit unrelated deletion manifest");
        assert_eq!(
            unrelated_recovery.evicted_transfer_ids(),
            &[unrelated.transfer_id]
        );
        let admission_error = StoreError::Blob(BlobStoreError::DepotVariantLimitExceeded {
            current: 2,
            limit: 2,
        });
        let selected_recovery = store
            .run_blob_pressure_recovery_after_cleanup(
                &admission_error,
                Priority::Immediate,
                None,
                (0, 1),
                BlobMaintenanceBudget::new(
                    MAX_BLOB_PRESSURE_FINAL_ROOT_ROWS + 64,
                    2,
                    MAX_BLOB_PRESSURE_FINAL_ROOT_BYTES + 128 * 1024 * 1024,
                )
                .expect("pressure plus one-manifest physical budget"),
                None,
            )
            .expect("select exact pressure recovery")
            .expect("typed depot capacity demand");
        let mut evicted = selected_recovery.evicted_transfer_ids().to_vec();
        evicted.sort_unstable();
        let mut expected = vec![selected.transfer_id, selected_shared.transfer_id];
        expected.sort_unstable();
        assert_eq!(evicted, expected);
        deletion_manifest_for_test(&store, unrelated.variant_id);
        deletion_manifest_for_test(&store, selected.variant_id);

        drop(store);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("reopen exact post-cache continuation store");

        let continued = store
            .continue_blob_pressure_recovery_after_cache_reconciliation(selected_recovery)
            .expect("continue the exact selected pressure recovery");
        assert!(continued.deficit_met());
        let read = store
            .database
            .begin_read()
            .expect("continuation manifest read");
        assert!(
            deletion::variant_has_deletion_manifest_read(&read, unrelated.variant_id)
                .expect("unrelated manifest remains")
        );
        assert!(
            !deletion::variant_has_deletion_manifest_read(&read, selected.variant_id)
                .expect("selected manifest finalized")
        );
    }

    #[test]
    fn blob_exact_physical_selection_stops_on_delayed_or_missing_authority() {
        // Break caught: an exact continuation must report no selected work
        // instead of falling through to an unrelated globally-ready manifest.
        let root = BlobTestRoot::new("pressure-exact-authority-boundary");
        let services = blob_services(0xba);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("exact authority-boundary store");
        let first = install_unreferenced_variant(
            &store,
            &services,
            b"exact authority first variant",
            1,
            true,
        );
        let second = install_unreferenced_variant(
            &store,
            &services,
            b"exact authority second variant",
            2,
            true,
        );
        store
            .test_admit_blob_deletion_manifest(first)
            .expect("admit first exact authority manifest");
        store
            .test_admit_blob_deletion_manifest(second)
            .expect("admit second exact authority manifest");
        let (unrelated, delayed) = if first < second {
            (first, second)
        } else {
            (second, first)
        };
        let delayed_manifest = deletion_manifest_for_test(&store, delayed);
        let next_retry_turn = {
            let read = store.database.begin_read().expect("read deletion turn");
            read.open_table(deletion::BLOB_DELETION_METADATA)
                .expect("deletion metadata")
                .get(deletion::BLOB_DELETION_MAINTENANCE_TURN)
                .expect("deletion turn lookup")
                .expect("deletion turn")
                .value()
                + 8
        };
        let write = store
            .database
            .begin_write()
            .expect("delay exact authority manifest");
        deletion::set_blob_deletion_phase_for_test(
            &write,
            delayed,
            delayed_manifest.phase,
            deletion::BlobDeletionRetry {
                category: Some(deletion::BlobDeletionFailureCategory::ChunkUnlink),
                attempts: 1,
                next_retry_turn,
            },
        )
        .expect("persist delayed exact authority");
        write.commit().expect("commit delayed exact authority");

        let read = store.database.begin_read().expect("exact selection read");
        assert!(matches!(
            deletion::select_exact_physical_work_read(&read, delayed, None, u64::MAX, u64::MAX,)
                .expect("delayed exact selection"),
            deletion::BlobDeletionSelection::Complete { .. }
        ));
        assert!(matches!(
            deletion::select_physical_work_read(&read, None, u64::MAX, u64::MAX)
                .expect("global unrelated selection"),
            deletion::BlobDeletionSelection::Work(work) if work.manifest.variant_id == unrelated
        ));
        let missing = BlobVariantId::from_bytes([0xff; 32]);
        assert_ne!(missing, first);
        assert_ne!(missing, second);
        assert!(matches!(
            deletion::select_exact_physical_work_read(&read, missing, None, u64::MAX, u64::MAX,)
                .expect("missing exact selection"),
            deletion::BlobDeletionSelection::Complete { .. }
        ));
    }

    #[test]
    fn blob_exact_continuation_does_not_credit_unrelated_release_when_authority_is_missing() {
        // Break caught: disappearance of the selected manifest is not proof
        // that this continuation released capacity. An unrelated manifest may
        // have finalized after the receipt baseline was captured.
        let root = BlobTestRoot::new("pressure-exact-missing-authority-credit");
        let services = blob_services(0xbc);
        let store = Store::open_for_mission(&root.database, services.authority)
            .expect("exact missing-authority credit store");
        let first = install_unreferenced_variant(
            &store,
            &services,
            b"exact missing authority first variant",
            1,
            true,
        );
        let second = install_unreferenced_variant(
            &store,
            &services,
            b"exact missing authority second variant",
            2,
            true,
        );
        store
            .test_admit_blob_deletion_manifest(first)
            .expect("admit first missing-authority manifest");
        store
            .test_admit_blob_deletion_manifest(second)
            .expect("admit second missing-authority manifest");
        let (unrelated, selected) = if first < second {
            (first, second)
        } else {
            (second, first)
        };
        let receipt_budget = BlobMaintenanceBudget::new(128, 2, 128 * 1024 * 1024)
            .expect("missing-authority receipt budget");
        let demand = pressure::BlobCapacityRecoveryDemand::new(
            pressure::BlobCapacityPartition::DepotVariants,
            Priority::Immediate,
            1,
        )
        .expect("missing-authority demand");
        let recovery = pressure::BlobCapacityRecoveryResult::recovered_with_physical_candidate(
            vec![BlobTransferId::new([0xbc; 32])],
            0,
            demand,
            0,
            0,
            selected,
        )
        .bind_physical_recovery(2, receipt_budget);

        let progress = store
            .run_durable_blob_capacity_gc_for(BlobCapacityGcTarget::Depot, receipt_budget, None)
            .expect("finalize only the unrelated manifest");
        assert_eq!(progress.manifests_finalized, 1);
        let read = store.database.begin_read().expect("manifest state read");
        assert!(
            !deletion::variant_has_deletion_manifest_read(&read, unrelated)
                .expect("unrelated authority finalized")
        );
        assert!(
            deletion::variant_has_deletion_manifest_read(&read, selected)
                .expect("selected authority remains")
        );
        drop(read);

        let write = store
            .database
            .begin_write()
            .expect("remove selected authority");
        {
            let mut manifests = write
                .open_table(deletion::BLOB_DELETION_MANIFESTS)
                .expect("selected authority table");
            assert!(
                manifests
                    .remove(selected.as_bytes().as_slice())
                    .expect("remove selected authority")
                    .is_some()
            );
        }
        write.commit().expect("commit missing selected authority");

        let continued = store
            .continue_blob_pressure_recovery_after_cache_reconciliation(recovery)
            .expect("continue with missing selected authority");
        assert!(!continued.deficit_met());
        assert_eq!(continued.recovered_units(), 0);
    }

    #[test]
